package.preload[ "aho_corasick" ] = assert( (loadstring or load)(
"-- Aho-Corasick自动机模块\
-- 用于高效的多模式字符串匹配\
\
local aho_corasick = {}\
\
local byte = string.byte\
local char = string.char\
\
-- 创建一个新的节点\
local function create_node()\
    return {\
        to = {},    -- 子节点的映射,键为字符的字节值,值为对应的子节点\
        output = {}, -- 存储该节点对应的完整模式和相关信息\
        fail = nil,  -- 失败指针,指向匹配失败时应跳转的节点\
        word = false -- 标记该节点是否是某个模式的结束\
    }\
end\
\
-- 清理失败指针\
local function clear_fail_pointers(node)\
    node.fail = nil\
    for _, child in pairs(node.to) do\
        clear_fail_pointers(child)\
    end\
end\
\
-- 添加模式到Trie树\
local function add_pattern(ac, pattern, info)\
    local node = ac.root\
    for i = 1, #pattern do\
        local c = byte(pattern, i)\
        if not node.to[c] then\
            node.to[c] = create_node()\
        end\
        node = node.to[c]\
    end\
    node.word = true\
    table.insert(node.output, {pattern = pattern, info = info})\
    ac.fail_built = false\
end\
\
-- 从Trie树删除模式\
local function remove_pattern(ac, pattern, info)\
    local node = ac.root\
    local path = {}\
    for i = 1, #pattern do\
        local c = byte(pattern, i)\
        if not node.to[c] then\
            return false\
        end\
        table.insert(path, {node = node, char = c})\
        node = node.to[c]\
    end\
    if not node.word then\
        return false\
    end\
    if not info then\
        node.output = {}\
    else\
        for index, value in ipairs(node.output) do\
            if value.info == info then\
                table.remove(node.output, index)\
                ac.fail_built = false\
                break\
            end\
        end\
    end\
    if #node.output == 0 then\
        node.word = false\
        -- 清理不必要的节点\
        for i = #path, 1, -1 do\
            local parent = path[i].node\
            local c = path[i].char\
            node = parent.to[c]\
            if next(node.to) == nil and not node.word then\
                parent.to[c] = nil\
            else\
                break\
            end\
        end\
        ac.fail_built = false\
    end\
    return true\
end\
\
-- 构建失败指针\
local function build_fail(ac)\
    -- 清理旧的失败指针\
    clear_fail_pointers(ac.root)\
\
    -- 初始化队列和根节点\
    local queue = {}\
    local root = ac.root\
\
    -- 将根节点的所有子节点加入队列，并设置它们的失败指针指向根节点\
    for _, child in pairs(root.to) do\
        child.fail = root\
        table.insert(queue, child)\
    end\
\
    -- 广度优先搜索构建失败指针\
    while #queue > 0 do\
        local node = table.remove(queue, 1)\
        for c, child in pairs(node.to) do\
            -- 将当前节点的子节点加入队列\
            table.insert(queue, child)\
\
            -- 查找失败指针\
            local fail = node.fail\
            while fail ~= root and not fail.to[c] do\
                fail = fail.fail\
            end\
            child.fail = fail.to[c] or root\
        end\
    end\
    ac.fail_built = true\
end\
\
-- 在文本中匹配模式\
local function match(ac, text, all)\
    if not ac.fail_built then\
        build_fail(ac)\
    end\
\
    if all == nil then\
        all = true\
    end\
\
    local node = ac.root\
    local results = {}\
    local results_idx = 0\
\
    for i = 1, #text do\
        local c = byte(text, i)\
        while node ~= ac.root and not node.to[c] do\
            node = node.fail\
        end\
        node = node.to[c] or ac.root\
        if node.word or (node.fail and node.fail.word) then\
            for _, output in ipairs(node.output) do\
                results_idx = results_idx + 1\
                results[results_idx] = output\
                if not all then\
                    return results\
                end\
            end\
            for _, output in ipairs(node.fail.output) do\
                results_idx = results_idx + 1\
                results[results_idx] = output\
            end\
        end\
    end\
    return results\
end\
\
-- 展示当前Trie树的状态，包括失败指针\
local function display_trie(ac)\
    local node_id_map = {}\
    local id_counter = 0\
\
    -- 为每个节点分配唯一ID\
    local function assign_ids(node)\
        if node_id_map[node] then\
            return node_id_map[node]\
        end\
        id_counter = id_counter + 1\
        node_id_map[node] = id_counter\
        return id_counter\
    end\
\
    -- 获取节点到根的路径\
    local function get_path(node)\
        local path = {}\
        local current = node\
        local visited = {}\
        while current ~= ac.root and not visited[current] do\
            visited[current] = true\
            local found = false\
            for char_value, child in pairs(ac.root.to) do\
                if child == current then\
                    table.insert(path, 1, char(char_value))\
                    current = ac.root\
                    found = true\
                    break\
                end\
            end\
            if not found then\
                for parent in pairs(node_id_map) do\
                    for char_value, child in pairs(parent.to) do\
                        if child == current then\
                            table.insert(path, 1, char(char_value))\
                            current = parent\
                            found = true\
                            break\
                        end\
                    end\
                    if found then break end\
                end\
            end\
            if not found then break end\
        end\
        return table.concat(path)\
    end\
\
    -- 递归函数，将节点及其子节点转换为字符串\
    local function node_to_string(node, prefix, char_value)\
        local output = {}\
        table.insert(output, prefix)\
        if char_value then\
            table.insert(output, string.format(\"'%s' \", char(char_value)))\
        end\
        local node_id = assign_ids(node)\
        table.insert(output, string.format(\"(ID: %d) \", node_id))\
        if node.word then\
            table.insert(output, \"[词尾] \")\
        end\
        if #node.output > 0 then\
            table.insert(output, \"输出: \")\
            for _, out in ipairs(node.output) do\
                table.insert(output, string.format(\"(%s, %s) \", out.pattern, tostring(out.info)))\
            end\
        end\
        -- 添加失败指针信息\
        if node.fail then\
            local fail_id = assign_ids(node.fail)\
            local fail_path = get_path(node.fail)\
            table.insert(output, string.format(\"失败指针: ID %d ('%s') \", fail_id, fail_path))\
        end\
        table.insert(output, \"\\n\")\
\
        -- 对子节点的字符进行排序，确保输出顺序一致\
        local sorted_chars = {}\
        for c in pairs(node.to) do\
            table.insert(sorted_chars, c)\
        end\
        table.sort(sorted_chars)\
\
        -- 递归处理所有子节点\
        for _, c in ipairs(sorted_chars) do\
            table.insert(output, node_to_string(node.to[c], prefix .. \"  |-- \", c))\
        end\
\
        return table.concat(output)\
    end\
\
    -- 返回整个Trie树的字符串表示\
    return \"Trie树结构（包括失败指针）:\\n\" .. node_to_string(ac.root, \"\", nil)\
end\
\
-- 创建一个新的Aho-Corasick自动机实例\
function aho_corasick.new()\
    local ac = {\
        root = create_node(),\
        fail_built = false,\
    }\
\
    return setmetatable(\
        ac,\
        {\
            __index = {\
                add_pattern = add_pattern,\
                remove_pattern = remove_pattern,\
                build_fail = build_fail,\
                display = display_trie,\
                match = match,\
            }\
        }\
    )\
end\
\
--[[\
使用说明:\
1. 创建AC自动机实例:\
   local ac = aho_corasick.new()\
\
2. 添加模式:\
   ac:add_pattern(\"pattern\", info)\
   其中info可以是任何与该模式相关的信息\
\
3. 删除模式:\
   ac:remove_pattern(\"pattern\", info)\
   info为可选参数。如果提供，只删除匹配该info的模式\
   删除成功返回true，模式不存在返回false\
\
4. 构建失败指针:\
   ac:build_fail()\
   在添加或删除模式后，必须调用此方法来重建失败指针\
\
5. 执行匹配:\
   local results = ac:match(\"text\")\
   返回的results是一个包含所有匹配结果的表\
\
6. 显示Trie树结构:\
   local trie_structure = ac:display()\
   返回一个字符串，表示当前Trie树的结构\
\
示例:\
local ac = aho_corasick.new()\
ac:add_pattern(\"he\", \"pronoun\")\
ac:add_pattern(\"she\", \"pronoun\")\
ac:add_pattern(\"his\", \"possessive\")\
ac:add_pattern(\"hers\", \"possessive\")\
ac:build_fail()\
\
-- 删除模式\
ac:remove_pattern(\"he\", \"pronoun\")\
ac:build_fail()  -- 重建失败指针\
\
local trie_structure = ac:display()\
print(trie_structure)\
\
local results = ac:match(\"ushers\")\
for i, result in ipairs(results) do\
    print(string.format(\"匹配 %d: 模式 = %s, 信息 = %s\", i, result.pattern, tostring(result.info)))\
end\
\
注意:\
- 在调用match之前，必须先添加所有模式并调用build_fail\
- 添加或删除模式后，需要重新调用build_fail来重建失败指针\
- match方法返回的结果包含所有匹配，包括重叠匹配\
- display方法返回一个字符串，可以用于调试或可视化Trie树结构\
]]\
\
return aho_corasick"
, '@'.."./lualib/aho_corasick.lua" ) )

package.preload[ "appcidr" ] = assert( (loadstring or load)(
"local cjson = require(\"cjson\")\
local kernel = require(\"c.kernel\")\
local actor = require(\"luactor\")\
local myip = require(\"myip\")\
local myutil = require(\"myutil\")\
local log = require(\"log\")\
local ccrypto = require(\"c.crypto\")\
local mime = require(\"mime\")\
local cidr_enable, cidr = pcall(require, \"c.cidr\")\
local appcidr = {\
    subtype = \"appcidr\",\
    help = \"appcidr module, configure/save, also including cidr rule management\",\
    enabled = false,\
    filename = \"m01_cr.bin\", -- binary file name\
    save_filename = \"m01_cr_save.bin\", -- saved binary file name\
    save_file = nil, -- saved binary file\
    key = '\\x02\\x00\\x02\\x01\\x00\\x06\\x00\\x06\\x00\\x00\\x00\\x00', -- AES key prefix\
    magic = 0x20251105, -- magic number for version control\
    ver = \"0.0.0.0\", -- version of loaded file\
    cidr_rule_file = nil -- currently loaded file path\
}\
\
-- C structure layout (8-byte aligned for 32/64-bit compatibility):\
-- typedef struct cidr_policy_rule_ {\
--     unsigned int rule_id;       // 4 bytes\
--     unsigned int app_id;        // 4 bytes\
--     unsigned long long start_key; // 8 bytes (raw key)\
--     unsigned long long end_key;   // 8 bytes (raw key)\
--     unsigned int mask;          // 4 bytes (prefix length)\
--     unsigned int hit_count;     // 4 bytes (hit count for this rule)\
--     unsigned int is_ipv6;       // 4 bytes\
--     unsigned int padding;       // 4 bytes\
-- } cidr_policy_rule_t;  // Total: 40 bytes per rule\
\
local function write_base64_to_tmp(content)\
    local decoded = mime.unb64(content)\
    if not decoded then\
        return nil, \"failed to decode base64 content\"\
    end\
    local tmp_name = string.format(\"cidr_%d_%d.bin\", os.time(), math.random(0, 9999))\
    local tmp_path = lcmd_tmp_path(tmp_name)\
    local f, err = io.open(tmp_path, \"wb\")\
    if not f then\
        return nil, string.format(\"failed to open temp file: %s (%s)\", tmp_path, tostring(err))\
    end\
    local ok, werr = f:write(decoded)\
    f:close()\
    if not ok then\
        os.remove(tmp_path)\
        return nil, string.format(\"failed to write temp file: %s\", tostring(werr))\
    end\
    return tmp_path, nil\
end\
\
local function load_base64_file(path)\
    local f, err = io.open(path, \"rb\")\
    if not f then\
        return nil, string.format(\"failed to open base64 file: %s (%s)\", tostring(path), tostring(err))\
    end\
    local content = f:read(\"*a\")\
    f:close()\
    if not content or #content == 0 then\
        return nil, \"empty base64 file\"\
    end\
    return write_base64_to_tmp(content)\
end\
\
-- Show CIDR rule file version\
local function get_version()\
    if appcidr.ver ~= \"0.0.0.0\" then\
        return appcidr.ver\
    end\
    local cidr_file = appcidr.cidr_rule_file or appcidr.save_file\
    if not cidr_file then\
        return appcidr.ver\
    end\
    local f = io.open(cidr_file, \"rb\")\
    if not f then\
        return appcidr.ver\
    end\
    local header = f:read(20)\
    f:close()\
    if not header or #header < 20 then\
        return appcidr.ver\
    end\
    local b1, b2, b3, b4 = string.byte(header, 17, 20)\
    if not b1 then\
        return appcidr.ver\
    end\
    return string.format(\"%d.%d.%d.%d\", b1, b2, b3, b4)\
end\
\
local function file_exists(path)\
    local f = io.open(path, \"rb\")\
    if f then\
        f:close()\
        return true\
    end\
    return false\
end\
\
-- Load CIDR signature library\
local function cidr_load(t)\
\
    local load_path = nil\
    local save_path = appcidr.save_file\
    local is_temp = false\
\
    if t and type(t.content) == \"string\" then\
        local tmp_path, err = write_base64_to_tmp(t.content)\
        if err then\
            return \"Failed to decode/save CIDR content: \" .. err\
        end\
        load_path = tmp_path\
        is_temp = true\
    elseif t and type(t.base64_file) == \"string\" then\
        local tmp_path, err = load_base64_file(t.base64_file)\
        if err then\
            return \"Failed to decode/save CIDR content: \" .. err\
        end\
        load_path = tmp_path\
        is_temp = true\
    elseif t and type(t.file) == \"string\" then\
        load_path = t.file\
    else\
        local local_path = \"./\" .. appcidr.filename\
        if file_exists(save_path) then\
            load_path = save_path\
        elseif file_exists(local_path) then\
            load_path = local_path\
        else\
            return \"no CIDR file found to load\"\
        end\
    end\
\
    if not load_path or load_path == \"\" then\
        return \"invalid CIDR file path\"\
    end\
\
    local err, ver = cidr.load(load_path, save_path, appcidr.magic, appcidr.key)\
    if is_temp then\
        os.remove(load_path)\
    end\
    if err then\
        log.error(string.format(\"Failed to load CIDR file: %s\", tostring(err)))\
        return err\
    end\
\
    appcidr.cidr_rule_file = save_path\
    appcidr.ver = ver or appcidr.ver or \"\"\
\
    return nil\
end\
\
-- Add single CIDR rule\
local function add_rule(t)\
    if type(t) ~= \"table\" then\
        return \"invalid parameters\"\
    end\
\
    local rule_id = t.rule_id\
    local app_id = t.app_id\
    local cidr_str = t.cidr\
\
    if not rule_id or not app_id or not cidr_str then\
        return \"missing required parameters: app_id, rule_id, cidr\"\
    end\
\
    local ip, prefix = cidr_str:match(\"^([^/]+)/(%d+)$\")\
    if not ip or not prefix then\
        return \"invalid CIDR format: \" .. tostring(cidr_str)\
    end\
    local prefix_len = tonumber(prefix)\
    if not prefix_len or prefix_len < 16 or prefix_len > 64 then\
        return \"invalid prefix length: \" .. tostring(prefix)\
    end\
\
    -- Send to kernel\
    local rule_table = {{\
        rule_id = rule_id,\
        app_id = app_id,\
        ip = ip,\
        prefix_len = prefix_len\
    }}\
\
    local ok, err = cidr.add_rule(appcidr.cidr_rule_file, rule_table, appcidr.magic, appcidr.key)\
    if not ok then\
        return \"Failed to add rule: \" .. tostring(err)\
    end\
\
    log.info(string.format(\"Added CIDR rule: rule_id=%d, app_id=%d\", rule_id, app_id))\
    return nil\
end\
\
-- Delete single CIDR rule\
local function del_rule(t)\
    if type(t) ~= \"table\" then\
        return \"invalid parameters\"\
    end\
\
    local rule_id = t.rule_id\
    local app_id = t.app_id\
\
    if not rule_id and not app_id then\
        return \"missing required parameters: rule_id or app_id\"\
    end\
    if rule_id and app_id then\
        return \"invalid parameters: only one of rule_id or app_id is allowed\"\
    end\
\
    if not appcidr.cidr_rule_file or appcidr.cidr_rule_file == \"\" then\
        return \"no cidr file loaded\"\
    end\
\
    local rule_table = {{\
        rule_id = rule_id,\
        app_id = app_id\
    }}\
\
    local ok, err = cidr.del_rule(appcidr.cidr_rule_file, rule_table, appcidr.magic, appcidr.key)\
    if not ok then\
        return \"Failed to delete rule: \" .. tostring(err)\
    end\
\
    log.info(string.format(\"Deleted CIDR rule: rule_id=%s\", tostring(rule_id)))\
    return nil\
end\
\
local function query_rule(t)\
    if type(t) ~= \"table\" then\
        local err = \"invalid parameters\"\
        log.error(err)\
        return err\
    end\
    if not t.rule_id and not t.app_id and not t.ip and not t.cidr then\
        local err = \"missing query parameters\"\
        log.error(err)\
        return err\
    end\
    if t.cidr and not t.cidr:match(\"/%d+$\") then\
        local err = \"invalid CIDR format: missing prefix_len\"\
        log.error(err)\
        return err\
    end\
    if t.cidr and not t.ip then\
        local parsed_ip, parsed_prefix_len = t.cidr:match(\"^([^/]+)/(%d+)$\")\
        if not parsed_ip or not parsed_prefix_len then\
            local err = \"invalid CIDR format: \" .. tostring(t.cidr)\
            log.error(err)\
            return err\
        end\
        t.ip = parsed_ip\
        t.prefix_len = tonumber(parsed_prefix_len)\
    end\
\
    local result, err = cidr.query(t)\
    if not result then\
        log.error(string.format(\"Failed to query CIDR rules: %s\", tostring(err)))\
        return tostring(err)\
    end\
    return result\
end\
\
-- Flush all CIDR rules\
local function flush_rules()\
    local ok, err = cidr.flush()\
    if not ok then\
        log.error(string.format(\"Failed to flush rules: %s\", tostring(err)))\
        return \"Failed to flush rules: \" .. tostring(err)\
    end\
    log.info(\"Flushed all CIDR rules\")\
    appcidr.cidr_rule_file = nil\
    appcidr.ver = \"0.0.0.0\"\
    return nil\
end\
\
-- Get statistics (without hit_rules, but with hit counts)\
local function get_stats()\
    if not cidr_enable then\
        return \"appcidr module not enabled\"\
    end\
\
    local res, err = cidr.get_stats()\
    if not res then\
        log.error(string.format(\"Failed to request CIDR stats: %s\", err))\
        return err\
    end\
    local stats = {\
        memory = res.memory,\
        top_array_memory = res.top_array_memory,\
        trie_node_memory = res.trie_node_memory,\
        total_rules = res.total_rules,\
        ipv4_rules = res.ipv4_rules,\
        ipv6_rules = res.ipv6_rules,\
        max_trie_depth = res.max_trie_depth,\
        total_trie_nodes = res.total_trie_nodes,\
        top_array_used = res.top_array_used,\
        total_hits = res.total_hits or 0,\
        ipv4_hits = res.ipv4_hits or 0,\
        ipv6_hits = res.ipv6_hits or 0,\
        total_packets = res.total_packets or 0,\
        match_packets = res.match_packets or 0\
    }\
    return {\
        stats = stats,\
        ver = appcidr.ver,\
        rule_file = appcidr.cidr_rule_file\
    }\
end\
\
local function set_config(t)\
    if type(t) ~= \"table\" then\
        return \"invalid parameters\"\
    end\
    local ok, err = cidr.set_config(t)\
    if not ok then\
        log.error(string.format(\"Failed to set CIDR config: %s\", tostring(err)))\
        return err\
    end\
    return nil\
end\
\
local function get_config()\
    local res, err = cidr.get_config()\
    if not res then\
        log.error(string.format(\"Failed to get CIDR config: %s\", tostring(err)))\
        return err\
    end\
    return res\
end\
-- Get hit rules with hit statistics\
local function get_hit_rules()\
    local res, err = cidr.hit_rules()\
    if not res then\
        log.error(string.format(\"Failed to request CIDR stats: %s\", err))\
        return err\
    end\
\
    return {\
        hit_rules = res.hit_rules or {},\
        total_hit_rules = res.total_hit_rules or 0,\
        returned_hit_rules = res.returned_hit_rules or 0,\
        ipv4_hit_rules = res.ipv4_hit_rules or 0,\
        ipv6_hit_rules = res.ipv6_hit_rules or 0,\
        ver = appcidr.ver,\
        rule_file = appcidr.cidr_rule_file\
    }\
end\
\
-- Read configuration\
local function read()\
    return {\
        enabled = appcidr.enabled,\
        config = get_config()\
    }\
end\
\
-- Write configuration\
local function write(msg)\
    if type(msg) ~= \"table\" then\
        return\
    end\
\
    if type(msg.enabled) == \"boolean\" and msg.enabled ~= appcidr.enabled then\
        appcidr.enabled = msg.enabled\
        if appcidr.enabled then\
            cidr_load()\
            kernel.set_engine(CENUM.ENGINE_TYPE_CIDR_POLICY, 1)\
