local mystring = require(\"mystring\")\
local myutil = require(\"myutil\")\
local policy_com = require(\"ct.policy\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local pktpolicy = require(\"pktpolicy\")\
\
local appctrl = {\
    subtype = \"appctrl\",\
    timer_name = 'appctrl_upload',\
    help = \"set appctrl and send info to server\",\
    pcnt = 0,\
    max_pcnt = 20,\
    list_max_cnt = 5000,\
    max_appid_cnt = 100,\
    addr = \"message.189cube.com:9890\",\
    policies = { -- index\
        -- index, string\
        -- mac\
        -- appid, appid list\
        -- once\
        -- scnt\
        -- time\
            -- {weekdays = \"1,2,3,4,5\", time = \"00:00-19:00,21:00-24:00\"}\
        -- action_type, string \"0xff12\"\
        -- times\
            -- {weekdays = {[1] = true, [2] = true}, time = {{start_hour = 0, end_hour = 0}}, windex = 0, tindex = 0, lasttime = 0}\
        -- action\
        -- dscp_value\
        -- push_period\
        -- ip_port\
        -- ports\
        -- direct\
    },\
    all_len = 0,\
    all_cnt = 0,\
    disable = {}, -- policy index, when hit and once is true, {\"1\" = true, \"2\" = true}\
    push_enable = false,\
}\
\
local function appconf_del(msg)\
    local indexes = msg.index or {}\
    if type(indexes) ~= \"table\" then\
        return \"invalid index\"\
    end\
    local _, err_info = lcmd_run({subtype = \"pktpolicy\", action = \"del\", index = indexes, ftype = appctrl.subtype})\
    if err_info then return err_info end\
    for _, index in pairs(indexes) do\
        if appctrl.policies[index] and myutil.is_numeric_string(index) then\
            appctrl.policies[index] = nil\
            appctrl.pcnt = appctrl.pcnt - 1\
        else\
            log.warn(\"No such index to delete\")\
        end\
    end\
end\
\
local function appconf_add(t)\
    if type(t.policies) ~= \"table\" then\
        return \"must add table for appctrl conf\"\
    end\
    -- check input\
    for _, policy in pairs(t.policies) do\
        local pass, err_msg = policy_com.check_app_input(policy, appctrl.list_max_cnt, appctrl.max_appid_cnt)\
        if not pass then\
            return err_msg or \"\"\
        end\
\
        -- check action_type\
        if not policy.action_type or not tonumber(policy.action_type) or not myutil.is_numeric_string(tostring(tonumber(policy.action_type))) then\
            return \"The field action_type format does not meet the requirements.\"\
        end\
\
        -- check index\
        if not pktpolicy.check_index(policy.index, appctrl.subtype) then\
            return \"index is used in other policy\"\
        end\
\
        -- add new policy\
        if not appctrl.policies[policy.index] and appctrl.pcnt >= appctrl.max_pcnt then\
            return \"can not exceed the limit count \"..tostring(appctrl.max_pcnt)\
        end\
    end\
    -- add policy\
    for _, policy in pairs(t.policies) do\
        appconf_del({index = {policy.index}})\
        local ok, msg = lcmd_run({\
            subtype = \"pktpolicy\",\
            action = \"add\",\
            policies = {\
                {\
                    index = policy.index,\
                    appid = policy.appid,\
                    mac = policy.mac,\
                    time = policy.time,\
                    action = policy.action,\
                    dscp_value = policy.dscp_value,\
                    ip_port = policy.ip_port,\
                    ports = policy.ports,\
                    direct = policy.direct,\
                    type = appctrl.subtype,\
                }\
            }\
        })\
        if not ok or type(msg) ~= \"table\" then\
