    end\
    return {msg = \"add success in appctrl\"}\
end\
\
local function stat()\
    local res = {}\
    for k, v in pairs(appctrl.policies) do\
        res[k] = {\
            index = v.index,\
            appid = v.appid,\
            mac = v.mac,\
            time = v.time,\
            -- times = v.times,            -- time after parsing\
