function appmlp.postinit()\
    appmlp.index = actor.subscribe(\"PKTPOLICY\", appmlp_get)\
    timer.mod(appmlp.timer_name, appmlp.period, 0, all_send)\
end\
\
function appmlp.finish()\
    if appmlp.index then actor.unsubscribe(\"PKTPOLICY\", appmlp.index) end\
    timer.del(appmlp.timer_name)\
end\
\
actor.action_set(appmlp.subtype, \"write\", write, [[configure appmlp, {action_type = string, addr = string, period = number, policies = list, real_time = boolean}]])\
actor.action_set(appmlp.subtype, \"read\", read, \"{addr, action_type, period, real_time, stat = {pcnt, max_pcnt, max_appid_cnt, all_len, all_cnt, cache_cnt, max_cache_cnt}}\")\
actor.action_set(appmlp.subtype, \"add\", appconf_add, [[{policies = [{index = string, appid = list, mac = string, time = list, action = continue/fin/drop/dscp, dscp_value = number, ip_port = list, ports = list, direct = string}]}]])\
actor.action_set(appmlp.subtype, \"del\", appconf_del, [[del policy, {index = [\"1\",\"2\"...]}]])\
actor.action_set(appmlp.subtype, \"stat\", stat, \"{index:{index:string, appid:list, mac:string, time:list, action:continue/fin/drop/dscp, dscp_value:number}}\")\
actor.action_set(appmlp.subtype, \"flush\", function() for index, _ in pairs(appmlp.policies) do appconf_del({index = {index}}) end end, \"appmlp conf flush\")\
actor.action_set(appmlp.subtype, \"show_conf_save\", function () return {subtype = appmlp.subtype, action = \"write\", policies = appmlp.policies, addr = appmlp.addr, action_type = appmlp.action_type} end, \"show appmlp save conf msg\")\
\
return appmlp\
"
, '@'.."./service/appmlp.lua" ) )

package.preload[ "appqos" ] = assert( (loadstring or load)(
"local cjson = require(\"cjson\")\
local actor = require(\"luactor\")\
local myip = require(\"myip\")\
local mystring = require(\"mystring\")\
local myutil = require(\"myutil\")\
local policy_com = require(\"ct.policy\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local pktpolicy = require(\"pktpolicy\")\
\
local appqos = {\
    subtype = \"appqos\",\
    help = \"set appqos for safeguard app\",\
    timer_name = \"appqos_check\",\
    pcnt = 0,\
    list_max_cnt = 5000,\
    max_pcnt = 20,\
    max_appid_cnt = 100,\
    enable = true,\
    ac_period = 600,\
    cf_period = 1200,\
    mode = \"full\",  -- \"full\" or \"normal\"\
    policies = { -- index(string) as keyword\
        -- {\
            -- index, string\
            -- appid, appid list\
            -- mac\
            -- macs, mac list\
            -- mac_last_time, mac: last_time\
            -- app_last_time, app: last_time\
            -- dscp_value\
            -- rltapp, boolean default true\
        -- }\
    },\
    his_policies = nil, -- display when module is not enabled\
}\
\
local function appconf_del(msg)\
    local indexes = msg.index or {}\
    if type(indexes) ~= \"table\" then\
        return \"invalid index\"\
    end\
    local _, err_info = lcmd_run({subtype = \"pktpolicy\", action = \"del\", index = indexes, ftype = appqos.subtype})\
    if err_info then return err_info end\
    for _, index in pairs(indexes) do\
        if appqos.policies[index] and myutil.is_numeric_string(index) then\
            appqos.policies[index] = nil\
            appqos.pcnt = appqos.pcnt - 1\
            lcmd_run{type = \"sys\", action = \"save_conf_change\"}\
        else\
            log.warn(\"No such index to delete\")\
        end\
    end\
end\
\
local function appconf_add(t)\
    if not appqos.enable then\
        return \"appqos module is not enabled\"\
    end\
    if type(t.policies) ~= \"table\" then\
        return \"must add table for appqos conf\"\
    end\
    -- check input\
    for _, policy in pairs(t.policies) do\
        policy[\"action\"] = \"dscp\"\
        local pass, err_msg = policy_com.check_app_input(policy, appqos.list_max_cnt, appqos.max_appid_cnt)\
        if not pass then\
            return err_msg or \"\"\
        end\
\
        -- check index\
        if not pktpolicy.check_index(policy.index, appqos.subtype) then\
            return \"index is used in other policy\"\
        end\
\
        -- check appid\
        if #policy.appid <= 0 then\
            return \"appid cannot be an empty array\"\
        else\
            for _, id in ipairs(policy.appid) do\
                if not pktpolicy.check_appid(id, appqos.subtype) then\
                    return \"appid \"..id..\" is used in other policy\"\
                end\
                if not policy.mac or policy.mac == \"\" then  -- 仅当动态终端保障模式时，检查appid是否与自身策略冲突\
                    for index, one in pairs(appqos.policies) do\
                        if index ~= policy.index and myutil.inarr(id, one.appid) then\
                            return \"appid \"..id..\" is used in appqos policy \".. one.index\
                        end\
                    end\
                end\
            end\
        end\
\
        -- add new policy\
        if not appqos.policies[policy.index] and appqos.pcnt >= appqos.max_pcnt then\
            return \"can not exceed the limit count \"..tostring(appqos.max_pcnt)\
        end\
    end\
    -- add policy\
    for _, policy in pairs(t.policies) do\
        appconf_del({index = {policy.index}})\
        local s = {\
            index = policy.index,\
            appid = policy.appid,\
            mac = policy.mac or \"\",\
            macs = {},\
            mac_last_time = {},\
            app_last_time = {},\
            action = policy.action,\
            dscp_value = policy.dscp_value,\
            rltapp = policy.rltapp or true,\
        }\
        appqos.policies[policy.index] = s\
        appqos.pcnt = appqos.pcnt + 1\
        lcmd_run{type = \"sys\", action = \"save_conf_change\"}\
    end\
    return {msg = \"add success in appqos\"}\
end\
\
local function appconf_flush()\
    for index, _ in pairs(appqos.policies) do\
        appconf_del({index = {index}})\
    end\
end\
\
local function write(t)\
    if type(t.enable) == \"boolean\" and t.enable ~= appqos.enable then\
        appqos.enable = t.enable\
        if not appqos.enable then\
            appqos.his_policies = {}\
            for index, policy in pairs(appqos.policies) do\
                appqos.his_policies[index] = policy\
            end\
            appconf_flush()\
        else\
            appconf_add({policies = appqos.his_policies})\
            appqos.his_policies = nil\
        end\
    end\
    if type(t.mode) == \"string\" and t.mode ~= appqos.mode then\
        if t.mode == \"full\" or t.mode == \"normal\" then\
            appqos.mode = t.mode\
        end\
    end\
    if type(t.ac_period) == \"number\" and t.ac_period ~= appqos.ac_period  then\
        appqos.ac_period = t.ac_period\
    end\
    if type(t.cf_period) == \"number\" and t.cf_period ~= appqos.cf_period  then\
        appqos.cf_period = t.cf_period\
    end\
    if type(t.policies) == \"table\" then\
        appconf_add({policies = t.policies})\
    end\
end\
\
local function read()\
    return {\
        pcnt = appqos.pcnt,\
        max_pcnt = appqos.max_pcnt,\
        max_appid_cnt = appqos.max_appid_cnt,\
        enable = appqos.enable,\
        mode = appqos.mode,\
        ac_period = appqos.ac_period,\
        cf_period = appqos.cf_period,\
    }\
end\
\
local function stat(t)\
    local res = {}\
    local acc_dev_cnt = 0\
    for k, v in pairs(appqos.policies) do\
        res[k] = {\
            index = v.index,\
            appid = v.appid,\
            mac = v.mac,\
            macs = v.macs,\
            mac_last_time = t.all and v.mac_last_time,\
            app_last_time = t.all and v.app_last_time,\
            dscp_value = v.dscp_value,\
            rltapp = v.rltapp,\
        }\
        acc_dev_cnt = acc_dev_cnt + #v.macs\
    end\
    for k, v in pairs(appqos.his_policies or {}) do\
        res[k] = {\
            index = v.index,\
            appid = v.appid,\
            mac = v.mac,\
            macs = v.macs,\
            mac_last_time = t.all and v.mac_last_time,\
            app_last_time = t.all and v.app_last_time,\
            dscp_value = v.dscp_value,\
            rltapp = v.rltapp,\
            enable = t.all and appqos.enable,\
        }\
        acc_dev_cnt = acc_dev_cnt + #v.macs\
    end\
    res[\"acc_dev_cnt\"] = acc_dev_cnt\
    return res\
end\
\
local function apprule_get(msg)\
    if not appqos.enable or type(msg) ~= \"table\" or type(msg.apprule_table) ~= \"table\" then\
        return\
    end\
    local info = msg.apprule_table\
    local mac = myip.mac_fmt(info.mac)\
    for _, policy in pairs(appqos.policies) do\
        if type(policy.appid) == \"table\" and myutil.inarr(info.appid, policy.appid) then\
            if mac == myip.mac_fmt(policy.mac) then\
                policy.app_last_time[info.appid] = os.time()\
            else\
                policy.mac_last_time[mac] = os.time()\
            end\
        end\
    end\
end\
\
local function freeze(index, mac)\
    local policy = appqos.policies[index]\
    if policy then\
        for id, m in ipairs(policy.macs) do\
            if m == mac then\
                table.remove(policy.macs, id)\
                return true\
            end\
        end\
    end\
    return false\
end\
\
local function policy_check()\
    if not appqos.enable then\
        return\
    end\
    local now_time = os.time()\
    for index, policy in pairs(appqos.policies) do\
        local update = false\
        if policy.mac and policy.mac ~= \"\" then     -- 指定终端应用保障\
            for appid, last_time in pairs(policy.app_last_time) do\
                if #policy.macs == 0 then\
                    table.insert(policy.macs, policy.mac)\
                    update = true\
                elseif now_time - last_time >= appqos.ac_period + appqos.cf_period then\
                    policy.app_last_time[appid] = nil\
                    if not next(policy.app_last_time) then\
                        table.remove(policy.macs, 1)\
                        update = true\
                    end\
                end\
            end\
        else        -- 动态终端应用保障\
            for mac, last_time in pairs(policy.mac_last_time) do\
                if not myutil.inarr(mac, policy.macs) then\
                    table.insert(policy.macs, mac)\
                    update = true\
                elseif now_time - last_time >= appqos.ac_period + appqos.cf_period then\
                    policy.mac_last_time[mac] = nil\
                    if freeze(index, mac) then\
                        update = true\
                    end\
                end\
            end\
        end\
        if update then\
            if #policy.macs > 0 then\
                local macs = {}\
                for _, m in ipairs(policy.macs) do\
                    table.insert(macs, m)\
                end\
                if appqos.mode == \"full\" then\
                    lcmd_run({ subtype = \"pktpolicy\", action = \"add\", policies = { { index = policy.index, appid = {}, macs = macs, action = policy.action, dscp_value = policy.dscp_value, type = appqos.subtype } } })\
                elseif appqos.mode == \"normal\" then\
                    -- todo\
                end\
            else\
                lcmd_run({subtype = \"pktpolicy\", action = \"del\", index = {index}, ftype = appqos.subtype})\
            end\
        end\
    end\
end\
\
local function check_index(t)\
    local policies = appqos.his_policies and appqos.his_policies or appqos.policies\
    if type(t.index) == \"string\" and policies[t.index] then\
        return false\
    end\
    return true\
end\
\
local function check_appid(t)\
    for _, policy in pairs(appqos.his_policies and appqos.his_policies or appqos.policies) do\
        if tonumber(t.appid) and myutil.inarr(t.appid, policy.appid) then\
            return false\
        end\
    end\
    return true\
end\
\
function appqos.postinit()\
    appqos.index = actor.subscribe(\"APPRULE\", apprule_get)\
    timer.mod(appqos.timer_name, 5, 0, policy_check)\
end\
\
function appqos.finish()\
    if appqos.index then actor.unsubscribe(\"APPRULE\", appqos.index) end\
    timer.del(appqos.timer_name)\
end\
\
actor.action_set(appqos.subtype, \"write\", write, [[configure appqos, {ac_period = number, cf_period = number, enable = boolean, mode = string, policies = list}]])\
actor.action_set(appqos.subtype, \"read\", read, [[read appqos configure]])\
actor.action_set(appqos.subtype, \"stat\", stat, \"{index:{index:string, appid:list, mac:string, macs:list, dscp_value:number, rltapp:boolean}}\")\
actor.action_set(appqos.subtype, \"add\", appconf_add, [[{policies = [{index = string, dscp_value = number, mac = string, appid = list, rltapp = boolean}]}]])\
actor.action_set(appqos.subtype, \"del\", appconf_del, [[del policy, {index = [\"1\",\"2\"...]}]])\
actor.action_set(appqos.subtype, \"flush\", appconf_flush, \"appqos conf flush\")\
actor.action_set(appqos.subtype, \"check_index\", check_index, \"appqos conf flush\")\
actor.action_set(appqos.subtype, \"check_appid\", check_appid, \"appqos conf flush\")\
actor.action_set(appqos.subtype, \"show_conf_save\", function () return {subtype = appqos.subtype, action = \"write\", policies = appqos.policies} end, \"show appqos save conf msg\")\
\
return appqos\
"
, '@'.."./service/appqos.lua" ) )

package.preload[ "apprule" ] = assert( (loadstring or load)(
"local actor = require \"luactor\"\
local cjson = require \"cjson\"\
local log = require\"log\"\
local myip = require\"myip\"\
local mystring = require\"mystring\"\
local kernel = require\"c.kernel\"\
local timer = require\"timer\"\
local mime = require\"mime\"\
local ctime = require\"c.time\"\
\
local apprule = {\
    type = \"apprule\",\
    subtype = \"apprule\",\
    help = \"app rule configure\",\
    period = 5,\
    timer_name = \"apprule_get\",\
    max_rule_cnt = 10000,\
    rule_clean_cnt = 1000,\
    min_ttl = 60,  -- 最小TTL\
    port_blacklist = {  -- 端口黑名单 {port = hit_cnt}\
        [53] = 0,\
    },\
    appid_blacklist = {  -- appid黑名单 {appid = hit_cnt}\
        [1660] = 0,\
    },\
    rules = {\
        -- dip:dport\
            -- appid\
            -- ruleid\
            -- hit_cnt\
            -- lasttime\
            -- maxttl, only for dns\
    },\
    rule_cnt = 0,\
    ex_del_cnt = 0,\
    ttl_clean_cnt = 0,  -- TTL清理统计\
    index = 0,\
}\
\
local function kernel_send(ktype, rule)\
    local ip, port, appid, ruleid = rule.ip, rule.port or 0, rule.appid, rule.ruleid\
    local port_mask = 0\
\
    if port ~= 0 then\
        port_mask = 0xffff\
    end\
    local buf = string.pack(\"=IIIc16HH\", 32, ruleid, appid, ip, port, port_mask)\
    kernel.send(ktype, buf)\
end\
\
local function del(t)\
    local key, ruleid = t.key, t.ruleid\
    local keys = {}\
    if key and apprule.rules[key] then\
        keys = {key}\
        apprule.rules[key] = nil\
    elseif ruleid then\
        for k,v in pairs(apprule.rules) do\
            if v.ruleid == ruleid then\
                apprule.rules[k] = nil\
                table.insert(keys, k)\
            end\
        end\
    end\
    for _,v in pairs(keys) do\
        if t.subtype then\
            apprule.ex_del_cnt = apprule.ex_del_cnt + 1\
        end\
        apprule.rule_cnt = apprule.rule_cnt - 1 \
        local ip, port = string.match(v, \"^(.+):(%d+)$\")\
        kernel_send(CENUM.MEMSHR_APP_RULE_DEL, {ip = myip.inet_aton(ip, true), port = tonumber(port or 0), appid = 0, ruleid = 0})\
    end\
    return\
end\
\
local function clean_rules()\
    local info = {}\
    for k,v in pairs(apprule.rules) do\
        table.insert(info, {hit_cnt = v.hit_cnt, key = k})\
    end\
    table.sort(info, function (t1,t2) return t1.hit_cnt < t2.hit_cnt end)\
    for i=1,apprule.rule_clean_cnt do\
        if info[i] then\
            local key = info[i].key\
            del({key = key})\
        end\
    end\
end\
\
local function is_in_blacklist(value, blacklist)\
    if value == 0 or value == nil then\
        return false\
    end\
    local hit = blacklist[value]\
    if type(hit) == \"number\" then\
        blacklist[value] = hit + 1\
        return true\
    end\
    return false\
end\
\
local function add(t)\
    local ip, port, ruleid, appid = t.ip or \"0.0.0.0\", t.port or 0, t.ruleid or 0, t.appid or 0\
    if is_in_blacklist(port, apprule.port_blacklist) then\
        return\
    end\
    if is_in_blacklist(appid, apprule.appid_blacklist) then\
        return\
    end\
    local key = string.format(\"%s:%d\", ip, port)\
    local uptime = ctime.get_uptime()\
    local rule = apprule.rules[key]\
    local ttl = tonumber(t.maxttl)\
    if ttl and ttl < apprule.min_ttl then\
        ttl = apprule.min_ttl\
    end\
    if rule then\
        if rule.ruleid ~= ruleid or rule.appid ~= appid then\
            del({key = key})\
        else\
            rule.lasttime = uptime\
            rule.maxttl = ttl\
            return\
        end\
    else\
        if apprule.rule_cnt >= apprule.max_rule_cnt then\
            clean_rules()\
        end\
    end\
    apprule.rules[key] = {ruleid = ruleid, appid = appid, hit_cnt = 0, lasttime = uptime, maxttl = ttl}\
    apprule.rule_cnt = apprule.rule_cnt + 1 \
    kernel_send(CENUM.MEMSHR_APP_RULE_ADD, {ip = myip.inet_aton(ip, true), port = tonumber(port), appid = appid, ruleid = ruleid})\
end\
\
local function flush(t)\
    -- make sure there are no cached IP rules in xapp before flush\
    lcmd_run({subtype = \"xapp\", action = \"rule_set\"})\
    apprule.rules, apprule.index, apprule.rule_cnt = {}, 0, 0\
    kernel.send(CENUM.MEMSHR_APP_RULE_FLUSH, \"\")\
end\
\
local function apprule_ttl_clean()\
    local uptime = ctime.get_uptime()\
    for key, rule in pairs(apprule.rules) do\
        if rule.maxttl and rule.maxttl > 0 and uptime - rule.lasttime >= rule.maxttl then\
            del({key = key})\
            apprule.ttl_clean_cnt = apprule.ttl_clean_cnt + 1\
        end\
    end\
end\
\
local function clean_blacklist_rules()\
    local to_del = {}\
    for key, rule in pairs(apprule.rules) do\
        local _, port = string.match(key, \"^(.+):(%d+)$\")\
        port = tonumber(port)\
        if (port and apprule.port_blacklist[port]) or (rule.appid and apprule.appid_blacklist[rule.appid]) then\
            table.insert(to_del, key)\
        end\
    end\
    for _, key in ipairs(to_del) do\
        del({key = key})\
    end\
    return #to_del\
end\
\
local function apprule_get_one(sbytes, pos, len)\
    local all_len, ruleid, appid, rip, ip, rport, port, mac, proto, _, next_post = string.unpack('=IIIc16c16HHc6BB', sbytes, pos)\
    local data\
    if all_len > 56 then\
        data = string.unpack('=c'.. (all_len - 56), sbytes, next_post)\
    end\
    mac = myip.mac_ntoa(mac)\
    ip = myip.inet_ntoa(ip)\
    if appid > CENUM.MAX_BASE_APPID then\
        rip = myip.inet_ntoa(rip)\
        local key = string.format(\"%s:%d\", rip, rport)\
        local rule = apprule.rules[key]\
        if rule then\
            rule.hit_cnt = rule.hit_cnt + 1\
        end\
    else\
        rip = \"\"\
        data = mime.b64(data)\
    end\
\
    local appinfo_table = {\
        mac = mac,\
        ip = ip,\
        port = port,\
        proto = proto,\
        appid = appid,\
        ruleid = ruleid,\
        data = data\
    }\
\
    actor.publish({msgtype = \"APPRULE\", apprule_table = appinfo_table})\
\
    return all_len\
end\
\
local function apprule_get(sbytes)\
    local len, used_len = sbytes:len(), 0\
    while used_len < len do\
        local one_size = apprule_get_one(sbytes, used_len + 1, len)\
        used_len = used_len + one_size\
    end\
    assert(used_len == len)\
    return len\
end\
\
local function merge_blacklist(key, arr)\
    local old_bl = apprule[key]\
    apprule[key] = {}\
    for _, v in ipairs(arr) do\
        local n = tonumber(v)\
        if n then\
            apprule[key][n] = old_bl[n] or 0\
        end\
    end\
end\
\
local function write(t)\
    if t.period and tonumber(t.period) ~= apprule.period then\
        apprule.period = tonumber(t.period)\
        timer.mod(apprule.timer_name, apprule.period, 0, function () kernel.call(CENUM.MEMSHR_APPINFO, \"\", apprule_get) end)\
    end\
    if type(t.max_rule_cnt) == \"number\" then\
        apprule.max_rule_cnt = t.max_rule_cnt\
    end\
    if type(t.rule_clean_cnt) == \"number\" then\
        apprule.rule_clean_cnt = t.rule_clean_cnt\
    end\
    if type(t.min_ttl) == \"number\" and t.min_ttl ~= apprule.min_ttl then\
        apprule.min_ttl = t.min_ttl\
    end\
    if type(t.port_blacklist) == \"table\" then\
        merge_blacklist(\"port_blacklist\", t.port_blacklist)\
    end\
    if type(t.appid_blacklist) == \"table\" then\
        merge_blacklist(\"appid_blacklist\", t.appid_blacklist)\
    end\
end\
\
function apprule.preinit()\
    -- if kernel module not reload, it must clean first\
    kernel.send(CENUM.MEMSHR_APP_RULE_FLUSH, \"\")\
    kernel.send(CENUM.MEMSHR_APPINFO_FLUSH, \"\")\
end\
\
function apprule.postinit()\
    timer.mod(apprule.timer_name, apprule.period, 0, function () kernel.call(CENUM.MEMSHR_APPINFO, \"\", apprule_get) end)\
    timer.mod(\"apprule_ttl_clean\", 300, 0, apprule_ttl_clean)  -- 5分钟周期的TTL清理定时器\
end\
\
actor.action_set(apprule.subtype, \"stat\", function () return {rule_cnt = apprule.rule_cnt, ex_del_cnt = apprule.ex_del_cnt, ttl_clean_cnt = apprule.ttl_clean_cnt, port_blacklist = apprule.port_blacklist, appid_blacklist = apprule.appid_blacklist} end, \"show apprule stat\")\
