local function appsig_upstat(action, stype)\
    local key, sigtype = nil, stype or \"\"\
    if action == \"add\" then\
        appsig_bin.add_cnt = appsig_bin.add_cnt + 1\
        key = stype..\"_addcnt\"\
    elseif action == \"del\" then\
        appsig_bin.del_cnt = appsig_bin.del_cnt + 1\
        key = stype..\"_delcnt\"\
    end\
\
    if key then\
        appsig_bin[key] = (appsig_bin[key] or 0) + 1\
    end\
end\
\
local function kernel_send_port(ktype, table)\
    for value,t in pairs(table) do\
        local proto, port = mystring.split(value, \"_\")\
        local buf = string.pack(\"=IIIHBB\", 16, t.ruleid or 0, t.appid or 0, tonumber(port) or 0, tonumber(proto) or 0, 0)\
        -- log.error(\"port add\", tonumber(port), port, mystring.data2hex(buf,\":\"))\
        kernel.send(ktype, buf)\
    end\
end\
\
local function kernel_send_payload(ktype, table)\
    for value,t in pairs(table) do\
        local len, proto, port, offset, payload, nexpost = 0, 0, 0, 0, \"\", 0\
        if value and #value > 13 then\
            local hexstr,_ = string.gsub(value, \"_\", \"\")\
            local data = mystring.hex2data(hexstr)\
            proto, port, offset, nexpost = string.unpack(\">BHH\", data)\
            payload = string.sub(data, nexpost)\
            len = #payload\
        end\
        local buf = string.pack(\"=IIIHHBBHc\"..len, 20 + len, t.ruleid or 0, t.appid or 0, offset, len, tonumber(proto) or 0, 0, tonumber(port) or 0, payload)\
        kernel.send(ktype, buf)\
    end\
end\
\
local function deal_file(filename, byte)\
    local f = io.open(filename, \"w\")\
    if f then\
        f:write(byte)\
        f:close()\
    end\
end\
\
local function load_sigfile(filename, show_ver)\
    if type(filename) ~= \"string\" then\
        return \"wrong sigfile path \"..tostring(filename)\
    end\
    local f = io.open(filename, \"r\")\
    if not f then\
        return \"failed to read \"..filename\
    end\
    local byte = f:read(\"a\")\
    f:close()\
    local magic, alllen, zlen, len, nextpos = string.unpack(\">IIII\", byte)\
    if not magic or not alllen or not zlen or not len or not nextpos then\
        return \"failed to load \"..filename\
    end\
    if #byte ~= alllen or magic ~= appsig_bin.magic then\
        return \"wrong sigfile \"..filename..\": magic \"..string.format(\"%X\", magic)..\", alllen \"..tostring(alllen)..\", ziplen \"..tostring(zlen)\
    end\
    local last = myutil.version_ntoa(string.sub(byte, nextpos, nextpos + 3))\
    if show_ver then\
        return last\
    end\
    appsig_bin.ver = last\
    local sigver = myutil.version_ntoa(string.sub(byte, nextpos + 4, nextpos + 7))\
    appsig_bin.coresig_ver = sigver\
    local key = string.pack(\">I\", len)\
    local cipherdata = ccrypto.decrypt(string.sub(byte, nextpos + 8, -1), appsig_bin.key .. key, \"ecb\")\
    cipherdata = string.sub(cipherdata, 1, zlen)\
    local sigstr = ccrypto.unzip(cipherdata, len)\
    if not sigstr or #sigstr ~= len then\
        return \"unzip fail, len \"..tostring(len).. \", unziplen \"..tostring(#(sigstr or \"\"))\
    end\
\
    local tbl = cjson.decode(sigstr)\
    local now = os.time()\
    if type(tbl) == \"table\" and type(tbl.sigs) == \"table\" and type(tbl.appdesc) == \"table\" then\
        for k,v in pairs(tbl.sigs) do\
            appsig_bin.sigs[k] = v\
        end\
        appsig_bin.ruleids, appsig_bin.appdesc = {}, {}\
        for k,v in pairs(tbl.appdesc) do\
            local id = tonumber(k) or 0\
            appsig_bin.appdesc[id] = v\
            table.insert(appsig_bin.ruleids, 1, {id = id, ts = now})\
        end\
    end\
    if appsig_bin.sigs and appsig_bin.sigs.diport and  appsig_bin.sigs.diport.simple then\
        local maxttl = nil\
        local ok, xapp_conf = lcmd_run({subtype = \"xapp\", action = \"read\"})\
        if ok and xapp_conf and type(xapp_conf.maxttl_tab) == \"table\" then\
            maxttl = xapp_conf.maxttl_tab.diport\
        end\
        local simple = appsig_bin.sigs.diport.simple\
        for k,v in pairs(simple) do\
            local desc = appsig_bin.appdesc[v.ruleid] or {}\
            -- for ipv6, if it is ip:port, it must be [ipv6]:port format.\
            local ip, port = myip.split_ipport(k)\
            lcmd_run({subtype = \"apprule\", action = \"add\", ip = ip, port = tonumber(port), ruleid = v.ruleid, appid = desc.appid or 0, maxttl = maxttl})\
        end\
    end\
\
    for k,v in pairs(appsig_bin.sigs) do\
        if k == \"port\" and v.base then\
            -- log.error(\"port add\", cjson.encode(v.base))\
            kernel_send_port(CENUM.MEMSHR_APP_BASEPORT_ADD, v.base)\
        elseif k == \"payload\" and v.base then\
            kernel_send_payload(CENUM.MEMSHR_APP_BASEPAYLOAD_ADD, v.base)\
        end\
    end\
end\
\
local function basesig_load()\
    for k,v in pairs(appsig_bin.sigs) do\
        if k == \"port\" and v.base then\
            kernel_send_port(CENUM.MEMSHR_APP_BASEPORT_ADD, v.base)\
        elseif k == \"payload\" and v.base then\
            kernel_send_payload(CENUM.MEMSHR_APP_BASEPAYLOAD_ADD, v.base)\
        end\
    end\
end\
\
local function appsig_load(t)\
    local err = nil\
    if t.file then\
        if t.show_ver then\
            return load_sigfile(t.file, t.show_ver)\
        end\
        err = load_sigfile(t.file)\
    end\
    if not t.file or err then\
        err = load_sigfile(appsig_bin.sig_file)\
    end\
    if err then\
        log.warn(string.format(\"read %s fail, err is: %s\", t.file or tostring(appsig_bin.sig_file), tostring(err)))\
    end\
end\
\
local function appsig_save(t)\
    if t.timer and appsig_bin.update_sig_cnt <= 0 then\
        return\
    end\
    local sigs = {sigs = appsig_bin.sigs, appdesc = {}}\
    for k,v in pairs(appsig_bin.appdesc) do\
        local ruleid = tostring(k) or \"\"\
        sigs.appdesc[ruleid] = v\
    end\
    local str = cjson.encode(sigs)\
    local len = #str\
\
    local zstr = ccrypto.zip(str, len > 1024 and len or 1024)\
    local key = string.pack(\">I\", len)\
    local last = os.date(\"%y.%m.%d.%H\")\
    local sigver = appsig_bin.coresig_ver\
\
    local cipherdata = ccrypto.encrypt(zstr, appsig_bin.key .. key, \"ecb\")\
    local byte = string.pack(\">IIIIc4c4\", appsig_bin.magic, #cipherdata + 6 * 4, #zstr, len, myutil.version_aton(last), myutil.version_aton(sigver))\
    byte = byte .. cipherdata\
    appsig_bin.update_sig_cnt = 0\
    deal_file(t.file or appsig_bin.sig_file, byte)\
end\
\
local function match_ua(value)\
    if not value or not appsig_bin.ac_ua then\
        return\
    end\
    local simple = appsig_bin.sigs.ua.simple\
\
    -- 使用 Aho-Corasick 自动机进行匹配\
    local matches = appsig_bin.ac_ua:match(value)\
    -- log.error(\"value:                      \"..value)\
    for _, match in ipairs(matches) do\
        -- log.error(\"match.pattern, match.info = \"..match.pattern..\", \"..match.info)\
        if string.find(value, match.info, 1, true) or string.find(\"^\"..value, match.info, 1, true) or string.find(value..\"$\", match.info, 1, true) or string.find(\"^\"..value..\"$\", match.info, 1, true) then\
            if simple[match.info] then\
                simple[match.info].hitcnt = simple[match.info].hitcnt + 1\
                return simple[match.info].ruleid\
            end\
        end\
    end\
end\
\
local function match_by_ac(value, ac_instance, simple_table)\
    if not value or not ac_instance then\
        return\
    end\
    local matches = ac_instance:match(value)\
    local max_match = nil\
    for _, match in ipairs(matches) do\
        if simple_table[match.pattern] then\
            if not max_match or match.info > max_match.info then\
                max_match = match\
            end\
        end\
    end\
    if max_match then\
        local s = simple_table[max_match.pattern]\
        s.hitcnt = s.hitcnt + 1\
        return s.ruleid\
    end\
end\
\
local function match_fuzzy_domain(suffix, value)\
    if not suffix or not value then\
        return\
    end\
    local simple = appsig_bin.sigs.fuzzy_domain.simple or {}\
    if type(simple[suffix]) ~= \"table\" then\
        return\
    end\
    local prefix = string.gsub(value, suffix..\"$\", \"\")\
    for _, tt in pairs(simple[suffix]) do\
        local get = true\
        for _, ss in ipairs(tt.parsed) do\
            if not string.find(prefix, ss, 1, true) then\
                get = false\
                break\
            end\
        end\
        if get then\
            tt.hitcnt = tt.hitcnt + 1\
            return tt.ruleid\
        end\
    end\
end\
\
local function match_tagsig(value)\
    if not value then\
        return\
    end\
    local simple = appsig_bin.tag.sigs.domain.simple\
    if simple[value] then\
        simple[value].hitcnt = simple[value].hitcnt + 1\
        return simple[value].ruleid\
    end\
end\
\
local function simple_sig_match(t)\
    local stype, value = t.stype, t.value\
    if not stype or not value then\
        return\
    end\
    value = string.lower(value)\
    if not appsig_bin.sigs[stype] then\
        return\
    end\
    local info = appsig_bin.sigs[stype]\
    local simple = info.simple or {}\
    if stype == \"domain\" then\
        local val = {mystring.split(value, \".\")}\
        for i = 1, #val do\
            local v = table.concat(val, \".\", i, #val)\
            if simple[v] then\
                simple[v].hitcnt = simple[v].hitcnt + 1\
                return simple[v].ruleid\
            end\
            local ruleid = match_fuzzy_domain(v, value)\
            if ruleid then\
                return ruleid\
            end\
            ruleid = match_tagsig(v)\
            if ruleid then\
                return ruleid\
            end\
        end\
    elseif stype == \"diport\" then\
        -- for ipv6 240e:3a3:4c79:8920::fd77:80, it can't distinguish value is ip ( 240e:3a3:4c79:8920::fd77:80 ) or ip:port ( [240e:3a3:4c79:8920::fd77]:80 ).\
        -- so, for ipv6, it must use ip or [ipv6]:port format.\
        if simple[value] then\
            simple[value].hitcnt = simple[value].hitcnt + 1\
            return simple[value].ruleid\
        end\
    elseif stype == \"ua\" then\
        return match_ua(t.value)\
    elseif stype == \"url\" then\
        return match_by_ac(t.value, appsig_bin.ac_url, appsig_bin.sigs.url.simple)\
    elseif stype == \"cookie\" then\
        return match_by_ac(t.value, appsig_bin.ac_cookie, appsig_bin.sigs.cookie.simple)\
    elseif stype == \"ref\" then\
        return match_by_ac(t.value, appsig_bin.ac_ref, appsig_bin.sigs.ref.simple)\
    end\
end\
\
local function simple_sig_del(rule_id, index, all)\
    local ruleid = rule_id or 0\
    local stype, desc = nil, appsig_bin.appdesc[ruleid]\
    if desc then\
        stype = desc[\"stype\"]\
        if index and index > 0 then\
            table.remove(appsig_bin.ruleids, index)\
        else\
            for id, rule in pairs(appsig_bin.ruleids) do\
                if ruleid == rule.id then\
                    table.remove(appsig_bin.ruleids, id)\
                    break\
                end\
            end\
        end\
\
        appsig_bin.appdesc[ruleid] = nil\
    else\
        return\
    end\
    if stype and appsig_bin.sigs[stype] then\
        local sigs = appsig_bin.sigs[stype]\
        local val = sigs.simple or {}\
        for k,v in pairs(val) do\
            if stype == \"fuzzy_domain\" then\
                for kk, tt in pairs(v) do\
                    if tt.ruleid == ruleid then\
                        v[kk] = nil\
                        if not next(v) then\
                            val[k] = nil\
                        end\
                        break\
                    end\
                end\
            elseif v.ruleid == ruleid then\
                val[k] = nil\
                if stype == \"ua\" and appsig_bin.ac_ua then\
                    local pattern = k:match(\"^%^?(.-)%$?$\")\
                    appsig_bin.ac_ua:remove_pattern(pattern, k)\
                end\
                if stype == \"url\" and appsig_bin.ac_url then\
                    appsig_bin.ac_url:remove_pattern(k, #k)\
                end\
                if stype == \"cookie\" and appsig_bin.ac_cookie then\
                    appsig_bin.ac_cookie:remove_pattern(k, #k)\
                end\
                if stype == \"ref\" and appsig_bin.ac_ref then\
                    appsig_bin.ac_ref:remove_pattern(k, #k)\
                end\
                break\
            end\
        end\
    end\
    if not all then\
        appsig_bin.update_sig_cnt = appsig_bin.update_sig_cnt + 1\
    end\
\
    lcmd_run({subtype = \"apprule\", action = \"del\", ruleid = ruleid})\
    appsig_upstat(\"del\", stype)\
end\
\
local function simple_sig_flush(t)\
    -- make sure there are no cached IP rules in xapp before flush\
    lcmd_run({subtype = \"xapp\", action = \"rule_set\"})\
    for ruleid, info in pairs(appsig_bin.appdesc) do\
        simple_sig_del(ruleid, nil, true)\
    end\
end\
\
\
local function refresh_ruleids()\
    local now = os.time()\
    for i = #appsig_bin.ruleids, 1, -1 do\
        -- print(appsig_bin.ruleids[i].ts, i, now - appsig_bin.ruleids[i].ts)\
        if now - appsig_bin.ruleids[i].ts > appsig_bin.valid_period then\
            simple_sig_del(appsig_bin.ruleids[i].id, i, false)\
        else\
            break\
        end\
    end\
    if #appsig_bin.ruleids == 0 then\
        appsig_bin.coresig_ver = \"0.0.0.0\"\
    end\
end\
\
local function tag_sig_del(rule_id, index)\
    local ruleid = rule_id or 0\
    local stype, desc = nil, appsig_bin.tag.appdesc[ruleid]\
    if desc then\
        stype = desc[\"stype\"]\
        if index and index > 0 then\
            table.remove(appsig_bin.tag.ruleids, index)\
        else\
            for id, rule in pairs(appsig_bin.tag.ruleids) do\
                if ruleid == rule.id then\
                    table.remove(appsig_bin.tag.ruleids, id)\
                    break\
                end\
            end\
        end\
\
        appsig_bin.tag.appdesc[ruleid] = nil\
    else\
        return\
    end\
    if stype and appsig_bin.tag.sigs[stype] then\
        local sigs = appsig_bin.tag.sigs[stype]\
        local val = sigs.simple or {}\
        for k,v in pairs(val) do\
            if v.ruleid == ruleid then\
                val[k] = nil\
                break\
            end\
        end\
    end\
\
    lcmd_run({subtype = \"apprule\", action = \"del\", ruleid = ruleid})\
    appsig_upstat(\"del\", \"tagsig\")\
end\
\
local function tag_sig_flush(t)\
    -- make sure there are no cached IP rules in xapp before flush\
    lcmd_run({subtype = \"xapp\", action = \"rule_set\"})\
    for k,v in pairs(appsig_bin.tag.sigs) do\
        for _,info in pairs(v.simple or {}) do\
            tag_sig_del(info.ruleid)\
        end\
    end\
end\
\
local function tag_sig_add(stype, ruleid, appid, prio, value, name)\
    if not ruleid or not appid or not name or not stype or not value or not prio then\
        return\
    end\
\
    if value == \"\" then\
        tag_sig_del(ruleid)\
        return\
    end\
\
    if appsig_bin.tag.appdesc[ruleid] then\
        tag_sig_del(ruleid)\
    elseif #appsig_bin.tag.ruleids >= appsig_bin.max_tag_sigcnt then\
        local rule = appsig_bin.tag.ruleids[#appsig_bin.tag.ruleids]\
        tag_sig_del(rule.id, #appsig_bin.tag.ruleids)\
    end\
\
    local now = os.time()\
    table.insert(appsig_bin.tag.ruleids, 1, {id = ruleid, ts = now})\
    appsig_bin.tag.appdesc[ruleid] = {appid = appid, prio = prio, stype = stype, name = name, value = value}\
    local allsigs = appsig_bin.tag.sigs\
    if not allsigs[stype] then\
        allsigs[stype] = {simple = {}}\
    elseif not allsigs[stype].simple then\
        allsigs[stype].simple = {}\
    end\
    local val = appsig_bin.tag.sigs[stype]\
    val.simple[value] = { ruleid = ruleid, hitcnt = 0 }\
    appsig_upstat(\"add\", \"tagsig\")\
end\
\
local function simple_sig_add(stype, ruleid, appid, prio, value, name)\
    if not ruleid or not appid or not name or not stype or not value or not prio then\
        return\
    end\
\
    if value == \"\" then\
        simple_sig_del(ruleid)\
        return\
    end\
\
    local update= false\
    if appsig_bin.appdesc[ruleid] then\
        update = true\
        simple_sig_del(ruleid)\
    elseif #appsig_bin.ruleids >= appsig_bin.max_sig_cnt then\
        update = true\
        local rule = appsig_bin.ruleids[#appsig_bin.ruleids]\
        simple_sig_del(rule.id, #appsig_bin.ruleids, false)\
    end\
\
    local now = os.time()\
    table.insert(appsig_bin.ruleids, 1, {id = ruleid, ts = now})\
    appsig_bin.appdesc[ruleid] = {appid = appid, prio = prio, stype = stype, name = name, value = value}\
    local allsigs = appsig_bin.sigs\
    if not allsigs[stype] then\
        allsigs[stype] = {simple = {}}\
    elseif not allsigs[stype].simple then\
        allsigs[stype].simple = {}\
    end\
    local val = appsig_bin.sigs[stype]\
    if stype == \"fuzzy_domain\" then\
        local pos = string.find(value, \":\")\
        if not pos then\
            return\
        end\
        local suffix = string.sub(value, pos+1, -1)\
        local tt = {mystring.split(value:sub(1, pos-1), \"%s&\")}\
        val.simple[suffix] = val.simple[suffix] or {}\
        val.simple[suffix][value] = {ruleid = ruleid, hitcnt = 0, parsed = tt}\
    else\
        val.simple[value] = { ruleid = ruleid, hitcnt = 0 }\
    end\
    if stype == \"ua\" and appsig_bin.ac_ua then\
        local pattern = value:match(\"^%^?(.-)%$?$\")\
        appsig_bin.ac_ua:add_pattern(pattern, value)\
    end\
    if stype == \"url\" and appsig_bin.ac_url then\
        appsig_bin.ac_url:add_pattern(value, #value)\
    end\
    if stype == \"cookie\" and appsig_bin.ac_cookie then\
        appsig_bin.ac_cookie:add_pattern(value, #value)\
    end\
    if stype == \"ref\" and appsig_bin.ac_ref then\
        appsig_bin.ac_ref:add_pattern(value, #value)\
    end\
\
    if not update then\
        appsig_bin.update_sig_cnt = appsig_bin.update_sig_cnt + 1\
    end\
    if stype == \"diport\" then\
        local maxttl = nil\
        local ok, xapp_conf = lcmd_run({subtype = \"xapp\", action = \"read\"})\
        if ok and xapp_conf and type(xapp_conf.maxttl_tab) == \"table\" then\
            maxttl = xapp_conf.maxttl_tab.diport\
        end\
        -- for ipv6, if it is ip:port, it must be [ipv6]:port format.\
        local ip, port = myip.split_ipport(value)\
        lcmd_run({subtype = \"apprule\", action = \"add\", ip = ip, port = tonumber(port), ruleid = ruleid, appid = appid, maxttl = maxttl})\
    end\
    appsig_upstat(\"add\", stype)\
end\
\
local function base_sig_del(rule_id, value)\
    local ruleid, delid, sigtype = rule_id or 0, nil, nil\
    for stype,info in pairs(appsig_bin.sigs) do\
        local sig = appsig_bin.sigs[stype]\
        for k,v in pairs(sig.base or {}) do\
            if v.ruleid == ruleid and (value == nil or value == k) then\
                sig.base[k], delid, sigtype = nil, ruleid, stype\
                break\
            end\
        end\
    end\
\
    if delid then\
        if sigtype == \"port\" then\
            kernel_send_port(CENUM.MEMSHR_APP_BASEPORT_DEL, {del = {ruleid = delid}})\
        elseif sigtype == \"payload\" then\
            kernel_send_payload(CENUM.MEMSHR_APP_BASEPAYLOAD_DEL, {del = {ruleid = delid}})\
        end\
        lcmd_run({subtype = \"apprule\", action = \"del\", ruleid = delid})\
        appsig_bin.update_sig_cnt = appsig_bin.update_sig_cnt + 1\
        appsig_upstat(\"del\", sigtype)\
    end\
end\
\
local function base_sig_flush(t)\
    -- make sure there are no cached IP rules in xapp before flush\
    lcmd_run({subtype = \"xapp\", action = \"rule_set\"})\
    for k,v in pairs(appsig_bin.sigs) do\
        local bsig = appsig_bin.sigs[k]\
        for val,info in pairs(v.base or {}) do\
            bsig.base[val] = nil\
            if type(info) == \"table\" and info.ruleid then\
                lcmd_run({ subtype = \"apprule\", action = \"del\", ruleid = info.ruleid })\
            end\
            appsig_upstat(\"del\", k)\
        end\
    end\
    kernel.send(CENUM.MEMSHR_APP_BASE_FLUSH, \"\")\
end\
\
local function base_sig_add(stype, ruleid, appid, prio, value, name, offset, proto, port)\
    if not ruleid or not appid or not name or not stype or not value or not prio or not offset then\
        return\
    end\
\
    if value == \"\" then\
        base_sig_del(ruleid)\
        return\
    end\
\
    local allsigs = appsig_bin.sigs\
    if not allsigs[stype] then\
        allsigs[stype] = {base = {}}\
    elseif not allsigs[stype].base then\
        allsigs[stype].base = {}\
    end\
\
    local val = appsig_bin.sigs[stype]\
    if stype == \"port\" then\
        base_sig_del(ruleid)\
        local pkey = tostring(tonumber(proto) or 0)..\"_\"..value\
        val.base[pkey] = {ruleid = ruleid, appid = appid, name = name}\
        local psig = {}\
        psig[pkey] = {ruleid = ruleid, appid = appid, name = name}\
        kernel_send_port(CENUM.MEMSHR_APP_BASEPORT_ADD, psig)\
    elseif stype == \"payload\" then\
        base_sig_del(ruleid)\
        local pkey = string.format(\"%02x_%04x_%04x_%s\", tonumber(proto) or 0, tonumber(port) or 0, offset, value)\
        local psig = {}\
        val.base[pkey] = {ruleid = ruleid, appid = appid, name = name}\
        psig[pkey] = {ruleid = ruleid, appid = appid, name = name}\
        kernel_send_payload(CENUM.MEMSHR_APP_BASEPAYLOAD_ADD, psig)\
    else\
        return\
    end\
    appsig_bin.update_sig_cnt = appsig_bin.update_sig_cnt + 1\
    appsig_upstat(\"add\", stype)\
end\
\
local function appsig_update(t)\
    local simple, base, tag = t.simple or {}, t.base or {}, t.tag or {}\
    if t.all and #simple > 0 then\
        simple_sig_flush()\
    end\
    if t.all and #base > 0 then\
        base_sig_flush()\
    end\
    if t.all and #tag > 0 then\
        tag_sig_flush()\
    end\
    local has_ua_sig, has_url_sig, has_cookie_sig, has_ref_sig = false, false, false, false\
    for k,v in pairs(simple) do\
        simple_sig_add(v.sigtype, v.ruleid, v.appid, v.prio or 0, v.sigvalue, v.name)\
        if k % 100 == 0 and appsig_bin.gc_switch then collectgarbage(\"collect\") end\
        if v.sigtype == \"ua\" then has_ua_sig = true end\
        if v.sigtype == \"url\" then has_url_sig = true end\
        if v.sigtype == \"cookie\" then has_cookie_sig = true end\
        if v.sigtype == \"ref\" then has_ref_sig = true end\
    end\
    for k,v in pairs(base) do\
        base_sig_add(v.sigtype, v.ruleid, v.appid, v.prio or 0, v.sigvalue, v.name, v.offset or 0, v.proto or 0, v.port or 0)\
        if k % 100 == 0 and appsig_bin.gc_switch then collectgarbage(\"collect\") end\
    end\
    for k,v in pairs(tag) do\
        tag_sig_add(v.sigtype, v.ruleid, v.appid, v.prio or 0, v.sigvalue, v.name)\
        if k % 100 == 0 and appsig_bin.gc_switch then collectgarbage(\"collect\") end\
    end\
    if t.all or appsig_bin.update_sig_cnt >= 100 then\
        appsig_save({})\
    end\
    if has_ua_sig and appsig_bin.ac_ua then\
        appsig_bin.ac_ua:build_fail()\
    end\
    if has_url_sig and appsig_bin.ac_url then\
        appsig_bin.ac_url:build_fail()\
    end\
    if has_cookie_sig and appsig_bin.ac_cookie then\
        appsig_bin.ac_cookie:build_fail()\
    end\
    if has_ref_sig and appsig_bin.ac_ref then\
        appsig_bin.ac_ref:build_fail()\
    end\
end\
\
local function get_desc(t)\
    if t.ruleid then\
        return appsig_bin.appdesc[t.ruleid] or appsig_bin.tag.appdesc[t.ruleid]\
    end\
    return {}\
end\
\
local function sig_stat(t)\
    if not t.stype or not t.value then\
        return\
    end\
    local sigs = appsig_bin.sigs[t.stype] or {}\
    local simple = sigs.simple or {}\
    return simple[t.value]\
end\
\
local function set_maxbaseappid(t)\
    if type(t.max_base_appid) == \"number\" and t.max_base_appid >= 0 then\
        kernel.send(CENUM.MEMSHR_APP_MAXBASEAPPID_SET, string.pack(\"=I\", t.max_base_appid))\
    end\
end\
\
local function get_maxbaseappid()\
    local max_base_appid = nil\
    local max_base_appid_string = kernel.read(CENUM.MEMSHR_APP_MAXBASEAPPID_GET, 4, \"\")\
    if max_base_appid_string and #max_base_appid_string == 4 then\
        max_base_appid = string.unpack(\"=I\", max_base_appid_string)\
    end\
    return max_base_appid\
end\
\
local function write(t)\
    if type(t.period) == \"number\" and t.period ~= appsig_bin.period then\
        appsig_bin.period = t.period\
        timer.mod(appsig_bin.timer_name, appsig_bin.period, 0, appsig_save, {timer = true})\
    end\
\
    if type(t.valid_period) == \"number\" and t.valid_period ~= appsig_bin.valid_period then\
        appsig_bin.valid_period = t.valid_period\
    end\
\
    if type(t.max_sig_cnt) == \"number\" and t.max_sig_cnt ~= appsig_bin.max_sig_cnt then\
        appsig_bin.max_sig_cnt = t.max_sig_cnt\
    end\
\
    if type(t.max_tag_sigcnt) == \"number\" and t.max_tag_sigcnt ~= appsig_bin.max_tag_sigcnt then\
        appsig_bin.max_tag_sigcnt = t.max_tag_sigcnt\
    end\
\
    if type(t.gc_switch) == \"boolean\" and t.gc_switch ~= appsig_bin.gc_switch then\
        appsig_bin.gc_switch = t.gc_switch\
    end\
end\
\
local function get_siginfo(t)\
    -- if type(t.appid) ~= \"number\" then\
    --     return \"appid invalid.\"\
    -- end\
    local res = {\
        appid = t.appid,\
        appname = \"\",\
        sig_ruleid = {domain = {}, diport = {}, port = {}, payload = {}},\
        latest = \"\",\
        all_count = 0,\
    }\
    local ruleids = {}\
    for ruleid, info in pairs(appsig_bin.appdesc) do\
        if info.appid == t.appid or not t.appid then\
            res.sig_ruleid[info.stype] = res.sig_ruleid[info.stype] or {}\
            table.insert(res.sig_ruleid[info.stype], ruleid)\
            ruleids[ruleid] = true\
        end\
    end\
    for stype, val in pairs(appsig_bin.sigs) do\
        for _, info in pairs(val.base or {}) do\
            if info.appid == t.appid or not t.appid then\
                res.sig_ruleid[stype] = res.sig_ruleid[stype] or {}\
                table.insert(res.sig_ruleid[stype], info.ruleid)\
                res.appname = info.name\
            end\
        end\
    end\
    for ruleid, info in pairs(appsig_bin.tag.appdesc) do\
        if info.appid == t.appid or not t.appid then\
            res.sig_ruleid[info.stype] = res.sig_ruleid[info.stype] or {}\
            table.insert(res.sig_ruleid[info.stype], ruleid)\
            ruleids[ruleid] = true\
        end\
    end\
    for stype, arr in pairs(res.sig_ruleid) do\
        res.all_count = res.all_count + #arr\
        table.sort(arr)\
        if not t.appid then\
            res.sig_count = res.sig_count or {}\
            res.sig_count[stype] = #arr\
        end\
    end\
    if not t.appid then\
        res.appname = \"all\"\
        res.sig_ruleid = nil\
        res.latest = appsig_bin.ver\
        return res\
    end\
\
    local id, ts = 0, 0\
    for _, info in ipairs(appsig_bin.ruleids) do\
        if ruleids[info.id] and info.ts > ts then\
            id = info.id\
            ts = info.ts\
        end\
    end\
    for _, info in ipairs(appsig_bin.tag.ruleids) do\
        if ruleids[info.id] and info.ts > ts then\
            id = info.id\
            ts = info.ts\
        end\
    end\
    local desc = get_desc({ruleid = id})\
    if desc and desc.name then\
        res.appname = desc.name\
        res.latest = os.date(\"%F %T\", ts)\
    end\
\
    return res\
end\
\
function appsig_bin.preinit()\
    -- if kernel module not reload, it must clean first\
    kernel.send(CENUM.MEMSHR_APP_BASE_FLUSH, \"\")\
end\
\
function appsig_bin.postinit()\
    basesig_load()\
    appsig_bin.sig_file = lcmd_data_path(appsig_bin.filename)\
    appsig_load({})\
    timer.mod(appsig_bin.timer_name, appsig_bin.period, 0, appsig_save, {timer = true})\
    timer.mod(\"appsig_refresh\", 3600, 0, refresh_ruleids)\
    appsig_bin.ac_ua = aho_corasick.new()\
    if appsig_bin.ac_ua then\
        for value in pairs(appsig_bin.sigs.ua.simple) do\
            local pattern = value:match(\"^%^?(.-)%$?$\")\
            appsig_bin.ac_ua:add_pattern(pattern, value)\
        end\
        appsig_bin.ac_ua:build_fail()\
    end\
    appsig_bin.ac_url = aho_corasick.new()\
    if appsig_bin.ac_url then\
        for value in pairs(appsig_bin.sigs.url.simple) do\
            appsig_bin.ac_url:add_pattern(value, #value)\
        end\
        appsig_bin.ac_url:build_fail()\
    end\
    appsig_bin.ac_cookie = aho_corasick.new()\
    if appsig_bin.ac_cookie then\
        for value in pairs(appsig_bin.sigs.cookie.simple) do\
            appsig_bin.ac_cookie:add_pattern(value, #value)\
        end\
        appsig_bin.ac_cookie:build_fail()\
    end\
    appsig_bin.ac_ref = aho_corasick.new()\
    if appsig_bin.ac_ref then\
        for value in pairs(appsig_bin.sigs.ref.simple) do\
            appsig_bin.ac_ref:add_pattern(value, #value)\
        end\
        appsig_bin.ac_ref:build_fail()\
    end\
end\
\
actor.action_set(appsig_bin.subtype, \"read\", function ()\
    local base_sigcnt = 0\
    for _, val in pairs(appsig_bin.sigs) do\
        for _, info in pairs(val.base or {}) do\
            if info.appid and info.ruleid then\
                base_sigcnt = base_sigcnt + 1\
            end\
        end\
    end\
    return { valid_period = appsig_bin.valid_period, max_sig_cnt = appsig_bin.max_sig_cnt,  period = appsig_bin.period, src_ver = appsig_bin.src_ver, ver = appsig_bin.ver, coresig_ver = appsig_bin.coresig_ver, sigcnt = #appsig_bin.ruleids, max_tag_sigcnt = appsig_bin.max_tag_sigcnt, tag_sigcnt = #appsig_bin.tag.ruleids, base_sigcnt = base_sigcnt }\
end, \"read appsig_bin conf\")\
-- actor.action_set(appsig_bin.subtype, \"show\", function () return {sigs = appsig_bin.sigs, ruleids = appsig_bin.ruleids} end, \"show appsig_bin sigs\")\
-- actor.action_set(appsig_bin.subtype, \"show_desc\", function () return {desc = appsig_bin.appdesc} end, \"show appsig_bin sigs\")\
actor.action_set(appsig_bin.subtype, \"stat\", function () return { add_cnt = appsig_bin.add_cnt, del_cnt = appsig_bin.del_cnt, domain_addcnt = appsig_bin.domain_addcnt or 0, domain_delcnt = appsig_bin.domain_delcnt or 0, diport_addcnt = appsig_bin.diport_addcnt or 0, diport_delcnt = appsig_bin.diport_delcnt or 0, ua_addcnt = appsig_bin.ua_addcnt or 0, ua_delcnt = appsig_bin.ua_delcnt or 0, url_addcnt = appsig_bin.url_addcnt or 0, url_delcnt = appsig_bin.url_delcnt or 0, cookie_addcnt = appsig_bin.cookie_addcnt or 0, cookie_delcnt = appsig_bin.cookie_delcnt or 0, ref_addcnt = appsig_bin.ref_addcnt or 0, ref_delcnt = appsig_bin.ref_delcnt or 0, fuzzy_domain_addcnt = appsig_bin.fuzzy_domain_addcnt or 0, fuzzy_domain_delcnt = appsig_bin.fuzzy_domain_delcnt or 0, tagsig_addcnt = appsig_bin.tagsig_addcnt or 0, tagsig_delcnt = appsig_bin.tagsig_delcnt or 0, port_addcnt = appsig_bin.port_addcnt or 0, port_delcnt = appsig_bin.port_delcnt or 0, payload_addcnt = appsig_bin.payload_addcnt or 0, payload_delcnt = appsig_bin.payload_delcnt or 0 } end, \"read appsig_bin stat\")\
actor.action_set(appsig_bin.subtype, \"write\", write, [[set appsig_bin conf, {period = number, valid_period = number, max_sig_cnt = number}]])\
actor.action_set(appsig_bin.subtype, \"save\", appsig_save, [[save app sig, {file = string}, default datapath + m01_sig.bin]])\
actor.action_set(appsig_bin.subtype, \"load\", appsig_load, [[load app sig, {file = string, show_ver = boolean}, default datapath + m01_sig.bin]])\
actor.action_set(appsig_bin.subtype, \"match\", simple_sig_match, [[search rule_id, {stype = string, value = string}]])\
actor.action_set(appsig_bin.subtype, \"get_desc\", get_desc, [[show appsig, {ruleid = number}]])\
actor.action_set(appsig_bin.subtype, \"add\", function (t) simple_sig_add(t.stype, t.ruleid, t.appid, t.prio or 0, t.value, t.name) end, [[add sig, {ruleid = number, appid = number, name = string, stype = string, value = string, prio = number}]])\
actor.action_set(appsig_bin.subtype, \"del\", function (t)\
    if type(t.ruleid) == \"number\" then\
        simple_sig_del(t.ruleid)\
        return string.format(\"delete ruleid: %s\", t.ruleid)\
    elseif type(t.appid) == \"number\" then\
        local del_ruleids = {}\
        for ruleid, info in pairs(appsig_bin.appdesc) do\
            if info.appid == t.appid then\
                simple_sig_del(ruleid)\
                table.insert(del_ruleids, ruleid)\
            end\
        end\
        return string.format(\"delete ruleids: %s\", cjson.encode(del_ruleids))\
    end\
end, [[del ruleid, {ruleid/appid = number}]])\
actor.action_set(appsig_bin.subtype, \"flush\", simple_sig_flush, [[flush ruleid]])\
actor.action_set(appsig_bin.subtype, \"sig_stat\", sig_stat, [[read sig_stat, {stype = string, value = string}]])\
actor.action_set(appsig_bin.subtype, \"base_add\", function (t) base_sig_add(t.stype, t.ruleid, t.appid, t.prio or 0, t.value, t.name, t.offset or 0, t.proto or 0, t.port or 0) end, [[add sig, {ruleid = number, appid = number, name = string, stype = string, value = string<require hex format>, offset = number<default 0>, prio = number, proto = number, port = number}]])\
actor.action_set(appsig_bin.subtype, \"base_del\", function (t)\
    if type(t.ruleid) == \"number\" then\
        base_sig_del(t.ruleid)\
        return string.format(\"delete ruleid: %s\", t.ruleid)\
    elseif type(t.appid) == \"number\" then\
        local del_ruleids = {}\
        for _, val in pairs(appsig_bin.sigs) do\
            for _, info in pairs(val.base or {}) do\
                if info.appid == t.appid then\
                    base_sig_del(info.ruleid)\
                    table.insert(del_ruleids, info.ruleid)\
                end\
            end\
        end\
        return string.format(\"delete ruleids: %s\", cjson.encode(del_ruleids))\
    end\
end, [[del ruleid, {ruleid/appid = number}]])\
actor.action_set(appsig_bin.subtype, \"base_flush\", base_sig_flush, [[flush ruleid]])\
actor.action_set(appsig_bin.subtype, \"tag_del\",function (t)\
    if type(t.ruleid) == \"number\" then\
        tag_sig_del(t.ruleid)\
        return string.format(\"delete ruleid: %s\", t.ruleid)\
    elseif type(t.appid) == \"number\" then\
        local del_ruleids = {}\
        for ruleid, info in pairs(appsig_bin.tag.appdesc) do\
            if info.appid == t.appid then\
                tag_sig_del(ruleid)\
                table.insert(del_ruleids, ruleid)\
            end\
        end\
        return string.format(\"delete ruleids: %s\", cjson.encode(del_ruleids))\
    end\
end, [[del ruleid, {ruleid/appid = number}]])\
actor.action_set(appsig_bin.subtype, \"tag_add\", function (t) tag_sig_add(t.stype, t.ruleid, t.appid, t.prio or 0, t.value, t.name) end, [[add sig, {all = boolean, ruleid = number, appid = number, name = string, stype = string, value = string, prio = number}]])\
