        arch.iface = t.iface\
    end\
end\
\
function arch.postinit()\
    local get_pppoe\
    -- init arch such as sn/pppoe..., must be OK, or will wait forever\
    while true do\
        local v = carch.init(arch.iface)\
        if not v then\
            local socket = require\"socket\"\
            log.error(\"Failed to arch init, sleep 10 seconds forever\")\
