package.preload[ "arping" ] = assert( (loadstring or load)(
"local mystring = require(\"mystring\")\
local actor = require(\"luactor\")\
local cjson = require(\"cjson\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local myip = require(\"myip\")\
local stats = require(\"stats\")\
local csocket = require\"c.socket\"\
\
local arping = {\
    type = \"arping\", \
    subtype = \"arping\", \
    help = \"get arping time delay\", \
\
    period = 0,\
    pkt_cnt = 5,\
    sindex = nil,\
    timer_name = \"arping_send\",\
    timer_send_one = \"arping_send_one\",\
    timer_get_arping = \"timer_get_arping\",\
    iface = \"br0\",\
    is_sending = false,\
    arp_host = {},\
    arp_data = {},\
    lat_avg = 1000, -- us\
}\
\
local function get_host()\
    local arps = myip.getarp(true)\
    local host = {}\
    for ip, v in pairs(arps) do\
        if type(v) == \"table\" and v.device == arping.iface then\
            if not (type(v.flags) == \"string\" and v.flags == \"0x0\") then\
                host[ip] = v.mac\
            end\
        end\
    end\
    return host\
end\
\
local function set_pcap_filter(enable, filter)\
    if enable then\
        lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_set\", keyname = arping.type, filter = filter})\
    else\
        lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_unset\", keyname = arping.type })\
    end\
end\
\
local function get_arping()\
    set_pcap_filter(false)\
\
    local data = {}\
    for mac, v in pairs(arping.arp_host) do\
        data[mac] = {\
            lan_avg = v.stats:getMean(),\
            lan_max = v.stats:getMax(),\
            lan_min = v.stats:getMin(),\
            lan_std = v.stats:getStdDev(),\
            arping_lost_pct = -1,\
            arping_mean_jitter = v.stats:getMeanJitter(),\
        }\
        if v.recv_cnt >= v.send_cnt or v.send_cnt <= 0 then\
            data[mac].arping_lost_pct = 0\
        else\
            data[mac].arping_lost_pct = (v.send_cnt - v.recv_cnt) * 100 / v.send_cnt\
        end\
        if type(v.send_time) == \"number\" then\
            -- if recv response, v.send_time will be nil\
            actor.publish({msgtype = \"ARPING\", mac = mac, lat = nil})  -- lat = nil, means lost\
        end\
    end\
    arping.arp_data = data\
    arping.arp_host = {}\
    arping.is_sending = false\
end\
\
local function send_series_arp(host, count)\
    for ip, mac in pairs(host) do\
        log.debug(\"Start sending ARP to\", ip)\
        local ok, sec, usec = csocket.arp_send(arping.iface, ip, 1)\
        if not ok then\
            log.error(\"send \"..ip..\" arp failed, err is \", sec)\
            break\
        end\
        if not arping.arp_host[mac] then\
            arping.arp_host[mac] = {\
                ip = ip,\
                stats = stats:new(),\
                send_cnt = 0,\
                recv_cnt = 0,\
            }\
        else\
            -- it's not first send\
            if type(arping.arp_host[mac].send_time) == \"number\" then\
                -- if recv response, v.send_time will be nil\
                actor.publish({msgtype = \"ARPING\", mac = mac, lat = nil})  -- lat = nil, means lost\
            end\
        end\
        arping.arp_host[mac].send_time = sec + usec / 1000000\
        arping.arp_host[mac].send_cnt = arping.arp_host[mac].send_cnt + 1\
        log.debug(\"End sending ARP to\", ip, \"at\", tostring(arping.arp_host[mac].send_time))\
    end\
    count = count - 1\
    if count == 0 then\
        timer.mod(arping.timer_get_arping, 2, 1, get_arping)\
    else\
        timer.mod(arping.timer_send_one, 2, 1, send_series_arp, host, count)\
    end\
end\
\
local function arp_check()\
    if arping.period <= 0 or arping.pkt_cnt <= 0 or arping.is_sending then\
        return\
    end\
\
    local host = get_host()\
    if not next(host) then\
        log.warn(\"no online hosts from arp\")\
        return\
    end\
\
    arping.is_sending = true\
    local filter = \"arp[6:2] = 0x0002\"\
    set_pcap_filter(true, filter)\
    send_series_arp(host, arping.pkt_cnt)\
end\
\
local function arp_get(msg)\
    local arp_pcap = msg.arp_pcap\
    if type(arp_pcap) ~= \"table\" or arp_pcap.opcode ~= 2 then\
        return\
    end\
\
    log.debug(\"Subscribe to arp_pcap info:\", cjson.encode(arp_pcap))\
    local arp = arping.arp_host[arp_pcap.sender_mac]\
    if type(arp) == \"table\" and arp.ip == arp_pcap.sender_ip and type(arp.send_time) == \"number\" then\
        local send_time = arp.send_time\
        arp.send_time = nil\
        local recv_time = tonumber(arp_pcap.timestamp)\
        local lat = math.floor((recv_time - send_time) * 1000000)   -- convert to us\
        if lat <= 0 then\
            lat = arping.lat_avg\
            log.debug(\"There have been some issues here,\", tostring(recv_time), \"-\", tostring(send_time), \"<= 0\")\
        end\
