    end\
    if type(t.period) == \"number\" and t.period ~= arping.period then\
        arping.period = t.period\
        timer.mod(arping.timer_name, arping.period, 0, arp_check)\
    end\
    if type(t.iface) == \"string\" and t.iface ~= arping.iface then\
