package.preload[ "cliclient" ] = assert( (loadstring or load)(
"local socket = require\"socket\"\
local unix = require\"socket.unix\"\
local cjson = require\"cjson\"\
local log = require\"log\"\
local mystring = require\"mystring\"\
\
local cliclient = {}\
\
local function usage()\
    return [[\
usage is following:\
\
1. ./CLI_client '{}'\
    all is in one json\
2. ./CLI_client help [subtype action]\
    help usage\
       only help, means all brief help\
       help and subtype, means subtype help\
       help and subtype and action, means action help for such subtype\
3. ./CLI_client subtype[:type] action ['{}']\
   args will be expanded to '{type = type, subtype = subtype, action = action, ...}'\
   last parameter can be empty if action need not any parameter\
]]\
end\
\
local function help(subtype, action)\
    if subtype == nil then\
        return '{\"action\":\"help\"}'\
    elseif action == nil then\
        return '{\"action\":\"help\", \"subtype\":\"'..subtype..'\"}'\
    else\
        return '{\"action\":\"help\", \"subtype\":\"'..subtype..'\", \"name\":\"'..action..'\"}'\
    end\
end\
\
local function cli_cmd(path, msg)\
    local t = unix.tcp()\
    local _, err = t:connect(path)\
    if err then\
        return nil, \"Failed to connect path \"..path..\", err is \"..err\
    end\
\
    t:settimeout(180)\
    local len = string.pack(\"I\", #msg)\
    t:send(len)\
    -- t:send(msg:sub(1, 3))\
    -- os.execute(\"sleep 8\")\
    -- t:send(msg:sub(4, -1))\
    t:send(msg)\
    -- log.trace(\"send msg \"..msg, \"len is \"..#msg)\
    local buf, err = t:receive(4)\
    if err then\
        t:close()\
        return nil, err\
    end\
    len = string.unpack(\"I\", buf)\
    local resp\
    if len > 0 then\
        resp, err = t:receive(len)\
    else\
        resp, err = \"\", nil\
    end\
    t:close()\
    return resp, err\
end\
\
local function cmd_prepair(stype, action, other)\
    local t = {}\
    if other then\
        local ok\
        ok, t = pcall(cjson.decode, other)\
        if not ok then\
            error(\"Failed to json decode for \"..other)\
        end\
    end\
\
    t.subtype, t.type = mystring.split(stype, \":\")\
    if not t.type then\
        t.type = t.subtype\
    end\
    t.action = action\
    return cjson.encode(t)\
end\
\
local function add_nonmainp_flag(msg)\
    local ok, t = pcall(cjson.decode, msg)\
    if not ok then\
        error(\"Failed to json decode for \"..msg)\
    end\
    if type(t.nonmainp) ~= \"nil\" then\
        error(msg..\" should not have the key nonmainp\")\
    end\
    t.nonmainp = true\
    return cjson.encode(t)\
end\
\
function cliclient.main(ismainp, path, ...)\
    local t = {...}\
    local argc = #t\
    local err, msg = nil, nil\
\
    if t[1] == \"help\" then\
        msg = help(t[2], t[3])\
    elseif argc == 1 then\
        local firstch = t[1]:sub(1, 1)\
        if firstch == \"{\" then -- json obj\
            msg = t[1]\
        elseif firstch == \"[\" then\
            return nil, usage()\
        else\
            msg = string.format([[{\"action\":\"%s\"}]], t[1])\
        end\
    elseif argc == 3 or argc == 2 then\
        msg = cmd_prepair(t[1], t[2], t[3])\
    else\
        return nil, usage()\
    end\
\
    if not ismainp then\
        msg = add_nonmainp_flag(msg)\
    end\
\
    local resp, err = cli_cmd(path, msg)\
    if err then\
        return nil, err..\"\\n\"..usage()\
    else\
        return resp, nil\
    end\
end\
\
return cliclient\
"
, '@'.."./lualib/cliclient.lua" ) )

package.preload[ "cliserver" ] = assert( (loadstring or load)(
"local socket = require(\"socket\")\
local unix = require(\"socket.unix\")\
local msocket = require(\"msocket\")\
local log = require(\"log\")\
local cjson = require(\"cjson\")\
\
local cliserver = {\
}\
\
local function cli_send(s, msg)\
    local buf = string.pack(\"I\", #msg)..msg\
    coroutine.yield()\
    local ret, err = msocket.polite_send(s, buf)\
    if err then\
        log.warn(\"Failed to send, err is\", err)\
    end\
end\
\
local function cli_recv(s)\
    -- recv head\
    local buf, err = msocket.polite_receive(s, 4)\
    if err then\
        return nil, \"error for receive, err is \"..err\
    end\
\
    local len = string.unpack(\"I\", buf)\
    if len <= 0 or len > 10000000 then\
        -- actually not need check larger then 10000000 (about 9.5MB),\
        -- here just avoid some tricks or carelessness to cause fault.\
        return nil, \"error unpack len, len is \"..len\
    end\
\
\
    -- recv body\
    buf, err = msocket.polite_receive(s, len)\
    if err then\
        return nil, \"error receive body, len is \"..len.. \", err is \"..err\
    end\
\
    return buf\
end\
\
local function cli_resp(s)\
    local msg, err = cli_recv(s)\
    if err then\
        return false, err\
    end\
\
    local ok, t = pcall(cjson.decode, msg)\
    if not ok then\
        return false, \"wrong input json msg \"..msg..\", err is \"..t\
    else\
        local ok, m = lcmd_run(t)\
        if not ok then\
            return false, string.format(\"failed run lcmd_run err(%s) for msg(%s) \", m, msg)\
        end\
        if m == nil then\
            return true, \"\"\
        end\
        local ok, reply = pcall(cjson.encode, m)\
        if not ok then\
            return false, string.format(\"failed run cjson encode err(%s)\", reply)\
        end\
        return true, reply\
    end\
end\
\
local function server_run(cc, s)\
    s:settimeout(0)\
\
    msocket.add(cc, s)\
    local ok, msg = cli_resp(s)\
    msocket.del(s)\
    if not ok then\
        -- do nothing\
    end\
\
    msocket.add(cc, nil, s)\
    cli_send(s, msg)\
    msocket.del(s, true)\
\
    s:close()\
end\
\
function cliserver.init(sockname) \
    local t = unix.tcp()\
\
    os.remove(sockname)\
    local _, err = t:bind(sockname)\
    if err then\
        return \"Failed to bind \"..sockname, \", err is \"..err\
    end\
\
    _, err = t:listen()\
    if err then\
        return \"Failed to listen \"..sockname, \", err is \"..err\
    end\
\
    -- coroutine init\
    local co = msocket.coroutine_create(\"cliserver\", 0, \
        function ()\
            local cc = coroutine.running()\
            while true do\
                local s = t:accept()\
                msocket.del(t)\
                server_run(cc, s)\
                msocket.add(cc, t)\
                coroutine.yield()\
            end\
        end\
    )\
    if not co then\
        return \"Failed to create coroutine cliserver, check coroutinename err\"\
    end\
   \
    msocket.add(co, t)\
    return nil\
end\
\
return cliserver\
"
, '@'.."./lualib/cliserver.lua" ) )

package.preload[ "coll_domain" ] = assert( (loadstring or load)(
"local actor = require(\"luactor\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local cjson = require(\"cjson\")\
local myip = require(\"myip\")\
local mime = require(\"mime\")\
local mystring = require(\"mystring\")\
local url = require(\"socket.url\")\
local dpi = require(\"svrcomm.dpi\")\
\
local coll_domain = {\
    type = \"coll_domain\",\
    subtype = \"coll_domain\",\
    help = \"collect domain/stock data and send to svrdata\",\
    timer_name = \"upload_ds_data\",\
    http_sindex = nil,\
    https_sindex = nil,\
\
    -- confs\
    addr = {\"b01.189cube.com:7870\"},\
    upload_period = 0,  -- default disable\
    session_period = 1800,\
    max_merge_count = 1000,\
    stock_rule = {\
        -- query\
        [\"gbapi.eastmoney.com\"] = {url = {\"[?&]code=%u*(%d+)&?\"}},\
        [\"ai.10jqka.com.cn\"] = {url = {\"[?&]code=%u*(%d+)&?\"}},\
        [\"www.iwencai.com\"] = {url = {\"[?&]q=%u*(%d+)&?\"}},\
        -- path\
        [\"stockpage.10jqka.com.cn\"] = {url = {\"[^/]/%u*(%d+)/?\"}},\
        [\"xueqiu.com\"] = {url = {\"[^/]/%u*(%d+)/?\"}},\
        -- ref\
        [\"quote.eastmoney.com\"] = {ref = {\"[^/]/%a*(%d+).html\"}},\
        [\"myfavor.eastmoney.com\"] = {ref = {\"[^/]/%a*(%d+).html\"}},\
    },\
\
    -- stat\
    raw_coll_count = 0,\
    discard_coll_count = 0,\
    all_merge_count = 0,\
    merge_data = {\
        -- pkey = \"mac_domain_domain_type_refer/mac_domain_domain_type_stock_code\"\
    },\
    merge_count = 0,\
\
    -- upload stat\
    upload_raw_len = 0,\
    upload_succ_len = 0,\
    upload_succ_count = 0,\
    upload_fail_len = 0,\
    upload_fail_count = 0,\
}\
\
local function finicall_json(err, data)\
    if err then\
        log.info(\"coll_domain \", cjson.encode(coll_domain.addr), \" finicall err, \", err)\
        coll_domain.upload_fail_count = coll_domain.upload_fail_count + 1\
        coll_domain.upload_fail_len = coll_domain.upload_fail_len + #data\
    else\
        coll_domain.upload_succ_count = coll_domain.upload_succ_count + 1\
        coll_domain.upload_succ_len = coll_domain.upload_succ_len + #data\
    end\
end\
\
local function upload_merge()\
    local data, now_time = {}, os.time()\
    for pkey, info in pairs(coll_domain.merge_data) do\
        local mac, domain, domain_type, dtype_value = mystring.split(pkey, \"_\")\
        local tt = {\
            type = info.type,\
            mac = mac,\
            domain = domain or \"\",\
            pv = info.pv,\
            duration = info.duration,\
            session = info.session,\
            osid = info.osid,\
            first_time = tostring(info.first_time),\
            update_time = tostring(info.update_time),\
            upload_time = tostring(now_time),\
            session_period = coll_domain.session_period,\
            upload_period = coll_domain.upload_period,\
        }\
        if info.type == \"domain\" then\
            tt.refer = dtype_value or \"\"\
            tt.domain_type = tonumber(domain_type)\
        elseif info.type == \"stock\" then\
            tt.stock_code = dtype_value or \"\"\
        end\
        table.insert(data, tt)\
    end\
    if #data <= 0 then\
        return\
    end\
    local data_json = cjson.encode(data)\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = {type = coll_domain.subtype, data = data}})\
    for _, addr in pairs(coll_domain.addr) do\
        log.info(string.format(\"coll_domain %s send msgcnt(%d)\", addr, #data))\
        dpi.async_call(addr, CENUM.COMM_ACTION_DEVOPS_DPI_DATA, data_json, finicall_json)\
    end\
    coll_domain.merge_data = {}\
    coll_domain.merge_count = 0\
end\
\
local function merge_info(dtype, mac, domain, domain_type, dtype_value)\
    if type(dtype) ~= \"string\" or type(mac) ~= \"string\" or type(domain) ~= \"string\" or type(dtype_value) ~= \"string\" then\
        return\
    end\
    coll_domain.raw_coll_count = coll_domain.raw_coll_count + 1\
    if coll_domain.merge_count >= coll_domain.max_merge_count then\
        coll_domain.discard_coll_count = coll_domain.discard_coll_count + 1\
        return\
    end\
    local osid, now_time = 0, os.time()\
    local ok, osinfo = lcmd_run({subtype = \"osinfo\", action = \"get_oss\", mac = mac or \"\"})\
    if ok and type(osinfo) == \"table\" and next(osinfo) then\
        osid = osinfo.decide_osid or osinfo.cloud_osid\
    end\
    local pkey = string.format(\"%s_%s_%d_%s\", mac, domain, domain_type, dtype_value)\
    if not coll_domain.merge_data[pkey] then\
        coll_domain.merge_data[pkey] = {type = dtype, pv = 1, duration = 1, session = 1, osid = osid, first_time = now_time, update_time = now_time, update_duration_time = now_time, update_session_time = now_time}\
        coll_domain.merge_count = coll_domain.merge_count + 1\
        coll_domain.all_merge_count = coll_domain.all_merge_count + 1\
    else\
        local one = coll_domain.merge_data[pkey]\
        one.pv = one.pv + 1\
        if now_time - one.update_duration_time >= 60 then\
