end\
\
local function parse_url_ref(urlstring, ref)\
    local pos = string.find(urlstring or \"\", \"/\") or 0\
    local domain = string.sub(urlstring or \"\", 1, pos - 1) or \"\"\
    if domain:sub(-5, -1) == \"http:\" then\
        domain = domain:sub(1, -6)\
    end\
    local ref_parsed = url.parse(ref) or {}\
    local refer = ref_parsed.host or \"\"\
\
    local rule, stock_code = coll_domain.stock_rule[domain], nil\
    if rule then\
        for _, reg_val in pairs(rule.url or {}) do\
            stock_code = string.match(urlstring, reg_val)\
            if stock_code then break end\
        end\
        for _, reg_val in pairs(rule.ref or {}) do\
            stock_code = string.match(ref, reg_val)\
            if stock_code then break end\
        end\
    end\
    return domain, refer, stock_code\
end\
\
local function http_deal(msg)\
    if coll_domain.upload_period <= 0 then\
        return\
    end\
    local data = msg.http_tables\
    for _, v in pairs(data) do\
        local mac = myip.mac_ntoa(v.mac)\
        local domain, refer, stock_code = parse_url_ref(v.url, v.ref)\
