            coll_domain.addr = t.addr\
        end\
    end\
    if type(t.upload_period) == \"number\" and t.upload_period >= 0 and t.upload_period ~= coll_domain.upload_period then\
        coll_domain.upload_period = t.upload_period\
        timer.mod(coll_domain.timer_name, coll_domain.upload_period, 0, upload_merge)\
    end\
    if type(t.session_period) == \"number\" and t.session_period >= 1 and t.session_period ~= coll_domain.session_period then\
        coll_domain.session_period = t.session_period\
