        coll_domain.max_merge_count = t.max_merge_count\
    end\
    if type(t.stock_rule) == \"table\" then\
        coll_domain.stock_rule = t.stock_rule\
    end\
    if type(t.stock_rule) == \"string\" and mime.unb64(t.stock_rule) then\
