package.preload[ "connfirst" ] = assert( (loadstring or load)(
"\
local actor = require(\"luactor\")\
local log = require(\"log\")\
local myip = require(\"myip\")\
local kernel = require(\"c.kernel\")\
\
\
local connfirst = {\
    type = \"connfirst\",\
    subtype = \"connfirst\",\
    help = \"connfirst\",\
\
    kcfmt = \"=BBBB\",\
    kcsize = 4,\
    kdfmt = \"=HBBIIHHBBBBIIc16c16HHBBH\",\
    kdsize = 68,\
}\
\
\
local function msg_handler(msg)\
    local len = #msg\
    if len < connfirst.kdsize then\
        return\
    end\
    local all_len, care_pkt, care_l7, ts_sec, ts_usec, orig_pkt_len, orig_l7_len, l3_off, l4_off, l7_off, direct, iif, oif, sip, dip, sport, dport, proto, _, data_len, next_pos = string.unpack(connfirst.kdfmt, msg)\
    if all_len ~= len then\
        return\
    end\
    local dt = {\
        care_pkt = care_pkt ~= 0 and true or false,\
        care_l7 = care_l7 ~= 0 and true or false,\
        ts_sec = ts_sec,\
        ts_usec = ts_usec,\
        orig_pkt_len = orig_pkt_len,\
        orig_l7_len = orig_l7_len,\
        l3_off = l3_off,\
        l4_off = l4_off,\
        l7_off = l7_off,\
        direct = direct,\
        iif = iif,\
        oif = oif,\
        sip = myip.inet_ntoa(sip),\
        dip = myip.inet_ntoa(dip),\
        sport = sport,\
        dport = dport,\
        proto = proto,\
    }\
    if data_len > 0 then\
        dt.data = string.sub(msg, next_pos, next_pos + data_len - 1)\
    end\
\
    actor.publish({msgtype = \"CONN_FIRST\", dt = dt})\
end\
\
local function write(t)\
    local enable, care_pkt, care_l7, pad = 0, 0, 0, 0\
    if type(t.enable) == \"boolean\" and t.enable then\
        enable = 1\
    end\
    if type(t.care_pkt) == \"boolean\" and t.care_pkt then\
        care_pkt = 1\
    end\
    if type(t.care_l7) == \"boolean\" and t.care_l7 then\
        care_l7 = 1\
    end\
    local data = string.pack(connfirst.kcfmt, enable, care_pkt, care_l7, pad) \
    kernel.send(CENUM.USR_KNL_CONN_FIRST_NOTIFY_CONF_SET, data)\
end\
\
local function get_conf(sbytes)\
    local len = #sbytes\
    if len == connfirst.kcsize then\
        local enable, care_pkt, care_l7, _ = string.unpack(connfirst.kcfmt, sbytes)\
        local conf = {}\
        conf.enable = enable ~= 0 and true or false\
        conf.care_pkt = care_pkt ~= 0 and true or false\
        conf.care_l7 = care_l7 ~= 0 and true or false\
        connfirst.conf = conf\
    end\
    return len\
end\
\
local function read()\
    connfirst.conf = {}\
    kernel.call(CENUM.USR_KNL_CONN_FIRST_NOTIFY_CONF_GET, \"\", get_conf)\
    return connfirst.conf\
end\
\
function connfirst.postinit()\
    lcmd_run({ subtype = \"msgenl\", action = \"register_handler\", mtype = CENUM.MSGENL_MSG_TYPE_CONN_FIRST, handler = msg_handler })\
end\
\
actor.action_set(connfirst.subtype, \"write\", write, \"write connfirst conf\")\
actor.action_set(connfirst.subtype, \"read\", read, \"read connfirst conf\")\
\
return connfirst\
\
"
, '@'.."./service/connfirst.lua" ) )

