local http = require\"socket.http\"\
local mhttps = require\"mhttps\"\
local surl = require\"socket.url\"\
local mime = require\"mime\"\
local ctime = require\"c.time\"\
local pb = require\"pb\"\
\
local crawler = {\
    type = \"crawler\",\
    subtype = \"crawler\",\
    help = \"send crawl_info to server\",\
    timer_name = \"crawl_heart\",\
\
    -- conf\
    heart_period = 86400,\
    addr = {\"xapp.189cube.com:7872:7871\"},\
    enable = false,         -- default is disable\
    ua = \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36\",\
    max_crawl_cnt = 30,     -- maximum number of climbs\
    seed = \"0\",\
\
    -- stat\
    all_len = 0,            -- total length reported\
    all_count = 0,          -- total number of reports\
    all_crawl_cnt = 0,      -- total number of crawling urls\
    all_success_cnt = 0,    -- total number of successful crawls\
    last_task = nil,        -- last task issued\
    heart_nexttime = nil,   -- next heartbeat time\
}\
\
local function crawl_task_reply(addr, action, msg)\
    local ok, array = pcall(pb.decode, \".plugin.ServerMsgs\", msg)\
    if not ok then\
        log.error(\"service for protobuf err\", msg)\
        return\
    end\
\
    for _,sdata in pairs(array.data) do\
        local ok, tt = pcall(pb.decode, \".plugin.CommonHdr\", sdata)\
        local pbin, pbout, pbytes = \"\", \"\", nil\
        if not ok then\
            log.error(\"no type action for protobuf \", sdata)\
            return\
        end\
\
        pbin, pbout = actor.pb_inout(tt.type, tt.action)\
        if not pbin then\
            log.error(\"no such pbin pbout for \", tt.type, tt.action)\
            return\
        end\
\
        local ok, srctt = pcall(pb.decode, pbin, sdata)\
        if not ok then\
            log.error(\"failed to decode pbin \", pbin)\
            return\
        end\
        local ok, result = lcmd_run(srctt)\
        if not ok then\
            log.error(\"failed to callback from\", addr, cjson.encode(srctt))\
        end\
    end\
end\
\
local function get_gwstat()\
    local gwstat = {\
        totalmem = 0,   -- kB\
        freemem = 0,    -- kB\
        plugmem = 0,    -- kB\
        cpunum = 0,\
        loadavg1 = 0,\
        loadavg5 = 0,\
        loadavg15 = 0,\
        dmod = \"\",\
        dswver = \"\",\
    }\
    for line in io.lines(\"/proc/meminfo\") do\
        local attr, size = mystring.split(line, \" \\t\")\
        size = tonumber(size) or 0\
        if attr == \"MemTotal:\" then\
            gwstat.totalmem = size\
        elseif attr == \"MemFree:\" then\
            gwstat.freemem = size\
        end\
    end\
    for line in io.lines(\"/proc/self/status\") do\
        local attr, size = mystring.split(line, \" \\t\")\
        size = tonumber(size) or 0\
        if attr == \"VmRSS:\" then\
            gwstat.plugmem = size\
        end\
    end\
    for line in io.lines(\"/proc/cpuinfo\") do\
        if line:sub(1, 9) == \"processor\" then\
            gwstat.cpunum = gwstat.cpunum + 1\
        end\
    end\
    local loadavg, err = myfile.read(\"/proc/loadavg\")\
    if err then\
        log.warn(\"get loadavg \", err)\
    end\
    gwstat.loadavg1, gwstat.loadavg5, gwstat.loadavg15 = mystring.split(loadavg or \"\", \" \\t\")\
    gwstat.loadavg1 = math.floor((tonumber(gwstat.loadavg1) or 0) * 100)\
    gwstat.loadavg5 = math.floor((tonumber(gwstat.loadavg5) or 0) * 100)\
    gwstat.loadavg15 = math.floor((tonumber(gwstat.loadavg15) or 0) * 100)\
    local _, arch = lcmd_run({subtype = \"arch\", action = \"read\"})\
    if type(arch) ~= \"table\" then\
        arch = {dmod = \"\", dswver = \"\"}\
    end\
    gwstat.dmod, gwstat.dswver = arch.dmod, arch.dswver\
\
    return gwstat\
end\
\
local trigger_heart_timer\
\
local function crawl_heart(lcmd)\
    if not crawler.enable then\
        return\
    end\
    if not lcmd then\
        trigger_heart_timer()\
    end\
    local gwstat = get_gwstat()\
    gwstat[\"type\"] = \"gw_stat\"\
    log.info(\"crawler heart msg, \", cjson.encode(gwstat))\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = gwstat})\
    local pbtype = actor.pbtype_get(gwstat.type)\
    local pbgwstat = pb.encode(pbtype, gwstat)\
    for _, addr in pairs(crawler.addr) do\
        dpi.pb_asyncall(addr, true, \"ACTION_SHORT_APP\", {pbgwstat}, nil, crawl_task_reply)\
    end\
end\
\
function trigger_heart_timer()\
    local period = math.floor(crawler.heart_period)\
    local half = math.floor(period / 2)\
    local range_min = period - half\
    local range_max = period + half\
    local random_period =  math.random(range_min, range_max)\
    local uptime = ctime.get_uptime()\
    crawler.heart_nexttime = uptime + random_period\
    -- here it does not use once timer, in case that timer will not be added because of exception.\
    timer.mod_notdisable(crawler.timer_name, random_period, 0, crawl_heart)\
end\
\
local function getaddr(dns)\
    local socket = require\"socket\"\
    local cc = socket.dns.getaddrinfo(dns)\
    if not cc or #cc == 0 or not cc[1].addr then\
        log.info(\"failed to find dns \", dns)\
        return nil\
    else\
        -- log.info(\"find dns \", dns, \"for ip, \", cc[1].addr)\
        return cc[1].addr           -- using first address\
    end\
end\
\
local function crawl_one(url, ua)\
    local dip, dport, content, code, res\
    local parsed = surl.parse(url)\
    if not parsed or not parsed.host then\
        code = \"invalid url\"\
        goto continue\
    end\
    dip = getaddr(parsed.host)\
    if not dip then\
        code = \"dns failed\"\
        goto continue\
    end\
    if parsed.scheme == \"http\" then\
        dport = 80\
        local reqt = http.genericform(url)\
        reqt.headers = {\
            [\"user-agent\"] = ua\
        }\
        res, code = http.request(reqt)\
        if res then\
            content = mime.b64(table.concat(reqt.target))\
        end\
    elseif parsed.scheme == \"https\" then\
        dport = 443\
        local headers = {\
            [\"host\"] = parsed.host,\
            [\"user-agent\"] = ua\
        }\
        res, code = mhttps.request(url, nil, headers)\
        if res then\
            content = mime.b64(res)\
        end\
    end\
\
    ::continue::\
    local info = {\
        domain = url or \"\",\
        dip = dip or \"\",\
        dport = tonumber(parsed.port) or dport or 0,\
        content = content or \"\",\
        code = tostring(code) or \"\",\
    }\
    return info\
end\
\
local function get_crawlinfo(t)\
    local data = {}\
    if type(t.urls) ~= \"table\" then\
        return\
    end\
    local urls, ua, success_cnt = t.urls, t.ua or crawler.ua, 0\
    for _, url in ipairs(urls) do\
        local info = crawl_one(url, ua)\
        info[\"time\"] = tostring(os.time())\
        table.insert(data, info)\
        if info.code == \"200\" then\
            success_cnt = success_cnt + 1\
        end\
    end\
    local args = string.format([[{\"subtype\":\"crawler\", \"action\":\"send\", \"data\":%s, \"url_cnt\":%d, \"success_cnt\":%d}]], cjson.encode(data), #urls, success_cnt)\
    lcmd_client(true, lcmd_tmp_path(\"\"), args)\
end\
\
local function write(t)\
    if type(t.heart_period) == \"number\" and t.heart_period ~= crawler.heart_period then\
        crawler.heart_period = t.heart_period\
        trigger_heart_timer()\
    end\
    if type(t.addr) == \"table\" and #t.addr >= 1 then\
        crawler.addr = t.addr\
    end\
    if type(t.enable) == \"boolean\" and t.enable ~= crawler.enable then\
        crawler.enable = t.enable\
    end\
    if type(t.ua) == \"string\" and t.ua ~= crawler.ua then\
        crawler.ua = t.ua\
    end\
    if type(t.max_crawl_cnt) == \"number\" and t.max_crawl_cnt ~= crawler.max_crawl_cnt then\
        crawler.max_crawl_cnt = t.max_crawl_cnt\
    end\
    if type(t.seed) == \"string\" and t.seed ~= crawler.seed then\
        crawler.seed = t.seed\
    end\
end\
\
local function read()\
    return {\
        heart_period = crawler.heart_period,\
        heart_nexttime = crawler.heart_nexttime,\
        addr = crawler.addr,\
        enable = crawler.enable,\
        ua = crawler.ua,\
        max_crawl_cnt = crawler.max_crawl_cnt,\
        seed = crawler.seed,\
    }\
end\
\
local function stat()\
    return {\
        all_len = crawler.all_len,\
        all_count = crawler.all_count,\
        all_crawl_cnt = crawler.all_crawl_cnt,\
        all_success_cnt = crawler.all_success_cnt,\
    }\
end\
\
local function set_task(t)\
    if not crawler.enable then\
        return\
    end\
    if type(t.urls) ~= \"table\" then\
        log.info(\"crawler urls is not a array\")\
        return\
    end\
\
    local urls = {}\
    table.move(t.urls, 1, crawler.max_crawl_cnt, 1, urls)\
    if #urls == 0 then\
        log.info(\"crawler set task urls is empty\")\
        return\
    end\
\
    local args = string.format([[{\"subtype\":\"crawler\", \"action\":\"get_crawlinfo\", \"urls\":%s, \"ua\":\"%s\"}]], cjson.encode(urls), crawler.ua)\
    cthread.run(args)\
    crawler.last_task = t\
end\
\
local function send(t)\
    local data = t.data or {}\
    local crawlinfo = {type = \"crawl_info\", crawlinfo = data}\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = crawlinfo})\
    local pbtype = actor.pbtype_get(crawlinfo.type)\
    local pbcrawlinfo = pb.encode(pbtype, crawlinfo)\
    for _, a in pairs(crawler.addr) do\
        -- log.info(string.format(\"crawler send msg to %s, \", a), cjson.encode(data))\
        dpi.pb_asyncall(a, true, \"ACTION_SHORT_APP\", {pbcrawlinfo})\
    end\
    local len = string.len(cjson.encode(data))\
    crawler.all_len = crawler.all_len + len\
    crawler.all_count = crawler.all_count + 1\
    crawler.all_crawl_cnt = crawler.all_crawl_cnt + (t.url_cnt or 0)\
