end\
\
actor.pbtype_add(\"gw_stat\", \".plugin.GatewayState\")\
actor.pbtype_add(\"crawl_info\", \".plugin.CrawlArr\")\
\
actor.action_set(crawler.subtype, \"read\", read, [[read crawler conf]])\
actor.action_set(crawler.subtype, \"write\", write, [[set crawler conf, {heart_period = number, addr = list, enable = boolean, ua = string, max_crawl_cnt = number}]])\
