\
local policy = {}\
\
-- action int value\
policy.actint = {\
    continue = 0x00,\
    fin = 0x01,\
    drop = 0x02,\
    dscp = 0x05,\
}\
\
-- get current specific time and day of week\
function policy.date_fmt()\
    local date = os.date([[*t]])\
    -- date.wday: Sunday 1, Monday 2, Tuesday 3, Wednesday 4, Thursday 5, Friday 6, Saturday 7\
    local wday = date.wday - 1\
    if wday == 0 then\
        wday = 7\
    end\
    return date, wday\
end\
\
--- get action value\
function policy.get_action(t)\
    return policy.actint[t.actkey]\
end\
\
--- get action by value\
function policy.get_actint(int)\
    for action, value in pairs(policy.actint) do\
        if value == (int & 0xff) then\
            if action == \"dscp\" then\
                return \"dscp_\"..(int >> 8)\
            end\
            return action\
        end\
    end\
end\
\
-- time conflict check\
local function check_time_conflict(tbl)\
    for k, v in pairs(tbl) do\
        local shour, smin, ssec, ehour, emin, esec = v.start_hour, v.start_min, v.start_sec, v.end_hour, v.end_min, v.end_sec\
        -- 配置全天00:00-24:00不应该有其它配置\
        if shour == 0 and smin == 0 and ssec == 0 and ehour == 24 and emin == 0 and esec == 0 then return true end\
        local start_t = (shour * 3600) + (smin *60) + ssec\
        local end_t = (ehour * 3600) + (emin *60) + esec\
        for index, time in pairs(tbl) do\
            local start_tc = (time.start_hour * 3600) + (time.start_min * 60) + time.start_sec\
            local end_tc = (time.end_hour * 3600) + (time.end_min * 60) + time.end_sec\
            -- 开始和结束时间不在其它范围中\
            if index ~= k and ((start_t >= start_tc and start_t <= end_tc) or (end_t >= start_tc and end_t <= end_tc)) then\
                return true\
            end\
        end\
    end\
    return false\
end\
\
-- parse and check the time in the format \"00:00-24:00\"\
local function parse_check_daytime(daytime)\
    if type(daytime) ~= \"string\" then return false end\
\
    local t = {}\
    local times = {mystring.split(daytime, \",\")}\
    if #times > 3 then return false end\
    for _, vd in ipairs(times) do\
        local shour, smin, ssec, ehour, emin, esec = string.match(vd, \"^(%d?%d):([0-5]?%d):?([0-5]?%d?)%-(%d?%d):([0-5]?%d):?([0-5]?%d?)$\")\
        if not shour or not smin or not ehour or not emin then return false end\
        shour = tonumber(shour)\
        smin = tonumber(smin)\
        ssec = tonumber(ssec) or 0\
        ehour = tonumber(ehour)\
        emin = tonumber(emin)\
        esec = tonumber(esec) or 0\
        if ehour < shour or shour < 0 or shour > 24 or ehour < 0 or ehour > 24 or emin < smin or esec < ssec then\
            return false\
        end\
        table.insert(t, {start_hour = shour, start_min = smin, start_sec = ssec, end_hour = ehour, end_min = emin, end_sec = esec})\
    end\
    if #t > 1 and check_time_conflict(t) then return false end\
    return true, t\
end\
\
-- parse and check the week in the format \"1,2,3,4,5,6,7\"\
local function parse_weekday(weekday)\
    if type(weekday) ~= \"string\" then return false end\
    if weekday == \"\" then\
        return {\
            [1] = true,\
            [2] = true,\
            [3] = true,\
            [4] = true,\
            [5] = true,\
            [6] = true,\
            [7] = true\
        }\
    end\
    local t = {}\
    local wday = {mystring.split(weekday, \",\")}\
    for _, vw in ipairs(wday) do\
        if not myutil.is_numeric_string(vw) or tonumber(vw) < 1 or tonumber(vw) > 7 then\
            return false\
        end\
        local number = tonumber(vw)\
        if number then t[number] = true end\
    end\
    return t\
end\
\
-- verification time parameter format\
function policy.parse_time(times)\
    local res = {}\
    if type(times) ~= \"table\" then\
        return false\
    end\
    local weekdays, time = times.weekdays or \"\", times.time or \"\"\
    if time == \"\" then\
        time = \"00:00-24:00\"\
    end\
    local wday = parse_weekday(weekdays)\
    if not wday then\
        return false\
    end\
    local ok, dtime = parse_check_daytime(time)\
    if not ok then\
        return false\
    end\
    res = {weekdays = wday, time = dtime, windex = 0, tindex = 0, lasttime = 0}\
\
    return true, res\
end\
\
-- check whether the current time is within the policy range\
function policy.check_time(date, wday, times)\
    local time_matched, timeindex = false, 0\
    local weekdays, time = times.weekdays, times.time\
\
    if not weekdays[wday] then\
        return time_matched, nil\
    end\
    local date_t = (date.hour * 3600) + (date.min * 60) + date.sec\
    for tindex,vd in pairs(time) do\
        local start_tc = (vd.start_hour * 3600) + (vd.start_min * 60) + vd.start_sec\
        local end_tc = (vd.end_hour * 3600) + (vd.end_min * 60) + vd.end_sec\
        if start_tc <= date_t and date_t < end_tc then\
            time_matched, timeindex = true, tindex\
            break\
        end\
    end\
\
    return time_matched, timeindex\
end\
\
-- u01 upload\
function policy.send_uniform(subtype, addr, sendtype, array)\
