        return false, \"Policy is not a JSON object.\"\
    end\
    if type(list_max_cnt) ~= \"number\" then\
        return false, \"list_max_cnt is not a number.\"\
    end\
\
    if not msg.index or not msg.action or (msg.action == \"dscp\" and not msg.dscp_value) then\
        return false, \"The policy may lack fields index, action, and dscp_value.\"\
    end\
    if not myutil.is_numeric_string(msg.index) then\
        return false, \"The field index format does not meet the requirements.\"\
    end\
