    end\
    for _, ip_port in pairs(msg.ip_port or {}) do\
        local ip, port = myip.split_ipport(ip_port)\
        local ok, _ = myip.is_ipstring(ip)\
        if not ok or (port and (not myutil.is_numeric_string(port) or not myip.is_port(tonumber(port)))) then\
