\
function dmpapp.postinit()\
    local filter_appid = {}\
    for _, appid in ipairs(black_appid) do\
        filter_appid[appid] = true\
    end\
    dmpapp.filter_appid = filter_appid\
    timer.mod(dmpapp.timer_name, dmpapp.period, 0, upload_app)\
end\
