\
local domcent = {\
    type = \"domcent\",\
    subtype = \"domcent\",\
    help = \"get domain and manage\",\
    tname = \"clean_timeout\",\
    period = 0,\
    http_sindex = nil,\
    https_sindex = nil,\
    dns_sindex = nil,\
    dns_info = {\
