        -- }\
    },\
    max_maccnt = 50,\
    clean_maccnt = 10,\
    max_ipcnt = 1000,\
    clean_ipcnt = 100,\
}\
\
local function clean_cache(info, cleancnt, key_cnt)\
    local t ={}\
    for k,v in pairs(info) do\
        if type(v) == \"table\" then\
            table.insert(t, {key = k, time = v.uptime})\
        end\
    end\
    table.sort(t, function (t1, t2) return t1.time < t2.time end)\
    for i=1, cleancnt do\
        if t[i] and t[i].key and info[t[i].key] then\
            info[t[i].key] = nil\
            info[key_cnt] = info[key_cnt] - 1\
        end\
    end\
end\
\
local function check_timeout()\
    local timenow = ctime.get_uptime()\
    for kk,vv in pairs(domcent.dns_info) do\
        if type(vv) == \"table\" then\
            for k,v in pairs(vv) do\
                if type(v) == \"table\" and v.uptime and timenow - v.uptime >= v.maxttl then\
                    domcent.dns_info[kk][k] = nil\
                    domcent.dns_info[kk][\"ipcnt\"] = domcent.dns_info[kk][\"ipcnt\"] - 1\
                end\
            end\
            if domcent.dns_info[kk][\"ipcnt\"] == 0 then\
                domcent.dns_info[kk] = nil\
                domcent.dns_info.maccnt = domcent.dns_info.maccnt - 1\
            end\
        end\
    end\
end\
\
local function dns_deal(msg)\
    if domcent.period <= 0 then\
        return\
    end\
    local data = msg.dnstable\
    if not domcent.dns_info[data.mac] then\
        if domcent.dns_info.maccnt >= domcent.max_maccnt then\
            clean_cache(domcent.dns_info, domcent.clean_maccnt, \"maccnt\")\
        end\
        domcent.dns_info[data.mac] = {\
            ipcnt = 0\
        }\
        domcent.dns_info.maccnt = domcent.dns_info.maccnt + 1\
    end\
    if domcent.dns_info[data.mac].ipcnt >= domcent.max_ipcnt then\
        check_timeout()\
        if domcent.dns_info[data.mac].ipcnt >= domcent.max_ipcnt then\
            clean_cache(domcent.dns_info[data.mac], domcent.clean_ipcnt, \"ipcnt\")\
        end\
    end\
    local tt = {\
        domain = data.domain,\
        uptime = ctime.get_uptime(),\
        maxttl = (msg.maxttl == 0) and 60 or (msg.maxttl or 60),\
    }\
    for _,ip in pairs({mystring.split(msg.ips, \",\")}) do\
        if not domcent.dns_info[data.mac][ip] then\
            domcent.dns_info[data.mac].ipcnt = domcent.dns_info[data.mac].ipcnt + 1\
        end\
        domcent.dns_info[data.mac][ip] = tt\
    end\
    domcent.dns_info[data.mac].uptime = ctime.get_uptime()\
end\
\
local function dnscheck(t)\
    local mac, ip = t.mac, t.ip\
    if domcent.dns_info[mac] and domcent.dns_info[mac][ip] then\
        return domcent.dns_info[mac][ip]\
    end\
end\
local function write(t)\
    if type(t.period) == \"number\" and t.period >= 0 and t.period ~= domcent.period then\
        domcent.period = t.period\
        timer.mod(domcent.tname, domcent.period, 0, check_timeout)\
    end\
    if type(t.max_maccnt) == \"number\" and t.max_maccnt >= 0 and t.max_maccnt ~= domcent.max_maccnt then\
        domcent.max_maccnt = t.max_maccnt\
    end\
    if type(t.max_ipcnt) == \"number\" and t.max_ipcnt >= 0 and t.max_ipcnt ~= domcent.max_ipcnt then\
        domcent.max_ipcnt = t.max_ipcnt\
    end\
    if type(t.clean_maccnt) == \"number\" and t.clean_maccnt >= 0 and t.clean_maccnt ~= domcent.clean_maccnt then\
        domcent.clean_maccnt = t.clean_maccnt\
    end\
    if type(t.clean_ipcnt) == \"number\" and t.clean_ipcnt >= 0 and t.clean_ipcnt ~= domcent.clean_ipcnt then\
        domcent.clean_ipcnt = t.clean_ipcnt\
    end\
end\
\
local function stat(t)\
    if type(t.mac) == \"string\" then\
        if t.mac == \"all\" then\
            return domcent.dns_info\
        elseif domcent.dns_info[t.mac] then\
            return domcent.dns_info[t.mac]\
        else\
            return { error = \"mac not found\" }\
        end\
    end\
    return { maccnt = domcent.dns_info.maccnt }\
end\
\
function domcent.postinit()\
    timer.mod(domcent.tname, domcent.period, 0, check_timeout)\
    domcent.dns_sindex = actor.subscribe(\"DNS\", dns_deal)\
end\
\
function domcent.finish()\
    timer.del(domcent.tname)\
    if domcent.dns_sindex then\
        actor.unsubscribe(\"DNS\", domcent.dns_sindex)\
    end\
end\
\
actor.action_set(domcent.subtype, \"read\", function () return {period = domcent.period, max_maccnt = domcent.max_maccnt, max_ipcnt = domcent.max_ipcnt, clean_maccnt = domcent.clean_maccnt, clean_ipcnt = domcent.clean_ipcnt} end, \"read domcent conf\")\
actor.action_set(domcent.subtype, \"write\", write, \"set domcent conf, {period = number}, 0 means disable\")\
