actor.action_set(domcent.subtype, \"dnscheck\", dnscheck, \"{mac = xx:xx:xx, ip = 0.0.0.0}, check domain with mac and ip\")\
\
return domcent\
"
, '@'.."./service/domcent.lua" ) )

