package.preload[ "https" ] = assert( (loadstring or load)(
"local cjson = require(\"cjson\")\
local kernel = require(\"c.kernel\")\
local actor = require(\"luactor\")\
local myip = require(\"myip\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local https = {\
    subtype = \"https\",\
    period = 0,\
    timer_name = 'https_get',\
    all_count = 0,\
    all_len = 0,\
    pub_cnt = 0,\
    help = \"get https from kernel and send to server\"\
}\
\
local function https_get_one(sbytes, pos, len, now)\
    local all_len, appid = string.unpack('=II', sbytes, pos)\
    local sip = string.sub(sbytes, pos + 8, pos + 23)\
    local dip = string.sub(sbytes, pos + 24, pos + 39)\
    local sport, dport, ruleid, mac, svrname_len, next_post = string.unpack('=HHIc6H', sbytes, pos + 40)\
    local svrname = string.unpack('c'..svrname_len, sbytes, next_post)\
\
    assert(pos + all_len - 1 <= len and all_len >= svrname_len + 56)\
    local https_table = {\
        type = \"https_domain\",\
        mac = myip.mac_ntoa(mac),\
        sip = myip.inet_ntoa(sip),\
        dip = myip.inet_ntoa(dip),\
        sport = sport,\
        dport = dport,\
        appid = appid,\
        ruleid = ruleid,\
        domain = svrname,\
        timestamp = tostring(now)\
    }\
\
    -- log.info(\"recv one https_table from kernel, \", cjson.encode(https_table))\
    actor.publish({msgtype = \"HTTPS\", https_table = https_table})\
    https.pub_cnt = https.pub_cnt +1\
    if https.period > 0 then\
        lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = https_table})\
        https.all_count = https.all_count + 1\
        https.all_len = https.all_len + string.len(cjson.encode(https_table))\
    end\
    return all_len\
end\
\
local function https_get(sbytes)\
    local len, used_len = sbytes:len(), 0\
    local now = os.time()\
    while used_len < len do\
        local one_size = https_get_one(sbytes, used_len + 1, len, now)\
        used_len = used_len + one_size\
    end\
    assert(used_len == len)\
    return len\
end\
\
local function write(msg)\
    log.info(\"https period change to\", msg.period, \"from \", https.period)\
    if msg.period and msg.period ~= https.period then\
        https.period = msg.period\
        if https.period > 0 then\
            timer.mod(https.timer_name, https.period, 0, function () kernel.call(CENUM.MEMSHR_K2U_SSL_SVRNAME, \"\", https_get) end)\
        else\
            timer.mod(https.timer_name, 5, 0, function () kernel.call(CENUM.MEMSHR_K2U_SSL_SVRNAME, \"\", https_get) end)\
        end\
    end\
end\
\
function https.preinit()\
    -- if kernel module not reload, it must clean first\
    kernel.send(CENUM.MEMSHR_U2K_SSL_SVRNAME_FLUSH, \"\")\
end\
\
function https.postinit()\
    timer.mod(https.timer_name, 5, 0, function () kernel.call(CENUM.MEMSHR_K2U_SSL_SVRNAME, \"\", https_get) end)\
end\
\
actor.action_set(https.subtype, \"get_kernel\", function () kernel.call(CENUM.MEMSHR_K2U_SSL_SVRNAME, \"\", https_get) end, \
                 \"get https from kernel manualy\")\
actor.action_set(https.subtype, \"read\", function () return {period = https.period} end, \"read https conf\")\
actor.action_set(https.subtype, \"write\", write, [[set https period, {period = number}, 0 means close engine]])\
actor.action_set(https.subtype, \"stat\", function () return {all_len = https.all_len, all_count = https.all_count, pub_cnt =https.pub_cnt} end, \"read https stat\")\
actor.action_set(https.subtype, \"show_conf_svr\", function() return {type = \"lua_cmd\", subtype = \"https\"} end, \
                 [[show https conf msg to oper svr]])\
\
return https\
"
, '@'.."./service/https.lua" ) )

package.preload[ "immddata" ] = assert( (loadstring or load)(
"local actor = require(\"luactor\")\
local cjson = require(\"cjson\")\
local timer = require(\"timer\")\
local log = require(\"log\")\
local dpi = require(\"svrcomm.dpi\")\
\
\
local immddata = {\
    type = \"__immd_data\",\
    subtype = \"__immd_data\",\
    help = \"immediate data upload\",\
\
    max_svr_cnt = 8,\
\
    seed = \"\",\
    svrs = {\
    --[[\
        {\
            conf = {\
                addr = STRING,\
                ftypes = { STRING },\
            },\
            stat = {\
                upload_raw_len = NUMBER,\
                upload_succ_len = NUMBER,\
                upload_succ_count = NUMBER,\
                upload_fail_len = NUMBER,\
                upload_fail_count = NUMBER,\
            },\
            finicall = FUNCTION,\
        },\
    ]]--\
    },\
\
    extkeys = nil, -- string array or nil\
}\
\
\
local function svr_parse(t)\
    if type(t.addr) ~= \"string\" or t.addr == \"\" then\
        log.error(\"immddata invalid addr\")\
        return nil\
    end\
    local ftypes = type(t.ftypes) == \"table\" and t.ftypes or {}\
    local ftype_cnt = 0\
    for _, ftype in pairs(ftypes) do\
        if type(ftype) ~= \"string\" or ftype == \"\" then\
            log.error(\"immddata invalid ftype\")\
            return nil\
        end\
        ftype_cnt = ftype_cnt + 1\
    end\
    if ftype_cnt ~= #ftypes then\
        -- make sure that it is string array\
        log.error(\"immddata invalid ftypes\")\
        return nil\
    end\
\
    local v = {\
        conf = {\
            addr = t.addr,\
            ftypes = ftypes,\
        },\
        stat = {\
            upload_raw_len = 0,\
            upload_succ_len = 0,\
            upload_succ_count = 0,\
            upload_fail_len = 0,\
            upload_fail_count = 0,\
        },\
    }\
    v.finicall = function (err, data)\
        if not err then\
            v.stat.upload_succ_count = v.stat.upload_succ_count + 1\
            v.stat.upload_succ_len = v.stat.upload_succ_len + #data\
        else\
            v.stat.upload_fail_count = v.stat.upload_fail_count + 1\
            v.stat.upload_fail_len = v.stat.upload_fail_len + #data\
            log.warn(\"immddata fini: \", err)\
        end\
    end\
\
    return v\
end\
\
local function write(t)\
    local need_save = false\
\
    if type(t.seed) == \"string\" then\
        if t.seed == immddata.seed then\
            -- avoid that platform repeatedly issue identical configurations\
            return\
        end\
        if type(t.rules) ~= \"table\" then\
            return\
        end\
        immddata.seed = t.seed\
        need_save = true\
    end\
\
    if type(t.rules) == \"table\" then\
        local svrs = {}\
        for _, item in ipairs(t.rules) do\
            local v = svr_parse(item)\
            if v then\
                table.insert(svrs, v)\
                if #svrs >= immddata.max_svr_cnt then\
                    break\
                end\
            end\
        end\
        immddata.svrs = svrs\
        need_save = true\
    end\
\
    if need_save then\
        lcmd_run{type = \"sys\", action = \"save_conf_change\"}\
    end\
end\
\
local function read()\
    local t = {\
        seed = immddata.seed,\
        rules = {},\
    }\
    for _, v in ipairs(immddata.svrs) do\
        table.insert(t.rules, v.conf)\
    end\
    return t\
end\
\
local function stat()\
    local t = {}\
    for _, v in ipairs(immddata.svrs) do\
        table.insert(t, {\
            addr = v.conf.addr,\
            stat = v.stat,\
        })\
    end\
    return t\
end\
\
local function set_bconf(t)\
    if type(t.max_svr_cnt) == \"number\" and t.max_svr_cnt > 0 and t.max_svr_cnt ~= immddata.max_svr_cnt then\
        immddata.max_svr_cnt = t.max_svr_cnt\
    end\
    if type(t.extkeys) == \"table\" then\
        immddata.extkeys = t.extkeys\
        if #immddata.extkeys == 0 then\
            immddata.extkeys = nil\
        else\
            local valid = true\
            for _, key in ipairs(immddata.extkeys) do\
                if type(key) ~= \"string\" or key == \"\" then\
                    valid = false\
                    break\
                end\
            end\
            if not valid then\
                immddata.extkeys = nil\
            end\
        end\
    end\
end\
\
local function get_bconf()\
    return {\
        max_svr_cnt = immddata.max_svr_cnt,\
        extkeys = immddata.extkeys,\
    }\
end\
\
local function show_conf_svr()\
    return {\
        type = immddata.type,\
        seed = immddata.seed,\
    }\
end\
\
local function show_conf_save()\
    local t = {\
        type = immddata.type,\
        action = \"write\",\
        seed = immddata.seed,\
        rules = {},\
    }\
    for _, v in ipairs(immddata.svrs) do\
        table.insert(t.rules, v.conf)\
    end\
    return t\
end\
\
local function add(msg)\
    if type(msg.data) ~= \"table\" then\
        log.error(\"must add table for immddata\")\
        return\
    end\
    local dt = msg.data\
    if #dt == 0 then\
        if type(dt.type) ~= \"string\" then\
            log.error(\"no type for immddata\")\
            return\
        end\
        dt = { dt }\
    end\
\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = dt})\
\
    if type(msg.addrs) == \"table\" then\
        -- customize addrs, just upload\
        for _, addr in ipairs(msg.addrs) do\
            dpi.async_immd_send(addr, CENUM.COMM_ACTION_DEVOPS_DPI_IMMDDATA, dt, msg.extkeys, msg.finicall)\
        end\
        return\
    end\
\
    for _, v in ipairs(immddata.svrs) do\
        local rdt = dt\
        if #v.conf.ftypes > 0 then\
            rdt = {}\
            for _, data in ipairs(dt) do\
                for _, ftype in ipairs(v.conf.ftypes) do\
                    if data.type == ftype then\
                        table.insert(rdt, data)\
                        break\
                    end\
                end\
            end\
        end\
        if #rdt > 0 then\
            dpi.async_immd_send(v.conf.addr, CENUM.COMM_ACTION_DEVOPS_DPI_IMMDDATA, rdt, immddata.extkeys, v.finicall)\
        end\
    end\
end\
\
\
actor.action_set(immddata.subtype, \"write\", write,\"write immddata conf\")\
actor.action_set(immddata.subtype, \"read\", read, \"read immddata conf\")\
actor.action_set(immddata.subtype, \"stat\", stat, \"read immddata stat\")\
actor.action_set(immddata.subtype, \"set_bconf\", set_bconf, \"set bconf\")\
actor.action_set(immddata.subtype, \"get_bconf\", get_bconf, \"get bconf\")\
actor.action_set(immddata.subtype, \"show_conf_svr\", show_conf_svr, \"show immddata conf msg to oper svr\")\
actor.action_set(immddata.subtype, \"show_conf_save\", show_conf_save, \"save immddata conf to local file\")\
actor.action_set(immddata.subtype, \"add\", add, \"add json data for immddata send, {data = table}\")\
\
return immddata\
\
"
, '@'.."./service/immddata.lua" ) )

