package.preload[ "locdata" ] = assert( (loadstring or load)(
"local actor = require\"luactor\"\
local cjson = require\"cjson\"\
local lfs = require\"lfs\"\
\
local locdata = {\
    type = \"locdata\",\
    subtype = \"locdata\",\
    help = \"dump send data to local dir\",\
\
    dir = \"\",\
    maxline = 10000,\
    enable = false,\
    stat = {},\
}\
\
local function tconf_init(t)\
    if not locdata.stat[t.type] then\
        locdata.stat[t.type] = {\
            fname = locdata.dir .. \"/\" .. \"locdata-\" .. t.type ..\".\" .. os.date(\"%Y%m%d_%H%M%S\") .. \".json\",\
            cnt = 0\
        }\
    end\
end\
\
local function save_data(t)\
    local stat = locdata.stat[t.type]\
    if locdata.maxline > 0 and stat.cnt >= locdata.maxline then\
        return\
    end\
\
    local fp = io.open(stat.fname, 'a')\
    if fp then\
        fp:write(cjson.encode(t) .. \"\\n\")\
        fp:close()\
        stat.cnt = stat.cnt + 1\
    end\
end\
\
local function add(msg)\
    if locdata.dir == \"\" or not locdata.enable then\
        return\
    end\
    local t = msg.data\
    if type(t.type) == \"string\" then\
        tconf_init(t)\
        save_data(t)\
    elseif #t > 0 then\
        -- array\
        for _, v in ipairs(t) do\
            if type(v.type) == \"string\" then\
                tconf_init(v)\
                save_data(v)\
            end\
        end\
    end\
end\
\
local function read()\
    return {\
        dir = locdata.dir,\
        maxline = locdata.maxline,\
        enable = locdata.enable\
    }\
end\
\
local function stat()\
    return locdata.stat\
end\
\
local function clean()\
    for _,v in pairs(locdata.stat) do\
        os.remove(v['fname'])\
    end\
    locdata.stat = {}\
end\
\
local function write(t)\
    if type(t.dir) == \"string\" and t.dir ~= locdata.dir then\
        local attr = lfs.attributes(t.dir)\
        if not attr or attr.mode ~= \"directory\" then\
            local ok, err = lfs.mkdir(t.dir)\
            if not ok then\
                return \"failed to create directory, err is \" .. err\
            end\
        end\
        clean()\
        locdata.dir = t.dir\
    end\
\
    if type(t.maxline) == \"number\" and t.maxline > 0 then\
        locdata.maxline = t.maxline\
    end\
\
    if type(t.enable) == \"boolean\" and t.enable ~= locdata.enable then\
        locdata.enable = t.enable\
    end\
end\
\
actor.action_set(locdata.subtype, \"add\", add, \"add data to locdata {type = xx, ...}\")\
actor.action_set(locdata.subtype, \"read\", read, \"read locdata conf\")\
actor.action_set(locdata.subtype, \"stat\", stat, \"read locdata stat\")\
actor.action_set(locdata.subtype, \"write\", write, 'write locdata, {\"dir\":xxx, \"maxline\":xxx}')\
actor.action_set(locdata.subtype, \"clean\", clean, 'delete locdata files')\
\
return locdata\
"
, '@'.."./service/locdata.lua" ) )

