--\
-- Module\
--\
local mhttps = {\
    PORT       = 443,\
    TIMEOUT    = 5\
}\
\
--------------------------------------------------------------------\
-- Auxiliar Functions\
--------------------------------------------------------------------\
\
-- Insert default HTTPS port.\
local function default_https_port(u)\
    return url.build(url.parse(u, {port = mhttps.PORT}))\
end\
\
-- Convert an URL to a table according to Luasocket needs.\
local function urlstring_totable(url, body, result_table, user_headers)\
    url = {\
        url = default_https_port(url),\
        method = body and \"POST\" or \"GET\",\
        sink = ltn12.sink.table(result_table)\
    }\
    if body then\
        url.source = ltn12.source.string(body)\
        url.headers = {\
            [\"content-length\"] = #body,\
            [\"content-type\"] = \"application/x-www-form-urlencoded\",\
        }\
    end\
    if user_headers then\
        if not url.headers then\
            url.headers = {}\
        end\
        for k, v in pairs(user_headers) do\
            url.headers[k] = v\
        end\
    end\
    return url\
end\
\
-- Forward calls to the real connection object.\
local function reg(conn)\
    local mt = getmetatable(conn.sock).__index\
    for name, method in pairs(mt) do\
        if type(method) == \"function\" then\
            conn[name] = function (self, ...)\
                return method(self.sock, ...)\
            end\
        end\
    end\
end\
\
-- Return a function which performs the SSL/TLS connection.\
local function tcp()\
    -- 'create' function for LuaSocket\
    return function ()\
        local conn = {}\
        conn.sock = try(socket.tcp())\
        local st = getmetatable(conn.sock).__index.settimeout\
        function conn:settimeout(...)\
            return st(self.sock, mhttps.TIMEOUT)\
        end\
        -- Replace TCP's connection function\
        function conn:connect(host, port)\
            try(self.sock:connect(host, port))\
            local newsock = try(ssl.wrap(self.sock:getfd()))\
            self.sock:setfd(-1)\
            self.sock = newsock\
            self.sock:sni(host)\
            self.sock:settimeout(mhttps.TIMEOUT)\
            try(self.sock:dohandshake())\
            reg(self)\
            return 1\
        end\
        return conn\
    end\
end\
\
--------------------------------------------------------------------\
-- Main Function\
--------------------------------------------------------------------\
\
-- Make a HTTP request over secure connection.  This function receives\
--  the same parameters of LuaSocket's HTTP module (except 'proxy' and\
--  'redirect') plus LuaSec parameters.\
--\
-- @param url mandatory (string or table)\
-- @param body optional (string)\
-- @return (string if url == string or 1), code, headers, status\
--\
local function request(url, body, user_headers)\
    local result_table = {}\
    local stringrequest = type(url) == \"string\"\
    if stringrequest then\
        url = urlstring_totable(url, body, result_table, user_headers)\
    else\
        url.url = default_https_port(url.url)\
    end\
    if http.PROXY or url.proxy then\
        return nil, \"proxy not supported\"\
    elseif url.redirect then\
        return nil, \"redirect not supported\"\
    elseif url.create then\
        return nil, \"create function not permitted\"\
    end\
    -- New 'create' function to establish a secure connection\
    url.create = tcp()\
    local res, code, headers, status = http.request(url)\
    if res and stringrequest then\
        return table.concat(result_table), code, headers, status\
    end\
    return res, code, headers, status\
end\
\
local function download(url, body, filepath, headers)\
    if type(url) ~= \"string\" or type(filepath) ~= \"string\" then\
        return \"need valid params\"\
    end\
\
    local result, code, headers, status = request(url, body, headers)\
    if not result then\
        return code  -- here, code is err_msg\
    end\
\
    local f = io.open(filepath, \"w\")\
    if not f then\
        return \"failed to write file \" .. filepath\
    end\
    f:write(result)\
    f:close()\
    return nil, code, headers, status\
end\
\
--------------------------------------------------------------------------------\
-- Export module\
--\
\
mhttps.request = request\
mhttps.download = download\
\
return mhttps\
"
, '@'.."./lualib/mhttps.lua" ) )

