local cjson = require(\"cjson\")\
local timer = require(\"timer\")\
local log = require(\"log\")\
local myip = require(\"myip\")\
local myutil = require(\"myutil\")\
local mystring = require(\"mystring\")\
local ctime = require(\"c.time\")\
\
local murl = {\
    type = \"murl\",\
    subtype = \"murl\",\
    help = \"send murl data to server\",\
    timer_name = \"murldata_send\",\
\
    addrs = {},\
    http_enable = false,\
    https_enable = false,\
    period = 0,\
    maxcnt = 100,\
    extkeys = nil,\
\
    httpmt = {},\
    httpcnt = 0,\
    httpsmt = {},\
    httpscnt = 0,\
\
    lasttime = 0,  -- last upload time\
\
    stat = {\
        upload_succ_count = 0,\
        upload_succ_len = 0,\
        upload_fail_count = 0,\
        upload_fail_len = 0,\
    },\
}\
\
function murl.upload_finicall(err, data)\
    if not err then\
        murl.stat.upload_succ_count = murl.stat.upload_succ_count + 1\
        murl.stat.upload_succ_len = murl.stat.upload_succ_len + #data\
    else\
        murl.stat.upload_fail_count = murl.stat.upload_fail_count + 1\
        murl.stat.upload_fail_len = murl.stat.upload_fail_len + #data\
    end\
end\
\
function murl.upload_data(maxcnt_trigger)\
