    murl.lasttime = uptime \
end\
\
function murl.maxcnt_check_upload()\
    if murl.httpcnt + murl.httpscnt >= murl.maxcnt then\
        murl.upload_data(true)\
        timer.mod(murl.timer_name, murl.period, 0, murl.upload_data)\
    end\
end\
\
function murl.lasttime_init_check()\
    if murl.lasttime == 0 then\
        murl.lasttime = ctime.get_uptime()\
    end\
end\
\
function murl.collect_http(msg)\
    if not murl.http_enable then\
        return\
    end\
    local now = myutil.get_timestamp()\
