    end\
    timer.del(murl.timer_name)\
end\
\
\
actor.action_set(murl.subtype, \"write\", write, \"set murl conf\")\
actor.action_set(murl.subtype, \"read\", read, \"read murl conf\")\
actor.action_set(murl.subtype, \"stat\", stat, \"read murl stat\")\
\
return murl\
\
"
, '@'.."./service/murl.lua" ) )

package.preload[ "myfile" ] = assert( (loadstring or load)(
"local cjson = require(\"cjson\")\
local ccrypto = require(\"c.crypto\")\
\
local myfile = {\
    magic = 0x20240927,\
}\
\
function myfile.existed(src)\
    local fin = io.open(src, \"r\")\
    if fin == nil then\
        return nil\
    end\
    fin:close()\
    return \"existed\"\
end\
\
function myfile.copy(src, dst)\
    local fin = io.open(src, \"r\")\
    local fout = io.open(dst, \"w\")\
    if fin == nil or fout == nil then\
        if fin then fin:close() end\
        if fout then fout:close() end\
        return \"failed to copy\"\
    end\
    fout:write(fin:read(\"a\"))\
    fout:close()\
    fin:close()\
    return nil\
end\
\
function myfile.read(fname)\
    local f = io.open(fname, \"r\")\
    if f == nil then\
        return nil, \"failed to read file \"..fname\
    end\
    local data = f:read(\"a\")\
    f:close()\
    return data\
end\
\
function myfile.write(body, fname)\
    local f = io.open(fname, \"w\")\
    if f == nil then\
        return \"failed to write file \" .. fname\
    end\
    f:write(body)\
    f:close()\
    return nil\
end\
\
function myfile.store_json(t, fname)\
    local io = require\"io\"\
    local ok, msg = pcall(cjson.encode, t)\
    if not ok then\
        return msg\
    end\
\
    local f = io.open(fname, \"w\")\
    if f == nil then\
        return \"failed to write file \" .. fname\
    end\
\
    f:write(msg)\
    f:close()\
    return nil\
end\
\
function myfile.load_json(fname)\
    local io = require\"io\"\
\
    local f = io.open(fname, \"r\")\
    if f == nil then\
        return nil, \"failed to read file \" .. fname\
    end\
\
    local content = f:read(\"a\")\
    f:close()\
    if content == nil then\
        return nil, \"Empty read file \" .. fname\
    end\
    \
    local ok, t = pcall(cjson.decode, content)\
    if ok then\
        return t\
    else\
        return nil, \"cjson decode error\" .. t\
    end\
end\
\
function myfile.store_crypto_json(t, fname)\
    if type(fname) ~= \"string\" then\
        return \"file name error \" .. tostring(fname)\
    end\
\
    local ok, msg = pcall(cjson.encode, t)\
    if not ok then\
        return msg\
    end\
\
    local len = #msg\
    local zmsg = ccrypto.zip(msg, len > 1024 and len or 1024)\
    local key = string.pack(\">I8I8\", myfile.magic, len)\
    local cipherdata = ccrypto.encrypt(zmsg, key, \"ecb\")\
    local byte = string.pack(\">IIII\", myfile.magic, #cipherdata + 4 * 4, #zmsg, len)\
    byte = byte .. cipherdata\
\
    return myfile.write(byte, fname)\
end\
\
function myfile.load_crypto_json(fname)\
    if type(fname) ~= \"string\" then\
        return nil, \"file name error \" .. tostring(fname)\
    end\
\
    local byte, err = myfile.read(fname)\
    if err then\
        return nil, err\
    end\
    if byte == nil then\
        return nil, \"Empty read file \" .. fname\
    end\
\
    if #byte < 16 then\
        return nil, \"Damaged file \" .. fname\
    end\
    local magic, tlen, zlen, len, nextpos = string.unpack(\">IIII\", byte)\
    if not magic or not tlen or not zlen or not len or not nextpos then\
        return nil, \"failed to load \" .. fname\
    end\
    if #byte ~= tlen or magic ~= myfile.magic then\
        return nil, \"wrong file \" .. fname .. \": magic \" .. string.format(\"%X\", magic) .. \", total_len \" .. tostring(tlen)\
    end\
    local key = string.pack(\">I8I8\", magic, len)\
    local content = ccrypto.decrypt(string.sub(byte, nextpos, -1), key, \"ecb\")\
    content = string.sub(content, 1, zlen)\
    local msg = ccrypto.unzip(content, len)\
    if not msg or #msg ~= len then\
        return nil, \"unzip fail, len \" .. tostring(len) .. \", unzip_len \" .. tostring(#(msg or \"\"))\
    end\
\
    local ok, t = pcall(cjson.decode, msg)\
    if not ok then\
        return nil, \"cjson decode error\" .. t\
    end\
    return t\
end\
\
function myfile.length_of_file(fname)\
    local io = require\"io\"\
\
    local f = io.open(fname, \"r\")\
    if f == nil then\
        return 0\
    end\
\
    local len = f:seek(\"end\")\
    f:close()\
\
    if len and len > 0 then\
        return len\
    end\
    return 0\
end\
\
\
return myfile\
"
, '@'.."./lualib/myfile.lua" ) )

