    local y = fun() or 0\
    if y == 0 then  return 0 end\
    local m = fun() or 0\
    if m == 0 then  return 0 end\
    local d = fun() or 0\
    if d == 0 then  return 0 end\
    local H = fun() or 0\
    if H == 0 then  return 0 end\
    local M = fun() or 0\
    if M == 0 then  return 0 end\
    local S = fun() or 0\
    if S == 0 then  return 0 end\
\
    local ok, timestamp = pcall(os.time, {year=y, month=m, day=d, hour=H,min=M,sec=S})\
