-- 扁平化表\
local function flattenTable(t, result)\
    result = result or {}\
    for k, v in pairs(t) do\
        if type(v) == \"table\" then\
            flattenTable(v, result)\
        else\
            result[k] = v\
        end\
    end\
    return result\
end\
