<s:Envelope xmlns:s=\"http://www.w3.org/2003/05/soap-envelope\">\
    <s:Header>\
        <wsse:Security xmlns:wsse=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd\" xmlns:wsu=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd\">\
            <wsse:UsernameToken>\
                <wsse:Username>%s</wsse:Username>\
                <wsse:Password Type=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordDigest\">%s</wsse:Password>\
                <wsse:Nonce>%s</wsse:Nonce>\
                <wsu:Created>%s</wsu:Created>\
            </wsse:UsernameToken>\
        </wsse:Security>\
    </s:Header>\
    <s:Body xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\">\
        <%s xmlns=\"http://www.onvif.org/ver10/device/wsdl\">%s</%s>\
    </s:Body>\
</s:Envelope>\
]]\
    local passwordValue = passwordDigest or \"\"\
    return string.format(xmlTemplate, username, passwordValue, nonce, created, method, paramsXml, method)\
end\
\
-- 初始化组播socket\
local function muticast_init()\
    local socket, err = try(socket.udp4())\
    if not socket then\
        return nil, err\
    end\
    local ok, ip_addr = myip.getip(onvif.iface)\
    if not ok or ip_addr == \"\" then\
        socket:close()\
        return nil, \"Failed to get \" .. onvif.iface .. \" IP address\"\
    end\
\
    local ok, err = try(socket:setsockname(\"0.0.0.0\", onvif.onvif_port))\
    if not ok then\
        socket:close()\
        return nil, \"Failed to bind socket: \" .. tostring(err)\
    end\
    try(socket:settimeout(0.3))\
    local options = {{\"ip-multicast-if\", ip_addr}, {\"reuseaddr\", true}}\
    for _, opt in ipairs(options) do\
        local ok, err = try(socket:setoption(table.unpack(opt)))\
        if not ok then\
            socket:close()\
            return nil, \"Failed to set socket option: \" .. tostring(err)\
        end\
    end\
\
    return socket\
end\
\
-- tcp socket发送Http请求并接收回复\
local function http_post(url, soapBody)\
    if (url == nil) then\
        return false, nil, \"url is nil\"\
    end\
    local opt = {\
        timeout = 2\
    }\
    local response = http:post(url, soapBody, opt)\
    if (response == nil) or (response == \"\") or (type(response) ~= \"table\") then\
        return false, response, \"response is empty\"\
    end\
    if (response.code ~= 200) then\
        return true, response, response.status_line\
    end\
\
    if (response.headers == nil) or\
        (string.find(string.lower(response.headers[\"content-type\"]), \"application/soap+xml\") ~= nil) or\
        (response.body == nil) then\
        return false, response, \"response is not a soap message\"\
    end\
\
    return true, response, nil\
end\
\
local function extractXAddrs(data)\
    local function validateAndModifyUrl(url)\
        local httpUrl = url and url:match(\"http%S*\")\
        if httpUrl then\
            -- 查找 URL 中第一个空格或特定分隔符，定位 URL 结束位置\
            local endPos = httpUrl:find(\"%s\")\
            if endPos then\
                -- 如果找到空格，则只返回前面的部分（只保留第一个出现的url）\
                httpUrl = httpUrl:sub(1, endPos - 1)\
            end\
            return httpUrl\
        else\
            return nil\
        end\
    end\
\
    -- 尝试匹配 <wsdd:XAddrs>\
    local url = data:match(\"<wsdd:XAddrs>(.-)</wsdd:XAddrs>\")\
    url = validateAndModifyUrl(url)\
    if url then\
        return url\
    end\
\
    -- 尝试匹配 <d:XAddrs>\
    url = data:match(\"<d:XAddrs>(.-)</d:XAddrs>\")\
    url = validateAndModifyUrl(url)\
    if url then\
        return url\
    end\
\
    -- 尝试匹配 <*:XAddrs>\
    url = data:match(\"<([^:]+):XAddrs>(.-)</%1:XAddrs>\")\
    return validateAndModifyUrl(url)\
end\
\
-- 发送组播消息并接收回复\
local function dev_discovery()\
    local dev_count = 0\
    local discover = get_discover_msg()\
    try(onvif.muticast_scoket:sendto(discover, onvif.multicast_ip, onvif.onvif_port))\
    local start = os.time()\
    local _, gateway_ip = myip.getip(onvif.iface)\
    while (os.time() - start < onvif.timeout) do\
        local data, peeraddr, peerport = onvif.muticast_scoket:receivefrom()\
        if data and (peeraddr ~= gateway_ip) then\
            local url = extractXAddrs(data)\
            if url then\
                local devinfo = {}\
                devinfo.address = peeraddr\
                devinfo.data = data\
                devinfo.request_url = url\
                local mac_table = myip.getarp()\
                if mac_table == nil or mac_table[peeraddr] == nil then\
                    log.info(\"[onvif] Failed to get \" .. peeraddr ..\
                                 \" mac address from arp table, The mac address is obtained from the arp table after the tcp connection is attempted\")\
                else\
                    devinfo.mac = mac_table[peeraddr]\
                end\
                table.insert(onvif.devinfo_list, devinfo)\
                dev_count = dev_count + 1\
            else\
                log.info(\"[onvif] Failed to get \" .. peeraddr .. \" request url \" .. \"response data: \" .. data)\
            end\
        end\
    end\
    return dev_count\
end\
\
local function extractResponseData(soapResponse, methodName)\
    if (soapResponse == nil) or (methodName == nil) then\
        log.warn(\"[onvif] extract response data failed: soapResponse or methodName is nil\")\
        return nil\
    end\
    -- 构造搜索的响应方法名\
    local responsePattern = \"<tds:\" .. methodName .. \"Response\" .. \"(.-)</tds:\" .. methodName .. \"Response>\"\
    -- 找到对应的响应内容\
    local responseData = soapResponse:match(responsePattern)\
    if not responseData then\
        log.warn(\"[onvif] extract response data failed: \", methodName .. \"Response\")\
        return nil\
    end\
\
    local data = {}\
    local count = 0\
    -- 使用模式匹配来提取字段名和值\
    for k, v in responseData:gmatch(\"<(tds:%w+)>(.-)</%1>\") do\
        -- 清理命名空间前缀\
        local key = k:match(\"tds:(%w+)\")\
        if key then\
            data[key] = v\
            count = count + 1\
        end\
    end\
\
    if (count == 0) then\
        log.warn(\"[onvif] extract \" .. methodName .. \"Response value failed\")\
        return nil\
    end\
    return data\
end\
\
-- 获取设备数据\
local function get_info_by_method(url, method, params)\
    local ok, response, err = http_post(url, generate_ONVIF_Request(method, params))\
    if not ok then\
        log.error(\"[onvif] request failed: \", err)\
        return nil\
    end\
    local responseData = nil\
    local code = response.code\
    local status_line = response.status_line or response.err or \"unknown status\"\
    if (code == 200) then\
        responseData = extractResponseData(response.body, method)\
    elseif (code == 400) then -- 需要WS-UserNameToken密码认证\
        -- 遍历auth_list，采用不同的认证方式\
        for i, auth in ipairs(onvif.auth_list) do\
            if (auth.username ~= nil or auth.password ~= nil) then\
                local nonce = generateNonce()\
                local created = getISO8601Timestamp()\
                local passwordDigest = generatePasswordDigest(nonce, created, auth.password)\
                if (passwordDigest ~= nil) then\
                    local ok, response, err = http_post(url, generate_ONVIF_Request_with_WS_UserNameToken(auth.username,\
                                                                                                          passwordDigest,\
                                                                                                          nonce,\
                                                                                                          created,\
                                                                                                          method, params))\
                    if ok and (response.code == 200) then\
                        responseData = extractResponseData(response.body, method)\
                        goto deal_response_data\
                    elseif ok and (response.code == 400) then\
                        log.warn(\"[onvif] request \" .. url .. \" failed: \" .. status_line ..\
                                     \"  need correct WS-UserNameToken Authentication\")\
                    else\
                        log.error(\"[onvif] request failed: \", err)\
                    end\
                end\
            end\
        end\
        log.warn(\"[onvif] request \" .. url .. \" with all auth_list failed: \" .. status_line)\
        return nil\
    elseif (code == 401) then -- 需要Digest密码认证 TODO\
        log.warn(\"[onvif] request \" .. url .. \" failed: \" .. status_line .. \"  need correct Digest Authentication\")\
        return nil\
    else -- 其他错误\
        log.warn(\"[onvif] request \" .. url .. \" failed: \" .. status_line)\
        return nil\
    end\
\
    ::deal_response_data::\
    if responseData == nil then\
        log.warn(\"[onvif] extract response data failed: \", url)\
        return nil\
    else\
        return responseData\
    end\
\
end\
\
local function get_onvif_info()\
    -- 初始化组播socket\
    if (onvif.muticast_scoket == nil) then\
        local socket, err = muticast_init()\
        if not socket then\
            log.error(\"[onvif] Failed to create multicast socket: \", err)\
            return nil\
        end\
        onvif.muticast_scoket = socket\
        socket = nil\
    end\
\
    -- 发送组播探测设备\
    local dev_count = 0\
    local devinfo_count = 0\
    dev_count = dev_discovery()\
    onvif.muticast_scoket:close()\
    onvif.muticast_scoket = nil\
    if (dev_count == 0) then\
        log.info(\"[onvif] No device found\")\
        return nil\
    end\
\
    local collect_info_list = {}\
    local count = 0\
    -- 生成设备信息\
    for i, devinfo in ipairs(onvif.devinfo_list) do\
        local collect_info = {}\
        local success_method_cnt = 0\
        for i, item in pairs(onvif.method_list) do\
            local method = item.method\
            local params = item.params\
            local info_table = get_info_by_method(devinfo.request_url, method, params)\
            if (info_table == nil) then\
                log.info(\"[onvif] method \" .. method .. \" failed to get device information, url: \" ..\
                             devinfo.request_url)\
            else\
                collect_info[method] = info_table\
                collect_info[method .. \"_key_format\"] = item.key_format\
                success_method_cnt = success_method_cnt + 1\
            end\
        end\
        if (success_method_cnt > 0) then\
            if (devinfo.mac == nil) then\
                local mac_table = myip.getarp()\
                if mac_table == nil or mac_table[devinfo.address] == nil then\
                    log.info(\"[onvif] Failed to get \" .. devinfo.address ..\
                                 \" mac address from arp table again, discard this data\")\
                    goto next_devinfo\
                end\
                log.info(\"[onvif] Success to get \" .. devinfo.address .. \" mac: \" .. mac_table[devinfo.address])\
                devinfo.mac = mac_table[devinfo.address]\
            end\
            collect_info[\"address\"] = devinfo.address\
            collect_info[\"mac\"] = devinfo.mac\
            table.insert(collect_info_list, flattenTable(collect_info))\
            count = count + 1\
        end\
        ::next_devinfo::\
    end\
    onvif.devinfo_list = {}\
    return (count == 0) and nil or collect_info_list\
end\
\
local function onvif_upload()\
    local info_list = get_onvif_info()\
    if (info_list == nil) then\
        return nil\
    else\
        for i, info in ipairs(info_list) do\
            for key, key_format in pairs(info) do\
                if string.match(key, \"_key_format$\") then\
                    local value = key_format ~= \"\" and extractValuesByKeyOrder(info, key_format) or info\
                    local ok, ret = lcmd_run({\
                        subtype = \"osinfo\",\
                        action = \"add_sig\",\
                        key = \"mdns\",\
                        value = value,\
                        mac = info.mac,\
                        from = \"onvif\"\
                    })\
                end\
            end\
        end\
    end\
    return info_list\
end\
\
local function write(t)\
    if (type(t.iface) == string) then\
        onvif.iface = t.iface\
    end\
\
    if (type(t.period) == \"number\") and (t.period >= 0) and (t.period ~= onvif.period) then\
        onvif.period = t.period\
        timer.mod(onvif.timer_name, onvif.period, 0, onvif_upload)\
    end\
\
    if (type(t.timeout) == \"number\") and (t.timeout > 0 and t.timeout < 10) then\
        onvif.timeout = t.timeout\
    end\
\
    if (type(t.auth_list) == \"table\") then\
        onvif.auth_list = t.auth_list\
    end\
\
    if (type(t.method_list) == \"table\") then\
        onvif.method_list = t.method_list\
    end\
end\
\
local function read()\
    return {\
        iface = onvif.iface,\
        period = onvif.period,\
        timeout = onvif.timeout,\
        method_list = onvif.method_list,\
        auth_list = onvif.auth_list\
    }\
end\
\
function onvif.finish()\
    if (onvif.muticast_scoket ~= nil) then\
        onvif.muticast_scoket:close()\
        onvif.muticast_scoket = nil\
    end\
    onvif.devinfo_list = {}\
    timer.del(onvif.timer_name)\
end\
\
function onvif.postinit()\
    if onvif.period > 0 then\
        timer.mod(onvif.timer_name, onvif.period, 0, onvif_upload)\
    end\
end\
\
actor.action_set(onvif.subtype, \"read\", read, \"read onvif config\")\
actor.action_set(onvif.subtype, \"write\", write,\
                 \"set onvif config {iface=string, period=number, timeout=number, auth_list=table, method_list=table}\")\
actor.action_set(onvif.subtype, \"get_onvif\", get_onvif_info, \"manual get onvif info\")\
actor.action_set(onvif.subtype, \"onvif_upload\", onvif_upload, \"manual upload onvif info\")\
return onvif\
"
, '@'.."./service/onvif.lua" ) )

package.preload[ "operdata" ] = assert( (loadstring or load)(
"local log = require\"log\"\
local actor = require\"luactor\"\
local dpi = require\"svrcomm.dpi\"\
local cjson = require\"cjson\"\
local timer = require\"timer\"\
local mime = require\"mime\"\
local csys = require\"c.sys\"\
local ctime = require\"c.time\"\
\
\
local operdata = {\
    type = \"__oper_data\",\
    subtype = \"__oper_data\",\
    help = \"oper data server communication\",\
\
    autoid = 1,\
\
    rules = {\
        --{\
        --    addr = \"domain.domain.domain:port\",\
        --    filter = {\"tuple_info_v1\",\"pscan\"}  or  \"base64(chunk string)\"\
        --    uselconn = false,  -- default is false\
        --    period = 600,      -- default is 600\
        --    maxcnt = 100,      -- default is 100\
\
        --    -- followed not config\
        --    tname = \"\", -- timer name, also used as rule unique id\
        --    stat = {\
        --        okbyte = 0,\
        --        errbyte = 0,\
        --    },\
        --    msgarray = {},    -- valid when uselconn is false\
        --    lconn = nil,      -- point long connection object when uselconn is true\
        --    finicall = nil,   -- generate when configure\
        --    filtercall = nil, -- generate when configure\
        --},\
    },\
}\
\
\
local function get_autoid()\
    local id = operdata.autoid\
    operdata.autoid = operdata.autoid + 1\
    return id\
end\
\
local function operdata_send(rule)\
    if #rule.msgarray > 0 then\
        log.info(string.format(\"operdata %s send msgcnt(%d)\", rule.addr, #rule.msgarray))\
        local msg = cjson.encode(rule.msgarray)\
        dpi.async_call(rule.addr, CENUM.COMM_ACTION_DEVOPS_DPI_DATA, msg, rule.finicall)\
        rule.msgarray = {}\
    end\
end\
\
local function stat()\
    local t = {}\
\
    for _, rule in ipairs(operdata.rules) do\
        local item = {\
            addr = rule.addr,\
            filter = rule.filter,\
            uselconn = rule.uselconn,\
            period = rule.period,\
            maxcnt = rule.maxcnt,\
            msgcnt = #rule.msgarray,\
            okbyte = rule.stat.okbyte,\
            errbyte = rule.stat.errbyte,\
            tname = rule.tname,\
        }\
        if rule.lconn then\
            item.lconn = dpi.datalongconn_show(rule.lconn)\
        end\
        table.insert(t, item)\
    end\
\
    return t\
end\
\
local function read()\
    local t = {}\
    \
    for _, rule in ipairs(operdata.rules) do\
        local item = {\
            addr = rule.addr,\
            filter = rule.filter,\
            uselconn = rule.uselconn,\
            period = rule.period,\
            maxcnt = rule.maxcnt,\
        }\
        table.insert(t, item)\
    end\
\
    return t\
end\
\
local function rule_fini(rule)\
    if rule.uselconn then\
        dpi.datalongconn_stop(rule.lconn)\
        rule.lconn = nil\
    else\
        timer.del(rule.tname)\
        rule.msgarray = {}\
    end\
    rule.finicall = nil\
    rule.filtercall = nil\
end\
\
local function rule_del(t)\
    if type(t.tname) == \"string\" then\
        for pos, rule in ipairs(operdata.rules) do\
            if t.tname == rule.tname then\
                rule_fini(rule)\
                table.remove(operdata.rules, pos)\
                return\
            end\
        end\
    end\
end\
\
local function rule_flush()\
    for _, rule in ipairs(operdata.rules) do\
        rule_fini(rule)\
    end\
    operdata.rules = {}\
end\
\
local function load_chunk(chunk)\
    local func, err = load(chunk)\
    if not func then\
        log.error(\"load failed\")\
        return nil\
    end\
\
    local ff\
    local lua_signature = csys.get_lua_signature() \
    if string.byte(chunk) == string.byte(lua_signature) then\
        -- binary string\
        ff = func\
    else\
        -- text string\
        ff = func()\
        if type(ff) ~= \"function\" then\
            log.error(\"Error, it must return function\")\
            ff = nil\
        end\
    end\
    return ff\
end\
\
local function rule_add(t)\
    local rule = {}\
\
    if type(t.addr) ~= \"string\" then\
        return\
    end\
    rule.addr = t.addr\
\
    if type(t.filter) == \"string\" then\
        local ff = load_chunk(mime.unb64(t.filter))\
        if type(ff) ~= \"function\" then\
            return\
        end\
        rule.filtercall = ff\
    elseif type(t.filter) == \"table\" then\
        for _, v in ipairs(t.filter) do\
            if type(v) ~= \"string\" then\
                return\
            end\
        end\
        rule.filtercall = function (msg)\
            local dtypes = t.filter\
            for _, dt in ipairs(dtypes) do\
                if dt == \"all\" or (type(msg.type) == \"string\" and msg.type == dt) then\
                    return true\
                end\
            end\
            return false\
        end\
    else\
        return\
    end\
    rule.filter = t.filter\
\
    local uptime = ctime.get_uptime()\
    rule.tname = string.format(\"operdata_%d_%d\", get_autoid(), uptime)\
    rule.msgarray = {}\
    rule.stat = { okbyte = 0, errbyte = 0 }\
    rule.finicall = function (err, data)\
        local stat = rule.stat\
        if err then\
            log.info(\"operdata \", rule.addr, \" finicall err, \", err)\
            stat.errbyte = stat.errbyte + #data\
        else\
            stat.okbyte = stat.okbyte + #data\
        end\
    end\
\
    rule.period = (type(t.period) == \"number\") and t.period or 600\
    rule.maxcnt = (type(t.maxcnt) == \"number\") and t.maxcnt or 100\
    if type(t.uselconn) == \"boolean\" then\
        rule.uselconn = t.uselconn\
    else\
        rule.uselconn = false\
    end\
    if rule.uselconn then\
        rule.lconn = dpi.datalongconn_start(rule.addr, CENUM.COMM_ACTION_DEVOPS_DPI_DATA, rule.maxcnt, true, rule.finicall)\
    else\
        timer.mod(rule.tname, rule.period, 0, operdata_send, rule)\
    end\
\
    table.insert(operdata.rules, rule)\
    return rule.tname\
end\
\
local function write(t)\
    if type(t.rules) == \"table\" and #t.rules > 0 then\
        rule_flush()\
        for _, rule in ipairs(t.rules) do\
            rule_add(rule)\
        end\
    end\
end\
\
local function add(msg)\
    if type(msg.data) ~= \"table\" then\
        log.error(\"must add table for oper data\")\
        return\
    end\
\
    log.info(\"operdata add , \", cjson.encode(msg.data))\
\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = msg.data})\
\
    for _, rule in pairs(operdata.rules) do\
        local ok, result = pcall(rule.filtercall, msg.data)\
        if not ok then\
            log.error(\"failed to do filtercall, error is \"..result)\
            -- immediate break and ignore other rules, to expose this error asap\
            break\
        end\
        if result == true then\
            if rule.uselconn then\
                dpi.datalongconn_send(rule.lconn, msg.data)\
            else\
                table.insert(rule.msgarray, msg.data)\
                if #rule.msgarray >= rule.maxcnt then\
                    operdata_send(rule)\
                    timer.mod(rule.tname, rule.period, 0, operdata_send, rule)\
                end\
            end\
        end\
    end\
end\
\
actor.action_set(operdata.subtype, \"rule_add\", rule_add, 'add one rule, { \"addr\":\"string\",\"filter\":[\"\",...],... }')\
actor.action_set(operdata.subtype, \"rule_del\", rule_del, 'del one rule, { \"tname\":\"string\" }')\
actor.action_set(operdata.subtype, \"rule_flush\", rule_flush, \"flush rules\")\
actor.action_set(operdata.subtype, \"stat\", stat, \"read operdata stat\")\
actor.action_set(operdata.subtype, \"read\", read, \"read operdata conf\")\
actor.action_set(operdata.subtype, \"write\", write, 'write operdata, {\"rules\":[{}, ]}')\
actor.action_set(operdata.subtype, \"add\", add, \"add data for send, {data = TABLE}\")\
\
return operdata\
"
, '@'.."./service/operdata.lua" ) )

package.preload[ "oscloud" ] = assert( (loadstring or load)(
"\
local actor = require(\"luactor\")\
local log = require(\"log\")\
local myip = require(\"myip\")\
local cjson = require(\"cjson\")\
local mystring = require(\"mystring\")\
\
local oscloud = {\
    type = \"oscloud\",\
    subtype = \"oscloud\",\
    help = \"receive cloud dev desc\",\
    count = 0,\
    max_count = 64,\
    oss = {},\
}              -- use mac as key\
\
local function flush()\
    oscloud.oss = {}\
    oscloud.count = 0\
end\
\
local function del_oscloud_old()\
    local oldtime = os.time()\
    local mac\
\
    for k,v in pairs(oscloud.oss) do\
        if v.time and oldtime >= v.time then\
            oldtime = v.time\
            mac = k\
        end\
    end\
\
    oscloud.oss[mac] = nil\
    oscloud.count = oscloud.count -1\
end\
\
local function pdev_update(t)\
    local update = {need_save = false, macdesc = {}, rt_dev = {}}\
    local elink_type = t.elink_type or {[1] = \"elink\", [2] = \"FTTRsub\"}\
\
    if t.flush then\
        flush()                 -- only flush\
        return update\
    end\
\
    if t.replace then\
        flush()\
    end\
\
    if not t.devices or type(t.devices) ~= \"table\" then\
        return update\
    end\
\
    for k,v in pairs(t.devices) do\
        if v.replace and oscloud.oss[v.mac] then\
            oscloud.oss[v.mac] = nil\
            oscloud.count = oscloud.count - 1\
        end\
        v.desc.id = v.osid\
        local seam_mac = 0\
        for m,n in pairs(oscloud.oss) do\
            if m == v.mac then\
                seam_mac = 1\
                if v.desc.elinktype ~= n.desc.elinktype and elink_type[n.desc.elinktype] and not elink_type[v.desc.elinktype] then\
                    t.devices[k] = nil\
                elseif v.osid ~= n.osid or not mystring.same_table(v.desc, n.desc) then\
                    update.need_save = true\
                end\
            end\
        end\
        if seam_mac ~= 1 then\
            update.need_save = true\
        end\
    end\
\
    for _, v in pairs(t.devices) do\
        if myip.mac_check(\"\", v.mac) then\
            local mac = v.mac\
            local oss = oscloud.oss\
            if v.osid == 0 then\
                if oss[mac] then\
                    oscloud.count = oscloud.count - 1\
                end\
                oss[mac] = nil -- delete this oscloud\
            else\
                if not oss[mac] then\
                    oscloud.count = oscloud.count + 1\
                end\
                oss[mac] = {osid = v.osid, desc = v.desc or {}, time = os.time(), source = v.source or t.source}\
\
                local desc = oss[mac].desc\
                local routedev = v.rt_dev\
                desc.id = v.osid\
                if oscloud.count > oscloud.max_count then\
                    del_oscloud_old()  -- delete old oscloud\
                end\
                if oss[mac] and type(desc) == \"table\" then\
                    local id, ostype, brand, model, devtype, groupid, elinktype, os, dev_type_string, devtypeint, support_acctype, dev_subtype, ctei = desc.id, desc.ostype, desc.brand, desc.model, desc.devtype, desc.groupid, desc.elinktype, desc.os, desc.dev_type_string, desc.devtypeint, desc.support_acctype, desc.dev_subtype, desc.ctei\
                    update.macdesc[mac] = {id = id, model = model, brand = brand, devtype = devtype, ostype = ostype, os = os, dev_type_string = dev_type_string, elinktype = elinktype, devtypeint = devtypeint, source = oss[mac].source, support_acctype = support_acctype, dev_subtype = dev_subtype, ctei = ctei}\
                    update.rt_dev[mac] = routedev\
                    if id and ostype and brand and model and devtype and groupid then\
                        lcmd_run {subtype = \"sig\", action = \"write\", osid = id, ostype = ostype, brand = brand, model = model, devtype = devtype, groupid = groupid}\
                        log.info(\"update osinfo , \", cjson.encode(desc))   -- update to sig desc\
                    end\
                end\
            end\
        end\
    end\
    return update\
end\
\
local function pdev_show()\
    return oscloud.oss\
end\
\
local function pdev_getosid(t)\
    local oss = oscloud.oss\
    if type(t.mac) == \"string\" and oss[t.mac] then\
        return oss[t.mac].osid\
    else\
        return nil\
    end\
end\
\
actor.action_set(oscloud.subtype, \"pdev_update\", pdev_update, \"update cloud dev desc, {devices=table},eg:[{mac=string,osid=number,desc={ostype=number,brand=string,model=string,devtype=number,groupid=number}}]\")\
actor.action_set(oscloud.subtype, \"pdev_show\", pdev_show, \"show cloud put msg\")\
actor.action_set(oscloud.subtype, \"pdev_getosid\", pdev_getosid, \"get cloud osid, {mac=string}\")\
\
return oscloud\
"
, '@'.."./service/oscloud.lua" ) )

