    if type(origin) ~= \"table\" or type(desc) ~= \"table\" then\
        return\
    end\
\
    local oridesc = origin.desc or {}\
\
    local updesc = {model = desc.model_name, brand = desc.brand_name, dev_type = desc.dev_type_string, devtypeint = desc.dev_type_osgi, os = desc.os_string, elinktype = desc.elinktype or oridesc.elinktype or 0, dev_subtype = desc.dev_subtype, ctei = desc.ctei}\
