    local all_len = string.unpack('=H', sbytes, pos)\
    assert(all_len == 180 and pos + 179 <= len, string.format(\"all_len %d, pos %d, len %d\", all_len, pos, len))\
\
    local mac = string.sub(sbytes, pos + 2, pos + 7)\
    one.ip = string.sub(sbytes, pos + 8, pos + 23)\
    one.ip = myip.inet_ntoa(one.ip)\
    mac = myip.mac_ntoa(mac)\
    one.mac = mac\
