        end\
    end\
    oss[mac].firsttime = one.firsttime\
    oss[mac].mac = one.mac\
    oss[mac].osid_hostname = one.osid_hostname\
    if one.hostname then\
        oss[mac].hostname = one.hostname\
    end\
\
