        desc = desc or {}\
        local macdesc = {model_name = info.model, brand_name = info.brand, dev_type_string = info.dev_type_string or desc.dev_type, os_string = info.os or desc.os, dev_type_osgi = info.devtypeint or desc.devtypeint, elinktype = info.elinktype or 0, dev_subtype = info.dev_subtype, ctei = info.ctei}\
        if info.id then\
            mac_info_add({mac=mac, key=\"cloud_osid\", value=info.id})\
            mac_info_add({mac=mac, key=\"iscloud\", value=1})\
            mac_info_add({mac=mac, key=\"source\", value=info.source})\
