    end\
    if type(msg.maclevel) == \"table\" then\
        osinfo.maclevel = msg.maclevel\
        if not osinfo.maclevel[\"other\"] then\
            osinfo.maclevel[\"other\"] = -1\
        end\
    end\
    if type(msg.connd_type) == \"table\" then\
        osinfo.connd_type = msg.connd_type\
