        end\
    end\
    if type(msg.max_sigarr) == \"number\" and msg.max_sigarr ~= osinfo.max_sigarr then\
        osinfo.max_sigarr = msg.max_sigarr\
    end\
    if type(msg.max_siglen) == \"number\" and msg.max_siglen ~= osinfo.max_siglen then\
