    end\
end\
\
local function osinfo_save()\
    local r = {}\
    osinfo.pdev_conf = {}\
\
    r.action = \"write\"\
    r.type = \"lua_cmd\"\
    r.subtype = osinfo.subtype\
    r.period = osinfo.period\
    \
    local _, pdev_info = lcmd_run({subtype = \"oscloud\", action = \"pdev_show\"})\
    osinfo.pdev_conf.devices = {}\
    for k,v in pairs(pdev_info) do\
