actor.action_set(osinfo.subtype, \"get_oss\", get_oss, \"get osinfo msg\")\
actor.action_set(osinfo.subtype, \"flush_oss\", flush_oss, \"clean osinfo msg\")\
actor.action_set(osinfo.subtype, \"pdev_update\", pdev_update, 'update cloud dev desc, {devices=table},eg:[{mac=string,osid=number,desc={ostype=number,brand=string,model=string,devtype=number,groupid=number,elinktype=number,support_acctype=number,dev_type_string=string,dev_subtype=string,ctei=number}}]')\
