package.preload[ "pcap_dump" ] = assert( (loadstring or load)(
"local pcap = require\"pcap\"\
local actor = require\"luactor\"\
local kengine = require\"kengine\"\
local log = require\"log\"\
local lfs = require(\"lfs\")\
\
local pcap_dump = {\
    type = \"pcap_dump\",\
    subtype = \"pcap_dump\",\
    help = \"read/write/stat/replay pcap\",\
}\
\
local function pcap_replay_file(file)\
    local f = file\
    local big_endian = false\
    local magicstr = string.char(0xa1, 0xb2, 0xc3, 0xd4)\
    local pcap_hdr = f:read(24)\
    local magic, _ = string.unpack(\"c4c20\", pcap_hdr)\
    if magic == magicstr then\
        big_endian = true\
    end\
    local ts_sec, ts_usec, caplen, rlen = nil, nil, nil, nil\
    local pkt_hdr = f:read(16)\
    while pkt_hdr do\
        if big_endian then\
            ts_sec, ts_usec, caplen, rlen = string.unpack(\">IIII\",pkt_hdr)\
        else\
            ts_sec, ts_usec, caplen, rlen = string.unpack(\"<IIII\",pkt_hdr)\
        end\
        ts_sec = ts_sec + ts_usec/1000000\
        local pkt_data = f:read(caplen)\
        kengine.kengine_onepcap(pkt_data, ts_sec, caplen)\
        pkt_hdr = f:read(16)\
    end\
end\
\
local function pcap_run_file(path)\
    if path:match(\".+%.(%w+)$\") ~= \"pcap\" and path:match(\".+%.(%w+)$\") ~= \"pcapng\" then\
        return\
    end\
    if true then    -- use libpcap\
        local ok, cap, open_err = pcall(pcap.open_offline, path)\
        if not ok then\
            log.error(\"open_offline pcall error, \" .. cap)\
            return\
        end\
        if type(open_err) == \"string\" then\
            log.error(\"open_offline failed, \" .. open_err)\
            return\
        end\
        if cap ~= nil then\
            while true do\
                local ok, capdata, timestamp, wirelen = pcall(cap.next, cap)\
                if ok and capdata then\
                    kengine.kengine_onepcap(capdata, timestamp, wirelen)\
                else\
                    break\
                end\
            end\
            pcall(cap.close, cap)\
        end\
        return\
    end\
    local f = io.open(path, \"r\")\
    if not f then\
        return {err = \"Failed to read pcap file\"..path}\
    end\
    log.info(\"start to replay pcap file\"..path)\
    pcap_replay_file(f)\
    f:close()\
end\
\
local function pcap_run_dir(rootpath)\
    for file in lfs.dir(rootpath) do\
        if file ~= \".\" and file ~= \"..\" then\
            local path = rootpath .. \"/\" .. file\
            local attr = lfs.attributes(path)\
            if attr.mode == \"directory\" then\
                pcap_run_dir(path)\
            elseif attr.mode == \"file\" then\
                pcap_run_file(path)\
            end\
        end\
    end\
end\
\
local function replay(t)\
    if type(t) ~= \"table\" or type(t.file) ~= \"string\" then\
        return\
    end\
    local path = t.file\
    local attr = lfs.attributes(path)\
    if type(attr) ~= \"table\" then\
        log.error(\"Failed to replay \", path)\
        return\
    end\
    local ok, err = false, nil\
    if attr.mode == \"file\" then\
        --pcall(pcap_run_file, path)\
        ok, err = xpcall(pcap_run_file, lcmd_errhandle, path)\
    elseif attr.mode == \"directory\" then\
        --pcall(pcap_run_dir, path)\
        ok, err = xpcall(pcap_run_dir, lcmd_errhandle, path)\
    end\
    if not ok and err then\
        log.error(\"Failed to replay pcap \", path, \", error is \", err)\
    end\
end\
\
function pcap_dump.postinit()\
    kengine.setdefault_ifneeded({filter = \"udp port 53 or (tcp src port 53 and (((ip[2:2] - ((ip[0]&0xf)<<2)) - ((tcp[12]&0xf0)>>2)) != 0)) or udp port 67 or udp dst port 547\", iface = \"br0\", enable = true})\
end\
\
actor.action_set(pcap_dump.subtype, \"stat\", kengine.stat, \"read pcap stat\")\
actor.action_set(pcap_dump.subtype, \"read\", kengine.read, \"read pcap parameter\")\
actor.action_set(pcap_dump.subtype, \"write\", function(t) kengine.write(t) end, \"{filter=string, iface=string, enable=bool}, write pcap\")\
actor.action_set(pcap_dump.subtype, \"dynfilter_set\", kengine.dynfilter_set, \" { keyname = STRING, filter = STRING } \")\
actor.action_set(pcap_dump.subtype, \"dynfilter_unset\", kengine.dynfilter_unset, \" { keyname = STRING } \")\
actor.action_set(pcap_dump.subtype, \"replay\", replay, \" { file = STRING } \")\
\
return pcap_dump\
"
, '@'.."./service/pcap_dump.lua" ) )

package.preload[ "pcap_udp" ] = assert( (loadstring or load)(
"local actor = require(\"luactor\")\
local mime = require(\"mime\")\
local cjson = require(\"cjson\")\
local mystring = require(\"mystring\")\
local pcap_udp = {\
    type = \"pcap_udp\",\
    subtype = \"pcap_udp\",\
    help = \"get broadcast and multicast and unicast from pcap\",\
    upload_type = \"rawpkt\",\
    sindex = nil,\
    enable = false,\
    all_count = 0,\
    all_len = 0,\
    filter = \"(ip[16] == ip[12] and udp and not icmp) or (ip[16] >= 224)\"\
}\
\
local function get_osid(mac)\
    local osid = 0\
    local ok, oss = lcmd_run({subtype = \"osinfo\", action = \"get_oss\"})\
    if ok and type(oss) == \"table\" and type(oss[mac]) == \"table\" then\
        osid = oss[mac].decide_osid or oss[mac].cloud_osid or 0\
    end\
    return osid\
end\
\
local function udp_get(msg)\
    if not pcap_udp.enable then\
        return\
    end\
    local pcap_tables = msg.pcap_tables\
    if type(pcap_tables) ~= \"table\" then\
        return\
    end\
\
    local ip_16_str = mystring.split(pcap_tables.dip, \".\")   -- first byte of dip\
    local ip_12_str = mystring.split(pcap_tables.sip, \".\")   -- first byte of sip\
\
    if not ((ip_16_str == ip_12_str and pcap_tables.proto == 17 and pcap_tables.sport ~= 53 and pcap_tables.dport ~= 53) or (tonumber(ip_16_str) >= 224)) then\
        return\
    end\
    local data = {\
        type = pcap_udp.upload_type,\
        umac = pcap_tables.mac,\
        name = \"pcap_udp_\"..tostring(get_osid(pcap_tables.mac)),\
        pkt_len = #pcap_tables.data,\
        nol2 = false,\
        time = pcap_tables.timestamp,\
        data = mime.b64(pcap_tables.data)\
    }\
    lcmd_run({subtype = \"__oper_data\", action = \"add\", data = data})\
    pcap_udp.all_count = pcap_udp.all_count + 1\
    pcap_udp.all_len = pcap_udp.all_len + string.len(cjson.encode(data))\
end\
\
local function set_pcap_filter(enable)\
    if enable then\
        lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_set\", keyname = pcap_udp.type, filter = pcap_udp.filter })\
    else\
        lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_unset\", keyname = pcap_udp.type })\
    end\
end\
\
local function write(t)\
    if type(t.enable) == \"boolean\" and t.enable ~= pcap_udp.enable then\
        pcap_udp.enable = t.enable\
        set_pcap_filter(pcap_udp.enable)\
    end\
end\
\
function pcap_udp.postinit()\
    if pcap_udp.enable then\
        set_pcap_filter(true)\
    end\
    pcap_udp.sindex = actor.subscribe(\"PCAP\", udp_get)\
end\
\
function pcap_udp.finish()\
    if pcap_udp.enable then\
        set_pcap_filter(false)\
    end\
    if pcap_udp.sindex then\
        actor.unsubscribe(\"PCAP\", pcap_udp.sindex)\
    end\
end\
\
actor.action_set(pcap_udp.subtype, \"read\", function() return {enable = pcap_udp.enable} end, \"get enable\")\
actor.action_set(pcap_udp.subtype, \"write\", write, \"set enable\")\
actor.action_set(pcap_udp.subtype, \"stat\", function () return {all_count = pcap_udp.all_count, all_len = pcap_udp.all_len} end, \"read stat\")\
return pcap_udp"
, '@'.."./service/pcap_udp.lua" ) )

