    set_mergeconf(t)\
end\
\
function pqprobe.postinit()\
    pqprobe.tl_sindex = actor.subscribe(\"TUPLE\", tuple_filter)\
    pqprobe.dns_sindex = actor.subscribe(\"PCAP\",  dns_filter)\
