\
return pqprobe\
"
, '@'.."./service/pqprobe.lua" ) )

package.preload[ "pscan" ] = assert( (loadstring or load)(
"\
local cjson = require(\"cjson\")\
local actor = require(\"luactor\")\
local myip = require(\"myip\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local mystring= require(\"mystring\")\
local myfile = require(\"myfile\")\
local cthread = require\"c.thread\"\
local slaxml = require\"nselib.slaxml\"\
local cct_enable, cct = pcall(require, \"c.ct\")\
\
local pscan = {\
    subtype = \"pscan\",\
    period = 0,\
    timer_name = 'pscan_timer', \
    repo = 'http://101.89.180.237:7890/repo_n01/n780/',\
    argv = ' --max-rate 10 -sV -oX ',\
    prog = 'n01',\
    isrunning = false,\
    dst= \"192.168.1.0/24\",\
    oui = \"\",\
    iface = \"br0\",\
\
    -- stat\
    count = 0, \
    run_cnt = 0, \
    all_len = 0,\
\
    help = \"parse n01 result and send to oper_data\"\
}\
\
local function get_element(t, filter)\
    local element = {}\
\
    if type(t) ~= \"table\" then\
        return element\
    end\
    for k,v in pairs(t) do\
        local name = v.name or \"\"\
        local flname = filter[name]\
        if flname and v.type == \"element\" then\
            if not element[name] then\
                element[name] = {} \
            end\
            table.insert(element[name], v[flname])\
        end\
    end\
    for k,v in pairs(filter) do\
        if not element[k] then\
            element[k] = {}\
        end\
    end\
\
    return element\
end\
\
local function get_attr(info, name, filter)\
    local attr = {}\
    if type(info) ~= \"table\" then\
        return attr\
    end\
    for _, v in pairs(info) do\
        if v.name == name and v.type == \"element\" then\
            for _, att in pairs(v.attr) do\
                if att.name and filter[att.name] then\
                    attr[att.name] = att.value\
                end\
            end\
        end\
    end\
    return attr\
end\
\
local function parse_hostscript(ip, mac, hostscripts)\
    local script_info = {}\
    if type(hostscripts) ~= \"table\" then\
        return script_info\
    end\
    for _, v in pairs(hostscripts) do\
        local script = get_attr({v}, \"script\", {id = true})\
        local info = {}\
        for k,v in pairs(v.kids) do\
            if v.name == \"table\" then\
                table.insert(info, v)\
            end\
        end\
        if #info > 0 then\
            local one = {type = \"dev_vuln\", mac = mac, ip = ip, script_name = script.id or \"\", vuln_info = cjson.encode(info)}\
            table.insert(script_info, one)\
        end\
    end\
    return script_info\
end\
\
local function parse_ports(ip, mac, ports)\
    local port_info = {}\
    if type(ports) ~= \"table\" then\
        return port_info\
    end\
    for _, v in pairs(ports) do\
        local port, state, service = {}, {}, {}\
        port = get_attr({v}, \"port\", {protocol = true, portid = true})\
        state = get_attr(v.kids, \"state\", {state = true})\
        service = get_attr(v.kids, \"service\", {name = true, version = true, product = true})\
\
        local portid = tonumber(port.portid)\
        if portid then\
            local one = {type = \"pscan_v1\", mac = mac, ip = ip, port = portid, proto = port.protocol or \"\", status = state.state or \"\", svr = service.name or \"\", version = service.version or \"\", product = service.product or \"\"}\
            table.insert(port_info, one)\
        end\
    end\
    return port_info\
end\
\
local function parse_addr(address)\
    local ip, mac, addr = nil, nil ,{}\
    for k,v in pairs(address) do\
        if type(v) == \"table\" and #v == 2 then\
            local key, value\
            key = v[2].value\
            value = v[1].value\
            addr[key] = value\
        end\
    end\
    return addr[\"ipv4\"] or \"\", addr[\"mac\"] or \"\"\
end\
\
local function add_one(all, info)\
    for k,v in pairs(info) do\
        table.insert(all, v)\
    end\
end\
\
local function file_parse(file)\
    local all, info, nmaprun, hosts = {}, nil, nil, nil\
    local data , err = myfile.read(file)\
    log.debug(\"read data \" , data)\
    if err then\
        log.warn(\"parse file \", err)\
    end\
\
    info = slaxml.parseDOM(data or \"\", { stripWhitespace=true,simple=true })\
    if info and info.kids then\
        nmaprun = get_element(info.kids, {nmaprun = \"kids\"})\
        hosts = get_element(nmaprun.nmaprun[1], {host = \"kids\"})\
    end\
    for k,v in pairs(hosts.host) do\
        local one, ip, mac, ports, hostscript\
        one = get_element(v, {address = \"attr\", ports = \"kids\", hostscript = \"kids\"})\
        ip, mac = parse_addr(one.address)\
        ports = parse_ports(ip, mac, one.ports[1])\
        hostscript = parse_hostscript(ip, mac, one.hostscript[1])\
        \
        add_one(all, ports)\
        add_one(all, hostscript)\
    end\
\
    return all\
end\
\
--t.file\
local function parse(msg)\
    local res = file_parse(msg.file)\
    log.info(\"parse file:\", cjson.encode(res), \"file name:\", msg.file)\
    for k, v in pairs(res) do\
        local str = cjson.encode(v)\
        if v.ip == \"\" or v.mac == \"\" then\
            log.info(\"scan ignore one \", str)\
        else\
            log.info(\"scan send one \", str)\
            lcmd_run({subtype = \"__oper_data\", action = \"add\", data = v})\
            pscan.count = pscan.count + 1\
            pscan.all_len = pscan.all_len + string.len(str)\
        end\
    end\
end\
\
-- t.url\
-- t.save_file\
local function do_download(t)\
    if t.save_file == nil then\
        log.warn(\"save file is nil\")\
        return false\
    end\
\
    local http = require\"socket.http\"\
    local body, code = http.request(t.url)\
    if code ~= 200 then\
        log.error(string.format(\"failed to download (%s), code (%s)\", t.url, code))\
        return false\
    end\
\
    myfile.write(body, t.save_file)\
    return true\
end\
\
-- t.cmd\
local function run_cmd(t)\
    return  t.cmd, os.execute(t.cmd)\
end\
\
-- t.zfile\
-- t.extra_dir\
local function do_extra(t)\
    local cmd = string.format(\"mkdir -p %s && cd %s  && tar zxf %s\", t.extra_dir, t.extra_dir, t.zfile)\
    return run_cmd({cmd=cmd})\
end\
\
local function get_route()\
    local net_dst =  {}\
    local rt_regex = \"((.*)/%w+) (%w+) (%w+)\"\
    local f = io.popen(\"ip route | grep src\")\
    for line in f:lines() do\
        local net, _, _, dev_name = string.match(line, rt_regex)\
        if net then\
            net_dst[dev_name] = net\
        end\
    end\
    f:close()\
    return net_dst\
end\
\
local function get_lan_info()\
    if cct_enable then\
        local netinfo = cct.getnetinfo()\
        local netmask = cct.getdhcpserver() or {}\
        local lan_ip = netinfo.lan_ip\
        local subnetmask = netmask.SubnetMask\
        if lan_ip and #lan_ip > 0 and subnetmask then\
            local mask, err = myip.mask_atob_fast(subnetmask)\
            if not err then\
                local ip = lan_ip .. '/' .. tostring(mask)\
                return ip\
            end\
        end\
    end\
    local net_dst = get_route()\
    for m,n in pairs(net_dst) do\
        if m == pscan.iface then\
            return n\
        end\
    end\
    return \"192.168.1.0/24\"\
end\
\
--t.ret_code\
--t.ret_msg\
--t.file\
local function do_finish(t)\
    if not t.ret_code and not t.ret_msg then\
        log.error(\"invalid do finish , need ret_code and ret_msg\")\
        return\
    end\
\
    if t.ret_code == 0 and t.file  then\
        -- parse result\
        parse({file = t.file})\
    else\
        log.error(string.format(\"finish error ret_code(%d), ret_msg(%s)\", t.ret_code, t.ret_msg))\
    end\
\
    pscan.isrunning = false\
end\
\
\
--t.ret_code\
--t.ret_msg\
--t.file\
local function post_finish(t)\
    local args = \"\"\
    if t.ret_code ~= 0 then\
        args = string.format([[{\"subtype\":\"pscan\", \"action\":\"finish\", \"ret_code\":%d, \"ret_msg\":\"%s\"}]], \
                                    t.ret_code, t.ret_msg)\
    else\
        args = string.format([[{\"subtype\":\"pscan\", \"action\":\"finish\", \"file\":\"%s\",\"ret_code\":%d, \"ret_msg\":\"%s\"}]], \
                                    t.file, t.ret_code, t.ret_msg)\
    end\
    log.info(args)\
    lcmd_client(true, lcmd_tmp_path(\"\"), args)\
end\
\
-- t.prog\
-- t.dst\
-- t.repo\
-- t.oui\
-- this func must run in thread\
local function pscan_proc(t)\
    local n01_dir = lcmd_tmp_path(\".\"..t.prog)\
    local tgz_file = lcmd_tmp_path(t.prog..\".tgz\")\
    local n01_file = n01_dir..\"/\"..t.prog\
    local n01_result = n01_file..\".xml\"\
    --\
    -- download nmap tarball to tmp path\
    local pkg_existed = myfile.existed(tgz_file)\
    if not pkg_existed then\
        local dl_url = string.format(\"%s/%s/n01.tgz\",t.repo , t.oui)\
        local succ = do_download({url = dl_url, save_file = tgz_file})\
        if not succ then\
            post_finish({ret_msg=string.format(\"download n01 failed, url(%s)\", dl_url), ret_code = -1 })\
            return\
        end\
    end\
\
    -- extra nmap tarball to tmp_path\
    local n01_existed = myfile.existed(n01_file)\
    if not n01_existed then\
        local cmd, succ, ret_code, ret_msg = do_extra({zfile= tgz_file, extra_dir=n01_dir})\
        if not succ then\
            post_finish({ret_msg=string.format(\"do extra failedi cmd(%s), ret_msg(%s), ret_code(%d)\",\
                                                cmd, ret_msg, ret_code), ret_code = -1})\
            return\
        end\
    end\
\
    -- check n01 existed\
    local existed_n01 =  myfile.existed(n01_file)\
    if not existed_n01 then\
        post_finish({ret_msg=\"do scan failed, n01 not found !\", ret_code = -1})\
        return\
    end\
\
    -- do scan\
    local scan_cmd = string.format(\"cd %s &&  %s %s %s %s\", n01_dir, n01_file, t.argv, n01_result, t.dst)\
    local cmd, succ, ret_msg, ret_code = run_cmd({cmd = scan_cmd})\
    if not succ then\
        post_finish({ret_msg=string.format(\"do scan failedi cmd(%s), ret_msg(%s), ret_code(%d)\", \
                                            cmd, ret_msg, ret_code), ret_code = -1})\
        return\
    end\
    post_finish({ret_msg=\"parse n01 result file\", ret_code = 0, file = n01_result})\
end\
\
function pscan.postinit()\
    local _, arch = lcmd_run({type = \"arch\", action = \"read\"})\
    pscan.oui = arch.oui\
end\
\
local function get_dst()\
    local dst = get_lan_info()\
    if dst ~= \"\" then\
        pscan.dst = dst\
    end\
end\
\
local function pscan_process(msg)\
    if pscan.isrunning  then\
        log.info(\"pscan is running\")\
        return {info=\"scan service is running\"}\
    end\
    pscan.isrunning = true\
    pscan.run_cnt = pscan.run_cnt + 1\
\
    get_dst()\
\
    if pscan.dst == \"\" or pscan.oui == \"\"  then\
        log.error(\"please check pscan.dst or pscan.oui is correct\")\
    end\
\
    local args = string.format([[{\"subtype\":\"pscan\", \"action\":\"proc\",\"prog\":\"%s\",\"dst\":\"%s\",\"repo\":\"%s\",\"oui\":\"%s\",\"argv\":\"%s\"}]],\
                                pscan.prog, pscan.dst, pscan.repo, pscan.oui, pscan.argv)\
    log.info(\"run thread =\" , args)\
    cthread.run(args)\
    return {info=\"starting scan service\"}\
end\
\
local function write(msg)\
    if msg.period and msg.period ~= pscan.period then\
        log.info(\"period change to\", msg.period, \"from \", pscan.period)\
        pscan.period = msg.period\
        timer.mod(pscan.timer_name, pscan.period, 0, pscan_process)\
    end\
\
    if msg.argv and msg.argv ~= pscan.argv then\
        pscan.argv = msg.argv\
        log.info(\"argv change to \",msg.argv,\" from \",pscan.argv)\
    end\
\
    if msg.iface and msg.iface ~= pscan.iface then\
        pscan.iface = msg.iface\
        log.info(\"iface change to \",msg.argv,\" from \",pscan.iface)\
    end\
\
    if msg.repo and msg.repo ~= pscan.repo then\
        pscan.repo = msg.repo\
    end\
\
    if msg.dst and msg.dst ~= pscan.dst then\
        pscan.dst = msg.dst\
    end\
end\
\
actor.action_set(pscan.subtype, \"read\", function () return {period = pscan.period, dst = pscan.dst, repo=pscan.repo, argv = pscan.argv, iface = pscan.iface} end, \"read pscan conf\")\
actor.action_set(pscan.subtype, \"write\", write, [[ set pscan period and argv, {period = number,argv = string}, period = 0 means close model,argv = nil means use default argv,argv can be changed by yourself]])\
actor.action_set(pscan.subtype, \"stat\", function () return {oui = pscan.oui, len = pscan.all_len, isrunning=pscan.isrunning, data_cnt = pscan.count, run_cnt = pscan.run_cnt} end, \"read pscan stat\")\
actor.action_set(pscan.subtype, \"parse\", parse, [[file = scan.txt parse pscan result file]])\
actor.action_set(pscan.subtype, \"proc\", pscan_proc, [[need 4 args {prog,dst,repo,oui} to start scan service]])\
actor.action_set(pscan.subtype, \"start\", pscan_process, [[start pscan and upload data]])\
actor.action_set(pscan.subtype, \"finish\", do_finish, [[report finish stat]])\
\
return pscan\
"
, '@'.."./service/pscan.lua" ) )

package.preload[ "qblstats" ] = assert( (loadstring or load)(
"local actor = require(\"luactor\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local cjson = require(\"cjson\")\
local mystring = require(\"mystring\")\
local myutil = require(\"myutil\")\
local stats = require(\"stats\")\
local ctime = require(\"c.time\")\
\
\
local qblstats = {\
    type = \"qblstats\",\
    subtype = \"qblstats\",\
    help = \"quality baseline stats\",\
\
    timer_name = \"qblstats_time_check\",\
    check_period = 5,\
\
    arping_index = nil,\
    portrate_index = nil,\
    qualcol_index = nil,\
    lanhost_index = nil,\
\
    lastday = {},\
    thisday = {\
        time = \"\",\
    },\
\
    lasthour = {},\
    thishour = {\
        time = \"\",\
    },\
\
    drtenable = false,\
    lastdrt = {},\
    thisdrt = {\
        time = \"\",\
    },\
\
    universal_metatable = {\
        __index = {\
            output = function(v)\
                return {\
                    count = v.stats:getCount(),\
                    avg = v.stats:getMean(),\
                    max = v.stats:getMax(),\
                    min = v.stats:getMin(),\
                    std = v.stats:getStdDev(),\
                    mjt = v.stats:getMeanJitter(),\
                }\
            end,\
        },\
    },\
}\
\
local function get_day_hour()\
    local t = myutil.os_date(\"*t\")\
    local day = string.format(\"%04d-%02d-%02d\", t.year, t.month, t.day)\
    local hour = string.format(\"%02d:00-%02d:00\", t.hour, t.hour + 1)\
    return day, hour\
end\
\
local function bl_output(obj)\
    local t = {}\
    for k, v in pairs(obj) do\
        if type(v) == \"table\" then\
            if v.output then\
                t[k] = v.output(v)\
            else\
                t[k] = bl_output(v)\
            end\
        else\
            t[k] = v\
        end\
    end\
    return t\
end\
\
local function time_check()\
    local day, hour = get_day_hour()\
\
    if qblstats.thishour.time ~= hour then\
        qblstats.lasthour = bl_output(qblstats.thishour)\
        qblstats.thishour = { time = hour }\
    end\
    if qblstats.thisday.time ~= day then\
        qblstats.lastday = bl_output(qblstats.thisday)\
        qblstats.thisday = { time = day }\
    end\
end\
\
local function bl_handle(msg, tpl)\
    time_check()\
    tpl.update(qblstats.thishour, msg)\
    tpl.update(qblstats.thisday, msg)\
    if qblstats.drtenable then\
        tpl.update(qblstats.thisdrt, msg)\
    end\
end\
\
local function arping_deal(msg)\
    qblstats.arping_metatable = qblstats.arping_metatable or {\
        __index = {\
            output = function(v)\
                return {\
                    count = v.stats:getCount(),\
                    lan_avg = v.stats:getMean(),\
                    lan_max = v.stats:getMax(),\
                    lan_min = v.stats:getMin(),\
                    lan_std = v.stats:getStdDev(),\
                    arping_lost_pct = (v.send_cnt > 0) and ((v.send_cnt - v.recv_cnt) * 100 / v.send_cnt) or 0,\
                    arping_mean_jitter = v.stats:getMeanJitter(),\
                }\
            end,\
        },\
    }\
    qblstats.arping_tpl = qblstats.arping_tpl or {\
        update = function(obj, msg)\
            if not obj[\"lanhost\"] then\
                obj[\"lanhost\"] = {}\
            end\
            if not obj[\"lanhost\"][msg.mac] then\
                obj[\"lanhost\"][msg.mac] = {}\
            end\
            if not obj[\"lanhost\"][msg.mac][\"arping\"] then\
                obj[\"lanhost\"][msg.mac][\"arping\"] = setmetatable({\
                    stats = stats:new(),\
                    send_cnt = 0,\
                    recv_cnt = 0,\
                }, qblstats.arping_metatable)\
            end\
            local v = obj[\"lanhost\"][msg.mac][\"arping\"]\
            v.send_cnt = v.send_cnt + 1\
            if type(msg.lat) == \"number\" then\
                v.stats:update(msg.lat)\
                v.recv_cnt = v.recv_cnt + 1\
            end\
        end,\
    }\
    bl_handle(msg, qblstats.arping_tpl)\
end\
\
local function portrate_deal(msg)\
    qblstats.portrate_tpl = qblstats.portrate_tpl or {\
        update = function(obj, msg)\
            for k, rate in pairs(msg) do\
                if not obj[\"gateway\"] then\
                    obj[\"gateway\"] = {}\
                end\
                if not obj[\"gateway\"][k] then\
                    obj[\"gateway\"][k] = setmetatable({\
                        stats = stats:new(),\
                    }, qblstats.universal_metatable)\
                end\
                obj[\"gateway\"][k].stats:update(rate)\
            end\
        end,\
    }\
    bl_handle(msg.port_rate, qblstats.portrate_tpl)\
end\
\
local function qualcol_deal(msg)\
    qblstats.flowlat_tpl = qblstats.flowlat_tpl or {\
        update = function(obj, msg)\
            if not obj[\"lanhost\"] then\
                obj[\"lanhost\"] = {}\
            end\
            if not obj[\"lanhost\"][msg.mac] then\
                obj[\"lanhost\"][msg.mac] = {}\
            end\
            if not obj[\"lanhost\"][msg.mac][\"flowlan\"] then\
                obj[\"lanhost\"][msg.mac][\"flowlan\"] = setmetatable({\
                    stats = stats:new(),\
                }, qblstats.universal_metatable)\
            end\
            if msg.lan_lat > 0 then\
                obj[\"lanhost\"][msg.mac][\"flowlan\"].stats:update(msg.lan_lat)\
            end\
\
            if not obj[\"lanhost\"][msg.mac][\"flowwan\"] then\
                obj[\"lanhost\"][msg.mac][\"flowwan\"] = setmetatable({\
                    stats = stats:new(),\
                }, qblstats.universal_metatable)\
            end\
            if msg.wan_lat > 0 then\
                obj[\"lanhost\"][msg.mac][\"flowwan\"].stats:update(msg.wan_lat)\
            end\
\
            if not obj[\"lanhost\"][msg.mac][\"lostpct\"] then\
                obj[\"lanhost\"][msg.mac][\"lostpct\"] = setmetatable({\
                    stats = stats:new(),\
                }, qblstats.universal_metatable)\
            end\
            local pkt_loss_rate = (msg.pkt_pl_cnt > 0) and (msg.pkt_loss_cnt / msg.pkt_pl_cnt) or -1\
            if pkt_loss_rate >= 0 then\
                obj[\"lanhost\"][msg.mac][\"lostpct\"].stats:update(pkt_loss_rate)\
            end\
        end\
    }\
    bl_handle(msg.quality_data, qblstats.flowlat_tpl)\
end\
\
local function lanhost_deal(msg)\
    qblstats.lanhost_tpl = qblstats.lanhost_tpl or {\
        update = function(obj, msg)\
            if not obj[\"lanhost\"] then\
                obj[\"lanhost\"] = {}\
            end\
            for mac, info in pairs(msg) do\
                if not obj[\"lanhost\"][mac] then\
                    obj[\"lanhost\"][mac] = {}\
                end\
\
                if not obj[\"lanhost\"][mac][\"txrate\"] then\
                    obj[\"lanhost\"][mac][\"txrate\"] = setmetatable({\
                        stats = stats:new(),\
                    }, qblstats.universal_metatable)\
                end\
                obj[\"lanhost\"][mac][\"txrate\"].stats:update(info.txrate)\
\
                if not obj[\"lanhost\"][mac][\"rxrate\"] then\
                    obj[\"lanhost\"][mac][\"rxrate\"] = setmetatable({\
                        stats = stats:new(),\
                    }, qblstats.universal_metatable)\
                end\
                obj[\"lanhost\"][mac][\"rxrate\"].stats:update(info.rxrate)\
\
                if not obj[\"lanhost\"][mac][\"dev_power_level\"] then\
                    obj[\"lanhost\"][mac][\"dev_power_level\"] = setmetatable({\
                        stats = stats:new(),\
                    }, qblstats.universal_metatable)\
                end\
                obj[\"lanhost\"][mac][\"dev_power_level\"].stats:update(info.dev_power_level)\
\
                if not obj[\"lanhost\"][mac][\"nego_rate\"] then\
                    obj[\"lanhost\"][mac][\"nego_rate\"] = setmetatable({\
                        stats = stats:new(),\
                    }, qblstats.universal_metatable)\
                end\
                obj[\"lanhost\"][mac][\"nego_rate\"].stats:update(info.nego_rate)\
\
                obj[\"lanhost\"][mac][\"osid\"] = obj[\"lanhost\"][mac][\"osid\"] or info.osid\
                obj[\"lanhost\"][mac][\"dev_type\"] = obj[\"lanhost\"][mac][\"dev_type\"] or info.dev_type\
                obj[\"lanhost\"][mac][\"ip\"] = obj[\"lanhost\"][mac][\"ip\"] or info.ip\
                obj[\"lanhost\"][mac][\"acc_type\"] = obj[\"lanhost\"][mac][\"acc_type\"] or info.acc_type\
                obj[\"lanhost\"][mac][\"acc_port\"] = obj[\"lanhost\"][mac][\"acc_port\"] or info.acc_port\
            end\
        end\
    }\
    bl_handle(msg.lan_host, qblstats.lanhost_tpl)\
end\
\
local function write(t)\
    if type(t.check_period) == \"number\" and t.check_period ~= qblstats.check_period then\
        qblstats.check_period = t.check_period\
        timer.mod(qblstats.timer_name, qblstats.check_period, 0, time_check)\
    end\
end\
\
local function read()\
    return {\
        check_period = qblstats.check_period,\
        drtenable = qblstats.drtenable,\
    }\
end\
\
local function stat()\
    return {\
        thishour = qblstats.thishour,\
        thisday = qblstats.thisday,\
        thisdrt = qblstats.thisdrt,\
    }\
end\
\
local function get_blinfo()\
    return {\
        hour = (qblstats.lasthour.time and #qblstats.lasthour.time > 0) and qblstats.lasthour or nil,\
        day = (qblstats.lastday.time and #qblstats.lastday.time > 0) and qblstats.lastday or nil,\
    }\
end\
\
local function drt_get_time()\
    local t = myutil.os_date(\"*t\")\
    return string.format(\"%04d%02d%02d_%02d:%02d\", t.year, t.month, t.day, t.hour, t.min)\
end\
\
local function drt_stop()\
    if not qblstats.drtenable then\
        return\
    end\
    qblstats.drtenable = false\
    qblstats.thisdrt.time = qblstats.thisdrt.time..\"-\"..drt_get_time()\
    qblstats.lastdrt = bl_output(qblstats.thisdrt)\
    qblstats.thisdrt = { time = \"\" }\
end\
\
local function drt_start()\
    drt_stop()\
    qblstats.drtenable = true\
    qblstats.thisdrt = { time = drt_get_time() }\
end\
\
local function drt_show()\
    return bl_output(qblstats.thisdrt)\
end\
\
local function drt_showlast()\
    return qblstats.lastdrt\
end\
\
function qblstats.postinit()\
    qblstats.arping_index = actor.subscribe(\"ARPING\", arping_deal)\
    qblstats.portrate_index = actor.subscribe(\"DEV_PORT_RATE\", portrate_deal)\
    qblstats.qualcol_index = actor.subscribe(\"QUALCOL\", qualcol_deal)\
    qblstats.lanhost_index = actor.subscribe(\"LAN_HOST\", lanhost_deal)\
\
    timer.mod(qblstats.timer_name, qblstats.check_period, 0, time_check)\
end\
\
function qblstats.finish()\
    if qblstats.arping_index then\
        actor.unsubscribe(\"ARPING\", qblstats.arping_index)\
    end\
    if qblstats.portrate_index then\
        actor.unsubscribe(\"DEV_PORT_RATE\", qblstats.portrate_index)\
    end\
    if qblstats.qualcol_index then\
        actor.unsubscribe(\"QUALCOL\", qblstats.qualcol_index)\
    end\
    if qblstats.lanhost_index then\
        actor.unsubscribe(\"LAN_HOST\", qblstats.lanhost_index)\
    end\
end\
\
actor.action_set(qblstats.subtype, \"write\", write, \"write qblstats conf, {check_period = number}\")\
actor.action_set(qblstats.subtype, \"read\", read, \"read qblstats conf\")\
actor.action_set(qblstats.subtype, \"stat\", stat, \"read qblstats stat\")\
actor.action_set(qblstats.subtype, \"get_blinfo\", get_blinfo, \"get blinfo\")\
\
------------------------------------------------------------------------------------------\
-- 在设置/重置质差计算的定时器时，如果定时器是开的话，调用 drt_start，否则调用 drt_stop 。\
\
-- 在质差计算的定时器处理方法内：\
-- 1. 先调用 drt_stop\
-- 2. 如果有质差需求，则调用 drt_showlast\
-- 3. 在方法结束前调用 drt_start\
\
-- 对于模块的 drt_show，属于调试方法，用于展示当前的统计。\
------------------------------------------------------------------------------------------\
actor.action_set(qblstats.subtype, \"drt_start\", drt_start, \"drt start\")\
actor.action_set(qblstats.subtype, \"drt_stop\", drt_stop, \"drt stop\")\
actor.action_set(qblstats.subtype, \"drt_show\", drt_show, \"drt show\")\
actor.action_set(qblstats.subtype, \"drt_showlast\", drt_showlast, \"drt showlast\")\
\
return qblstats\
\
"
, '@'.."./service/qblstats.lua" ) )

