function qcalc.pre_lat_deal(quality_data, protos, pre_lat_thres)\
    if type(quality_data) ~= \"table\" or type(pre_lat_thres) ~= \"number\" then\
        return false, \"data preprocessing failed due to incorrect data format.\"\
    end\
    -- 时延归一处理\
    local function lat_deal(lat, lat_thres)\
        if lat_thres == 0 then\
            return -1\
        end\
        return (lat > lat_thres and lat_thres or lat) / lat_thres\
    end\
    local pre_lat_thres_us = pre_lat_thres * 1000000\
    local qdata = {\
        ip = quality_data.ip,\
        mac = quality_data.mac,\
        osid = quality_data.osid,\
        appid = quality_data.appid <= CENUM.MAX_BASE_APPID and protos[quality_data.appid] ~= \"dns\" and protos[quality_data.appid] ~= \"http\" and protos[quality_data.appid] ~= \"https\" and 0 or quality_data.appid,\
        proto = protos[quality_data.base_appid],\
        ruleid = quality_data.ruleid,\
        lat1 = lat_deal(quality_data.lat1, pre_lat_thres_us),\
        wan_lat = lat_deal(quality_data.wan_lat, pre_lat_thres_us),\
        wan_app_lat = lat_deal(quality_data.wan_app_lat, pre_lat_thres_us),\
        lat2 = lat_deal(quality_data.lat2, pre_lat_thres_us),\
        lan_lat = lat_deal(quality_data.lan_lat, pre_lat_thres_us),\
        lan_app_lat = lat_deal(quality_data.lan_app_lat, pre_lat_thres_us),\
        http_lat = lat_deal(quality_data.http_lat, pre_lat_thres_us),\
        -- 这里使用 0xffffffff 表示一个有效的 0 值，以保证后续不会因此判断连接失败\
        pkt_loss_rate = (quality_data.pkt_pl_cnt > 0) and ((quality_data.pkt_loss_cnt > 0) and (quality_data.pkt_loss_cnt / quality_data.pkt_pl_cnt) or 0xffffffff) or 0,\
        -- pkts_in_rate = (quality_data.duration > 0) and (quality_data.pkts_in / (quality_data.duration * 1e-6)) or 0,                                                -- 单位：pps\
        -- pkts_out_rate = (quality_data.duration > 0) and (quality_data.pkts_out / (quality_data.duration * 1e-6)) or 0,                                              -- 单位：pps\
        -- pkts_rate = (quality_data.duration > 0) and ((quality_data.pkts_in + quality_data.pkts_out) / (quality_data.duration * 1e-6)) or 0,                         -- 单位：pps\
        -- rx_rate = (quality_data.duration > 0) and ((quality_data.bytes_in * 8 * 1e-3) / (quality_data.duration * 1e-6)) or 0,                                       -- 单位：kbps\
        -- tx_rate = (quality_data.duration > 0) and ((quality_data.bytes_out * 8 * 1e-3) / (quality_data.duration * 1e-6)) or 0,                                      -- 单位：kbps\
        -- rate = (quality_data.duration > 0) and ((quality_data.bytes_in * 8 * 1e-3 + quality_data.bytes_out * 8 * 1e-3) / (quality_data.duration * 1e-6)) or 0,      -- 单位：kbps\
        -- lan_std = quality_data.lan_std,\
        -- wan_std = quality_data.wan_std,\
        -- lat_std = quality_data.lat_std,\
    }\
    return true, qdata\
end\
\
function qcalc.calc_score(qdata, lmodel, app_lmodel, low_score_thres, high_score_thres, stat_out, cache_is_full, stat_ruleid_max)\
    local model = app_lmodel[tostring(qdata.appid)] and app_lmodel[tostring(qdata.appid)][qdata.proto] or lmodel[qdata.proto]\
    if not model then\
        return\
    end\
\
    local is_new_app, score_tbl, conn_succ = false, { score = 0 }, nil\
    if model.policy == \"or\" then\
        conn_succ = false\
        for f, w in pairs(model.weight) do\
            conn_succ = (qdata[f] > 0) or conn_succ\
            score_tbl[f..\"_score\"] = (qdata[f] == 0xffffffff) and 0 or (qdata[f] * w + 0)  -- + 0 是为了处理 -0.1 * 0 = -0.0 的情况\
            score_tbl[\"score\"] = score_tbl[f..\"_score\"] + score_tbl[\"score\"]\
        end\
    elseif model.policy == \"and\" then\
        conn_succ = true\
        for f, w in pairs(model.weight) do\
            conn_succ = (qdata[f] > 0) and conn_succ\
            score_tbl[f..\"_score\"] = (qdata[f] == 0xffffffff) and 0 or (qdata[f] * w + 0)\
            score_tbl[\"score\"] = score_tbl[f..\"_score\"] + score_tbl[\"score\"]\
        end\
    else\
        return\
    end\
\
    stat_out[qdata.mac] = stat_out[qdata.mac] or {contrib = {}}\
    if not stat_out[qdata.mac][tostring(qdata.appid)] then\
        is_new_app = true\
        if cache_is_full then\
            return\
        end\
        stat_out[qdata.mac][tostring(qdata.appid)] = {\
            flow_all_cnt = 0,\
            conn_succ_cnt = 0,\
            flow_hscore_cnt = 0,\
            ruleid_hit_set = {\
                count = 0,\
                ruleid_set = {}\
            }\
        }\
    end\
    local flow_stats = stat_out[qdata.mac][tostring(qdata.appid)]\
    local contrib_stats = stat_out[qdata.mac][\"contrib\"]\
\
    -- 处理 ruleid，进行去重统计\
    if qdata.ruleid and type(qdata.ruleid) == \"number\" and qdata.ruleid >= 0 then\
        local ruleid_str = tostring(qdata.ruleid)\
        if not flow_stats.ruleid_hit_set.ruleid_set[ruleid_str] then\
            -- 检查是否超过大小限制，使用 ruleid_hit_set 的一个特殊键来存储计数\
            local current_count = flow_stats.ruleid_hit_set.count or 0\
            if type(stat_ruleid_max) == \"number\" and current_count <= stat_ruleid_max then\
                flow_stats.ruleid_hit_set.ruleid_set[ruleid_str] = true\
                flow_stats.ruleid_hit_set.count = current_count + 1\
            end\
        end\
    end\
\
    flow_stats.flow_all_cnt = flow_stats.flow_all_cnt + 1\
    if conn_succ then\
        flow_stats.conn_succ_cnt = flow_stats.conn_succ_cnt + 1\
        score_tbl[\"score\"] = (score_tbl[\"score\"] + model.bias) * 100\
        if score_tbl[\"score\"] >= high_score_thres then\
            flow_stats.flow_hscore_cnt = flow_stats.flow_hscore_cnt + 1\
        elseif score_tbl[\"score\"] < low_score_thres then\
            for f, w in pairs(model.weight) do\
                local contrib = math.abs(score_tbl[f..\"_score\"])\
                if contrib > 0 then\
                    if not contrib_stats[f] then\
                        contrib_stats[f] = stats:new()\
                    end\
                    contrib_stats[f]:update(contrib)\
                end\
            end\
        end\
    end\
\
    score_tbl[\"conn_succ\"] = conn_succ and 1 or 0\
    lcmd_run({subtype = \"qcollect\", action = \"set_field\", data = score_tbl})\
    return is_new_app\
end\
\
local function qualcol_deal(msg)\
    if not qcalc.enable then\
        return\
    end\
\
    -- 数据预处理\
    local ok, qdata = qcalc.pre_lat_deal(msg.quality_data, qcalc.protos, qcalc.pre_lat_thres)\
    if not ok then\
        log.error(qdata)\
        return\
    end\
\
    local cache_is_full = qcalc.stat_all_app_cnt >= qcalc.stat_all_app_max\
    -- 计算单条流得分，并统计数据\
    local is_new_app = qcalc.calc_score(qdata, qcalc.lmodel, qcalc.app_lmodel, qcalc.low_score_thres, qcalc.high_score_thres, qcalc.statdata, cache_is_full, qcalc.stat_ruleid_max)\
    if is_new_app and not cache_is_full then\
        qcalc.stat_all_app_cnt = qcalc.stat_all_app_cnt + 1\
    end\
end\
\
function qcalc.quality_check(statin, hscore_weight, consuc_weight, q_event_requir, q_event_qapp_max, calc_last_score)\
    -- 质差事件详情\
    local q_event = {\
        timestamp = myutil.os_time(),\
        dev_num = 0,\
        flow_num = 0,\
        score = 0,\
        event_cnt = 0,\
        qdev_num = 0,\
        qdev_info = {\
            -- [mac] = { dev_score, dev_flow_num, low_lan, low_lan_net, low_lan_app, low_wan, low_wan_net, low_wan_app, low_http, low_lost_pct, qapp_info = { [appid] = { app_score, app_flow_num } } }\
        },\
    }\
\
    -- 对质差应用的分数进行排序\
    local function comp_score(table1, table2)\
        if type(table1.app_score) ~= \"number\" then\
            return false\
        end\
        if type(table2.app_score) ~= \"number\" then\
            return true\
        end\
        return table1.app_score < table2.app_score\
    end\
\
    local home_flow_all_cnt, home_conn_succ_cnt, home_flow_hscore_cnt = 0, 0, 0\
    -- 遍历整个质量统计数据\
    for mac, mac_obj in pairs(statin) do\
        local qapp_info = {}\
        local dev_flow_all_cnt, dev_conn_succ_cnt, dev_flow_hscore_cnt = 0, 0, 0\
        -- 遍历终端下所有应用的统计数据\
        for app_id, app_obj in pairs(mac_obj) do\
            if app_id ~= \"contrib\" then\
                local appscore = calc_last_score(app_obj.flow_all_cnt, app_obj.conn_succ_cnt, app_obj.flow_hscore_cnt, consuc_weight, hscore_weight)\
                if appscore > 0 and appscore < q_event_requir.pass_score and app_obj.flow_all_cnt >= q_event_requir.app_min_num then\
                    -- 从 ruleid_hit_set.ruleid_set 生成 ruleids 数组\
                    local ruleid_hit_array = {}\
                    for ruleid_str, _ in pairs(app_obj.ruleid_hit_set.ruleid_set) do\
                        table.insert(ruleid_hit_array, tonumber(ruleid_str))\
                    end\
                    table.insert(qapp_info, {\
                        app_score = appscore,\
                        appid = tonumber(app_id),\
                        ruleids = ruleid_hit_array,\
                        app_flow_num = app_obj.flow_all_cnt,\
                        app_conn_succ_num = app_obj.conn_succ_cnt,\
                        app_flow_hscore_num = app_obj.flow_hscore_cnt,\
                    })\
                end\
                dev_flow_all_cnt = app_obj.flow_all_cnt + dev_flow_all_cnt\
                dev_conn_succ_cnt = app_obj.conn_succ_cnt + dev_conn_succ_cnt\
                dev_flow_hscore_cnt = app_obj.flow_hscore_cnt + dev_flow_hscore_cnt\
            end\
        end\
        table.sort(qapp_info, comp_score)\
        local dev_score = calc_last_score(dev_flow_all_cnt, dev_conn_succ_cnt, dev_flow_hscore_cnt, consuc_weight, hscore_weight)\
        if dev_score > 0 and dev_score < q_event_requir.pass_score and dev_flow_all_cnt >= q_event_requir.dev_min_num then\
            q_event.qdev_num = q_event.qdev_num + 1\
            q_event.qdev_info[mac] = {\
                dev_score = dev_score,\
                dev_flow_num = dev_flow_all_cnt,\
                qapp_info = table.move(qapp_info, 1, q_event_qapp_max, 1, {}),\
            }\
            for f, stat in pairs(mac_obj.contrib) do\
                if type(stat) == \"table\" and stat.getMean then\
                    q_event.qdev_info[mac][\"low_\"..f] = stat:getMean()\
                end\
            end\
        end\
        q_event.dev_num = q_event.dev_num + 1\
        home_flow_all_cnt = dev_flow_all_cnt + home_flow_all_cnt\
        home_conn_succ_cnt = dev_conn_succ_cnt + home_conn_succ_cnt\
        home_flow_hscore_cnt = dev_flow_hscore_cnt + home_flow_hscore_cnt\
    end\
    q_event.flow_num = home_flow_all_cnt\
    q_event.score = calc_last_score(home_flow_all_cnt, home_conn_succ_cnt, home_flow_hscore_cnt, consuc_weight, hscore_weight)\
    if q_event.score == -1 or q_event.qdev_num == 0 then\
        return false, q_event\
    end\
\
    return true, q_event\
end\
\
-- 计算最终得分\
function qcalc.calc_last_score(flow_all_cnt, conn_succ_cnt, flow_hscore_cnt, consuc_weight, hscore_weight)\
    if flow_all_cnt == 0 or conn_succ_cnt == 0 then\
        return -1\
    end\
    return (consuc_weight * (conn_succ_cnt / flow_all_cnt) + hscore_weight * (flow_hscore_cnt / conn_succ_cnt)) * 100\
end\
\
local function event_qcalc()\
    if not qcalc.enable then\
        return\
    end\
\
    -- 暂停基线统计\
    lcmd_run({subtype = \"qblstats\", action = \"drt_stop\"})\
\
    -- 检查是否发生质差\
    qcalc.last_statdata = qcalc.statdata\
    local happen, event_info = qcalc.quality_check(qcalc.statdata, qcalc.lmodel_hscore_weight, qcalc.lmodel_consuc_weight, qcalc.q_event_requir, qcalc.q_event_qapp_max, qcalc.calc_last_score)\
\
    -- 恢复基线统计\
    lcmd_run({subtype = \"qblstats\", action = \"drt_start\"})\
\
    qcalc.statdata = {}\
    qcalc.stat_all_app_cnt = 0\
    qcalc.last_qcalc = event_info\
    if not happen then\
        return\
    end\
    qcalc.q_event_cnt_day = qcalc.q_event_cnt_day + 1\
    event_info.event_cnt = qcalc.q_event_cnt_day\
    if qcalc.q_event_cnt_hour >= qcalc.q_event_max then\
        return\
    end\
\
    -- 收集根因数据\
    event_info.rcinfo = {}\
    local _, gw_info = lcmd_run({subtype = \"qrcstats\", action = \"get_gw_info\"})\
    if type(gw_info) == \"table\" then\
        event_info.rcinfo.gw_info = gw_info\
    end\
    local _, port_rate = lcmd_run({subtype = \"qrcstats\", action = \"get_port_rate\"})\
    if type(port_rate) == \"table\" then\
        event_info.rcinfo.port_rate = port_rate\
    end\
    local _, wifi_info = lcmd_run({subtype = \"qrcstats\", action = \"get_wifi_self\"})\
    if type(wifi_info) == \"table\" then\
        event_info.rcinfo.wifi_info = wifi_info\
    end\
    local _, wifi_neighbor = lcmd_run({subtype = \"qrcstats\", action = \"get_wifi_neighbor\"})\
    if type(wifi_neighbor) == \"table\" then\
        event_info.rcinfo.wifi_neighbor = wifi_neighbor\
    end\
    local _, online_host = lcmd_run({subtype = \"qrcstats\", action = \"get_online_term\"})\
    if type(online_host) == \"table\" then\
        for mac, info in pairs(event_info.qdev_info) do\
            for k, v in pairs(online_host[mac] or online_host[string.lower(mac)] or {}) do\
                info[k] = v\
            end\
        end\
    end\
    local _, arping = lcmd_run({subtype = \"arping\", action = \"get_arping\"})\
    if type(arping) == \"table\" then\
        for mac, info in pairs(event_info.qdev_info) do\
            for k, v in pairs(arping[mac] or arping[string.lower(mac)] or {}) do\
                info[k] = v\
            end\
        end\
    end\
\
    -- 收集基线数据\
    event_info.blinfo = {}\
    local _, blinfo = lcmd_run({subtype = \"qblstats\", action = \"get_blinfo\"})\
    if type(blinfo) == \"table\" then\
        if type(blinfo.hour) == \"table\" then\
            event_info.blinfo.hour = {\
                time = blinfo.hour.time,\
                gateway = blinfo.hour.gateway,\
                lanhost = {},\
            }\
            for mac, info in pairs(event_info.qdev_info) do\
                if type(blinfo.hour.lanhost) == \"table\" then\
                    event_info.blinfo.hour.lanhost[mac] = blinfo.hour.lanhost[mac]\
                end\
            end\
        end\
        if type(blinfo.day) == \"table\" then\
            event_info.blinfo.day = {\
                time = blinfo.day.time,\
                gateway = blinfo.day.gateway,\
                lanhost = {},\
            }\
            for mac, info in pairs(event_info.qdev_info) do\
                if type(blinfo.day.lanhost) == \"table\" then\
                    event_info.blinfo.day.lanhost[mac] = blinfo.day.lanhost[mac]\
                end\
            end\
        end\
    end\
    local _, lastdrt = lcmd_run({subtype = \"qblstats\", action = \"drt_showlast\"})\
    if type(lastdrt) == \"table\" then\
        event_info.blinfo.lastdrt = {\
            time = lastdrt.time,\
            gateway = lastdrt.gateway,\
            lanhost = {},\
        }\
        for mac, info in pairs(event_info.qdev_info) do\
            if type(lastdrt.lanhost) == \"table\" then\
                event_info.blinfo.lastdrt.lanhost[mac] = lastdrt.lanhost[mac]\
            end\
        end\
    end\
\
    -- 上传事件数据\
    local len = string.len(cjson.encode({event_info}))\
    lcmd_run({subtype = \"qsvr\", action = \"oper_raw\", action_type = CENUM.COMM_ACTION_DEVOPS_DPI_QUALITY_EVENT, data = {event_info}})\
    event_info[\"type\"] = \"q_event\"\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = event_info})\
    qcalc.last_event = event_info\
    qcalc.upload_lasttime = myutil.os_time()\
    qcalc.upload_all_len = qcalc.upload_all_len + len\
    qcalc.upload_all_count = qcalc.upload_all_count + 1\
    qcalc.q_event_cnt_hour = qcalc.q_event_cnt_hour + 1\
end\
\
local function collect_rcbl()\
    if not qcalc.enable or not qcalc.sn_allow_upload then\
        return\
    end\
    local rcbl = {\
        timestamp = myutil.os_time(),\
        rcinfo = {},\
        blinfo = {},\
    }\
\
    -- 收集根因数据\
    local _, gw_info = lcmd_run({subtype = \"qrcstats\", action = \"get_gw_info\"})\
    if type(gw_info) == \"table\" then\
        rcbl.rcinfo.gw_info = gw_info\
    end\
    local _, port_rate = lcmd_run({subtype = \"qrcstats\", action = \"get_port_rate\"})\
    if type(port_rate) == \"table\" then\
        rcbl.rcinfo.port_rate = port_rate\
    end\
    local _, wifi_info = lcmd_run({subtype = \"qrcstats\", action = \"get_wifi_self\"})\
    if type(wifi_info) == \"table\" then\
        rcbl.rcinfo.wifi_info = wifi_info\
    end\
    local _, wifi_neighbor = lcmd_run({subtype = \"qrcstats\", action = \"get_wifi_neighbor\"})\
    if type(wifi_neighbor) == \"table\" then\
        rcbl.rcinfo.wifi_neighbor = wifi_neighbor\
    end\
\
    -- 收集基线数据\
    local _, blinfo = lcmd_run({subtype = \"qblstats\", action = \"get_blinfo\"})\
    if type(blinfo) == \"table\" then\
        rcbl.blinfo = blinfo\
    end\
\
    -- 数据上传\
    local len = string.len(cjson.encode({rcbl}))\
    lcmd_run({subtype = \"qsvr\", action = \"oper_raw\", action_type = CENUM.COMM_ACTION_DEVOPS_DPI_QUALITY_DATA_RCBL, data = {rcbl}})\
    rcbl[\"type\"] = \"rcbl_uplaod\"\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = rcbl})\
    qcalc.rcbl_stats.upload_all_len = qcalc.rcbl_stats.upload_all_len + len\
    qcalc.rcbl_stats.upload_all_count = qcalc.rcbl_stats.upload_all_count + 1\
    qcalc.rcbl_stats.upload_lasttime = rcbl.timestamp\
end\
\
local function update_sn_allow()\
    local _, arch = lcmd_run({subtype = \"arch\", action = \"read\"})\
    if type(arch) ~= \"table\" then\
        return\
    end\
    local snmd5 = ccrypto.md5(arch.sn)\
    local _, _, _, d = string.unpack(\">IIII\", snmd5)\
    if d % 1000 < qcalc.sn_upload_scope then\
        qcalc.sn_allow_upload = true\
    else\
        qcalc.sn_allow_upload = false\
    end\
end\
\
local function read(t)\
    return {\
        seed = qcalc.seed,\
        enable = qcalc.enable,\
        q_event_max = qcalc.q_event_max,\
        q_event_qapp_max = qcalc.q_event_qapp_max,\
        stat_all_app_max = qcalc.stat_all_app_max,\
        stat_ruleid_max = qcalc.stat_ruleid_max,\
        period = qcalc.period,\
        sn_upload_scope = qcalc.sn_upload_scope,\
        model_conf = {\
            model_magic = qcalc.model_magic,\
            model_seed = qcalc.model_seed,\
            calc_period = qcalc.calc_period,\
            pre_lat_thres = qcalc.pre_lat_thres,\
            low_score_thres = qcalc.low_score_thres,\
            high_score_thres = qcalc.high_score_thres,\
            lmodel = t.show_model and qcalc.lmodel or nil,\
            app_lmodel = t.show_model and qcalc.app_lmodel or nil,\
            lmodel_hscore_weight = qcalc.lmodel_hscore_weight,\
            lmodel_consuc_weight = qcalc.lmodel_consuc_weight,\
            q_event_requir = qcalc.q_event_requir,\
        },\
    }\
end\
\
local function stat()\
    return {\
        upload_all_len = qcalc.upload_all_len,\
        upload_all_count = qcalc.upload_all_count,\
        upload_lasttime = qcalc.upload_lasttime,\
        q_event_cnt_day = qcalc.q_event_cnt_day,\
        q_event_cnt_hour = qcalc.q_event_cnt_hour,\
        stat_all_app_cnt = qcalc.stat_all_app_cnt,\
        last_qcalc = {\
            timestamp = qcalc.last_qcalc.timestamp,\
            dev_num = qcalc.last_qcalc.dev_num,\
            flow_num = qcalc.last_qcalc.flow_num,\
            score = qcalc.last_qcalc.score,\
            qdev_num = qcalc.last_qcalc.qdev_num,\
            qdev_info = qcalc.last_qcalc.qdev_info,\
        },\
        rcbl_stats = qcalc.rcbl_stats,\
        sn_allow_upload = qcalc.sn_allow_upload,\
    }\
end\
\
local function load_lmodel(lmodel)\
    if type(lmodel) ~= \"table\" then\
        return\
    end\
    for protocol, model in pairs(qcalc.lmodel) do\
        if type(lmodel[protocol]) ~= \"table\" then\
            return\
        end\
        for key, value in pairs(model) do\
            if type(lmodel[protocol][key]) ~= type(value) then\
                return\
            end\
        end\
        for f, w in pairs(model.weight) do\
            if type(lmodel[protocol][\"weight\"][f]) ~= type(w) then\
                return\
            end\
        end\
    end\
    return lmodel\
end\
\
local function write(t)\
    local need_save = nil\
\
    qcalc.seed = myutil.check_input(t.seed, \"string\", qcalc.seed) or qcalc.seed\
    if myutil.check_input(t.enable, \"boolean\", qcalc.enable) ~= nil then\
        qcalc.enable = t.enable\
        if qcalc.enable then\
            timer.mod(qcalc.timer_name, qcalc.calc_period, 0, event_qcalc)\
            timer.mod(qcalc.timer_name_rcbl, qcalc.period, 0, collect_rcbl)\
            timer.mod(\"qcalc_event_timer_day\", 86400, 0, function () qcalc.q_event_cnt_day = 0 end)\
            timer.mod(\"qcalc_event_timer_hour\", 3600, 0, function () qcalc.q_event_cnt_hour = 0 end)\
            if qcalc.calc_period > 0 then\
                lcmd_run({subtype = \"qblstats\", action = \"drt_start\"})\
            end\
        else\
            timer.del(qcalc.timer_name)\
            timer.del(qcalc.timer_name_rcbl)\
            timer.del(\"qcalc_event_timer_day\")\
            timer.del(\"qcalc_event_timer_hour\")\
            lcmd_run({subtype = \"qblstats\", action = \"drt_stop\"})\
        end\
    end\
    qcalc.q_event_max = myutil.check_input(t.q_event_max, \"uinteger\", qcalc.q_event_max) or qcalc.q_event_max\
    qcalc.q_event_qapp_max = myutil.check_input(t.q_event_qapp_max, \"uinteger\", qcalc.q_event_qapp_max) or qcalc.q_event_qapp_max\
    qcalc.stat_all_app_max = myutil.check_input(t.stat_all_app_max, \"uinteger\", qcalc.stat_all_app_max) or qcalc.stat_all_app_max\
    qcalc.stat_ruleid_max = myutil.check_input(t.stat_ruleid_max, \"uinteger\", qcalc.stat_ruleid_max) or qcalc.stat_ruleid_max\
    if myutil.check_input(t.period, \"uinteger\", qcalc.period) then\
        qcalc.period = t.period\
        timer.mod(qcalc.timer_name_rcbl, qcalc.period, 0, collect_rcbl)\
    end\
    if myutil.check_input(t.sn_upload_scope, \"unumber\", qcalc.sn_upload_scope) and t.sn_upload_scope <= 1000 then\
        qcalc.sn_upload_scope = t.sn_upload_scope\
        update_sn_allow()\
    end\
\
    -- model config\
    if myutil.check_input(t.model_seed, \"string\", qcalc.model_seed) then\
        need_save = true\
        qcalc.model_seed = t.model_seed\
        if myutil.check_input(t.calc_period, \"uinteger\", qcalc.calc_period) then\
            qcalc.calc_period = t.calc_period\
            timer.mod(qcalc.timer_name, qcalc.calc_period, 0, event_qcalc)\
            if qcalc.enable and qcalc.calc_period > 0 then\
                lcmd_run({subtype = \"qblstats\", action = \"drt_start\"})\
            else\
                lcmd_run({subtype = \"qblstats\", action = \"drt_stop\"})\
            end\
        end\
        qcalc.pre_lat_thres = myutil.check_input(t.pre_lat_thres, \"uinteger\", qcalc.pre_lat_thres) or qcalc.pre_lat_thres\
        if (myutil.check_input(t.low_score_thres, \"unumber\", nil) and myutil.check_input(t.high_score_thres, \"unumber\", qcalc.high_score_thres)) or\
            (myutil.check_input(t.low_score_thres, \"unumber\", qcalc.low_score_thres) and myutil.check_input(t.high_score_thres, \"unumber\", nil)) then\
            if t.low_score_thres <= t.high_score_thres then\
                qcalc.low_score_thres = t.low_score_thres\
                qcalc.high_score_thres = t.high_score_thres\
            end\
        end\
        qcalc.lmodel = load_lmodel(t.lmodel) or qcalc.lmodel\
        if type(t.app_lmodel) == \"table\" then\
            for appid, lmodel in pairs(t.app_lmodel) do\
                if type(appid) == \"string\" and tonumber(appid) then\
                    qcalc.app_lmodel[appid] = load_lmodel(lmodel) or qcalc.app_lmodel[appid]\
                end\
            end\
        end\
        if (myutil.check_input(t.lmodel_hscore_weight, \"range0_1\", nil) and myutil.check_input(t.lmodel_consuc_weight, \"range0_1\", qcalc.lmodel_consuc_weight)) or\
            (myutil.check_input(t.lmodel_hscore_weight, \"range0_1\", qcalc.lmodel_hscore_weight) and myutil.check_input(t.lmodel_consuc_weight, \"range0_1\", nil)) then\
            qcalc.lmodel_hscore_weight = t.lmodel_hscore_weight\
            qcalc.lmodel_consuc_weight = t.lmodel_consuc_weight\
        end\
        if type(t.q_event_requir) == \"table\" then\
            qcalc.q_event_requir.pass_score = myutil.check_input(t.q_event_requir.pass_score, \"unumber\", qcalc.q_event_requir.pass_score) or qcalc.q_event_requir.pass_score\
            qcalc.q_event_requir.dev_min_num = myutil.check_input(t.q_event_requir.dev_min_num, \"uinteger\", qcalc.q_event_requir.dev_min_num) or qcalc.q_event_requir.dev_min_num\
            qcalc.q_event_requir.app_min_num = myutil.check_input(t.q_event_requir.app_min_num, \"uinteger\", qcalc.q_event_requir.app_min_num) or qcalc.q_event_requir.app_min_num\
        end\
    end\
\
    if need_save and not t.postinit then\
        local err = myfile.store_crypto_json(read({show_model = true}).model_conf, qcalc.filename)\
        if err then\
            log.error(err)\
        else\
            log.trace(\"save model_conf to local file \"..qcalc.filename)\
        end\
    end\
end\
\
local function update(t)\
    if myutil.check_input(t.model_seed, \"string\", qcalc.model_seed) and type(t.data) == \"string\" and #t.data > 0 then\
        local ok, model_json = pcall(mime.unb64, t.data)\
        if not ok or not model_json then\
            log.error(\"Wrong base64 model_conf \"..t.data)\
            return \"Wrong base64 model_conf.\"\
        end\
        local ok, model_conf = pcall(cjson.decode, model_json)\
        if not ok or type(model_conf) ~= \"table\" then\
            log.error(\"Wrong json model_conf \"..model_json)\
            return \"Wrong json model_conf.\"\
        end\
        model_conf.model_seed = t.model_seed\
        write(model_conf)\
    end\
end\
\
function qcalc.postinit()\
    qcalc.filename = lcmd_data_path(\"model_conf.bin\")\
    local model_conf, err = myfile.load_crypto_json(qcalc.filename)\
    if err or type(model_conf) ~= \"table\" then\
        log.info(err)\
    elseif model_conf.model_magic ~= qcalc.model_magic then\
        log.info(\"local model_conf magic not match\")\
    else\
        model_conf.postinit = true\
        write(model_conf)\
    end\
\
    update_sn_allow()\
    qcalc.qindex = actor.subscribe(\"QUALCOL\", qualcol_deal)\
end\
\
function qcalc.finish()\
    if qcalc.qindex then\
        actor.unsubscribe(\"QUALCOL\", qcalc.qindex)\
    end\
    timer.del(qcalc.timer_name)\
    timer.del(qcalc.timer_name_rcbl)\
    timer.del(\"qcalc_event_timer_day\")\
    timer.del(\"qcalc_event_timer_hour\")\
end\
\
actor.action_set(qcalc.subtype, \"show_conf_svr\", function() return {type = qcalc.type, seed = qcalc.seed} end, \"show qcalc conf msg to oper svr\")\
\
actor.action_set(qcalc.subtype, \"read\", read, \"read qcalc conf\")\
actor.action_set(qcalc.subtype, \"read_seed\", function () return qcalc.model_seed end, \"read qcalc model_seed\")\
actor.action_set(qcalc.subtype, \"stat\", stat, \"read qcalc stat\")\
actor.action_set(qcalc.subtype, \"show_stat\", function () return qcalc.statdata end, \"show qcalc statdata\")\
actor.action_set(qcalc.subtype, \"show_last_stat\", function () return qcalc.last_statdata end, \"show qcalc last statdata\")\
actor.action_set(qcalc.subtype, \"show_last_event\", function () return qcalc.last_event end, \"show qcalc last_event\")\
actor.action_set(qcalc.subtype, \"write\", write, \"write qcalc conf, {seed = string, enable = boolean, q_event_max = integer, q_event_qapp_max = integer, stat_all_app_max = integer, stat_ruleid_max = integer, period = uinteger, sn_upload_scope = unumber}\")\
actor.action_set(qcalc.subtype, \"update\", update, \"update model conf, {model_seed = string, data = base64_string}\")\
actor.action_set(qcalc.subtype, \"upload_rcbl\", collect_rcbl, \"trigger upload rcbl once\")\
\
return qcalc\
"
, '@'.."./service/qcalc.lua" ) )

package.preload[ "qcollect" ] = assert( (loadstring or load)(
"local actor = require(\"luactor\")\
local cjson = require(\"cjson\")\
local sampling = require(\"sampling\")\
local ccrypto = require(\"c.crypto\")\
local myutil = require(\"myutil\")\
local myfile = require(\"myfile\")\
local stats = require(\"stats\")\
local log = require(\"log\")\
local has_ftcsv, ftcsv = pcall(require, \"ftcsv\")\
\
local qcollect = {\
    type = \"qcollect\",\
    subtype = \"qcollect\",\
    help = \"data collection for poor network quality\",\
    upload_type = \"quality_data\",\
    upload_mode = \"qsvr\", -- \"none\", \"qsvr\", \"svrdata\", \"operdata\", \"all\"\
    tindex = nil,\
\
    -- config\
    enable = false,\
    ratio = nil, -- data sampling, 1:100, 单个家庭数据随机采样\
    sensing_host = { [\"PC\"] = true, [\"phone\"] = true, [\"Pad\"] = true, [\"ROUTER\"] = true, [\"elink\"] = true, [\"FTTRsub\"] = true },    -- 空数组表示不关注是否为有感终端\
    sn_upload_scope = 0, -- [0, 1000], 按照网关sn千分比采样上报\
\
    -- stat\
    dsmp = nil,\
    all_len = 0,\
    all_count = 0,\
    sn_allow_upload = true,\
    upload_data = nil,\
}\
\
local function calc_avg_lat(lat_info, start_i, stat)\
    local latency_cnt = lat_info.latency_cnt or 0\
    local lat_calc_sum, lat_calc_cnt = 0, 0\
    for i = start_i, latency_cnt, 2 do\
        lat_calc_sum = lat_calc_sum + (lat_info[\"lat\"..i] or 0)\
        lat_calc_cnt = lat_calc_cnt + 1\
        if type(stat) == \"table\" and stat.update then\
            stat:update(lat_info[\"lat\"..i])\
        end\
    end\
    if lat_calc_cnt == 0 then   -- No delay record\
        return 0\
    end\
    local lat_avg = math.modf(lat_calc_sum/lat_calc_cnt)\
    return lat_avg\
end\
\
local function pub_upload(tt)\
    if type(tt) ~= \"table\" then\
        return\
    end\
    qcollect.upload_data = tt\
    actor.publish({msgtype = \"QUALCOL\", quality_data = tt})\
    qcollect.upload_data = nil\
\
    if qcollect.upload_mode ~= \"none\" and (not qcollect.dsmp or qcollect.dsmp:accept()) and qcollect.sn_allow_upload then\
        if qcollect.upload_mode == \"operdata\" or qcollect.upload_mode == \"all\" then\
            lcmd_run({subtype = \"__oper_data\", action = \"add\", data = tt})\
        end\
        if qcollect.upload_mode == \"svrdata\" or qcollect.upload_mode == \"all\" then\
            lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = tt})\
        end\
        if qcollect.upload_mode == \"qsvr\" or qcollect.upload_mode == \"all\" then\
            lcmd_run({subtype = \"qsvr\", action = \"add\", data = tt})\
        end\
        qcollect.all_len = qcollect.all_len + string.len(cjson.encode(tt))\
        qcollect.all_count = qcollect.all_count + 1\
    end\
end\
\
local function tuple_deal(msg)\
    if not qcollect.enable then\
        return\
    end\
\
    local tuple_info = msg.tuple_info\
\
    local ok, oss = lcmd_run({subtype = \"osinfo\", action = \"get_oss\"})\
    if not ok or type(oss) ~= \"table\" then\
        oss = {}\
    end\
    local dev_type = (oss[tuple_info.mac] and oss[tuple_info.mac].desc and oss[tuple_info.mac].desc.dev_type) or \"OTHER\"\
    if #qcollect.sensing_host > 0 and not qcollect.sensing_host[dev_type] then\
        return\
    end\
\
    local wan_stat, lan_stat, lat_stat, raw_info = stats:new(), stats:new(), stats:new(), {}\
    for i = 1, tuple_info.latency_cnt or 0 do\
        lat_stat:update(tuple_info[\"lat\"..i])\
        table.insert(raw_info, tuple_info[\"lat\"..i])\
    end\
    pub_upload({\
        type = qcollect.upload_type,\
        mac = tuple_info.mac,\
        osid = oss[tuple_info.mac] and (oss[tuple_info.mac].decide_osid or oss[tuple_info.mac].cloud_osid or 0) or 0,\
        sip = tuple_info.sip,\
        dip = tuple_info.dip,\
        sport = tuple_info.sport,\
        dport = tuple_info.dport,\
        proto = tuple_info.proto,\
        appid = tuple_info.app_id,\
        ruleid = tuple_info.ruleid,\
        base_appid = tuple_info.base_appid,\
        raw_lat = table.concat(raw_info, \",\"),\
        lat1 = tuple_info.lat1,\
        wan_lat = calc_avg_lat(tuple_info, 1, wan_stat),\
        wan_app_lat = calc_avg_lat(tuple_info, 3),\
        lat2 = tuple_info.lat2,\
        lan_lat = calc_avg_lat(tuple_info, 2, lan_stat),\
        lan_app_lat = calc_avg_lat(tuple_info, 4),\
        http_lat = (tuple_info.base_appid == 6 and tuple_info.latency_cnt >= 4) and (tuple_info.lat1 + tuple_info.lat2 + tuple_info.lat3 + tuple_info.lat4) or 0,\
        pkt_loss_cnt = tuple_info.retransmit_cnt,\
        pkt_pl_cnt = tuple_info.proto == 6 and tuple_info.L7_total or 0,\
        pkts_in = tuple_info.pkts_in,\
        pkts_out = tuple_info.pkts_out,\
        bytes_in = tuple_info.bytes_in,\
        bytes_out = tuple_info.bytes_out,\
        duration = lat_stat:getSum(),\
        lat_status = tuple_info.lat_status,\
        timestamp = tostring(myutil.os_time()),\
        start_time = tostring(tuple_info.start_time),\
        end_time = tostring(tuple_info.end_time),\
        wan_std = wan_stat:getStdDev(),\
        lan_std = lan_stat:getStdDev(),\
        lat_std = lat_stat:getStdDev(),\
        wan_mjt = wan_stat:getMeanJitter(),\
        lan_mjt = lan_stat:getMeanJitter(),\
        lat_mjt = lat_stat:getMeanJitter(),\
    })\
end\
\
local function set_field(t)\
    local upload_data, data = qcollect.upload_data, t.data\
    if type(upload_data) ~= \"table\" or type(data) ~= \"table\" then\
        return\
    end\
    for key, value in pairs(data) do\
        upload_data[key] = value\
    end\
end\
\
local function update_sn_allow()\
    local _, arch = lcmd_run({subtype = \"arch\", action = \"read\"})\
    if type(arch) ~= \"table\" then\
        return\
    end\
    local snmd5 = ccrypto.md5(arch.sn)\
    local _, _, _, d = string.unpack(\">IIII\", snmd5)\
    if d % 1000 < qcollect.sn_upload_scope then\
        qcollect.sn_allow_upload = true\
    else\
        qcollect.sn_allow_upload = false\
    end\
end\
\
local function read()\
    local sensing_host = {}\
    for dev_type, _ in pairs(qcollect.sensing_host) do\
        table.insert(sensing_host, dev_type)\
    end\
    return {\
        enable = qcollect.enable,\
        ratio = qcollect.dsmp and qcollect.dsmp:getRatio() or nil,\
        sensing_host = sensing_host,\
        sn_upload_scope = qcollect.sn_upload_scope,\
        upload_mode = qcollect.upload_mode,\
    }\
end\
\
local function stat()\
    return {\
        all_len = qcollect.all_len,\
        all_count = qcollect.all_count,\
        dsmp = qcollect.dsmp and qcollect.dsmp:show() or nil,\
        sn_allow_upload = qcollect.sn_allow_upload,\
    }\
end\
\
local function set_maxbaseappid(enable)\
    if enable then\
        lcmd_run({subtype = \"appsig_bin\", action = \"set_maxbaseappid\", max_base_appid = 7})\
    else\
        lcmd_run({subtype = \"appsig_bin\", action = \"set_maxbaseappid\", max_base_appid = 0})\
    end\
end\
\
local function write(t)\
    if type(t.enable) == \"boolean\" and t.enable ~= qcollect.enable then\
        qcollect.enable = t.enable\
        set_maxbaseappid(qcollect.enable)\
    end\
    if type(t.ratio) == \"number\" and 0 <= t.ratio and t.ratio < 1 then\
        qcollect.dsmp = t.ratio > 0 and sampling.newAverager(t.ratio) or nil\
    end\
    if type(t.sensing_host) == \"table\" then\
        qcollect.sensing_host = {}\
        for _, dev_type in ipairs(t.sensing_host) do\
            if type(dev_type) == \"string\" and dev_type ~= \"\" then\
                qcollect.sensing_host[dev_type] = true\
            end\
        end\
    end\
    if type(t.sn_upload_scope) == \"number\" and 0 <= t.sn_upload_scope and t.sn_upload_scope <= 1000 then\
        qcollect.sn_upload_scope = t.sn_upload_scope\
        update_sn_allow()\
    end\
    if type(t.upload_mode) == \"string\" and t.upload_mode ~= qcollect.upload_mode then\
        if t.upload_mode == \"none\" or t.upload_mode == \"qsvr\" or t.upload_mode == \"svrdata\" or t.upload_mode == \"operdata\" or t.upload_mode == \"all\" then\
            qcollect.upload_mode = t.upload_mode\
        end\
    end\
end\
\
local function replay(t)\
    if not has_ftcsv or type(ftcsv.parseLine) ~= \"function\" then\
        return\
    end\
    if not myfile.existed(t.csv_file) then\
        return\
    end\
    for i, line in ftcsv.parseLine(t.csv_file, \",\", {bufferSize=2^16}) do\
        if type(line) == \"table\" then\
            pub_upload({\
                type = qcollect.upload_type,\
                mac = line.mac,\
                osid = tonumber(line.osid),\
                sip = line.sip,\
                dip = line.dip,\
                sport = tonumber(line.sport),\
                dport = tonumber(line.dport),\
                proto = tonumber(line.proto),\
                appid = tonumber(line.appid),\
                protoid = tonumber(line.protoid),\
                base_appid = tonumber(line.base_appid),\
                raw_lat = line.raw_lat,\
                lat1 = tonumber(line.lat1),\
                wan_lat = tonumber(line.wan_lat),\
                wan_app_lat = tonumber(line.wan_app_lat),\
                lat2 = tonumber(line.lat2),\
                lan_lat = tonumber(line.lan_lat),\
                lan_app_lat = tonumber(line.lan_app_lat),\
                http_lat = tonumber(line.http_lat),\
                pkt_loss_cnt = tonumber(line.pkt_loss_cnt),\
                pkt_pl_cnt = tonumber(line.pkt_pl_cnt),\
                pkts_in = tonumber(line.pkts_in),\
                pkts_out = tonumber(line.pkts_out),\
                bytes_in = tonumber(line.bytes_in),\
                bytes_out = tonumber(line.bytes_out),\
                duration = tonumber(line.duration),\
                lat_status = line.lat_status,\
                timestamp = line.timestamp,\
                start_time = line.start_time,\
                end_time = line.end_time,\
                wan_std = tonumber(line.wan_std),\
                lan_std = tonumber(line.lan_std),\
                lat_std = tonumber(line.lat_std),\
                wan_mjt = tonumber(line.wan_mjt),\
                lan_mjt = tonumber(line.lan_mjt),\
                lat_mjt = tonumber(line.lat_mjt),\
            })\
        end\
    end\
end\
\
function qcollect.preinit()\
    -- if kernel module not reload, it must set default first\
    set_maxbaseappid(qcollect.enable)\
end\
\
function qcollect.postinit()\
    update_sn_allow()\
    qcollect.tindex = actor.subscribe(\"TUPLE\", tuple_deal)\
end\
\
function qcollect.finish()\
    if qcollect.tindex then\
        actor.unsubscribe(\"TUPLE\", qcollect.tindex)\
    end\
end\
\
actor.action_set(qcollect.subtype, \"read\", read, \"read qcollect conf\")\
actor.action_set(qcollect.subtype, \"stat\", stat, \"read qcollect stat\")\
actor.action_set(qcollect.subtype, \"write\", write, \"write qcollect conf, {enable = boolean, ratio = number, sensing_host = list<dev_type>, sn_upload_scope = number, upload_mode = string}\")\
actor.action_set(qcollect.subtype, \"set_field\", set_field, \"set qcalc result to qcollect, {data = {score = number, conn_succ = boolean, lat1_score = number, ...}}\")\
actor.action_set(qcollect.subtype, \"replay\", replay, \"replay quality_data from csv file, {csv_file = string}\")\
\
return qcollect\
"
, '@'.."./service/qcollect.lua" ) )

package.preload[ "qrcstats" ] = assert( (loadstring or load)(
"local mystring = require(\"mystring\")\
local actor = require(\"luactor\")\
local cjson = require(\"cjson\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local ctime = require(\"c.time\")\
local myutil = require(\"myutil\")\
local myfile = require(\"myfile\")\
\
local qrcstats = {\
    type = \"qrcstats\",\
    subtype = \"qrcstats\",\
    help = \"get root cause stats\",\
\
    collect_period = 0,\
    scan_channel_interval = 86400,\
    scan_neighbor_interval = 604800,\
    get_neighbor_res = 600,\
    timer_name = \"qrcstats_period_check\",\
    timer_get_scanchannel = \"get_scan_channel\",\
    timer_get_scan5Gchannel = \"get_scan_5Gchannel\",\
    timer_get_neighbor = \"get_scan_neighbor\",\
    timer_get_res = \"read_neighbor_res\",\
    scan_neighbor_time = \"03:00-04:00\",\
    sensing_host = { [\"PC\"] = true, [\"phone\"] = true, [\"Pad\"] = true,},     -- 空数组表示不关注有感终端\
    rate_limit = 1000,  -- kbps\
    int_ver = nil,\
\
    gw_info = {},\
    lan_hosts = {},   -- online\
    port_rate = {},\
    wifi_self = {},\
    wifi_neighbor ={\
        lasttime = nil,\
        daytime = nil,\
        scan_time = nil,\
        self_scan = false,\
        wself = {},\
        neighbor = {},\
    },\
    scan_channel = {\
        status = false,\
        lasttime = nil,\
    },\
\
    lhinfo = {},        -- last online hosts\
    lninfo = {},        -- last network info\
}\
\
function qrcstats.gdbus_parse(res, file)\
    local cmd_res = res or myfile.read(file or \"\")\
    if type(cmd_res) ~= \"string\" or cmd_res == \"\" then\
        log.error(\"gdbus cmd_res is not string or empty\")\
        return\
    end\
\
    -- 去除开头非{的字符:去除尾部非}的字符:将'转为\":去除成对的<>:去除开头{和\"之间的字符:去除uint32、uint64等整数符号:去除double符:将byte的值转换为十进制:保留字典:保留数组:匹配最后一个平衡{}\
    local result = cmd_res:gsub(\"^%s*[^{]+\", \"\"):gsub(\"[^}]+%s*$\", \"\"):gsub(\"'\", \"\\\"\"):gsub(\"(%b<>)\", function (w) return w:sub(2,-2) end):gsub('^{.-\"', '{\"'):gsub(\"u?int%d%d%s+(%-?%d+)\", \"%1\"):gsub(\"double%s+(%-?%d+%.?%d*)\", \"%1\"):gsub(\"byte%s+0x(%w+)\", function(hex) return tonumber(hex, 16) end):gsub(\"@a[%{%}%a]+%s+(%b{})\", \"%1\"):gsub(\"@a[%{%}%a]+%s+(%b[])\", \"%1\"):match(\"^(%b{})$\")\
\
    if not result then\
        log.error(\"failed to parse gdbus cmd_res, invalid data:\", cmd_res)\
        return\
    end\
\
    -- 将JSON字符串解析为Lua表\
    local ok, tbl, err = pcall(cjson.decode, result)\
    if not ok or not tbl then\
        log.error(\"decode json failed:\", result, \",pcall error is\", tostring(tbl), \",err is\", tostring(err))\
        return\
    end\
    return tbl\
end\
\
function qrcstats.gdbus_call(cmd)\
    if type(cmd) ~= \"string\" or cmd == \"\" then\
        log.warn(\"gdbus cmd is not string or empty:\", tostring(cmd))\
        return {}\
    end\
    log.debug(\"start gdbus call:\", cmd)\
    local res = myutil.popen(cmd)\
    if res == \"\" then\
        log.error(\"call gdbus cmd failed\")\
        return {}\
    end\
    log.debug(\"end gdbus call\")\
    return qrcstats.gdbus_parse(res) or {}\
end\
\
local function get_dev_info()\
    local info = qrcstats.gdbus_call(\"gdbus call -d com.ctc.igd1 -o /com/ctc/igd1/Info/Device -m com.ctc.igd1.Properties.GetAll com.ctc.igd1.DeviceInfo -y\")\
    if type(info.MAC) == \"string\" then\
        info.MAC = mystring.data2hex(mystring.hex2data(info.MAC, \"-:\"), \":\")\
    end\
