end\
\
local function bytes_delta_calc(now_bytes, old_bytes)\
    local delta_bytes = 0\
    if now_bytes >= old_bytes then\
        delta_bytes = now_bytes - old_bytes\
    else\
        delta_bytes = now_bytes\
    end\
    return delta_bytes\
end\
\
local function calc_term_rate(now, period, old)\
    local rxrate, txrate = 0, 0\
    if type(old) == \"table\" and period > 0 and now.OnlineTime > 0 then\
        local rx_bytes = bytes_delta_calc(now.RxBytes, old.RxBytes)\
        local tx_bytes = bytes_delta_calc(now.TxBytes, old.TxBytes)\
        if now.OnlineTime >= period then\
            rxrate = math.floor((rx_bytes * 8) / (1000 * period))   --kbps\
            txrate = math.floor((tx_bytes * 8) / (1000 * period))\
        else\
            rxrate = math.floor((rx_bytes * 8) / (1000 * now.OnlineTime))\
            txrate = math.floor((tx_bytes * 8) / (1000 * now.OnlineTime))\
        end\
    end\
    return rxrate, txrate\
end\
\
local function calc_port_rate(now, period, old)\
    local rate = {\
        wan_txrate = 0,\
        wan_rxrate = 0,\
        lan_txrate = 0,\
        lan_rxrate = 0,\
        lan1_txrate = 0,\
        lan1_rxrate = 0,\
        lan2_txrate = 0,\
        lan2_rxrate = 0,\
        lan3_txrate = 0,\
        lan3_rxrate = 0,\
        lan4_txrate = 0,\
        lan4_rxrate = 0,\
        wifi_txrate = 0,\
        wifi_rxrate = 0,\
    }\
    if period <= 0 then\
        return rate\
    end\
    if type(now.WANTxBytes) == \"number\" and type(old.WANTxBytes) == \"number\" and now.WANTxBytes >= old.WANTxBytes then\
        local wan_txbytes = bytes_delta_calc(now.WANTxBytes, old.WANTxBytes)\
        rate.wan_txrate = math.floor((wan_txbytes * 8) / (1000 * period))\
    end\
    if type(now.WANRxBytes) == \"number\" and type(old.WANRxBytes) == \"number\" and now.WANRxBytes >= old.WANRxBytes then\
        local wan_rxbytes = bytes_delta_calc(now.WANRxBytes, old.WANRxBytes)\
        rate.wan_rxrate = math.floor((wan_rxbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN1TXByte) == \"number\" and type(old.LAN1TXByte) == \"number\" and now.LAN1TXByte >= old.LAN1TXByte then\
        local lan1_txbytes = bytes_delta_calc(now.LAN1TXByte, old.LAN1TXByte)\
        rate.lan1_txrate = math.floor((lan1_txbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN1RXByte) == \"number\" and type(old.LAN1RXByte) == \"number\" and now.LAN1RXByte >= old.LAN1RXByte then\
        local lan1_rxbytes = bytes_delta_calc(now.LAN1RXByte, old.LAN1RXByte)\
        rate.lan1_rxrate = math.floor((lan1_rxbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN2TXByte) == \"number\" and type(old.LAN2TXByte) == \"number\" and now.LAN2TXByte >= old.LAN2TXByte then\
        local lan2_txbytes = bytes_delta_calc(now.LAN2TXByte, old.LAN2TXByte)\
        rate.lan2_txrate = math.floor((lan2_txbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN2RXByte) == \"number\" and type(old.LAN2RXByte) == \"number\" and now.LAN2RXByte >= old.LAN2RXByte then\
        local lan2_rxbytes = bytes_delta_calc(now.LAN2RXByte, old.LAN2RXByte)\
        rate.lan2_rxrate = math.floor((lan2_rxbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN3TXByte) == \"number\" and type(old.LAN3TXByte) == \"number\" and now.LAN3TXByte >= old.LAN3TXByte then\
        local lan3_txbytes = bytes_delta_calc(now.LAN3TXByte, old.LAN3TXByte)\
        rate.lan3_txrate = math.floor((lan3_txbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN3RXByte) == \"number\" and type(old.LAN3RXByte) == \"number\" and now.LAN3RXByte >= old.LAN3RXByte then\
        local lan3_rxbytes = bytes_delta_calc(now.LAN3RXByte, old.LAN3RXByte)\
        rate.lan3_rxrate = math.floor((lan3_rxbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN4TXByte) == \"number\" and type(old.LAN4TXByte) == \"number\" and now.LAN4TXByte >= old.LAN4TXByte then\
        local lan4_txbytes = bytes_delta_calc(now.LAN4TXByte, old.LAN4TXByte)\
        rate.lan4_txrate = math.floor((lan4_txbytes * 8) / (1000 * period))\
    end\
    if type(now.LAN4RXByte) == \"number\" and type(old.LAN4RXByte) == \"number\" and now.LAN4RXByte >= old.LAN4RXByte then\
        local lan4_rxbytes = bytes_delta_calc(now.LAN4RXByte, old.LAN4RXByte)\
        rate.lan4_rxrate = math.floor((lan4_rxbytes * 8) / (1000 * period))\
    end\
    if type(now.WiFiTxBytes) == \"number\" and type(old.WiFiTxBytes) == \"number\" and now.WiFiTxBytes >= old.WiFiTxBytes then\
        local wifi_txbytes = bytes_delta_calc(now.WiFiTxBytes, old.WiFiTxBytes)\
        rate.wifi_txrate = math.floor((wifi_txbytes * 8) / (1000 * period))\
    end\
    if type(now.WiFiRxBytes) == \"number\" and type(old.WiFiRxBytes) == \"number\" and now.WiFiRxBytes >= old.WiFiRxBytes then\
        local wifi_rxbytes = bytes_delta_calc(now.WiFiRxBytes, old.WiFiRxBytes)\
        rate.wifi_rxrate = math.floor((wifi_rxbytes * 8) / (1000 * period))\
    end\
    rate.lan_txrate = rate.lan1_txrate + rate.lan2_txrate + rate.lan3_txrate + rate.lan4_txrate + rate.wifi_txrate\
    rate.lan_rxrate = rate.lan1_rxrate + rate.lan2_rxrate + rate.lan3_rxrate + rate.lan4_rxrate + rate.wifi_rxrate\
    return rate\
end\
\
local function get_neighbor_scan(self_scan, read_file)\
    if not read_file then\
        lcmd_run({subtype = \"dumh\", action = \"execve\", cmd = \"cat /tmp/diaginfo/wifi_info > /opt/upt/apps/apps/opt/preinstall/b01odmv3/data/wifi_info\"})\
        timer.mod(qrcstats.timer_get_res, 60, 1, get_neighbor_scan, self_scan, true)\
        -- 需要等待wifi_info文件生成之后再触发OP插件设置启动周边WiFi扫描，经过测试如果和网关接口同时触发会导致无法生成wifi_info文件\
        os.execute([[gdbus call -y -d com.ctc.appframework1 -o /com/ctc/appframework1 -m com.ctc.appframework1.AppAgent.PostMsg \"opmaintainv3\" '{\"RequestOper\":\"GET_DATA_BY_NAME\",\"Parameter\":{\"set\":[{\"name\":\"GATEWAY_START_INTERF_SCAN\"}]},\"CmdType\":\"GET_DATA_BY_NAME\",\"SequenceId\":\"C097BA98\"}']])  -- SequenceId 取值为OP插件方提供的默认值，未做修改\
        return\
    end\
\
    local info, err = myfile.load_json(lcmd_data_path(\"wifi_info\"))\
    if type(info) ~= \"table\" then\
        local op_neigh_info = qrcstats.gdbus_call([[gdbus call -y -d com.ctc.appframework1 -o /com/ctc/appframework1 -m com.ctc.appframework1.AppAgent.PostMsg \"opmaintainv3\" '{\"RequestOper\":\"GET_DATA_BY_NAME\",\"Parameter\":{\"get\":[\"GATEWAY_INTERFERE\"]},\"CmdType\":\"GET_DATA_BY_NAME\",\"SequenceId\":\"C097BA98\"}']])    -- SequenceId 取值为OP插件方提供的默认值，未做修改\
        local op_wifi_conf = qrcstats.gdbus_call([[gdbus call -y -d com.ctc.appframework1 -o /com/ctc/appframework1 -m com.ctc.appframework1.AppAgent.PostMsg \"opmaintainv3\" '{\"RequestOper\":\"GET_DATA_BY_NAME\",\"Parameter\":{\"get\":[\"GATEWAY_WIFI_CONFIG_GET\"]},\"CmdType\":\"GET_DATA_BY_NAME\",\"SequenceId\":\"C097BA98\"}']]) or {}     -- SequenceId 取值为OP插件方提供的默认值，未做修改\
        if type(op_neigh_info) == \"table\" and tonumber(op_neigh_info.Status) == 0 and type(op_neigh_info.GATEWAY_INTERFERE) == \"table\" then\
            info = op_neigh_info.GATEWAY_INTERFERE\
            info.Interference_2G = info.Interference_2G or {}\
            info.Interference_5G = info.Interference_5G or {}\
            info.Time = op_neigh_info.Time\
            info.Info = type(op_wifi_conf.GATEWAY_WIFI_CONFIG_GET) == \"table\" and tonumber(op_wifi_conf.GATEWAY_WIFI_CONFIG_GET.status) == 0 and op_wifi_conf.GATEWAY_WIFI_CONFIG_GET.list or {}\
        else\
            log.error(\"failed to get wifi neighbor\")\
            return\
        end\
    end\
\
    if self_scan then\
        local timet = myutil.timestr_to_timetab(info.Time)\
        local timen = os.date([[*t]])\
        if type(timet) ~= \"table\" or timet.year ~= timen.year or timet.month ~= timen.month or timet.day ~= timen.day then\
            os.remove(lcmd_data_path(\"wifi_info\"))\
            return\
        end\
    end\
\
    local wself, neigh= {}, {}\
    for _, v in ipairs(info.Info) do\
        local tt = {\
            ssid = v.SSID,                                  -- 网关接口和OP插件接口取出的字段名一致\
            enable = tonumber(v.Enable or v.wifiEnable),    -- Enable为网关接口字段名，wifiEnable为OP插件接口字段名\
            rfband = v.Band or v.RFBand,                    -- Band为网关接口字段名，RFBand为OP插件接口字段名\
            rate = tonumber(v.Rate),                        -- Rate为网关接口字段名，无对应OP插件接口字段\
            bandwidth = v.Bandwidth or v.bandwidth,         -- Bandwidth为网关接口字段名，bandwidth为OP插件接口字段名\
            mode = v.Mode or v.workmode,                    -- Mode为网关接口字段名，workmode为OP插件接口字段名\
            channel = tonumber(v.Channel),                  -- 网关接口和OP插件接口取出的字段名一致\
            client_count = tonumber(v.ClientCount),         -- ClientCount为网关接口字段名，无对应OP插件接口字段\
            power_level = tonumber(v.RSSI),                 -- RSSI为网关接口字段名，无对应OP插件接口字段\
            ber = tonumber(v.BER),                          -- BER为网关接口字段名，无对应OP插件接口字段\
        }\
        table.insert(wself, tt)\
    end\
\
    -- Interference 2G/5G 在网关接口和OP插件接口取出的字段名均一致\
    for _,v in ipairs(info.Interference_2G) do\
        local tt = {\
            ssid = v.SSID,\
            bssid = v.BSSID,\
            channel = tonumber(v.Channel),\
            power_level = tonumber(v.RSSI),\
            rfband = \"2.4G\",\
        }\
        table.insert(neigh, tt)\
    end\
    for _,v in ipairs(info.Interference_5G) do\
        local tt = {\
            ssid = v.SSID,\
            bssid = v.BSSID,\
            channel = tonumber(v.Channel),\
            power_level = tonumber(v.RSSI),\
            rfband = \"5G\",\
        }\
        table.insert(neigh, tt)\
    end\
\
    os.remove(lcmd_data_path(\"wifi_info\"))\
    qrcstats.wifi_neighbor.wself = wself\
    qrcstats.wifi_neighbor.neighbor = neigh\
    qrcstats.wifi_neighbor.scan_time = info.Time\
    qrcstats.wifi_neighbor.self_scan = self_scan\
end\
\
local function check_wifi_neighbor()\
    if qrcstats.int_ver and not string.match(qrcstats.int_ver, \"^4%.\") then\
        return\
    end\
    if not qrcstats.wifi_neighbor.daytime then\
        local start_hour, start_min, end_hour, end_min = string.match(qrcstats.scan_neighbor_time, \"(%d+):(%d+)-(%d+):(%d+)\")\
        if start_hour and start_min and end_hour and end_min then\
            local shour = tonumber(start_hour)\
            local smin = tonumber(start_min)\
            local ehour = tonumber(end_hour)\
            local emin = tonumber(end_min)\
            if (ehour > shour or (ehour == shour and emin >= smin)) and (shour >= 0 and shour < 24 and ehour >= 0 and ehour < 24 and smin >= 0 and smin < 60 and emin >= 0 and emin < 60) then\
                local date = myutil.os_date([[*t]])\
                local ntime = date.hour * 60 + date.min\
                local stime = shour * 60 + smin\
                local etime = ehour * 60 + emin\
                qrcstats.wifi_neighbor.daytime = {\
                    shour = shour,\
                    smin = smin,\
                    ehour = ehour,\
                    emin = emin,\
                    actime = (stime <= ntime and ntime <= etime) and math.random(ntime, etime) or math.random(stime, etime),\
                }\
            end\
        end\
    end\
\
    local now = myutil.get_timestamp()\
    local dt = qrcstats.wifi_neighbor.daytime\
    if (not qrcstats.wifi_neighbor.lasttime or now - qrcstats.wifi_neighbor.lasttime >= qrcstats.scan_neighbor_interval) and type(dt) == \"table\" then\
        local date = myutil.os_date([[*t]])\
        local ntime = date.hour * 60 + date.min\
        if ntime >= dt.actime and date.hour >= dt.shour and date.hour <= dt.ehour then\
            log.info(\"start scanning wifi neighbor\")\
            collect_wifi_neighbor()\
            timer.mod(qrcstats.timer_get_neighbor, qrcstats.get_neighbor_res, 1, get_neighbor_scan, true)\
            qrcstats.wifi_neighbor.lasttime = now\
            qrcstats.wifi_neighbor.daytime = nil\
        end\
    end\
end\
\
local function focus_host(hosts, oss)\
    if type(hosts) ~= \"table\" or not next(hosts) or type(oss) ~= \"table\" then\
        return false\
    end\
\
    for mac, v in pairs(hosts) do\
        if v.acc_type == 1 then\
            local dev_type = oss[mac] and oss[mac].desc and oss[mac].desc.dev_type\
            if qrcstats.sensing_host[dev_type] and (v.rxrate > qrcstats.rate_limit or v.txrate > qrcstats.rate_limit) then\
                return true\
            end\
        end\
    end\
    return false\
end\
\
local function update_info()\
    local dinfo = get_dev_info()\
    local pinfo = get_pon_info()\
    local ninfo = get_network_info()\
    local diaginfo = get_diag_info()\
    local hinfo = get_lan_hosts()\
    local wconf = get_wifi_conf()\
    local winfo = get_wifi_info()\
    local dnsconf = get_dns_conf() or {}\
\
    local gw_info = {\
        cpu_use = dinfo.CPUUsage,\
        mem_use = dinfo.MEMUsage,\
        flash_use = dinfo.FlashUsage,\
        uptime = dinfo.SysDuration,\
\
        cpu_temp = diaginfo.CPUTemperature,\
        cpu_temp_threshold = diaginfo.CPUTempThreshold,\
        pon_temp_threshold = diaginfo.PONTempThreshold,\
        sys_flash_threshold = diaginfo.SystemFlashThreshold,\
        ct_num = diaginfo.ConntrackNumber,\
        ct_num_threshold = diaginfo.ConnNumThreshold,\
        lan1_nego_rate = diaginfo.LAN1NegoRate,\
        lan2_nego_rate = diaginfo.LAN2NegoRate,\
        lan3_nego_rate = diaginfo.LAN3NegoRate,\
        lan4_nego_rate = diaginfo.LAN4NegoRate,\
\
        pon_temp = pinfo.Temperature,\
        pon_txpower = pinfo.TXPower,\
        pon_rxpower = pinfo.RXPower,\
\
        pon_duration = ninfo.PONDuration,\
        pppoe_duration = ninfo.PPPOEDuration,\
\
        dev_num = #hinfo,\
\
        gwdns = type(dnsconf.SAFE_DNS) == \"table\" and type(dnsconf.SAFE_DNS.gwdns) == \"table\" and table.concat(dnsconf.SAFE_DNS.gwdns, \",\") or \"\",\
        fwkdns = type(dnsconf.SAFE_DNS) == \"table\" and type(dnsconf.SAFE_DNS.fwkdns) == \"table\" and table.concat(dnsconf.SAFE_DNS.fwkdns, \",\") or \"\",\
    }\
\
    local ok, oss = lcmd_run({subtype = \"osinfo\", action = \"get_oss\"})\
    if not ok or type(oss) ~= \"table\" then\
        oss = {}\
    end\
    local lan_hosts, hm = {}, {}\
    for i, v in ipairs(qrcstats.lhinfo) do\
        hm[v.MAC] = i\
    end\
    for _,v in ipairs(hinfo) do\
        local tt = {\
            mac = v.MAC,\
            osid = oss[v.MAC] and (oss[v.MAC].decide_osid or oss[v.MAC].cloud_osid or 0) or 0,\
            dev_type = oss[v.MAC] and oss[v.MAC].desc and oss[v.MAC].desc.dev_type or \"OTHER\",\
            ip = v.IP,\
            dev_power_level = v.PowerLevel,\
            acc_type = v.ConnectionType,\
            acc_port = v.Port,\
            nego_rate = v.NegoRate,\
            max_tx_bandwidth = v.MaxUSBandwidth,\
            max_rx_bandwidth = v.MaxDSBandwidth,\
            ssid_name = nil,\
        }\
        tt.rxrate, tt.txrate = calc_term_rate(v, qrcstats.collect_period, hm[v.MAC] and qrcstats.lhinfo[hm[v.MAC]] or nil)\
        if v.ConnectionType == 1 then\
            tt.ssid_name = type(wconf[tostring(v.Port)]) == \"table\" and wconf[tostring(v.Port)].SSID or \"\"\
        end\
        lan_hosts[v.MAC] = tt\
    end\
    qrcstats.lhinfo = hinfo\
\
    local port_rate = calc_port_rate(ninfo, qrcstats.collect_period, qrcstats.lninfo)\
    qrcstats.lninfo = ninfo\
\
    local sinfo = qrcstats.wifi_self\
    local chan_stat = qrcstats.scan_channel\
    local uptime = ctime.get_uptime()\
    sinfo.dual_band = winfo.DualBand and 1 or 0\
    sinfo.enable5G = winfo.Enable5G and 1 or 0\
    sinfo.rate_priority5G = winfo.RatePriority5G and 1 or 0\
    sinfo.channel_score = winfo.ChannelScanScore\
    sinfo.channel_score5G = winfo.ChannelScanScore5G\
    if chan_stat.status and winfo.ChannelScanStatus == 1 and winfo.ChannelScanStatus5G == 1 then\
        set_scan_status(\"2.4G\")\
        set_scan_status(\"5G\")\
        chan_stat.status = false\
    end\
    if not chan_stat.lasttime or uptime - chan_stat.lasttime >= qrcstats.scan_channel_interval then\
        log.info(\"start scanning wifi channel\")\
        scan_wifi_channel(\"2.4G\")\
        scan_wifi_channel(\"5G\")\
\
        chan_stat.lasttime = uptime\
        chan_stat.status = true\
    end\
    sinfo.wifis = {}\
    for _, v in pairs(wconf) do\
        local wifi = {\
            ssid = v.SSID,\
            channel = v.Channel,\
            channel_in_use = v.ChannelInUse,\
            power_level = v.Powerlevel,\
            power_value = v.PowerValue,\
            rfband = ((v.RFBand == 0) and \"2.4G\") or ((v.RFBand == 1) and \"5G\"),\
        }\
        table.insert(sinfo.wifis, wifi)\
    end\
\
    qrcstats.gw_info = gw_info\
    qrcstats.lan_hosts = lan_hosts\
    qrcstats.port_rate = port_rate\
\
    actor.publish({msgtype = \"DEV_PORT_RATE\", port_rate = port_rate})\
    actor.publish({msgtype = \"LAN_HOST\", lan_host = lan_hosts})\
\
    if not focus_host(lan_hosts, oss) then\
        check_wifi_neighbor()\
    end\
end\
\
local function get_wifi_neighbor()\
    return {\
        wself = qrcstats.wifi_neighbor.wself,\
        neighbor = qrcstats.wifi_neighbor.neighbor,\
        scan_time = qrcstats.wifi_neighbor.scan_time,\
        self_scan = qrcstats.wifi_neighbor.self_scan and 1 or 0,\
    }\
end\
\
local function write(msg)\
    if type(msg.collect_period) == \"number\" and msg.collect_period ~= qrcstats.collect_period then\
        qrcstats.collect_period = msg.collect_period\
        timer.mod(qrcstats.timer_name, qrcstats.collect_period, 0, update_info)\
    end\
    if type(msg.scan_channel_interval) == \"number\" and msg.scan_channel_interval ~= qrcstats.scan_channel_interval then\
        qrcstats.scan_channel_interval = msg.scan_channel_interval\
    end\
    if type(msg.scan_neighbor_interval) == \"number\" and msg.scan_neighbor_interval ~= qrcstats.scan_neighbor_interval then\
        qrcstats.scan_neighbor_interval = msg.scan_neighbor_interval\
    end\
    if type(msg.scan_neighbor_time) == \"string\" and msg.scan_neighbor_time ~= qrcstats.scan_neighbor_time then\
        qrcstats.scan_neighbor_time = msg.scan_neighbor_time\
        qrcstats.wifi_neighbor.daytime = nil\
    end\
    if type(msg.get_neighbor_res) == \"number\" and msg.get_neighbor_res ~= qrcstats.get_neighbor_res then\
        qrcstats.get_neighbor_res = msg.get_neighbor_res\
    end\
    if type(msg.sensing_host) == \"table\" then\
        qrcstats.sensing_host = {}\
        for _, dev_type in ipairs(msg.sensing_host) do\
            if type(dev_type) == \"string\" and dev_type ~= \"\" then\
                qrcstats.sensing_host[dev_type] = true\
            end\
        end\
    end\
    if type(msg.rate_limit) == \"number\" and msg.rate_limit ~= qrcstats.rate_limit then\
        qrcstats.rate_limit = msg.rate_limit\
    end\
end\
\
local function read()\
    local sensing_host = {}\
    for k,_ in pairs(qrcstats.sensing_host) do\
        table.insert(sensing_host, k)\
    end\
    return {\
        collect_period = qrcstats.collect_period,\
        scan_channel_interval = qrcstats.scan_channel_interval,\
        scan_neighbor_interval = qrcstats.scan_neighbor_interval,\
        scan_neighbor_time = qrcstats.scan_neighbor_time,\
        get_neighbor_res = qrcstats.get_neighbor_res,\
        sensing_host = sensing_host,\
        rate_limit = qrcstats.rate_limit,\
    }\
end\
\
local function stat()\
    return {\
        wifi_neighbor = {\
            lasttime = qrcstats.wifi_neighbor.lasttime,\
            daytime = qrcstats.wifi_neighbor.daytime,\
        },\
        wifi_self = {\
            lasttime = qrcstats.scan_channel.lasttime\
        }\
    }\
end\
\
function qrcstats.postinit()\
    local ok, arch = lcmd_run({subtype = \"arch\", action = \"read\"})\
    if ok and type(arch) == \"table\" then\
        qrcstats.int_ver = arch.int_ver\
    end\
    get_neighbor_scan(false)\
end\
\
function qrcstats.finish()\
end\
\
actor.action_set(qrcstats.subtype, \"read\", read, \"read conf\")\
actor.action_set(qrcstats.subtype, \"stat\", stat, \"read status of scanning channel and neighbor wifi\")\
actor.action_set(qrcstats.subtype, \"write\", write, \"write qrcstats conf, {collect_period = number, scan_channel_interval = number, scan_neighbor_interval = number, scan_neighbor_time = [[03:00-04:00]], get_neighbor_res = number, sensing_host = list<dev_type>, rate_limit = number}\")\
actor.action_set(qrcstats.subtype, \"get_dev_info\", get_dev_info, \"get dev info\")\
actor.action_set(qrcstats.subtype, \"get_pon_info\", get_pon_info, \"get pon info\")\
actor.action_set(qrcstats.subtype, \"get_network_info\", get_network_info, \"get network info\")\
actor.action_set(qrcstats.subtype, \"get_diag_info\", get_diag_info, \"get diag info\")\
actor.action_set(qrcstats.subtype, \"get_lan_hosts\", get_lan_hosts, \"get onlie lan hosts\")\
actor.action_set(qrcstats.subtype, \"get_wifi_conf\", get_wifi_conf, \"get wifi conf\")\
actor.action_set(qrcstats.subtype, \"get_wifi_info\", get_wifi_info, \"get wifi info\")\
actor.action_set(qrcstats.subtype, \"get_dns_conf\", get_dns_conf, \"get wifi info\")\
actor.action_set(qrcstats.subtype, \"scan_wifi_channel\", function (t) return scan_wifi_channel(t.band) end, \"scan wifi channel,{band = [[2.4G]] / [[5G]]}\")\
actor.action_set(qrcstats.subtype, \"set_scan_status\", function (t) return set_scan_status(t.band) end, \"set status of scanning channel to 0,{band = [[2.4G]] / [[5G]]}\")\
actor.action_set(qrcstats.subtype, \"collect_wifi_neighbor\", collect_wifi_neighbor, \"collect wifi neighbor\")\
actor.action_set(qrcstats.subtype, \"get_gw_info\", function () return qrcstats.gw_info end, \"get gw info\")\
actor.action_set(qrcstats.subtype, \"get_online_term\", function () return qrcstats.lan_hosts end, \"get online term\")\
actor.action_set(qrcstats.subtype, \"get_port_rate\", function () return qrcstats.port_rate end, \"get port rate\")\
actor.action_set(qrcstats.subtype, \"get_wifi_self\", function () return qrcstats.wifi_self end, \"get self wifi\")\
actor.action_set(qrcstats.subtype, \"get_wifi_neighbor\", get_wifi_neighbor, \"get neighbor wifi\")\
actor.action_set(qrcstats.subtype, \"gdbus_parse\", function (t) if t.cmd_res or t.file then return qrcstats.gdbus_parse(t.cmd_res, t.file) end end, \"parse gdbus cmd_res, {cmd_res = string, file = string}\")\
actor.action_set(qrcstats.subtype, \"check_wifi_neighbor\", function () log.info(\"trigger scanning wifi neighbor\") collect_wifi_neighbor() timer.mod(qrcstats.timer_get_neighbor, 60, 1, get_neighbor_scan, true) end, \"trigger a check wifi neighbor\")\
\
\
return qrcstats\
"
, '@'.."./service/qrcstats.lua" ) )

package.preload[ "qsvr" ] = assert( (loadstring or load)(
"local log = require\"log\"\
local actor = require\"luactor\"\
local dpi = require\"svrcomm.dpi\"\
local cjson = require\"cjson\"\
local timer = require\"timer\"\
local mystring = require\"mystring\"\
\
local ctime = require\"c.time\"\
\
local oper_init                 -- this function must be declared firstly\
local oper_heart\
local qsvr_send\
\
local qsvr = {\
    type = \"qsvr\",\
    subtype = \"qsvr\",\
    help = \"oper server, send heart/init/result/data to server\",\
    timer_name = \"qsvr_heart\",\
    inittimer_name = \"qsvr_init\",\
    datatimer_name = \"qsvr_data\",\
\
    -- conf\
    init_period = 1,\
    init_lasttime = 0,\
    init_doing = false,\
\
    period = 1800,\
    maxmsglen = 80000,         -- 80K\
    heart_period = 0,\
    addr = nil,\
    seed = \"\",\
\
    -- var\
    initok = false,\
    msg_array = {},\
    msg_len  = 0,   -- msg_len is the all data length in msg_array\
\
    -- stat\
    stat = {\
        upload_raw_len = 0,\
        upload_succ_len = 0,\
        upload_succ_count = 0,\
        upload_fail_len = 0,\
        upload_fail_count = 0,\
    },\
}\
\
local function msg_reply(t, msg, addr)\
    local reply = {}\
    for _, v in pairs(t) do\
        if type(v) == \"table\" then\
            local result = actor.deal_reply(v)\
            if type(result) == \"string\" or type(result) == \"table\" then\
                table.insert(reply, {result = result, seed = v.seed, status = 0})\
            end\
        end\
    end\
    if #reply > 0 then\
        log.info(string.format(\"deal reply %s qsvr msg, reply(%s)\", addr, cjson.encode(reply)))\
    end\
end\
\
local function oper_deal_reply(addr, action, msg, initphrase)\
    if initphrase then\
        qsvr.initok = true\
        timer.mod(qsvr.datatimer_name, qsvr.period, 0, qsvr_send)\
        lcmd_run({subtype = \"qcalc\", action = \"write\", enable = true})\
        lcmd_run({subtype = \"qcollect\", action = \"write\", enable = true})\
        lcmd_run({subtype = \"arping\", action = \"write\", period = 300})\
        lcmd_run({subtype = \"qrcstats\", action = \"write\", collect_period = 300})\
        log.info(string.format(\"qsvr init OK for addr %s, action is 0x%x\", addr, action))\
    end\
\
    if not msg or msg == \"\" then\
        log.info(string.format(\"ignore empty qsvr msg, action 0x%x\", action))\
        return\
    end\
    log.info(string.format(\"receive %s qsvr, action 0x%x, msg(%s)\", addr, action, msg))\
\
    local ok, t = pcall(cjson.decode, msg)\
    if not ok then\
        log.error(string.format(\"failed json decode msg(%s), err(%s)\", msg, t))\
        return\
    end\
    if type(t) ~= \"table\" or #t == 0 then\
        log.info(string.format(\"ignore empty json or not table for msg(%s)\", msg))\
        return\
    end\
    msg_reply(t, msg, addr)\
end\
\
local function oper_raw(t)\
    if type(t.action_type) ~= \"number\" or type(t.data) ~= \"table\" then\
        log.error(\"wrong format for qsvr oper raw, look into help\")\
        return\
    end\
\
    if not qsvr.initok and not t.addr then\
        log.warn(\"Wait qsvr init ok first, just ignore this raw\")\
        return\
    end\
\
    local addrs = t.addr or qsvr.addr\
    for _, addr in ipairs(addrs or {}) do\
        dpi.async_call(addr, t.action_type, cjson.encode(t.data), t.finicall, t.recvcall, table.unpack(t.recvargs or {}))\
    end\
end\
\
local function init_fini_call(err, msg)\
    if err then\
        log.warn(\"qsvr oper init failed, err \", err)\
    end\
    qsvr.init_doing = false\
    qsvr.init_lasttime = ctime.get_uptime()\
end\
\
local function show_oper_init()\
    local ok, model_seed = lcmd_run({subtype = \"qcalc\", action = \"read_seed\"})\
    if not ok or type(model_seed) ~= \"string\" then\
        return\
    end\
    return {{type = \"qcalc\", model_seed = model_seed, uptime = ctime.get_uptime()}} -- it must be an array.\
end\
\
function oper_init()\
    if qsvr.initok then\
        return\
    end\
    if #qsvr.addr == 0 then\
        log.warn(\"No oper server addr, just ignore this init\")\
        return\
    end\
\
    local uptime = ctime.get_uptime()\
    if qsvr.init_doing then\
        if uptime > qsvr.init_lasttime + 14400 then\
            log.warn(\"Wrong qsvr init msg coroutine, must init again\")\
        else\
            return\
        end\
    else\
        if uptime < qsvr.init_lasttime + qsvr.init_period then\
            log.trace(\"another qsvr init will be triggered after \", qsvr.init_lasttime + qsvr.init_period - uptime, \" secs\")\
            return\
        end\
    end\
\
    local t = show_oper_init()\
    if type(t) ~= \"table\" then\
        return \"Wait for qsvr init.....\"\
    end\
\
    qsvr.init_period = qsvr.init_period * 3 > 14400 and 14400 or qsvr.init_period * 3\
    qsvr.init_doing = true\
\
    local msg = cjson.encode(t)\
    log.info(\"will trigger qsvr init with period, \", qsvr.init_period, \" msg, \", msg)\
    for _, addr in ipairs(qsvr.addr) do\
        dpi.async_call(addr, CENUM.COMM_ACTION_DEVOPS_DPI_QUALITY_INIT, msg, init_fini_call, oper_deal_reply, true)\
    end\
end\
\
local function show_oper_heart()\
    local ok, model_seed = lcmd_run({subtype = \"qcalc\", action = \"read_seed\"})\
    if not ok or type(model_seed) ~= \"string\" then\
        return\
    end\
    return {{type = \"qcalc\", model_seed = model_seed}}  -- it must be an array.\
end\
\
local function trigger_heart_timer()\
    local period = math.floor(qsvr.heart_period)\
    local half = math.floor(period / 2)\
    local range_min = period - half\
    local range_max = period + half\
    local random_period =  math.random(range_min, range_max)\
    local uptime = ctime.get_uptime()\
    qsvr.heart_nexttime = uptime + random_period\
    -- here it does not use once timer, in case that timer will not be added because of exception.\
    timer.mod_notdisable(qsvr.timer_name, random_period, 0, oper_heart)\
end\
\
function oper_heart()\
    if #qsvr.addr == 0 then\
        log.warn(\"No oper server addr, just ignore this heart\")\
        return\
    end\
    trigger_heart_timer()\
\
    if not qsvr.initok then\
        log.warn(\"Wait init ok first, just ignore this heart\")\
        return\
    end\
    local t = show_oper_heart()\
    if type(t) ~= \"table\" then\
        return \"failed to prepair heart msg.....\"\
    end\
\
    local msg = cjson.encode(t)\
    log.info(\"will heart oper qsvr with msg \"..msg)\
    qsvr.heart_lasttime = ctime.get_uptime()\
    for _, addr in ipairs(qsvr.addr) do\
        dpi.async_call(addr, CENUM.COMM_ACTION_DEVOPS_DPI_QUALITY_HEART, msg, nil, oper_deal_reply)\
    end\
end\
\
-- the following is the data reporting section\
local function finicall(err, data)\
    if not err then\
        qsvr.stat.upload_succ_count = qsvr.stat.upload_succ_count + 1\
        qsvr.stat.upload_succ_len = qsvr.stat.upload_succ_len + #data\
    else\
        qsvr.stat.upload_fail_count = qsvr.stat.upload_fail_count + 1\
        qsvr.stat.upload_fail_len = qsvr.stat.upload_fail_len + #data\
        log.warn(\"qsvr fini: \"..err)\
    end\
end\
\
function qsvr_send()\
    if #qsvr.msg_array == 0 then\
        return\
    end\
    local msgstring = cjson.encode(qsvr.msg_array)\
    for _, addr in pairs(qsvr.addr) do\
        log.info(string.format(\"qsvr %s send msgcnt(%d)\", addr, #qsvr.msg_array))\
        dpi.async_call(addr, CENUM.COMM_ACTION_DEVOPS_DPI_QUALITY_DATA, msgstring, finicall)\
        qsvr.stat.upload_raw_len = qsvr.stat.upload_raw_len + #msgstring\
    end\
    qsvr.msg_len = 0\
    qsvr.msg_array = {}\
end\
\
local function add(msg)\
    if qsvr.period <= 0 then\
        return\
    end\
    if not qsvr.initok then\
        log.warn(\"Wait qsvr init ok first, just ignore this add\")\
        return\
    end\
\
    if type(msg.data) ~= \"table\" then\
        log.error(\"must add table for qsvr data\")\
        return\
    end\
\
    lcmd_run({subtype = \"locdata\", action = \"add\", data = msg.data})\
\
    local mm = cjson.encode(msg.data)\
    qsvr.msg_len = qsvr.msg_len + #mm\
    table.insert(qsvr.msg_array, msg.data)\
\
    if qsvr.msg_len >= qsvr.maxmsglen then\
        qsvr_send()\
        timer.mod(qsvr.datatimer_name, qsvr.period, 0, qsvr_send)\
    end\
end\
\
local function read()\
    return {\
        seed = qsvr.seed,\
        period = qsvr.period,\
        maxmsglen = qsvr.maxmsglen,\
        heart_period = qsvr.heart_period,\
        addr = qsvr.addr,\
        initok = qsvr.initok,\
        init_period = qsvr.init_period,\
        heart_lasttime = qsvr.heart_lasttime,\
        heart_nexttime = qsvr.heart_nexttime,\
        inittimer_name = qsvr.inittimer_name,\
        datatimer_name = qsvr.datatimer_name,\
        msgcnt = #qsvr.msg_array,\
        msglen = qsvr.msg_len,\
    }\
end\
\
local function write(t)\
    if type(t.addr) == \"table\" then\
        if not mystring.same_table(t.addr, qsvr.addr) then\
            qsvr.addr = t.addr\
            qsvr.initok = false\
            qsvr.init_period = 1\
            qsvr.msg_array = {}\
            qsvr.msg_len = 0\
            timer.del(qsvr.inittimer_name)\
            timer.del(qsvr.datatimer_name)\
            lcmd_run({subtype = \"qcalc\", action = \"write\", enable = false})\
            lcmd_run({subtype = \"qcollect\", action = \"write\", enable = false})\
            lcmd_run({subtype = \"arping\", action = \"write\", period = 0})\
            lcmd_run({subtype = \"qrcstats\", action = \"write\", collect_period = 0})\
            if #qsvr.addr > 0 then\
                timer.mod_notdisable(qsvr.inittimer_name, 5, 0, oper_init)\
            end\
        end\
    end\
\
    if type(t.heart_period) == \"number\" and t.heart_period ~= qsvr.heart_period then\
        qsvr.heart_period = t.heart_period\
        trigger_heart_timer()\
    end\
\
    if type(t.period) == \"number\" and t.period ~= qsvr.period then\
        qsvr.period = t.period\
        timer.mod(qsvr.datatimer_name, qsvr.period, 0, qsvr_send)\
    end\
\
    if type(t.maxmsglen) == \"number\" and t.maxmsglen ~= qsvr.maxmsglen then\
        qsvr.maxmsglen = t.maxmsglen\
    end\
\
    if type(t.seed) == \"string\" and t.seed ~= qsvr.seed then\
        qsvr.seed = t.seed\
    end\
end\
\
function qsvr.postinit()\
    qsvr.init_lasttime = ctime.get_uptime()\
end\
\
actor.action_set(qsvr.subtype, \"show_conf_svr\", function() return {type = qsvr.type, seed = qsvr.seed} end, \"show qsvr conf msg to oper svr\")\
actor.action_set(qsvr.subtype, \"show_oper_init\", show_oper_init, \"show init msg to oper server\")\
actor.action_set(qsvr.subtype, \"show_oper_heart\", show_oper_heart, \"show heart msg to oper server\")\
\
actor.action_set(qsvr.subtype, \"read\", read, 'read qsvr conf')\
actor.action_set(qsvr.subtype, \"stat\", function () return qsvr.stat end, \"read qsvr stat\")\
actor.action_set(qsvr.subtype, \"write\", write, 'write qsvr conf, {\"heart_period\":NN, \"addr\":[ADDR1, ADDR2, ...], \"period\":NN, \"seed\":\"SEED\", \"maxmsglen\":NN}')\
actor.action_set(qsvr.subtype, \"oper_init\", oper_init, \"send init msg to oper server\")\
actor.action_set(qsvr.subtype, \"oper_heart\", oper_heart, \"send heart msg to oper server\")\
actor.action_set(qsvr.subtype, \"oper_raw\", oper_raw, [[send raw msg to oper server, {action_type = xx, data = table, addr = [\"\"], recvcall = recv_func, finicall = finish_call, recvargs = recv_args(table)}]])\
actor.action_set(qsvr.subtype, \"add\", add, \"add json data for qsvr send, {data = table}\")\
\
return qsvr\
"
, '@'.."./service/qsvr.lua" ) )

package.preload[ "quic" ] = assert( (loadstring or load)(
"local cjson = require(\"cjson\")\
local actor = require(\"luactor\")\
local log = require(\"log\")\
local myutil = require(\"myutil\")\
local mystring = require(\"mystring\")\
local ccrypto = require(\"c.crypto\")\
