local quic = {\
    type = \"quic\",\
    subtype = \"quic\",\
    help = \"get quic from PCAP and send to server\",\
\
    upload_type = \"https_domain\",\
    upload_mode = \"none\", -- \"none\", \"svrdata\", \"operdata\", \"all\"\
\
    period = 5,\
    sindex = nil,\
\
    pub_count = 0,\
    all_count = 0,\
    all_len = 0,\
\
    filter = \"udp port 443\",\
}\
\
\
local function get_quic_varint(data, offset)\
    -- variable-length integer (https://www.rfc-editor.org/rfc/rfc9000.html#name-variable-length-integer-enc)\
    local first_byte = string.byte(data, offset)\
    local two_msb = first_byte >> 6\
    local length, value = nil, nil\
    if two_msb == 0 then\
        length = 1\
        value = first_byte & 0x3F\
    elseif two_msb == 1 then\
        length = 2\
        value = string.unpack(\">H\", string.sub(data, offset, offset + 1))\
        value = value & 0x3FFF\
    elseif two_msb == 2 then\
        length = 4\
        value = string.unpack(\">I\", string.sub(data, offset, offset + 3))\
        value = value & 0x3FFFFFFF\
    elseif two_msb == 3 then\
        length = 8\
        -- in case that \">I8\" may overflow, so get real str first and then unpack\
        local real_str = string.char(first_byte & 0x3F)..string.sub(data, offset + 1, offset + 7)\
        value = string.unpack(\">I8\", real_str)\
    else\
        -- impossible\
    end\
    return length, value\
end\
\
local function generate_hkdf_label(length, label, context)\
    -- HKDF-Expand-Label and HkdfLabel (https://datatracker.ietf.org/doc/html/rfc8446#section-7.1)\
    local len_bytes = string.pack(\">H\", length)\
    local real_label = \"tls13 \"..label\
    local label_bytes = string.pack(\"B\", #real_label)..real_label\
    local context_bytes = string.pack(\"B\", #context)..context\
    return len_bytes..label_bytes..context_bytes\
end\
\
local function adjust_packet_number(max_pkt_num, pkt_num, n)\
    local k = max_pkt_num + 1 -- max_pkt_num == G_MAXUINT64 ? max_pkt_num : max_pkt_num + 1\
    local u = k & ~((1 << n) - 1)\
    local a = u | pkt_num\
    local b = (u + (1 << n)) | pkt_num\
    local a1 = k < a and a - k or k - a\
    local b1 = k < b and b - k or k - b\
    return (a1 < b1 and a or b)\
end\
\
local function extractSniWithQUICCrypto(chlo_data)\
    if string.sub(chlo_data, 1, 4) ~= \"CHLO\" then\
        -- Unexpected handshake message\
        return\
    end\
\
    local pos = 5\
    local tagnum = string.unpack(\"<H\", string.sub(chlo_data, pos, pos + 1))\
    -- skip Tag Number\
    pos = pos + 2\
    -- skip Padding\
    pos = pos + 2\
\
    local tagsInOrder = {}\
    local tagsOffsetEnd = {}\
    for i = 1,tagnum,1 do\
        local tag_type = string.sub(chlo_data, pos, pos + 3)\
        pos = pos + 4\
        if string.byte(tag_type, 4, 4) == 0x00 then\
            tag_type = string.sub(tag_type, 1, 3)\
        end\
        local tag_offset_end = string.unpack(\"<I\", string.sub(chlo_data, pos, pos + 3))\
        pos = pos + 4\
        table.insert(tagsInOrder, tag_type)\
        tagsOffsetEnd[tag_type] = tag_offset_end\
    end\
\
    local vdata = string.sub(chlo_data, pos)\
    for i, tag_type in ipairs(tagsInOrder) do\
        if tag_type == \"SNI\" then\
            local pos_start = 1\
            if i > 1 then\
                pos_start = tagsOffsetEnd[tagsInOrder[i-1]] + 1\
            end\
            local sni = string.sub(vdata, pos_start, tagsOffsetEnd[tag_type])\
            return sni\
        end\
    end\
    return\
end\
\
local function extractSniWithTLS(data)\
    -- the format of the ClientHello is described in https://datatracker.ietf.org/doc/html/rfc8446\
    --[[******************************* TLS Handshake Format ********************************\
    * handshake-type(1byte) + length(3bytes)\
    * client-hello, version(2bytes) + random(32bytes) + sessionid(1byte len + sessionid) + cipher(2bytes len + cipher) + compress(1byte len + compress)\
    * extension len(2bytes)\
    * extension, type(2bytes) + length(2bytes)\
    * servname ext, length(2bytes) + type(1byte) + len(2bytes) + real server name\
    ************************************************************************************--]]\
    local hand_type = string.byte(data, 1)\
    if hand_type ~= 0x01 then\
        -- not Client Hello\
        return\
    end\
\
    local data_len = #data\
    local pos = 1\
    local session_len, next_pos, cipher_len, compress_len, ext_all_len, ext_type, ext_len = 0, 0, 0, 0, 0, 0, 0\
\
    -- get skip session ID len\
    -- len(handshake-type + length + client-hello + version + random) == 38\
    session_len, next_pos = string.unpack(\">B\", data, pos + 38)\
    if data_len < next_pos + session_len + 2 - 1 then\
        return nil\
    end\
\
    -- get skip cipher len and skip session ID\
    cipher_len, next_pos = string.unpack(\">H\", data, next_pos + session_len)\
    if data_len < next_pos + cipher_len + 1 - 1 then\
        return nil\
    end\
\
    -- get skip compress len and skip cipher\
    compress_len, next_pos = string.unpack(\">B\", data, next_pos + cipher_len)\
    if data_len < next_pos + compress_len + 2 - 1 then\
        return nil\
    end\
\
    -- get ext_all len and skip compress\
    ext_all_len, next_pos = string.unpack(\">H\", data, next_pos + compress_len)\
\
    -- find svrname\
    local len = 0\
    local svrname\
    while len < ext_all_len do\
        if next_pos + ext_len + 3 > #data then\
            return nil\
        end\
        ext_type, ext_len, next_pos = string.unpack(\">HH\", data, next_pos + ext_len)\
        if ext_type == 0 then\
            if next_pos + 4 > #data then\
                return nil\
            end\
            local svrname_list_length, svrname_type, svrname_length, next_pos = string.unpack(\">HBH\", data, next_pos)\
            if len + 4 + 5 + svrname_length > ext_all_len then\
                return nil\
            end\
            if next_pos + svrname_length - 1 > #data then\
                return nil\
            end\
            svrname = string.unpack(\">c\"..svrname_length, data, next_pos)\
            return svrname\
        end\
        len = len + 4 + ext_len\
    end\
    return\
end\
\
local function get_full_crypto_data(payload)\
    -- The payload of an Initial packet includes a CRYPTO frame (or frames) containing a cryptographic handshake message, ACK frames, or both.\
    -- PING, PADDING, and CONNECTION_CLOSE frames of type 0x1c are also permitted.\
    -- See <https://datatracker.ietf.org/doc/html/rfc9000#section-17.2.2>\
    local datarr = {}\
    local payload_len = #payload\
    local pos = 1\
    while pos <= payload_len do\
        local len_frame_type, frame_type = get_quic_varint(payload, pos)\
        pos = pos + len_frame_type\
        if frame_type == 0x00 or frame_type == 0x01 then\
            -- PADDING or PING\
        elseif frame_type == 0x02 or frame_type == 0x03 then\
            -- ACK\
            local len_largest_acked, largest_acked = get_quic_varint(payload, pos)\
            pos = pos + len_largest_acked\
            local len_ack_delay, ack_delay = get_quic_varint(payload, pos)\
            pos = pos + len_ack_delay\
            local len_ack_range_count, ack_range_count = get_quic_varint(payload, pos)\
            pos = pos + len_ack_range_count\
            local len_first_ack_range, first_ack_range = get_quic_varint(payload, pos)\
            pos = pos + len_first_ack_range\
            for i=1,ack_range_count,1 do\
                local len_gap, gap = get_quic_varint(payload, pos)\
                pos = pos + len_gap\
                local len_range_length, range_length = get_quic_varint(payload, pos)\
                pos = pos + len_range_length\
            end\
            if frame_type == 0x03 then\
                local len_ect0_count, ect0_count = get_quic_varint(payload, pos)\
                pos = pos + len_ect0_count\
                local len_ect1_count, ect1_count = get_quic_varint(payload, pos)\
                pos = pos + len_ect1_count\
                local len_ecn_ce_count, ecn_ce_count = get_quic_varint(payload, pos)\
                pos = pos + len_ecn_ce_count\
            end\
        elseif frame_type == 0x06 then\
            -- CRYPTO\
            local len_offset, offset = get_quic_varint(payload, pos)\
            pos = pos + len_offset\
            local len_length, length = get_quic_varint(payload, pos)\
            pos = pos + len_length\
            local one_piece = string.sub(payload, pos, pos + length - 1)\
            pos = pos + length\
            table.insert(datarr, { offset = offset, data = one_piece })\
        elseif frame_type == 0x1c then\
            -- CONNECTION_CLOSE\
            local len_errcode, errcode = get_quic_varint(payload, pos)\
            pos = pos + len_errcode\
            local len_err_frame_type, err_frame_type = get_quic_varint(payload, pos)\
            pos = pos + len_err_frame_type\
            local len_reason_phrase_length, reason_phrase_length = get_quic_varint(payload, pos)\
            pos = pos + len_reason_phrase_length\
            -- skip reason_phrase\
            pos = pos + reason_phrase_length\
        else\
            -- spurious\
            return\
        end\
    end\
    if #datarr <= 0 then\
        -- no CRYPTO\
        return\
    end\
    table.sort(datarr, function(a, b)\
        return a.offset < b.offset\
    end)\
    local crypto_data = \"\"\
    for _, v in ipairs(datarr) do\
        crypto_data = crypto_data..v.data\
    end\
    return crypto_data\
end\
\
local function extractCryptoStreamData(payload, version)\
    local crypto_data\
\
    if version == \"Q043\" or version == \"Q046\" then\
        -- iterate over the payload and skip all non-CRYPTO-stream frames\
        local counter = 1\
\
        -- skip over any zero-bytes at the start of the payload as they indicate padding\
        while string.byte(payload, counter, counter) == 0x00 do\
            counter = counter + 1\
        end\
\
        local first_nonzero_payload_byte = string.byte(payload, counter, counter)\
        local fnz_payload_byte_bit3 = ((first_nonzero_payload_byte & 0x20) ~= 0)\
\
        if (first_nonzero_payload_byte & 0x9f) ~= 0x80 then\
            -- Unexpected frame\
            -- we just care the first Client Hello\
            return\
        end\
        if string.byte(payload, counter + 1, counter + 1) ~= 0x01 then\
