            return\
        end\
        counter = counter + 2\
        if fnz_payload_byte_bit3 then\
            -- indicates that a Data Length(16 bit) is present in the STREAM header\
            local stream_data_length = string.unpack(\">H\", string.sub(payload, counter, counter + 1))\
            crypto_data = string.sub(payload, counter + 2, counter + 2 + stream_data_length - 1)\
        else\
            -- indicates that the STREAM frame extends to the end of the Packet\
            crypto_data = string.sub(payload, counter + 2)\
