    -- also refer https://datatracker.ietf.org/doc/html/draft-ietf-quic-transport-22#section-17.2.2, https://datatracker.ietf.org/doc/html/rfc9001#appendix-A.2\
    -- type(1 byte) + version(4) + DCIL(1) + DCID + SCIL(1) + SCID + TOKEN_L(<=8) + TOKEN + LENGTH(<=8) + Packet_Numer(<=4) + Protected_PAYLOAD + Authentication_Tag(16 bytes)\
    -- Protected_PAYLOAD:  [Protected Payload (1/2/3)] + Sampled part of Protected Payload (16) + Protected Payload Remainder (*)\
    -- LENGTH = len(Packet_Numer) + len(Protected_PAYLOAD) + len(Authentication_Tag)\
    local scid_len_offset = 1 + 4 + 1 + #dcid + 1\
    local scid_len = string.byte(data, scid_len_offset)\
    local token_len_offset = scid_len_offset + scid_len + 1\
    local len_token_len, token_len = get_quic_varint(data, token_len_offset)\
    local token_offset = token_len_offset + len_token_len\
    local token = string.sub(data, token_offset, token_offset + token_len - 1)\
    local payload_len_offset = token_offset + token_len\
    local len_length, length = get_quic_varint(data, payload_len_offset)\
    local packet_number_offset = payload_len_offset + len_length\
    local smaple_offset = packet_number_offset + 4\
    local sample = string.sub(data, smaple_offset, smaple_offset + 16 - 1)\
\
    -- get the unmasked first byte and packet number\
    local initial_secret = ccrypto.hkdf_extract(\"SHA256\", initial_salt, dcid)\
    if not initial_secret then\
        return\
    end\
    local client_initial_secret = ccrypto.hkdf_expand(\"SHA256\", initial_secret, generate_hkdf_label(32, \"client in\", \"\"), 32)\
    if not client_initial_secret then\
        return\
    end\
    local hp_key = ccrypto.hkdf_expand(\"SHA256\", client_initial_secret, generate_hkdf_label(16, \"quic hp\", \"\"), 16)\
    if not hp_key then\
        return\
    end\
    local sample_cryp = ccrypto.encrypt(sample, hp_key, \"ecb\")\
    local mask = string.sub(sample_cryp, 1, 5)\
    local mask_uint8_arr = {}\
    for i=1,#mask,1 do\
        mask_uint8_arr[i] = string.byte(mask, i)\
    end\
    local packet0 = string.byte(data, 1)\
    if (packet0 & 0x80) == 0x80 then\
        -- Long header: 4 bits masked\
        packet0 = packet0 ~ (mask_uint8_arr[1] & 0x0f);  -- ~ is XOR\
    else\
