    for i=1,packet_number_len,1 do\
        local one_byte_int = string.byte(data, packet_number_offset + i - 1)\
        packet_number = packet_number | ((one_byte_int ~ mask_uint8_arr[1 + i]) << (8 * (packet_number_len - i)))\
    end\
    -- here the packet_number is not the full packet number(8 bytes), which need to calculate with the last stored packet number.\
    -- we just care the first Initial packet, so assume 0 as the last stored packet number\
    local full_packet_number = adjust_packet_number(0, packet_number, packet_number_len * 8)\
    --if full_packet_number ~= 0 and full_packet_number ~= 1 then\
    --    return\
    --end\
\
    -- get pp_key and nonce\
    local pp_key = ccrypto.hkdf_expand(\"SHA256\", client_initial_secret, generate_hkdf_label(16, \"quic key\", \"\"), 16)\
    local pp_iv = ccrypto.hkdf_expand(\"SHA256\", client_initial_secret, generate_hkdf_label(12, \"quic iv\", \"\"), 12)\
    if not pp_key or not pp_iv then\
        return\
    end\
    local nonce_uint8_arr = {}\
    for i=1,#pp_iv,1 do\
        nonce_uint8_arr[i] = string.byte(pp_iv, i)\
    end\
    for i=1,8,1 do\
        local j = #nonce_uint8_arr - i + 1\
        nonce_uint8_arr[j] = nonce_uint8_arr[j] ~ ((full_packet_number << 8 * (8 - i)) >> 56) -- here means (uint8_t )(full_packet_number >> 8 * (i-1))\
    end\
    local nonce = \"\"\
    for i=1,#nonce_uint8_arr,1 do\
        nonce = nonce..string.char(nonce_uint8_arr[i])\
    end\
    -- get real header, replace encrypted first byte and packet_number by plaintext\
    local header_length = packet_number_offset + packet_number_len - 1\
    local packet_number_bytes = string.sub(string.pack(\">I\", full_packet_number), 4 - packet_number_len + 1, 4)\
    local real_header = string.char(packet0)..string.sub(data, 2, header_length - packet_number_len)..packet_number_bytes\
