    local payload_len = #data - header_length - 16\
    local payload = string.sub(data, payload_offset, payload_offset + payload_len - 1)\
    local atag = string.sub(data, #data - 16 + 1)\
\
    -- decrypt the payload\
    local plaintext, atag_r = ccrypto.gcm_decrypt(payload, pp_key, nonce, real_header)\
    if atag ~= atag_r then\
        -- authentication failed\
