\
local function version_to_string(version)\
    if myutil.is_printable_string(version) then\
        return version\
    end\
    return string.format(\"0x%s\", mystring.data2hex(version))\
end\
\
local function get_sni(data)\
    local first_byte = string.byte(data, 1, 1)\
    local first_byte_bit1 = ((first_byte & 0x80) ~= 0)\
    local first_byte_bit2 = ((first_byte & 0x40) ~= 0)\
    local first_byte_bit3 = ((first_byte & 0x20) ~= 0)\
    local first_byte_bit4 = ((first_byte & 0x10) ~= 0)\
    local first_byte_bit5 = ((first_byte & 0x08) ~= 0)\
    local first_byte_bit6 = ((first_byte & 0x04) ~= 0)\
    local first_byte_bit7 = ((first_byte & 0x02) ~= 0)\
    local first_byte_bit8 = ((first_byte & 0x01) ~= 0)\
\
    -- Identifying the QUIC Version of a Packet\
    local version\
    if first_byte_bit1 then\
        -- [quic: long header], [gquic Q046: long header]\
        version = string.sub(data, 2, 5)\
    elseif first_byte_bit5 and not first_byte_bit2 then\
        -- [gquic Q043]\
        if not first_byte_bit8 then\
            -- packet without version\
            return\
        end\
        version = string.sub(data, 10, 13)\
    else\
        -- [quic: short header]\
        -- packet without version\
        return\
    end\
\
    -- Extracting the CID\
