        if version == \"Q043\" then\
            if first_byte_bit3 or first_byte_bit4 then\
                -- Unexpected packet number length\
                -- Two bits should be 00, which indicates that 1 byte of the packet number is present\
                return\
            end\
            payload = string.sub(data, 27)\
        else\
            if not first_byte_bit7 or not first_byte_bit8 then\
                -- Unexpected packet number length\
                -- Two bits should be 11, which indicates that 4 bytes of the packet number is present\
                return\
            end\
            payload = string.sub(data, 31)\
