        if first_byte_bit3 or first_byte_bit4 then\
            -- Not an initial packet\
            -- Non-initial packets are encrypted with keys not available to anyone except the client and server.\
            return\
        end\
        local initial_salt\
        if version == \"Q050\" then\
            initial_salt = string.char(0x50, 0x45, 0x74, 0xef, 0xd0, 0x66, 0xfe, 0x2f, 0x9d, 0x94, 0x5c, 0xfc, 0xdb, 0xd3, 0xa7, 0xf0, 0xd3, 0xb5, 0x6b, 0x45)\
        elseif version == \"T051\" then\
            initial_salt = string.char(0x7a, 0x4e, 0xde, 0xf4, 0xe7, 0xcc, 0xee, 0x5f, 0xa4, 0x50, 0x6c, 0x19, 0x12, 0x4f, 0xc8, 0xcc, 0xda, 0x6e, 0x03, 0x3d)\
        elseif version == string.char(0xff, 0x00, 0x00, 0x1d) then\
            -- about quic version (https://datatracker.ietf.org/doc/html/draft-ietf-quic-transport-29#section-15)\
            -- The version number for the final version of this specification(0x00000001), is reserved for the version of the protocol that is published as an RFC 9000.\
            -- Version numbers used to identify IETF drafts are created by adding the draft number to 0xff000000.  For example, draft-ietf-quic-transport-29 would be identified as 0xff00001D.\
            initial_salt = string.char(0xaf, 0xbf, 0xec, 0x28, 0x99, 0x93, 0xd2, 0x4c, 0x9e, 0x97, 0x86, 0xf1, 0x9c, 0x61, 0x11, 0xe0, 0x43, 0x90, 0xa8, 0x99)\
        elseif version == string.char(0x00, 0x00, 0x00, 0x01) then\
            initial_salt = string.char(0x38, 0x76, 0x2c, 0xf7, 0xf5, 0x59, 0x34, 0xb3, 0x4d, 0x17, 0x9a, 0xe6, 0xa4, 0xc8, 0x0c, 0xad, 0xcc, 0xbb, 0x7f, 0x0a)\
