\
local function quic_get(sbytes)\
    if quic.period <= 0 then\
        return\
    end\
\
    local dt = sbytes.pcap_tables\
    if type(dt) ~= \"table\" or dt.dport ~= 443 or dt.proto ~= 17 then\
        return\
    end\
    local l7_data = string.sub(dt.data, dt.offset)\
    if dt.l7_len <= 0 or #l7_data < dt.l7_len then\
        return\
    end\
    if #l7_data > dt.l7_len then\
        l7_data = string.sub(l7_data, 1, dt.l7_len)\
    end\
\
    local ok, sni, version = pcall(get_sni, l7_data)\
    if not ok then\
        log.error(\"quic get sni failed:\", sni) \
        return\
    end\
    if not sni then\
        return\
    end\
\
    local _, ruleid = lcmd_run({ action = \"match\", subtype = \"appsig_bin\", stype = \"domain\", value = sni })\
    local _, desc = lcmd_run({ action = \"get_desc\", subtype = \"appsig_bin\", ruleid = ruleid })\
    local appid = desc and desc.appid or 0\
    local quic_table = {\
        type = quic.upload_type,\
        timestamp = tostring(os.time()),\
        mac = dt.mac,\
        sip = dt.sip,\
        dip = dt.dip,\
        sport = dt.sport,\
        dport = dt.dport,\
        appid = appid,\
        ruleid = ruleid or 0,\
        domain = sni,\
    }\
\
    --log.info(\"recv one quic_table, \", version, \":\", cjson.encode(quic_table))\
    actor.publish({msgtype = \"QUIC\", quic_table = quic_table})\
    quic.pub_count = quic.pub_count + 1\
\
    if quic.upload_mode ~= \"none\" then\
        if quic.upload_mode == \"operdata\" or quic.upload_mode == \"all\" then\
            lcmd_run({subtype = \"__oper_data\", action = \"add\", data = quic_table})\
        end\
        if quic.upload_mode == \"svrdata\" or quic.upload_mode == \"all\" then\
            lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = quic_table})\
        end\
