    else\
        lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_unset\", keyname = quic.type })\
    end\
end\
\
local function write(t)\
    if type(t.period) == \"number\" and t.period >= 0 and t.period ~= quic.period then\
        local filter_enable\
        if quic.period == 0 then\
            filter_enable = true \
        elseif t.period == 0 then\
            filter_enable = false\
        end\
        if type(filter_enable) == \"boolean\" then\
            set_pcap_filter(filter_enable)\
        end\
        quic.period = t.period\
    end\
\
    if type(t.upload_type) == \"string\" and t.upload_type ~= \"\" and t.upload_type ~= quic.upload_type then\
        quic.upload_type = t.upload_type\
    end\
    if type(t.upload_mode) == \"string\" and t.upload_mode ~= \"\" and t.upload_mode ~= quic.upload_mode then\
        if t.upload_mode == \"none\" or t.upload_mode == \"svrdata\" or t.upload_mode == \"operdata\" or t.upload_mode == \"all\" then\
            quic.upload_mode = t.upload_mode\
        end\
    end\
end\
\
local function read()\
    return {\
        type = quic.type,\
        action = \"write\",\
        seed = quic.seed,\
        period = quic.period,\
        upload_type = quic.upload_type,\
        upload_mode = quic.upload_mode,\
    }\
end\
\
local function readcc()\
    if quic.seed then\
        return {\
            type = quic.type,\
            seed = quic.seed,\
        }\
    end\
\
    return {\
        type = quic.type,\
        period = quic.period,\
        upload_type = quic.upload_type,\
        upload_mode = quic.upload_mode,\
    }\
end\
\
