actor.action_set(quic.subtype, \"write\", write, \"set quic conf, {period = number}, 0 means disable\")\
actor.action_set(quic.subtype, \"read\", read, \"read quic conf\")\
actor.action_set(quic.subtype, \"readcc\", readcc, \"read quic config cut\")\
actor.action_set(quic.subtype, \"stat\", stat, \"read quic stat\")\
