    self.min = nil\
    self.sumOfSquares = 0\
    self.sumOfDiff = 0\
    self.lastValue = nil\
    self.firstValue = nil\
end\
\
-- 更新统计数据\
function stats:update(value)\
    if type(value) ~= \"number\" then return end\
    self.count = self.count + 1\
    self.sum = self.sum + value\
    self.max = self.max and math.max(self.max, value) or value\
    self.min = self.min and math.min(self.min, value) or value\
    self.sumOfSquares = self.sumOfSquares + value * value\
    self.sumOfDiff = self.lastValue and (self.sumOfDiff + math.abs(value - self.lastValue)) or self.sumOfDiff\
    self.lastValue = value\
    self.firstValue = self.firstValue or value\
end\
\
-- 合并统计数据\
function stats:merge(stat)\
    if type(stat) ~= \"table\" then return end\
    self.sum = self.sum + stat.sum\
    self.count = self.count + stat.count\
    self.max = (self.max and stat.max) and math.max(self.max, stat.max) or (self.max or stat.max)\
    self.min = (self.min and stat.min) and math.min(self.min, stat.min) or (self.min or stat.min)\
    self.sumOfSquares = stat.sumOfSquares + self.sumOfSquares\
    self.sumOfDiff = self.lastValue and (stat.firstValue and (self.sumOfDiff + stat.sumOfDiff + math.abs(stat.firstValue - self.lastValue)) or self.sumOfDiff) or stat.sumOfDiff\
    self.lastValue = stat.lastValue or self.lastValue\
    self.firstValue = self.firstValue or stat.firstValue\
end\
\
-- 获取平均值\
function stats:getMean()\
    if self.count == 0 then return 0 end\
    return self.sum / self.count\
end\
\
-- 获取最大值\
function stats:getMax()\
    return self.max\
end\
\
-- 获取最小值\
function stats:getMin()\
    return self.min\
end\
\
-- 获取统计数据个数\
function stats:getCount()\
    return self.count\
end\
\
-- 获取总和\
function stats:getSum()\
    return self.sum\
end\
\
-- 获取标准差\
function stats:getStdDev()\
    if self.count <= 1 then return 0 end\
    local variance = (self.sumOfSquares - (self.sum * self.sum) / self.count) / (self.count - 1)\
    return math.sqrt(variance)\
end\
\
-- 获取平均抖动\
function stats:getMeanJitter()\
    if self.count <= 1 then return 0 end\
    return self.sumOfDiff / (self.count - 1)\
end\
\
return stats\
"
, '@'.."./lualib/stats.lua" ) )

package.preload[ "svrcomm" ] = assert( (loadstring or load)(
"local cjson = require \"cjson\"\
local log = require \"log\"\
local msocket = require \"msocket\"\
local mystring = require \"mystring\"\
local myip = require \"myip\"\
local socket = require \"socket\"\
local cssl_enable, cssl = pcall(require, \"c.ssl\")\
\
local svrcomm = {\
    localaddr = \"\", \
    localaddr_ipv6 = \"\",\
}\
\
-- TLS/SSL client parameters\
local sslparams = {\
    mode = \"client\",\
    protocol = \"tlsv1_2\",\
    verify = \"none\",\
    options = \"all\",\
}\
\
\
local function ssl_wrap_conn(svr, issync, timeout)\
    local addr = svr.addr or \"\"\
\
    local conn, err\
    if cssl_enable then\
        conn, err = cssl.wrap(svr.sock:getfd())  -- do not support sslparams now\
        if conn then\
            svr.sock:setfd(-1)\
        end\
    else\
        local ssl_enable, ssl = pcall(require, \"ssl\")  -- luasec\
        if not ssl_enable then\
            return \"luasec ssl not enable\"\
        end\
        conn, err = ssl.wrap(svr.sock, sslparams)\
    end\
    if not conn then\
        log.error(addr..\" ssl wrap failed, error is \"..err)\
        return err\
    end\
    svr.sock = conn\
\
    if type(timeout) == \"number\" then\
        conn:settimeout(timeout)\
    else\
        conn:settimeout(2)\
    end\
    local ok, err = conn:dohandshake()\
    if not ok then\
        log.error(addr..\" dohandshake failed, error is \"..err)\
        return err\
    end\
\
    if not issync then\
        conn:settimeout(0)\
    end\
    return nil\
end\
\
-- data long conn, just use ssl\
--\
\
local function datalong_sock_run(svr, recvcall, ...)\
    local sock = svr.sock\
    sock:settimeout(0)\
    local addr, port = myip.split_ipport(svr.addr)\
    svr.status = \"connecting\"\
    local err = msocket.svr_connect(svr.co, sock, addr, port)\
    if err then \
        log.error(\"datalong \"..svr.addr..\" connect failed, error is \"..err)\
        return\
    end\
    svr.status = \"connected\"\
\
    if svr.sslflag then\
        svr.status = \"ssl_handshake_doing\"\
        local err = ssl_wrap_conn(svr)\
        if err then\
            return\
        end\
        svr.status = \"ssl_handshake_done\"\
        sock = svr.sock\
    end\
\
    while true do\
        svr.status = \"waiting\"\
        local exit, data = msocket.coroutine_yield()\
        if exit then\
            break\
        end\
\
        svr.status = \"sending\"\
        err = msocket.svr_send(svr.co, sock, data)\
        if err then\
            log.error(\"datalong \"..svr.addr..\" send data failed, error is \"..err)\
            break\
        end\
\
        svr.status = \"recving\"\
        _, err = msocket.svr_receive(svr.co, sock, svr.addr, recvcall, data, ...)\
        if err then\
            log.error(\"datalong \"..svr.addr..\" recv data failed, error is \"..err)\
            break\
        end\
    end\
