end\
\
local function coroutine_datalong_run(svr, recvcall, ...)\
    log.warn(\"will start datalong sock with addr \", svr.addr)\
    svr.sock = socket.tcp()\
    local ok, r = pcall(datalong_sock_run, svr, recvcall, ...)\
    if not ok then\
