end\
\
-- server running structures\
-- running var\
--   co\
--   addr\
--\
--   long sock running\
--   status, connecting/connected/listening/replying/closed\
\
local function long_sock_run(svr, init_data, recvcall, key)\
    local sock = svr.sock\
    sock:settimeout(0)\
    local addr, port = myip.split_ipport(svr.addr)\
    svr.status = \"connecting\"\
