end\
\
local function short_sock_run(co, svr, data, funcall, ...)\
    -- connect\
    local addrport = svr.addr\
    local sock = svr.sock\
    sock:settimeout(0)\
    local addr, port = nil, nil\
    if string.find(addrport, \".\", 1, true) then\
        -- ipv4, 49.75.1.23:80 or 49.75.1.23:80:443\
        addr, port = mystring.split(addrport, \":\")\
    else\
        -- ipv6, [240e:3a3:4c79:8920:21f7:1879:ac1:fd77]:80 or [240e:3a3:4c79:8920:21f7:1879:ac1:fd77]:80:443\
        addr, port = string.match(addrport, \"^%[(.+)%]:([^:]+)\")\
    end\
    local err = msocket.svr_connect(co, sock, addr, port)\
