    svr.addr = addr\
    svr.action = action\
    svr.sslflag = sslflag\
    log.trace(\"init all co with addr \" .. addr)\
end\
\
local function short_sock_run_sec(co, svr, data, recvcall, ...)\
    local keyreq_cnt = 0\
    local key = svr.calltb.ckey_getcall(svr.addr)\
    while true do\
        if not key then\
            if keyreq_cnt >= 1 then\
                return \"request ckey over limit\"\
            end\
            local raddr, ckey_action, buf = svr.calltb.ckey_packcall(svr.addr)\
            local svrckey = { addr=raddr, sslflag=true, sock=socket.tcp() }\
            pcall(short_sock_run, co, svrckey, buf, svr.calltb.ckey_recvcall, false, false, svr.addr, svr.proto)\
            svrckey.sock:close()\
            key = svr.calltb.ckey_getcall(svr.addr)\
            log.trace(\"get ckey from \", raddr, \"ckey = \", key)\
            keyreq_cnt = keyreq_cnt + 1\
        end\
\
        if key then\
            local buf, realkey = svr.calltb.data_packcall(svr.proto, svr.action, data, key)\
            local svrdata = { addr=svr.addr, sslflag=false, sock=socket.tcp() }\
            local ok, err = pcall(short_sock_run, co, svrdata, buf, svr.calltb.client_recvcall, realkey, svr.proto, recvcall, ...)\
            svrdata.sock:close()\
            if ok and err and err == \"RESULT_CKEY_ERROR\" then\
                log.error(svr.addr..\" ckey(\"..key..\") error\")\
