end\
\
local function coroutine_short_run_sec(svr, data, finicall, recvcall, ...)\
    log.info(\"svr sec coroutine start \"..svr.addr)\
    local co = coroutine.running()\
    local ok, err = pcall(short_sock_run_sec, co, svr, data, recvcall, ...)\
    if type(finicall) == \"function\" then\
        finicall(err, data)\
    end\
    log.info(\"svr sec coroutine finish \"..svr.addr, \", ok is \", ok, \", err is \", err)\
    msocket.coroutine_exit(co)\
end\
\
local function index_svr_call_sec(svr, data, finicall, recvcall, ...)\
    if type(svr.addr) ~= \"string\" then\
        if type(finicall) == \"function\" then\
            finicall(\"failed find IP for dns\", data)\
        end\
        return\
    end\
    local coname = string.format(\"svr_%s\", svr.addr)\
    if type(svr.action) == \"number\" then\
