        return err\
    end\
    if action ~= CENUM.COMM_ACTION_RESULT_OK then\
        if action == CENUM.COMM_ACTION_RESULT_CKEY_ERROR then\
            return \"RESULT_CKEY_ERROR\"\
        end\
        return \"RESULT_NOT_OK\"\
    end\
\
    if has_recvcall then\
        local resmsg = msg or \"\"\
