    bufsize_def = 80000,  -- bytes\
    max_svr_cnt = 8,\
    tlvpub_enable = false,\
\
    seed = \"\",\
    svrs = {\
    --[[\
        {\
            conf = {\
                addr = STRING,\
                period = NUMBER,\
                bufsize = NUMBER,\
                ftypes = { STRING },\
            },\
            stat = {\
                upload_raw_len = NUMBER,\
                upload_succ_len = NUMBER,\
                upload_succ_count = NUMBER,\
                upload_fail_len = NUMBER,\
                upload_fail_count = NUMBER,\
            },\
            tname = STRING,\
            marr = {},  -- msg array\
            mlen = NUMBER,\
            finicall = FUNCTION,\
        },\
    ]]--\
    },\
}\
\
local function get_autoid()\
    local id = svrdata.autoid or 1\
    svrdata.autoid = id + 1\
    return id\
end\
\
local function svrdata_send_json(v)\
    if #v.marr == 0 then\
        return\
    end\
