    log.info(\"send json to DMP\", v.conf.addr, msgstring)\
    dpi.async_dmp_send_json(v.conf.addr, CENUM.COMM_ACTION_UPLOAD_MULTI_JSON, msgstring, v.finicall)\
    v.stat.upload_raw_len = v.stat.upload_raw_len + #msgstring\
    v.marr = {}\
    v.mlen = 0\
end\
