local function svrdata_filter(v, msg)\
    if type(msg.type) ~= \"string\" then\
        return false\
    end\
    if v.conf.period <= 0 then\
        return false\
    end\
    if #v.conf.ftypes == 0 then\
        return true\
    end\
    for _, ftype in ipairs(v.conf.ftypes) do\
        if msg.type == ftype then\
            return true\
        end\
    end\
    return false\
end\
\
local function svr_parse(t)\
    if type(t.addr) ~= \"string\" or t.addr == \"\" then\
        log.error(\"svrdata invalid addr\")\
        return nil\
    end\
    local ftypes = type(t.ftypes) == \"table\" and t.ftypes or {}\
