end\
\
local function send()\
    for _, v in ipairs(svrdata.svrs) do\
        svrdata_send_json(v)\
    end\
end\
\
local function add_json(msg)\
    if type(msg.data) ~= \"table\" then\
        log.error(\"must add table for svr data\")\
