            [\"lcmd_tmp_path\"] = \"function\",\
            [\"lcmd_data_path\"] = \"function\",\
            [\"lcmd_conf_save_filename\"] = \"function\",\
            [\"lcmd_runmsg\"] = \"function\",\
            [\"lcmd_boot\"] = \"function\",\
            [\"lcmd_init\"] = \"function\",\
            [\"lcmd_loop\"] = \"function\",\
            [\"lcmd_client\"] = \"function\",\
            [\"lcmd_unittest\"] = \"function\",\
        }\
    end\
\
    local info = {}\
    for k, v in pairs(_G) do\
        local vt = type(v)\
        if type(vtype) == \"nil\" or (type(vtype) == \"string\" and vtype == vt) then\
            if knowns[k] ~= vt then\
                if not info[vt] then\
                    info[vt] = {}\
                end\
                if vt == \"boolean\" or (vt == \"number\" and v ~= math.huge) then\
                    info[vt][k] = v\
                else\
                    info[vt][k] = tostring(v)\
                end\
            end\
        end\
    end\
    return info\
end\
\
local function plat_sync(t)\
    if type(t.pubip) == \"string\" and t.pubip ~= \"\" and t.pubip ~= sys.publicip then\
        sys.publicip = t.pubip\
    end\
    if type(t.time) == \"string\" and t.time ~= \"\" then\
        local ts = tonumber(t.time)\
        if type(ts) == \"number\" then\
            if ts > 0 then\
                if math.type(ts) == \"integer\" then\
                    myutil.set_timestamp(ts)\
                else\
                    local ti, tf = math.modf(ts)\
                    myutil.set_timestamp(ti, math.floor(tf * 1000000))\
                end\
            else\
                -- <= 0 means reset\
                myutil.reset_timestamp()\
            end\
        end\
    end\
end\
\
local function write(t)\
    local need_save = false\
\
    if type(t.sw_def_enabled) == \"boolean\" and t.sw_def_enabled ~= sys.sw_def_enabled then\
        sys.sw_def_enabled = t.sw_def_enabled\
        need_save = true\
    end\
\
    if type(t.procmem_period) == \"number\" and t.procmem_period ~= sys.procmem_period then\
        sys.procmem_period = t.procmem_period\
        timer.mod_notdisable(sys.procmem_timer_name, sys.procmem_period, 0, process_memory_check)\
    end\
    if type(t.procmem_max) == \"number\" and t.procmem_max ~= sys.procmem_max then\
        sys.procmem_max = t.procmem_max\
    end\
    if type(t.mtrim_enabled) == \"boolean\" and t.mtrim_enabled ~= sys.mtrim_enabled then\
        sys.mtrim_enabled = t.mtrim_enabled\
    end\
\
    if need_save then\
        lcmd_run{type = \"sys\", action = \"save_conf_change\"}\
    end\
end\
\
local function sys_conf_save()\
    return { type = sys.subtype, action = \"write\", sw_def_enabled = sys.sw_def_enabled}\
end\
\
--[[\
    模拟内存泄漏的方法\
    @param period    泄漏周期，单位秒\
    @param blocksize 单次分配的字节数\
    @param kernel    是否使用内核接口，true表示内核，false或nil表示用户空间\
]]\
local function simulate_memleak(t)\
    local period = tonumber(t.period) or 10\
    local blocksize = tonumber(t.blocksize) or (1 * 1024 * 1024) -- 1MB\
    local is_kernel = false\
    if t and t.kernel == true then\
        is_kernel = true\
    end\
\
    if period > 0 and blocksize > 0 then\
        if is_kernel then\
            -- 内核模式：只分配内存不释放（真正的内存泄露）\
            local ok, kernel = pcall(require, \"c.kernel\")\
            if not ok then\
                log.error(\"simulate_memleak: kernel module not available\")\
                return\
            end\
            timer.mod(sys.kernel_leak_timer_name, period, 0, function ()\
                log.error(\"simulate kernel memory leak, blocksize: \", blocksize)\
                local data = string.pack(\"=I\", blocksize)\
                kernel.send(CENUM.MEMSHR_U2K_TMEM_MALLOC, data)\
            end)\
        else\
            -- 用户空间模式：只分配内存不释放（真正的内存泄露）\
            timer.mod(sys.leak_timer_name, period, 0, function ()\
                log.error(\"simulate userspace memory leak, blocksize: \", blocksize)\
                local ptr = csys.tmem_malloc(blocksize)\
                if ptr then\
                    log.error(\"simulate userspace memory leak, malloc success, ptr: \", tostring(ptr), \" (leaked)\")\
                end\
                -- 不保存ptr，内存泄露\
            end)\
        end\
    end\
end\
\
-- 停止内存泄漏模拟（已分配的内存无法释放）\
local function stop_memleak(t)\
    local is_kernel = false\
    if t and t.kernel == true then\
        is_kernel = true\
    end\
\
    if is_kernel then\
        -- 内核模式：只停止定时器，内存无法释放（已泄露）\
        timer.del(sys.kernel_leak_timer_name)\
        log.error(\"stop kernel memory leak, timer deleted (leaked memory cannot be freed)\")\
    else\
        -- 用户空间模式：只停止定时器，内存无法释放（已泄露）\
        timer.del(sys.leak_timer_name)\
        log.error(\"stop userspace memory leak, timer deleted (leaked memory cannot be freed)\")\
    end\
end\
\
function sys.postinit()\
    sys.now_seed = sys.save_seed -- MUST NOT trigger save conf when init\
\
    sys.init_uptime = get_uptime()\
\
    if sys.sw_def_enabled then\
        sysswitch(sys.sw_def_enabled)\
    end\
\
    timer.mod_notdisable(sys.procmem_timer_name, sys.procmem_period, 0, process_memory_check)\
end\
\
actor.action_set(sys.subtype, \"boottime\", function() return sys.boottime end, \"return boottime of process\")\
\
actor.action_set(sys.subtype, \"dpi_uptime\", function() return get_uptime() - sys.init_uptime end, \"get dpi uptime\")\
actor.action_set(sys.subtype, \"sys_uptime\", function() return get_uptime() end, \"get sys uptime\")\
actor.action_set(sys.subtype, \"dpi_stime\", function() return os.date(\"%F %T\", os.time() - get_uptime() + sys.init_uptime) end, \"get dpi start time\")\
actor.action_set(sys.subtype, \"sys_stime\", function() return os.date(\"%F %T\", os.time() - get_uptime()) end, \"get sys start time\")\
actor.action_set(sys.subtype, \"uptime_to_date\", \
        function(msg)\
            if type(msg.uptime) ~= \"number\" then\
                return { err = \"uptime missed\" }\
            end\
            local date = uptime_to_date(msg.uptime)\
            if not date then\
                return { err = \"invalid uptime\" }\
            end\
            return { date = date }\
        end,\
        \"convert uptime to date, { uptime = number }\")\
actor.action_set(sys.subtype, \"show_endian\", function() return { endian = csys.show_endian() } end, \"show endian\")\
actor.action_set(sys.subtype, \"unbypass\", function () sysswitch(true) end, \"close bypass stat, enable engine\")\
actor.action_set(sys.subtype, \"bypass\", function () sysswitch(false) end, \"bypass engine\")\
actor.action_set(sys.subtype, \"set_log\", set_log,\
                 \"set log parameters, {level = [fatal | error | warn | info | debug | trace], file = filename}\")\
actor.action_set(sys.subtype, \"set_msocket\", msocket.write, \"{maxcount = number}, limit the number of identical name, default 3\")\
actor.action_set(sys.subtype, \"read\", read, \"read all var\")\
actor.action_set(sys.subtype, \"write\", write, \"write conf\")\
actor.action_set(sys.subtype, \"show_conf_save\", sys_conf_save, \"save sys conf to local file\")\
\
actor.action_set(sys.subtype, \"save\", save, \"save msg to local file\")\
actor.action_set(sys.subtype, \"save_conf_change\", save_conf_change, \"trigger conf save to local file, no args\")\
actor.action_set(sys.subtype, \"get_conf_master_sync\", get_conf_master_sync, \"get all conf in master which need sync to slave lua, internal use\")\
\
actor.action_set(sys.subtype, \"show_memory\", show_memory, \"show memory usage\")\
actor.action_set(sys.subtype, \"collect_memory\", collect_memory, \"collect garbage\")\
actor.action_set(sys.subtype, \"show_process_memory\", function() local mem,mem_org=myutil.get_process_memory() return { mem = mem, mem_org = mem_org } end, \"show process memory usage\")\
actor.action_set(sys.subtype, \"malloc_trim\", function () csys.malloc_trim() end, \"malloc_trim\")\
actor.action_set(sys.subtype, \"exit\", lcmd_loop_exit, \"exit lua engine, only for memory test\")\
actor.action_set(sys.subtype, \"leak\", leak_memory, \"{file = xxx}, show mem leak info into file\")\
actor.action_set(sys.subtype, \"load\", load_string_file, \"{string = xxx, file = xxx}, load string or file\")\
actor.action_set(sys.subtype, \"show_pbcnt\", function () return actor.pbcnt end, \"show all actor publish count\")\
actor.action_set(sys.subtype, \"extperm_set\", actor.extperm_set, \"perm conf set\")\
actor.action_set(sys.subtype, \"extperm_get\", actor.extperm_get, \"perm conf get\")\
actor.action_set(sys.subtype, \"show_crypto_conf\", function (t) local conf, err = myfile.load_crypto_json(t.file or lcmd_conf_save_filename()) return { conf = conf, err = err } end, \"decrypt data file, and unzip it, {file = string}, default ../data/conf_init.bin\")\
actor.action_set(sys.subtype, \"plat_sync\", plat_sync, \"{ pubip = string, time = string }\")\
\
timer.mod(\"sys_save_conf\", 60, 0, \
          function() \
              if sys.now_seed ~= sys.save_seed then\
                  save()\
                  sys.now_seed = sys.save_seed\
              end\
          end\
)\
\
local dpi = require\"svrcomm.dpi\"\
actor.action_set(sys.subtype, \"dcache_stat\", dpi.dcache_stat, \"show dcache stat\")\
actor.action_set(sys.subtype, \"dcache_restart\", dpi.dcache_restart, \"restart dcache, {max = maxdns, cycle = secs}\")\
actor.action_set(sys.subtype, \"dpiwrite\", dpi.write, \"dpi write, { use_seconn = boolean, pthlimit = number, pthtimeout = number, pthuseasync = boolean }\")\
actor.action_set(sys.subtype, \"dpiread\", dpi.read, \"dpi read\")\
actor.action_set(sys.subtype, \"pthcall\", pth.call, \"pthcall\")\
actor.action_set(sys.subtype, \"pth_recvcall\", pth.recvcall, \"pth_recvcall\")\
actor.action_set(sys.subtype, \"pth_finicall\", pth.finicall, \"pth_finicall\")\
actor.action_set(sys.subtype, \"pthcallcache_stat\", pth.cache_stat, \"pthcallcache_stat\")\
actor.action_set(sys.subtype, \"simulate_memleak\", simulate_memleak, \"{ period = number, blocksize = number, kernel = boolean }, simulate memory leak, kernel=true for kernel mode\")\
actor.action_set(sys.subtype, \"stop_memleak\", stop_memleak, \"{ kernel = boolean }, stop memory leak, kernel=true for kernel mode\")\
\
local ckey = require\"svrcomm.ckey\"\
actor.action_set(\"ckey\", \"write\", ckey.write, \"ckey write, { addr = string, key = string, lease = number}, { max = number }\")\
actor.action_set(\"ckey\", \"read\", ckey.read, \"ckey read\")\
actor.action_set(\"ckey\", \"del\", ckey.del, \"ckey del, { addr = string }\")\
actor.action_set(\"ckey\", \"flush\", ckey.flush, \"ckey flush\")\
actor.action_set(\"ckey\", \"request\", ckey.request, \"ckey request, { addr = string }\")\
actor.action_set(\"ckey\", \"show_conf_master_sync\", ckey.show_conf_master_sync, \"ckey conf in master which need sync to slave lua\")\
\
return sys\
"
, '@'.."./service/sys.lua" ) )

package.preload[ "termact" ] = assert( (loadstring or load)(
"local actor = require(\"luactor\")\
local myip = require(\"myip\")\
local cjson = require(\"cjson\")\
local mime = require(\"mime\")\
local ccrypto = require(\"c.crypto\")\
local myutil = require(\"myutil\")\
local mystring = require(\"mystring\")\
local timer = require(\"timer\")\
local log = require(\"log\")\
local ctime = require(\"c.time\")\
\
local termact = {\
    type = \"termact\",\
    subtype = \"termact\",\
    help = \"collect termact to server\",\
\
    -- conf\
    enable = false,\
    rules = {\
        -- Samba, tcp dst port 445, \"4,FE534D42\", \"16,01002100\"\
        \"(tcp dst port 445 and tcp[((tcp[12]&0xf0)>>2)+4:4]=0xfe534d42 and tcp[((tcp[12]&0xf0)>>2)+16:4]=0x01002100)\",\
        -- DHCP, udp dst port 67    -- pcap_dump 默认的规则中已存在\
        -- DHCPV6, udp dst port 547\
        -- MDNS, udp dst port 5353\
        \"(udp dst port 547 or udp dst port 5353)\",\
        -- TV_Iptv, dst port 5501, 8090, 22024, \"0,6F70743D\", \"4,31323026\"\
        \"((udp dst port 5501 or udp dst port 8090 or udp dst port 22024) and udp[8:4]=0x6f70743d and udp[12:4]=0x31323026)\",\
        \"((tcp dst port 5501 or tcp dst port 8090 or tcp dst port 22024) and tcp[(tcp[12]&0xf0)>>2:4]=0x6f70743d and tcp[((tcp[12]&0xf0)>>2)+4:4]=0x31323026)\",\
        -- TV_PH_sn, dst port 13861, 23861, 33861, 43861, 53861, 63861, \"0,0200\", \"6,0109\"\
        \"((udp dst port 13861 or udp dst port 23861 or udp dst port 33861 or udp dst port 43861 or udp dst port 53861 or udp dst port 63861) and udp[8:2]=0x0200 and udp[14:2]=0x0109)\",\
        \"((tcp dst port 13861 or tcp dst port 23861 or tcp dst port 33861 or tcp dst port 43861 or tcp dst port 53861 or tcp dst port 63861) and tcp[(tcp[12]&0xf0)>>2:2]=0x0200 and tcp[((tcp[12]&0xf0)>>2)+6:2]=0x0109)\",\
        -- Dev_xiaomi_payload, tcp dst port 5222, \"0,C2FE0005\", \"4,0000\"\
        \"(tcp dst port 5222 and tcp[(tcp[12]&0xf0)>>2:4]=0xc2fe0005 and tcp[((tcp[12]&0xf0)>>2)+4:2]=0x0000)\",\
        -- 内网组播报文采集\
        \"net 224.0.0.0/8 or net 239.0.0.0/8\",\
    },\
    seed = \"0\",\
    matchft = nil,          -- match pkts filter table\
\
    -- stat\
    add_cnt = 0,            -- 终端行为域名添加次数\
    del_cnt = 0,            -- 终端行为域名删除次数\
    coll_pkgcnt = 0,        -- 采集报文总次数\
    coll_domcnt = 0,        -- 采集域名总次数\
    stdom = {\
        -- domain = true\
    }\
}\
\
local function stdom_update(t)\
    local domains = t.domains or {}\
    if t.all and #domains > 0 then\
        lcmd_run({subtype = \"termact\", action = \"flush\"})\
    end\
    for _, value in ipairs(domains) do\
        lcmd_run({subtype = \"termact\", action = \"add\", domain = value})\
    end\
end\
\
local function add_send(mac, key, data)\
    if key == \"term_pkt\" then\
        termact.coll_pkgcnt = termact.coll_pkgcnt + 1\
    else\
        termact.coll_domcnt = termact.coll_domcnt + 1\
    end\
    lcmd_run({subtype = \"osinfo\", action = \"add_sig\", key = key, value = data, mac = mac, from = key})\
end\
\
local function collect_dns(msg)\
    if not termact.enable then\
        return\
    end\
    local info = msg.dnstable\
    local mac, domain = info.mac or \"\", info.domain or \"\"\
    if termact.stdom[domain] then\
        add_send(mac, \"term_domain\", domain)\
    end\
end\
\
local function collect_http(msg)\
    if not termact.enable then\
        return\
    end\
    for _, info in pairs(msg.http_tables) do\
        local mac = myip.mac_ntoa(info.mac)\
        local host = myutil.urlsplit(info.url)\
        if termact.stdom[host] then\
            add_send(mac, \"term_domain\", host)\
        end\
    end\
end\
\
local function collect_https(msg)\
    if not termact.enable then\
        return\
    end\
    local info = msg.https_table\
    local mac, domain = info.mac or \"\", info.domain or \"\"\
    if termact.stdom[domain] then\
        add_send(mac, \"term_domain\", domain)\
    end\
end\
\
local function collect_quic(msg)\
    if not termact.enable then\
        return\
    end\
    local info = msg.quic_table\
    local mac, domain = info.mac or \"\", info.domain or \"\"\
    if termact.stdom[domain] then\
        add_send(mac, \"term_domain\", domain)\
    end\
end\
\
local function collect_pkg(msg)\
    if not termact.enable then\
        return\
    end\
    local match = termact.matchft\
    if not match then\
        return\
    end\
    local pt = msg.pcap_tables\
    if pt.proto ~= 6 and pt.proto ~= 17 then\
        return\
    end\
    if not myip.mac_check(\"\", pt.mac, false) or pt.l7_len <= 0 then\
        return\
    end\
    local proto = (pt.proto == 6) and \"tcp\" or \"udp\"\
    local sport, dport = tostring(pt.sport), tostring(pt.dport)\
    if match[proto..\"_sport\"][sport] or match[proto..\"_dport\"][dport] then\
        local payload_b64 = mime.b64(string.sub(pt.data, pt.offset, pt.offset + pt.l7_len - 1))\
        add_send(pt.mac, \"term_pkt\", pt.sip..\"_\"..pt.sport..\"_\"..pt.proto..\"_\"..pt.dip..\"_\"..pt.dport..\"_\"..payload_b64)\
        return\
    end\
    for subnet, _ in pairs(match.net) do\
        if myip.ip_is_in_subnet(pt.sip, subnet) or myip.ip_is_in_subnet(pt.dip, subnet) then\
            local payload_b64 = mime.b64(string.sub(pt.data, pt.offset, pt.offset + pt.l7_len - 1))\
            add_send(pt.mac, \"term_pkt\", pt.sip..\"_\"..pt.sport..\"_\"..pt.proto..\"_\"..pt.dip..\"_\"..pt.dport..\"_\"..payload_b64)\
            return\
        end\
    end\
end\
\
local function generate_match(rules)\
    local matchft = {udp_sport = {}, udp_dport = {}, tcp_sport = {}, tcp_dport = {}, net = {}}\
    for _, filter in ipairs(rules) do\
        for port in string.gmatch(filter, \"udp%s+src%s+port%s+([%d]+)\") do\
            matchft.udp_sport[port] = true\
        end\
        for port in string.gmatch(filter, \"udp%s+dst%s+port%s+([%d]+)\") do\
            matchft.udp_dport[port] = true\
        end\
        for port in string.gmatch(filter, \"tcp%s+src%s+port%s+([%d]+)\") do\
            matchft.tcp_sport[port] = true\
        end\
        for port in string.gmatch(filter, \"tcp%s+dst%s+port%s+([%d]+)\") do\
            matchft.tcp_dport[port] = true\
        end\
        for subnet in string.gmatch(filter, \"net%s+([%d%./]+)\") do\
            matchft.net[subnet] = true\
        end\
    end\
    return matchft\
end\
\
local function set_pcap_filter(enable)\
    if enable then\
        local filter = table.concat(termact.rules, \" or \")\
        lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_set\", keyname = termact.type, filter = filter })\
        termact.matchft = generate_match(termact.rules)\
        return\
    end\
    lcmd_run({ type = \"pcap_dump\", action = \"dynfilter_unset\", keyname = termact.type })\
    termact.matchft = nil\
end\
\
local function read()\
    local stdom_cnt = 0\
    for _, _ in pairs(termact.stdom) do\
        stdom_cnt = stdom_cnt + 1\
    end\
    return {\
        enable = termact.enable,\
        seed = termact.seed,\
        stdom_cnt = stdom_cnt,\
    }\
end\
\
local function write(t)\
    local need_reload = false\
    if type(t.enable) == \"boolean\" and t.enable ~= termact.enable then\
        termact.enable = t.enable\
        need_reload = true\
    end\
    if type(t.seed) == \"string\" and t.seed ~= termact.seed then\
        termact.seed = t.seed\
    end\
    if type(t.rules) == \"table\" and #t.rules > 0 then\
        termact.rules = t.rules\
        need_reload = true\
    end\
    if need_reload then\
        set_pcap_filter(termact.enable)\
    end\
end\
\
local function stat()\
    return {\
        add_cnt = termact.add_cnt,\
        del_cnt = termact.del_cnt,\
        coll_pkgcnt = termact.coll_pkgcnt,\
        coll_domcnt = termact.coll_domcnt,\
    }\
end\
\
function termact.postinit()\
    termact.dindex = actor.subscribe(\"DNS\", collect_dns)\
    termact.hindex = actor.subscribe(\"HTTP\", collect_http)\
    termact.qindex = actor.subscribe(\"QUIC\", collect_quic)\
    termact.hsindex = actor.subscribe(\"HTTPS\", collect_https)\
    termact.mindex = actor.subscribe(\"PCAP\", collect_pkg)\
    set_pcap_filter(termact.enable)\
end\
\
function termact.finish()\
    if termact.dindex then\
        actor.unsubscribe(\"DNS\", termact.dindex)\
    end\
    if termact.hindex then\
        actor.unsubscribe(\"HTTP\", termact.hindex)\
    end\
    if termact.hsindex then\
        actor.unsubscribe(\"HTTPS\", termact.hsindex)\
    end\
    if termact.qindex then\
        actor.unsubscribe(\"QUIC\", termact.qindex)\
    end\
    if termact.mindex then\
        actor.unsubscribe(\"PCAP\", termact.dindex)\
    end\
    set_pcap_filter(false)\
end\
\
actor.action_set(termact.subtype, \"read\", read, [[read termact conf]])\
actor.action_set(termact.subtype, \"write\", write, [[set termact conf, {enable=boolean,seed=string,rules=list}]])\
actor.action_set(termact.subtype, \"stat\", stat, [[read termact stat]])\
actor.action_set(termact.subtype, \"show_rules\", function () return {rules = termact.rules, matchft = termact.matchft} end, [[show termact rules]])\
actor.action_set(termact.subtype, \"add\", function(t)\
    if t.domain and not termact.stdom[t.domain] then\
        termact.stdom[t.domain] = true\
        termact.add_cnt = termact.add_cnt + 1\
    end\
end, [[add stdom, {domain=string}]])\
actor.action_set(termact.subtype, \"flush\", function()\
    for domain, _ in pairs(termact.stdom) do\
        termact.stdom[domain] = nil\
        termact.del_cnt = termact.del_cnt + 1\
    end\
end, [[flush stdom]])\
actor.action_set(termact.subtype, \"stdom_update\", stdom_update, [[{all=boolean,domains=list}]], \".plugin.TermDomainSig\")\
actor.action_set(termact.subtype, \"show_conf_svr\", function() return {type = \"termact\", subtype = \"termact\", seed = termact.seed} end, [[show termact conf msg to oper svr]])\
\
return termact\
"
, '@'.."./service/termact.lua" ) )

package.preload[ "timer" ] = assert( (loadstring or load)(
"local log = require\"log\"\
\
local timer = {\
