    log_add(log, func, result)\
\
    return result or {} \
end\
\
local function log_set(old, max, log)\
    local len = #old - max \
    if len >= 0 then\
        if log then\
            len = len + 1\
        end\
        for i=1,len do\
            table.remove(old, 1)\
        end\
    end\
    table.insert(old, log)\
end\
