local function host_add_one(host, par_mac, odm)\
    local one = {}\
    add_value(one, \"par_mac\", par_mac, \"\")\
    add_value(one, \"mac\", host.mac, \"\")\
    add_value(one, \"ip\", host.ip, \"\")\
