        add_value(one, \"rxbytes\", host.rxbytes, -1)\
        add_value(one, \"txbytes\", host.txbytes, -1)\
        add_value(one, \"power_level\", host.powerlevel, -1)\
        add_value(one, \"acc_speed\", host.negorate, -1)\
        add_value(one, \"sta_rxpkt_fail\", host.starxpktfail, -1)\
        add_value(one, \"sta_txpkt_fail\", host.statxpktfail, -1)\
        add_value(one, \"sta_rxpkt_retry\", host.starxpktretry, -1)\
        add_value(one, \"sta_txpkt_retry\", host.statxpktretry, -1)\
