    add_value(one, \"hostname\", host.hostname, \"\")\
    add_value(one, \"dev_type\", host.devtype, \"\")\
    add_value(one, \"model\", host.model, \"\")\
    add_value(one, \"brand\", host.brand, \"\")\
    add_value(one, \"os\", host.os, \"\")\
