end\
\
local function fmt_wifiport(wifi, host, odm, log, test)\
    local port, acctype = host.port, host.connectiontype\
    if not port or not acctype or acctype ~= 1 then\
        return\
    end\
\
    local ssids = nil\
    if test and type(test.getssid) == \"function\" then\
        ssids = test.getssid(port)\
        if not wifi[port] then\
            log_add(log, \"getssid(\"..tostring(port)..\")\", ssids)\
        end\
    end\
    if host.devname then\
        if not wifi[port] then\
            local wlan = ssids or call_api(\"getssid\", log, port)\
            if wlan and wlan.SSIDAlias then\
                local ssid = wlan.SSIDAlias\
                wifi[port] = ssid\
                port = ssid\
            end\
        else\
            port = wifi[port]\
        end\
    else\
        local wandev = ssids or call_api(\"getssid\", log, port)\
        if wandev.rfbrand == 0 then\
            port = \"2.4G\"\
        elseif wandev.rfbrand == 1 then\
            port = \"5G\"\
        end\
    end\
    host.port = port\
end\
\
local function get_lanhost_info(sn, test, log, brmacs_enable, agetime, oss)\
    local lanhost = test.lanhost or call_api(\"lanhost\", log)\
    local devname = call_api(\"devname\", log)\
    local odm = call_api(\"odm\", log)\
    local all_lanhost, wifi = {}, {}\
    for mac, host in pairs(lanhost) do\
        local macstr = myip.mac_fmt(host.macstring)\
        host.mac = macstr\
        if not myip.mac_check(\"\", macstr) then\
            goto continue\
        end\
\
        if odm == 1 then\
            fmt_wifiport(wifi, host, odm, log, test)\
        end\
        -- 用于调整天翼网关1.0 有线连接值不统一的问题\
        if odm == 0 then\
            host.connectiontype = host.connectiontype - 1\
        end\
        local one = host_add_one(host, sn, odm)    \
\
        --update devname\
        if devname[mac] then\
            add_value(one, \"devname\", devname[mac].devname, \"\")\
        end\
\
        --add level\
        if host.active ~= 1 then\
            add_value(one, \"level\", -1, -1)\
        else\
            add_value(one, \"level\", 1, 1)\
        end\
        all_lanhost[macstr]=one\
        ::continue::\
    end\
    log_add(log, \"get_lanhost_info\", all_lanhost)\
    if brmacs_enable then\
        local brinfo = get_brmacs(all_lanhost, agetime, test)\
        for k, v in pairs(brinfo) do\
            local mac_with_colon = k:gsub(\"%x%x\", function (w) return w..\":\" end, 5)\
            local osinfo = oss[mac_with_colon]\
            if osinfo and osinfo.desc and osinfo.desc.dev_type then\
                all_lanhost[k] = host_add_one(v, sn, odm)\
                add_value(all_lanhost[k], \"level\", 1, 1)\
            end\
        end\
        log_add(log, \"get_brmacs\", brinfo)\
    end\
    return all_lanhost\
end\
\
local function get_ap_ssid(wifi)\
    local wifis = {}\
    if type(wifi) ~= \"table\" or wifi.errmsg then\
        return wifis\
    end\
    for k,v in pairs(wifi) do\
        if v.radio and type(v.ap) == \"table\" then\
            local mode = v.radio.mode or \"\"\
            for _,wifinfo in pairs(v.ap) do\
                if wifinfo.apidx == 0 then\
                    wifis[mode] = wifinfo.ssid\
                end\
            end\
        end\
    end\
    return wifis\
end\
\
local function get_ext_apinfo(apinfo)\
    local info, devinfo = {}, {}\
    if type(apinfo) ~= \"table\" then\
        apinfo = {}\
    end\
    if type(apinfo.real_devinfo) == \"table\" and not apinfo.real_devinfo.errmsg then\
        devinfo = apinfo.real_devinfo\
    end\
    if type(apinfo.channel) == \"table\" and not apinfo.channel.errmsg then\
        info[\"2Gchannel\"] = apinfo.channel[\"2.4G\"]        \
        info[\"5Gchannel\"] = apinfo.channel[\"5G\"]        \
    end\
    if type(apinfo.workmode) == \"string\" then\
        info[\"workmode\"] = apinfo.workmode\
    end\
    local ssids = {}\
    ssids = get_ap_ssid(apinfo.wifi)\
    info[\"2Gssid\"] = ssids[\"2.4G\"]\
    info[\"5Gssid\"] = ssids[\"5G\"]\
    return info, devinfo\
end\
\
local function string_to_number(str)\
    local num\
    if type(str) == \"string\" then\
        local numstr = string.match(str,\"[-%d]+\")  \
        num = tonumber(numstr)\
    else\
        return str\
    end\
    return num \
end\
\
local function add_value_with_compare(info, key, value, default, invalid_value)\
    if not info[key] or (value and value ~= default and value ~= invalid_value and value ~= info[key]) then\
        add_value(info, key, value, default)\
    end\
end\
\
local function add_connd_host(macinfo, info, mac, parmac)\
    local one = macinfo or host_add_one({mac = mac}, parmac, 1)\
    add_value_with_compare(one, \"par_mac\", parmac, \"\")\
    add_value_with_compare(one, \"acc_type\", info.connecttype, -1)\
    if info.connecttype == 0 then\
        add_value(one, \"acc_port\", \"\", \"\")\
    else\
        add_value_with_compare(one, \"acc_port\", info.band, \"\")\
    end\
    add_value_with_compare(one, \"online_time\", string_to_number(info.onlineTime), -1)\
    add_value_with_compare(one, \"hostname\", info.hostname, \"\")\
    add_value_with_compare(one, \"power_level\", string_to_number(info.rssi), -1, 0)\
    add_value_with_compare(one, \"uploadspeed\", info.uploadspeed, \"\", \"0\")\
    add_value_with_compare(one, \"downloadspeed\", info.downloadspeed, \"\", \"0\")\
\
    -- update\
    add_value(one, \"active\", string_to_number(info.active), 1)\
    add_value_with_compare(one, \"ip\", info.ipaddr, \"\", \"0.0.0.0\")\
    add_value_with_compare(one, \"acc_speed\", string_to_number(info.negorate), -1, 0)\
    add_value_with_compare(one, \"rxbytes\", string_to_number(info.bytesreceived), -1, 0)\
    add_value_with_compare(one, \"txbytes\", string_to_number(info.bytessent), -1, 0)\
    add_value_with_compare(one, \"last_active_time\", info.activetime, \"\")\
    add_value_with_compare(one, \"last_inactive_time\", info.inactivetime, \"\")\
\
    -- extinfo with pkt\
    add_value_with_compare(one, \"sta_rxpkt_fail\", info.packetsfailreceived, -1)\
    add_value_with_compare(one, \"sta_txpkt_fail\", info.packetsfailsent, -1)\
    add_value_with_compare(one, \"sta_rxpkt_retry\", info.packetsretryreceived, -1)\
    add_value_with_compare(one, \"sta_txpkt_retry\", info.packetsretrysent, -1)\
    add_value_with_compare(one, \"pkt_total\", info.packetstotal, -1)\
    add_value_with_compare(one, \"sta_txpkt_total\", info.packetssent, -1)\
    add_value_with_compare(one, \"sta_rxpkt_total\", info.packetsreceived, -1)\
    add_value_with_compare(one, \"pkt_loss\", info.packetsloss, -1)\
\
    if not one.level or one.level < 2 then\
        add_value(one, \"level\", 2, 2)\
    end\
    if myip.mac_check(\"\", mac) then\
        lcmd_run{subtype = \"osinfo\", action = \"add\", key = \"hostname\", value = one.hostname, mac = mac, from = \"mesh\"}\
    end\
    return one\
end\
\
local function comp_mac(mac1, mac2)\
    local number1 = tonumber(mac1, 16)\
    local number2 = tonumber(mac2, 16)\
    if type(number1) ~= \"number\" then\
        return false\
    end\
    if type(number2) ~= \"number\" then\
        return true\
    end\
    return number1 < number2\
end\
\
local function get_connd_info(sn, test, log, lanhost, conndtype)\
    local elink =  test.elink or call_api(\"elink\", log)\
    local devinfo, connd_host, dir_graph, hprio_aray, hprio_mac, get_connd_success = str_to_table(elink.elinkinfo), {}, {}, {}, {}, false\
    local realdevs, abapmacs = {}, {}\
    for _, v in pairs(devinfo) do\
        if type(v) == \"table\" and v.Result == 0 and type(v.status) == \"table\" and type(v.status.real_devinfo) == \"table\" and not v.status.real_devinfo.errmsg then\
            local subdev = v.status.real_devinfo\
            for _, info in pairs(subdev) do\
                realdevs[info.mac] = true\
            end\
        end\
    end\
    for _, v in pairs(devinfo) do\
        if type(v) == \"table\" and v.Result == 0 and type(v.apMac) == \"string\" and #v.apMac == 12 then\
            local apmac = myip.mac_fmt(v.apMac)\
            if (not lanhost[apmac] or lanhost[apmac].active ~= 1) and not realdevs[apmac] then\
                abapmacs[apmac:sub(1, 10)] = apmac\
            end\
        end\
    end\
    for k,v in pairs(devinfo) do\
        if type(v) == \"table\" and v.Result == 0 and myip.mac_check(\"\", v.apMac) and type(v.apInfo) == \"table\" and type(v.status) == \"table\" then\
            get_connd_success = true\
            local mac = myip.mac_fmt(v.apMac)\
            local apInfo = v.apInfo\
            connd_host[mac] = connd_host[mac] or host_add_one({mac = mac}, sn, 1)\
            add_value(connd_host[mac], \"model\", apInfo.DeviceType, \"\")\
            add_value(connd_host[mac], \"os\", \"\", \"\")\
            add_value(connd_host[mac], \"active\", 1, 1)\
            add_value(connd_host[mac], \"level\", 3, 3)\
            add_value(connd_host[mac], \"sn\", apInfo.sn, \"\")\
            add_value(connd_host[mac], \"brand\", apInfo.vendor, \"\")\
            add_value(connd_host[mac], \"dev_type\", apInfo.APType or \"elink\", \"\")    -- 与组网插件沟通, APType 可能的取值：\"FTTRsub\", \"elink\"\
            if apInfo.APType == \"\" then     -- 测试中发现有返回 APType 取值 \"\" 的情况\
                add_value(connd_host[mac], \"dev_type\", \"elink\", \"\")\
            end\
\
            --add 2Gchannel 5Gchannel 2Gssid 5Gssid workmode\
            local extinfo, subdev = get_ext_apinfo(v.status)\
            add_value(connd_host[mac], \"2Gchannel\", extinfo[\"2Gchannel\"], -1)\
            add_value(connd_host[mac], \"5Gchannel\", extinfo[\"5Gchannel\"], -1)\
            add_value(connd_host[mac], \"2Gssid\", extinfo[\"2Gssid\"], \"\")\
            add_value(connd_host[mac], \"5Gssid\", extinfo[\"5Gssid\"], \"\")\
            add_value(connd_host[mac], \"workmode\", extinfo.workmode, \"\")\
\
            lcmd_run{subtype = \"osinfo\", action = \"add_sig\", key = \"elink\", value = {apInfo.DeviceType or \"\", apInfo.vendor or \"\"}, table = true, mac = mac, from = \"mesh\"}\
            lcmd_run{subtype = \"osinfo\", action = \"save_dev_desc\", mac = myip.mac_fmt(mac, \":\"), desc = {os = \"\", brand = apInfo.vendor or \"\", model = apInfo.DeviceType or \"\", dev_type = connd_host[mac].dev_type, devtypeint = 5, elinktype = conndtype[connd_host[mac].dev_type] or 1}}\
\
            --add elink host\
            dir_graph[mac] = {}\
            if lanhost[mac] then\
                table.insert(hprio_aray, mac)\
            end\
            for _, info in pairs(subdev) do\
                if abapmacs[info.mac:sub(1, 10)] then   -- 解决elink异常时real_devinfo中显示的组网设备mac与该设备的apMac相似，引起的拓扑中多一个设备的问题\
                    info.mac = abapmacs[info.mac:sub(1, 10)]\
                    abapmacs[info.mac:sub(1, 10)] = false\
                end\
                local mac2 = myip.mac_fmt(info.mac)\
                if myip.mac_check(\"\", mac2) then\
                    table.insert(dir_graph[mac], mac2)\
                    connd_host[mac2] = add_connd_host(connd_host[mac2], info, mac2, mac)\
                end\
            end\
        end\
    end\
    log_add(log, \"deal abnormal apMac\", abapmacs)\
    table.sort(hprio_aray, comp_mac)\
    for _, mac in ipairs(hprio_aray) do\
        hprio_mac[mac] = 1\
    end\
    return {connd_host, dir_graph, hprio_mac, get_connd_success}\
end\
\
local function comp_level(table1, table2)\
    if type(table1.level) ~= \"number\" then\
        return false\
    end\
    if type(table2.level) ~= \"number\" then\
        return true\
    end\
    return table1.level > table2.level\
end\
\
function topo.gen_topo_info(sn ,test, log, lanhost, connd_info, oss, conndtype)\
    local online_lanhost, offline_lanhost = {}, {}\
    local roots, topo_info, port_info = {}, {}, {}\
    local connd_host, dir_graph, hprio_mac, get_connd_success = connd_info[1], connd_info[2], connd_info[3], connd_info[4]\
    local dtype = {ROUTER = \"route\"}\
    local typewifi = {SMTDEV = 1, Pad = 1, phone = 1}\
    local bad_hostname = {unknown = true, empty = true, anonymous = true, [\"n/a\"] = true, unknow = true}\
    local suffix_sw, suffix_ap = 1, 1\
\
    -- 如果调用组网插件成功，则生成组网树\
    if get_connd_success then\
        roots, topo_info = d2tree.calc_trees(dir_graph, hprio_mac)\
    end\
    log_add(log, \"calc_trees\", {roots = roots, topo_info = topo_info})\
\
    for mac, info in pairs(topo_info) do\
        -- 无法在lanhost中直接找到root/branch时，关联root/branch到lanhost中在线的相似mac\
        -- 隐藏lanhost中与root/branch相似、不属于组网返回的在线节点\
        if (not lanhost[mac] or lanhost[mac].active ~= 1) and (info.ntype == \"root\" or info.ntype == \"branch\") then\
            for k, v in pairs(lanhost) do\
                if k:sub(1, 10) == mac:sub(1, 10) and not connd_host[k] and v.active == 1 and not v.hide then\
                    info.lan_mac = k\
                    v.hide = true\
                    break\
                end\
            end\
        -- 解决elink异常时将网关直连设备作为其下挂，而插件绘制拓扑以组网插件返回层级为准，此时出现的拓扑层级显示问题\
        elseif lanhost[mac] and lanhost[mac].active == 1 and lanhost[info.root]\
                and (lanhost[mac].acc_port ~= lanhost[info.root].acc_port or lanhost[mac].acc_type ~= lanhost[info.root].acc_type) then\
            if info.ntype == \"term\" then\
                topo_info[mac] = nil\
                connd_host[mac] = nil\
            else\
                info.parent = sn\
                info.ntype = \"root\"\
                info.root = mac\
                info.level = 1\
            end\
        else\
            -- do nothing\
        end\
    end\
    log_add(log, \"add_lan_mac\", topo_info)\
\
    -- 填充lanhost信息到生成树\
    for mac, info in pairs(lanhost) do\
        topo_info[mac] = topo_info[mac] or {}\
        for k, v in pairs(info) do\
            topo_info[mac][k] = v\
        end\
        if dtype[info.dev_type] then    -- 修复lanhost中可能读出数据为\"ROUTER\"的情况，topo数据上报使用\"route\"\
            topo_info[mac].dev_type = dtype[info.dev_type]\
        end\
    end\
    log_add(log, \"fill_lanhost\", topo_info)\
\
    -- 填充组网信息到生成树并与lanhost信息进行合并\
    -- 填充终端识别结果到生成树\
    for mac, info in pairs(topo_info) do\
        -- add connd_host\
        if connd_host[mac] then\
            for k, v in pairs(connd_host[mac]) do\
                info[k] = v\
            end\
        end\
        -- update par_mac\
        if info.parent then\
            info.par_mac = info.parent\
            if info.ntype == \"root\" then    -- 规避根节点组网设备无法在lanhost中关联到时，其父节点展示不准的问题\
                info.par_mac = sn\
            end\
        end\
        -- merge info\
        local laninfo = lanhost[mac]\
        if info.lan_mac then\
            laninfo = lanhost[info.lan_mac]\
        end\
        if laninfo and connd_host[mac] then\
            info.devname = laninfo.devname\
            if info.ntype == \"root\" then\
                info.par_mac = sn\
                info.acc_type = laninfo.acc_type\
                info.acc_port = laninfo.acc_port\
                info.power_level = laninfo.power_level\
                info.acc_speed = laninfo.acc_speed\
                info.online_time = laninfo.online_time\
                info.hostname = laninfo.hostname\
            end\
            if info.ip == \"\" or info.ip == \"0.0.0.0\" then\
                info.ip = laninfo.ip\
            end\
            if info.rxbytes == -1 then info.rxbytes = laninfo.rxbytes end\
            if info.txbytes == -1 then info.txbytes = laninfo.txbytes end\
            if info.sta_rxpkt_fail == -1 then info.sta_rxpkt_fail = laninfo.sta_rxpkt_fail end\
            if info.sta_txpkt_fail == -1 then info.sta_txpkt_fail = laninfo.sta_txpkt_fail end\
            if info.sta_rxpkt_retry == -1 then info.sta_rxpkt_retry = laninfo.sta_rxpkt_retry end\
            if info.sta_txpkt_retry == -1 then info.sta_txpkt_retry = laninfo.sta_txpkt_retry end\
            if info.pkt_total == -1 then info.pkt_total = laninfo.pkt_total end\
            if info.sta_txpkt_total == -1 then info.sta_txpkt_total = laninfo.sta_txpkt_total end\
            if info.sta_rxpkt_total == -1 then info.sta_rxpkt_total = laninfo.sta_rxpkt_total end\
            if info.pkt_loss == -1 then info.pkt_loss = laninfo.pkt_loss end\
            if info.hostname == \"\" then info.hostname = laninfo.hostname end\
            if info.last_active_time == \"\" then info.last_active_time = laninfo.last_active_time end\
            if info.last_inactive_time == \"\" then info.last_inactive_time = laninfo.last_inactive_time end\
        end\
        -- add desc\
        local mac_with_colon = mac:gsub(\"%x%x\", function (w) return w..\":\" end, 5)\
        local osinfo = oss[mac_with_colon]\
        if osinfo and osinfo.desc and osinfo.desc.dev_type then\
            info.model = osinfo.desc.model\
            info.brand = osinfo.desc.brand\
            if not info.workmode then    -- 定制路由器不使用平台识别\
                info.dev_type = dtype[osinfo.desc.dev_type] or osinfo.desc.dev_type\
                info.dev_subtype = osinfo.desc.dev_subtype\
            end\
            info.os = osinfo.desc.os\
            info.ctei = osinfo.desc.ctei or 0\
        else\
            info.model, info.brand, info.os, info.ctei = \"\", \"\", \"\", 0\
            if not info.workmode then    -- 定制路由器不使用平台识别\
                info.dev_type = \"\"\
                info.dev_subtype = \"\"\
            end\
        end\
        info.osid = 0\
        if osinfo then\
            info.osid = osinfo.decide_osid or osinfo.cloud_osid or 0\
        end\
        if conndtype[info.dev_type] then\
            info.osid = nil\
        end\
        info.source = \"\"\
        if osinfo and osinfo.iscloud then\
            info.source = osinfo.source or \"\"\
            info.support_acctype = osinfo.support_acctype\
        end\
        -- change hostname:unknown,empty,anonymous,N/A,unknow\
        if info.hostname then\
            local hname = string.lower(info.hostname)\
            if bad_hostname[hname] and info.model then\
                info.hostname = info.model\
            end\
        end\
    end\
    log_add(log, \"fill_connd_oss\", topo_info)\
\
    -- del invalid mac\
    topo_info[sn], topo_info[\"\"] = nil, nil\
\
    -- 生成在线节点与网关端口的映射表\
    for mac, info in pairs(topo_info) do\
        if info.active == 1 then\
            if (not info.ntype or info.ntype == \"root\") and tonumber(info.acc_port) then\
                local gw_port = info.acc_port\
                if not port_info[gw_port] then\
                    port_info[gw_port] = {}\
                end\
                if not info.hide then\
                    table.insert(port_info[gw_port], mac)\
                end\
            end\
            online_lanhost[mac] = info\
        else\
            offline_lanhost[mac] = info\
        end\
    end\
    log_add(log, \"gen_port_info\", port_info)\
\
    -- deal mesh\
    -- 选取主节点\
    for port, macs in pairs(port_info) do\
        -- sort the mac from small to large\
        table.sort(macs, comp_mac)\
        -- 同一端口相似mac分组\
        local cat_macs = {}\
        for _, mac in ipairs(macs) do\
            if not cat_macs[mac:sub(1, 10)] then\
                cat_macs[mac:sub(1, 10)] = {}\
            end\
            table.insert(cat_macs[mac:sub(1, 10)], mac)\
        end\
        -- 遍历同一端口下的每一组\
        for _, smacs in pairs(cat_macs) do\
            if #smacs > 1 then\
                local mesh_pmac = nil\
                for _, mac in pairs(smacs) do\
                    if topo_info[mac].ntype == \"branch\" or topo_info[mac].ntype == \"root\" then\
                        mesh_pmac = mac\
                    end\
                end\
                for _, mac in pairs(smacs) do\
                    if mesh_pmac and topo_info[mac].ntype == \"term\" then\
                        local mac_with_colon = mac:gsub(\"%x%x\", function (w) return w..\":\" end, 5)\
                        local mesh_desc = {dev_type = online_lanhost[mesh_pmac].dev_type, brand = online_lanhost[mesh_pmac].brand, model = online_lanhost[mesh_pmac].model, os = online_lanhost[mesh_pmac].os, devtypeint = 5, elinktype = conndtype[online_lanhost[mesh_pmac].dev_type] or 1}\
                        lcmd_run{subtype = \"osinfo\", action = \"save_dev_desc\", mac = mac_with_colon, desc = mesh_desc, need_save = true}\
                        online_lanhost[mac].dev_type, online_lanhost[mac].brand, online_lanhost[mac].model, online_lanhost[mac].os = online_lanhost[mesh_pmac].dev_type, online_lanhost[mesh_pmac].brand, online_lanhost[mesh_pmac].model, online_lanhost[mesh_pmac].os\
                    end\
                end\
            end\
        end\
        -- 选取主节点\
        local primary_mac = nil\
        local elink, fttr, route, other = {}, {}, {}, {}\
        for _, mac in pairs(macs) do\
            local one = online_lanhost[mac] or {}\
            if one.par_mac == sn then\
                if one.dev_type == \"elink\" then\
                    table.insert(elink, mac)\
                elseif one.dev_type == \"FTTRsub\" then\
                    table.insert(fttr, mac)\
                elseif one.dev_type == \"route\" then\
                    table.insert(route, mac)\
                elseif one.acc_type == 0 or one.acc_type == 2 then\
                    table.insert(other, mac)\
                end\
            end\
        end\
        primary_mac = fttr[1] or route[1] or elink[1]\
        if #route == 0 and #fttr + #elink > 1 then\
            primary_mac = \"SW\"\
        end\
        if primary_mac == \"SW\" then\
            primary_mac = primary_mac..tostring(suffix_sw)\
            suffix_sw = suffix_sw + 1\
            online_lanhost[primary_mac] = {par_mac = sn, mac = primary_mac, acc_type = 0, acc_port = port, active = 1, dev_type = \"SW\", level = 3}\
        end\
\
        if not primary_mac then\
            local mac = other[1]\
            if #other > 1 then\
                primary_mac = \"AP\"\
            elseif mac and online_lanhost[mac] and online_lanhost[mac].dev_type then\
                local dev_type = online_lanhost[mac].dev_type\
                local acc_type = online_lanhost[mac].acc_type\
                local support_acctype = online_lanhost[mac].support_acctype\
                if typewifi[dev_type] then\
                    primary_mac = \"AP\"\
                    if dev_type == \"SMTDEV\" and support_acctype and (support_acctype == 2 or (support_acctype == 3 and acc_type == 0)) then   -- 平台有识别且识别为仅支持有线或都支持且当前连接方式为有线\
                        primary_mac = nil\
                        online_lanhost[mac].wired_isolated_node = true\
                    end\
                end\
            end\
        end\
        if primary_mac == \"AP\" then\
            primary_mac = primary_mac..tostring(suffix_ap)\
            suffix_ap = suffix_ap + 1\
            online_lanhost[primary_mac] = {par_mac = sn, mac = primary_mac, acc_type = 0, acc_port = port, active = 1, dev_type = \"AP\", level = 3}\
        end\
        for _, mac in pairs(macs) do\
            if primary_mac and mac ~= primary_mac and online_lanhost[mac].par_mac == sn then\
                online_lanhost[mac].par_mac = primary_mac\
                if string.match(primary_mac, \"AP\") then\
                    online_lanhost[mac].acc_speed = -1\
                end\
                online_lanhost[mac].acc_port = \"\"\
                if connd_host[mac] and connd_host[mac].acc_type and connd_host[mac].acc_type ~= -1 then\
                    online_lanhost[mac].acc_type = connd_host[mac].acc_type     -- 修复选取主节点后连接方式显示异常的问题\
                end\
            elseif mac == primary_mac and online_lanhost[primary_mac].dev_type == \"route\" and #macs > 1 then\
                online_lanhost[primary_mac].workmode = \"bridge\"\
            end\
        end\
    end\
    for mac, info in pairs(online_lanhost) do\
        local dev_type = info.dev_type\
        local support_acctype = info.support_acctype\
        if dev_type and typewifi[dev_type] then\
            info.acc_type = 1\
            if dev_type == \"SMTDEV\" and support_acctype and (support_acctype == 2 or info.wired_isolated_node) then   -- 平台有识别且识别为仅支持有线；平台有识别且识别为都支持且当前连接方式为有线，同时该节点所在的网关port下只有此一个设备\
                info.acc_type = 0\
            end\
        end\
    end\
    log_add(log, \"gen_online_lanhost\", online_lanhost)\
\
    return online_lanhost, offline_lanhost\
end\
\
function topo.show_topo_info(t, online_lanhost, offline_lanhost, odm)\
    local max_count, route_suffix, lasttime, hang_count, topo_info, pmac = 64, 1, 0, 0, {}, nil\
    if type(t.date) == \"number\" and t.date > 0 then\
        lasttime = myutil.os_time() - t.date * 3600 * 24\
    end\
    --add online host\
    for k,v in pairs(online_lanhost) do\
        if not v.hide or (t.show_hide and v.hide) then\
            table.insert(topo_info,v)\
        end\
    end\
    --add route host\
    local _, rtdev = lcmd_run({subtype = \"osinfo\", action = \"get_rtdev\"})\
    if type(rtdev) ~= \"table\" then rtdev = {} end\
    for k,v in pairs(rtdev) do\
        if pmac ~= v.par_mac then\
            pmac = v.par_mac\
            hang_count = 0\
        end\
        local par_host = online_lanhost[v.par_mac]\
        if par_host and hang_count < topo.hang_max then\
            v.level = 0\
            v.acc_type = 1\
            if not v.mac then\
                v.mac = \"ROUTE\"..tostring(route_suffix)\
                route_suffix = route_suffix + 1\
                table.insert(topo_info,v)\
                hang_count = hang_count + 1\
            elseif v.mac and not online_lanhost[v.mac] then\
                local one =  host_add_one({mac = v.mac, connectiontype = 1, model = v.model, brand = v.brand, os = v.os, devtype = v.dev_type}, v.par_mac, odm)\
                one.level = 0\
                one.dev_subtype = v.dev_subtype\
                table.insert(topo_info,one)\
                hang_count = hang_count + 1\
            end\
            offline_lanhost[v.mac] = nil\
        end\
    end\
    --add offline host\
    if t.active ~= 1 then\
        for k,v in pairs(offline_lanhost) do\
            v.level = -1\
            if myip.time_strtotime(v.last_active_time) >= lasttime then\
                if not v.hide or (t.show_hide and v.hide) then    -- DBus方式调用时不再上报离线的hide数据,与在线数据做相同处理\
                    table.insert(topo_info,v)\
                end\
            end\
        end\
    end\
    if #topo_info > max_count then\
        table.sort(topo_info,comp_level)\
        for k,v in pairs(topo_info) do\
            if k > max_count then\
                topo_info[k] = nil\
            end\
        end\
    end\
    for k,v in pairs(topo_info) do\
        if v.hide == true then\
            v.active = -2\
        end\
        v.dev_subtype = v.dev_subtype or \"\"\
        v.ctei = v.ctei or 0\
        v.level, v.hide, v.lan_mac, v.ntype, v.parent, v.root, v.support_acctype, v.wired_isolated_node = nil, nil, nil, nil, nil, nil, nil, nil\
        if v.dev_type == \"route\" then\
            v.workmode = nil\
        end\
        if not t.show_hide then\
            v.source, v.osid = nil, nil\
        end\
    end\
    return topo_info\
end\
\
local function get_speed(speedtype, all, last, time)\
    local allspeed, lastspeed = all[speedtype], last[speedtype]\
    if type(allspeed) == \"table\" and type(lastspeed) == \"table\" then\
        for k,v in pairs(allspeed) do\
            local last = lastspeed[k]\
            local tx, rx = 0, 0\
            if type(v) == \"table\" and type(last) == \"table\" then\
                tx = v.tx_bytes - last.tx_bytes or v.tx_bytes\
                rx = v.rx_bytes - last.rx_bytes or v.rx_bytes\
            end\
            if tx > 0 then\
                v.up_speed = tx//(1024 * time)\
            end\
            if rx > 0 then\
                v.down_speed = rx//(1024 * time)\
            end\
        end\
    end\
end\
\
local function deal_speed(time, last_speed, wlan, speedinfo, accspeed)\
    local list = {}\
    local all_speed = {time = time, wan = {}, lan = {}, wifi = {}}\
    local all_type = {\"wan\", \"lan\", \"wifi\"}\
    local deal_time\
\
    if wlan and not wlan.osgi then\
        for k, v in pairs(wlan) do\
            local x = v.ssid or \"\"\
            all_speed.wifi[x] = {type = \"wifi\", subtype = v.ssid or \"\", up_speed = 0, down_speed = 0, tx_bytes = v.tx or 0, rx_bytes = v.rx or 0, acc_speed = 0}\
        end\
    end\
\
    if speedinfo and accspeed then\
        for i=1,4 do\
            local x = tostring(i)\
            all_speed.lan[x] = {type = \"lan\", subtype = x, up_speed = 0, down_speed = 0, tx_bytes = speedinfo[x..\"_tx\"] or 0, rx_bytes = speedinfo[x..\"_rx\"] or 0, acc_speed = accspeed[x..\"_speed\"] or 0}\
        end\
        all_speed.wan[1] = {type = \"wan\", subtype = \"1\", up_speed = 0, down_speed = 0, tx_bytes = speedinfo[\"wan_tx\"] or 0, rx_bytes = speedinfo[\"wan_rx\"] or 0, acc_speed = 0}\
    end\
\
    if last_speed.time and all_speed.time - last_speed.time < 180 and all_speed.time - last_speed.time > 0 then\
        deal_time = all_speed.time - last_speed.time\
        for _,v in pairs(all_type) do\
            get_speed(v, all_speed, last_speed, deal_time)\
        end\
    end\
\
    for k,v in pairs(all_speed) do\
        if type(v) == \"table\" then\
            for m,n in pairs(v) do\
                table.insert(list, n)         \
            end\
        end\
    end\
    topo.last_speed = all_speed\
    topo.last_speed.time = time\
\
    return list\
\
end\
\
local function show_speed(t)\
    -- postmsg input '{\"subtype\":\"ct\",\"stype\":\"postmsg\",\"action\":\"show_topo/show_speed\"}'\
    -- client and send_topo are not controlled\
    if not topo.postmsg_enable and t.stype then\
        return\
    end\
\
    --hot_topo\
    local ok, speeds = lcmd_run({subtype = \"hot_topo\", action = \"show_speed\"})\
    if ok and type(speeds) == \"table\" then\
        return speeds\
    end\
\
    local time = myutil.os_time()\
    local r = {list={}}\
    local wlan, speedinfo, accspeed\
    wlan = call_api(\"wlan\")\
    speedinfo = call_api(\"speed\")\
    accspeed = call_api(\"accspeed\")\
\
    local s = deal_speed(time, topo.last_speed or {}, wlan, speedinfo, accspeed)\
    if #s == 0 then\
        table.insert(r.list, {})\
    else\
        r.list = s\
    end\
\
    return r\
end\
\
local function show_topo(t)\
    if not topo.postmsg_enable and t.stype then\
        return\
    end\
    if t.cache then\
        local gw_info = str_to_table(topo.cache.gw_info)\
        local topo_info = (t.active ~= 1) and str_to_table(topo.cache.topo_info) or str_to_table(topo.cache.topo_active_info)\
        if not next(gw_info) and not next(topo_info) then\
            return \"There is currently no TOPO cache.\"\
        end\
        return {Result = 0, gw_info = gw_info, topo_info = topo_info, timestamp = topo.cache.time}\
    end\
    local btime, log, test = os.time(), {}, {}\
    local stype = t.stype or \"dpi\"\
    local odm = call_api(\"odm\")\
\
    if t.sendsig then\
        lcmd_run({subtype = \"sigcollect\", action = \"send\"})\
    end\
    if type(t.lanhost) == \"table\" and type(t.elinklanhost) == \"table\" then\
        test = {sn = t.sn, lanhost = t.lanhost, elink = t.elinklanhost, brmacs = t.brmacs, osinfo = t.osinfo, getssid = t.getssid}\
        log_add(log, \"lanhost\", test.lanhost)\
        log_add(log, \"elink\", test.elink)\
    end\
\
    local ok, arch = lcmd_run({subtype = \"arch\", action = \"read\"})\
    if not ok or type(arch) ~= \"table\" then\
        arch = {sn = \"\", dev_type = \"\"}\
    end\
    local ok_, oss = lcmd_run({subtype = \"osinfo\", action = \"get_oss\"})\
    if not ok_ or type(oss) ~= \"table\" then oss = {} end\
    oss = test.osinfo or oss\
    log_add(log, \"get_oss\", oss)\
    local ok__, conndtype = lcmd_run({subtype = \"osinfo\", action = \"get_conndtype\"})\
    if not ok__ or type(conndtype) ~= \"table\" then conndtype = {elink = 1, FTTRsub = 2} end\
    conndtype = test.conndtype or conndtype\
    log_add(log, \"get_conndtype\", conndtype)\
\
    local gw_info = get_gw_info(log)\
    topo.cache.gw_info = cjson.encode(gw_info)\
    if t.show_devtype then gw_info.Devname = arch.dev_type end  -- 应吴芳要求，定期上报时 Devname 字段含义修改为“网关类型”\
    local sn = test.sn or gw_info.mac or arch.sn\
    local lanhost = get_lanhost_info(sn, test, log, topo.brmacs_enable, topo.agetime, oss)\
    local connd_info = get_connd_info(sn, test, log, lanhost, conndtype)\
    log_add(log, \"get_connd_info\", connd_info)\
    local online_lanhost, offline_lanhost = topo.gen_topo_info(sn ,test, log, lanhost, connd_info, oss, conndtype)\
    topo.cache.topo_info = cjson.encode(topo.show_topo_info({}, str_to_table(cjson.encode(online_lanhost)), str_to_table(cjson.encode(offline_lanhost)), odm))\
    topo.cache.topo_active_info = cjson.encode(topo.show_topo_info({active = 1}, str_to_table(cjson.encode(online_lanhost)), {}, odm))\
    local topo_info = topo.show_topo_info(t, online_lanhost, offline_lanhost, odm)\
    topo.count = topo.count + 1\
    topo.cache.time = tostring(myutil.os_time())\
    local etime = os.time()\
    local result = {Result = 0, gw_info = gw_info, topo_info = topo_info}\
    log_set(topo.log, topo.max_debug, {cmd = \"show_topo\", call = log, send = true, type = stype, res = cjson.encode(result), btime = btime, etime = etime})\
\
    -- record call topo stype\
    topo.call_record[stype] = (topo.call_record[stype] or 0) + 1\
    return result\
end\
\
local function gen_tree(mac, array)\
\9local tree = {}\
\9tree.mac = mac\
\9tree.nodes = {}\
\
\9for k,v in pairs(array) do \
\9\9if v.mac == mac then\
\9\9\9tree.val = v\
\9\9\9array[k] = nil\
\9\9end\
\
\9\9if v.par_mac == mac then\
\9\9\9tree.nodes[v.mac] = gen_tree(v.mac,array)\
\9\9end\
\9end\
\
\9return tree\
end\
\
local function dump_tree(tree,level)\
\9local str = \"\"\
\9local sub = \"\"\
\9if tree.val then\
\9\9local one = tree.val\
\9\9str = string.format(\"|%smac(%s) ip(%s) active(%d) acc_type(%d) model(%s) brand(%s) dev_type(%s) dev_subtype(%s) os(%s) hostname(%s)\",\
\9\9\9\9\9\9\9string.rep(\"-\", level*8),tree.mac, one.ip or \"\", one.active or -1, one.acc_type or -1,one.model or \"\", one.brand or \"\", one.dev_type or \"\", one.dev_subtype or \"\", one.os or \"\", one.hostname or \"\") .. \" acc_port \"..tostring(one.acc_port or -1) .. \"\\n\"\
\9else\
\9\9str = string.format(\"|%s%s GW\\n\",string.rep(\"-\", level*8),tree.mac)\
\9end\
\
\9for k,v in pairs(tree.nodes) do \
\9\9sub = dump_tree(v, level+1)\
\9\9str = str..sub\
\9end\
\
\9return str\
end\
\
local function show_topo_tree(t)\
\9local tinfo = show_topo(t)\
\9local tree = gen_tree(t.sn or tinfo.gw_info.mac,tinfo.topo_info)\
\9return dump_tree(tree, 1)\
end\
\
local function test_tree(t)\
local list = {}\
table.insert(list, {par_mac=\"1\", mac = \"11\"})\
table.insert(list, {par_mac=\"1\", mac = \"12\"})\
table.insert(list, {par_mac=\"1\", mac = \"13\"})\
table.insert(list, {par_mac=\"11\", mac = \"111\"})\
table.insert(list, {par_mac=\"12\", mac = \"121\"})\
table.insert(list, {par_mac=\"12\", mac = \"122\"})\
table.insert(list, {par_mac=\"12\", mac = \"123\"})\
table.insert(list, {par_mac=\"12\", mac = \"124\"})\
table.insert(list, {par_mac=\"13\", mac = \"131\"})\
table.insert(list, {par_mac=\"13\", mac = \"132\"})\
table.insert(list, {par_mac=\"13\", mac = \"133\"})\
table.insert(list, {par_mac=\"133\", mac = \"1331\"})\
table.insert(list, {par_mac=\"1331\", mac = \"13311\"})\
table.insert(list, {par_mac=\"13311\", mac = \"133111\"})\
local tree = gen_tree(\"1\",list)\
return dump_tree(tree, 1)\
end\
\
local function show_debug(t)\
    local log = {}\
    if not t.send then\
        return topo.log\
    elseif topo.debug_enable == 0 then\
        return log\
    end\
    for k,v in pairs(topo.log) do\
        if v.send then\
            table.insert(log, v)\
            v.send = false\
        end\
    end\
    return log\
end\
\
local function send_topo_info()\
    local topo_info = show_topo({show_hide = 1, show_devtype = 1})\
    local data_uploaded = { type = \"topo_upload\", data = {topo_info}, period = topo.send_period, timestamp = tostring(myutil.os_time())}\
    lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = data_uploaded})\
    topo.send_count = topo.send_count + 1\
end\
\
local function send_topo_active_info()\
    local info = show_topo({ active = 1, show_hide = 1, show_devtype = 1})\
    if #info.topo_info > 0 then\
        local data_uploaded = { type = \"topo_upload\", data = {info}, period = topo.send_active_period, timestamp = tostring(myutil.os_time())}\
        lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = data_uploaded})\
        topo.send_active_count = topo.send_active_count + 1\
    end\
end\
\
local function write(msg)\
    if msg.send_period and msg.send_period ~= topo.send_period then\
        mylog.info(\"send_topo send_period change to \", msg.send_period, \"from \", topo.send_period)\
        topo.send_period = tonumber(msg.send_period)\
        timer.mod(\"send_topo\", topo.send_period, 0, send_topo_info)\
    end\
    if msg.send_active_period and msg.send_active_period ~= topo.send_active_period then\
        mylog.info(\"send_topo_active send_active_period change to \", msg.send_active_period, \"from \", topo.send_active_period)\
        topo.send_active_period = tonumber(msg.send_active_period)\
        timer.mod(\"send_topo_active\", topo.send_active_period, 0, send_topo_active_info)\
    end\
    if type(msg.postmsg_enable) == \"boolean\" then\
        topo.postmsg_enable = msg.postmsg_enable\
    end\
    if type(msg.hang_max) == \"number\" and msg.hang_max ~= topo.hang_max then\
        topo.hang_max = msg.hang_max\
    end\
    if type(msg.brmacs_enable) == \"boolean\" then\
        topo.brmacs_enable = msg.brmacs_enable\
    end\
    if type(msg.agetime) == \"number\" then\
        topo.agetime = msg.agetime\
    end\
    if type(msg.cache_refresh_period) == \"number\" and msg.cache_refresh_period ~= topo.cache_refresh_period then\
        topo.cache_refresh_period = msg.cache_refresh_period\
        timer.mod(\"refresh_topo_cache\", topo.cache_refresh_period, 0, show_topo, {})   -- refresh topo cache\
    end\
end\
\
local function debug(t)\
    local count\
    if t.enable then\
        topo.debug_enable = tonumber(t.enable)\
    end\
    if t.max_cnt then\
        count = tonumber(t.max_cnt) or 0\
        topo.max_debug = count\
    end\
\
    if count then\
        log_set(topo.log, count)\
    end\
end\
\
function topo.postinit()\
    timer.mod(\"send_topo\", topo.send_period, 0, send_topo_info)\
    timer.mod(\"send_topo_active\", topo.send_active_period, 0, send_topo_active_info)\
    timer.mod(\"init_topo_cache\", 120, 1, show_topo, {})   -- init topo cache\
    timer.mod(\"refresh_topo_cache\", topo.cache_refresh_period, 0, show_topo, {})   -- refresh topo cache\
end\
\
local function gen_topo_test(t)\
    local lanhost, osinfo, brmacs = t.lanhost or {}, t.osinfo or {}, t.brmacs or {}\
    local elinklanhost = {elinkinfo = cjson.encode(t.elinklanhost or {})}\
    local getssid = nil\
    if type(t.addr) == \"string\" and type(t.sn) == \"string\" then\
        osinfo = str_to_table(myutil.svrclient({addr = t.addr, sn = t.sn, cmd = {subtype = \"osinfo\", action = \"get_oss\"}, max_time = t.max_time}) or \"{}\")\
        if osinfo.error == -1 then\
            return osinfo\
        end\
        brmacs = str_to_table(myutil.svrclient({addr = t.addr, sn = t.sn, cmd = {subtype = \"sigcollect\", action = \"brctl_showmacs\"}, max_time = t.max_time}) or \"{}\")\
        lanhost = str_to_table(myutil.svrclient({addr = t.addr, sn = t.sn, cmd = {subtype = \"ct\", action = \"call_api\", func = \"lanhost\"}, max_time = t.max_time}) or \"{}\")\
        elinklanhost = str_to_table(myutil.svrclient({addr = t.addr, sn = t.sn, cmd = {subtype = \"ct\", action = \"call_api\", func = \"elink\"}, max_time = t.max_time}) or \"{}\")\
        getssid = function (port)\
            return str_to_table(myutil.svrclient({addr = t.addr, sn = t.sn, cmd = {subtype = \"ct\", action = \"call_api\", func = \"getssid\", port = port}, max_time = t.max_time}) or \"{}\")\
        end\
    end\
\
    local argv, info = {sn = t.sn, lanhost = lanhost, elinklanhost = elinklanhost, osinfo = osinfo, show_hide = t.show_hide, brmacs = brmacs, active = t.active, getssid = getssid}, nil\
    if t.show_topo then\
        info = show_topo(argv)\
    else\
        info = show_topo_tree(argv)\
    end\
    return info\
end\
\
function topo.check_topo_logic(t)\
    if not t.addr or not t.sn then\
        return \"missing addr or sn parameters.\"\
    end\
\
    local svr_topo = str_to_table(myutil.svrclient({addr = t.addr, sn = t.sn, cmd = {subtype = \"topo\", action = \"show_topo\", active = 1}, max_time = t.max_time}) or \"{}\")\
    if type(svr_topo) ~= \"table\" or type(svr_topo.topo_info) ~= \"table\" then\
        return \"get topo failed from svrclient.\"\
    end\
\
    local loc_topo = gen_topo_test({addr = t.addr, sn = t.sn, show_topo = 1, active = 1, max_time = t.max_time})\
    if type(loc_topo) ~= \"table\" or type(loc_topo.topo_info) ~= \"table\" then\
        return \"generate topo failed from local.\"\
    end\
\
    local cnode = {}\
    for _, one in ipairs(loc_topo.topo_info) do\
        local status = \"false, loc_mac\"\
        for _, info in ipairs(svr_topo.topo_info) do\
            if info.mac == one.mac then\
                status = \"false, diff parent\"\
                if info.par_mac == one.par_mac then\
                    status = \"true, same parent\"\
                end\
                break\
            end\
        end\
        cnode[one.mac] = status\
    end\
\
    for _, info in ipairs(svr_topo.topo_info) do\
        if cnode[info.mac] == nil then\
            cnode[info.mac] = \"false, svr_mac\"\
        end\
    end\
\
    for _, status in pairs(cnode) do\
        if status ~= \"true, same parent\" then\
            return {result = \"check failed!\", cnode = cnode}\
        end\
    end\
    return \"check passed!\"\
end\
\
local function read()\
    return {send_period = topo.send_period, send_active_period = topo.send_active_period, count = topo.count, send_count = topo.send_count, send_active_count = topo.send_active_count, enable=topo.debug_enable, postmsg_enable = topo.postmsg_enable, max_cnt=topo.max_debug, hang_max = topo.hang_max, brmacs_enable = topo.brmacs_enable, agetime = topo.agetime, cache_refresh_period = topo.cache_refresh_period}\
end\
\
actor.action_set(topo.subtype, \"show_topo\", show_topo, [[get topo info from CAPI and DBUS, {active = number,date = number}, active 1 means online, data filter last_active_time]]) \
actor.action_set(topo.subtype, \"show_topo_tree\", show_topo_tree, [[show topo info as tree struct args is same as show_topo  {active = number,date = number}, active 1 means online, data filter last_active_time]]) \
actor.action_set(topo.subtype, \"test_tree\", test_tree, [[test topo tree]])\
\
actor.action_set(topo.subtype, \"show_speed\", show_speed, [[get speed info from CAPI,lua will calculate]])\
actor.action_set(topo.subtype, \"show_debug\", show_debug, [[show log]])\
actor.action_set(topo.subtype, \"show_cache\", function () return topo.cache end, [[show topo cache]])\
actor.action_set(topo.subtype, \"write\", write, [[change get route period,{send_period = number, send_active_period = number, cache_refresh_period = number},default 86400 86400 1800]])\
actor.action_set(topo.subtype, \"read\", read, \"read topo stat\")\
actor.action_set(topo.subtype, \"topo_testset\", gen_topo_test, [[ct topo test, {lanhost={mac={}},elinklanhost={{},{}},osinfo={},addr=string(ip:port),sn=string,max_time=number,show_topo=boolean,active=number,show_hide=boolean,brmacs={mac={}}}]])\
actor.action_set(topo.subtype, \"check_topo_logic\", topo.check_topo_logic, \"check topo logic, {addr=string(ip:port),sn=string,max_time=number}\")\
actor.action_set(topo.subtype, \"debug\", debug, [[set topo debug, {enable=1/0, max_cnt=number}]])\
actor.action_set(topo.subtype, \"show_record\", function () return topo.call_record end, [[show call topo record]])\
return topo\
"
, '@'.."./service/topo.lua" ) )

package.preload[ "tuple" ] = assert( (loadstring or load)(
"local cjson = require(\"cjson\")\
local kernel = require(\"c.kernel\")\
local actor = require(\"luactor\")\
local myip = require(\"myip\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local mystring = require(\"mystring\")\
local policy_com = require(\"ct.policy\")\
\
local tuple = {\
    all_count = 0,\
    all_len = 0,\
    subtype = \"tuple\",\
    upload_type = \"tuple_info_v1\",\
    period = 5,\
    upload_mode = \"none\", -- \"none\", \"svrdata\", \"operdata\", \"all\"\
    timer_name = 'tuple_get', \
    help = \"get tuple from kernel, send to server\"\
}\
\
local function tuple_get_one(sbytes, pos, len)\
    local format='=IIIIIc16c16IIHHBBHc6HIIBBBBIIIIIIIIIIIIIIIIIIIHBBI'\
    local tuple_info = {}\
\
    tuple_info.all_len,\
    tuple_info.pkts_in,\
    tuple_info.pkts_out,\
    tuple_info.bytes_in,\
    tuple_info.bytes_out,\
    tuple_info.sip,\
    tuple_info.dip,\
    tuple_info.appid,\
    tuple_info.ruleid,\
    tuple_info.sport,\
    tuple_info.dport,\
    tuple_info.proto,\
    tuple_info.svr_local,\
    tuple_info.L7_total,\
    tuple_info.mac,\
    tuple_info.action,\
    tuple_info.start_time,\
    tuple_info.end_time,\
    tuple_info.state,\
    tuple_info.latency_valid,\
    _ , tuple_info.latency_cnt,\
    tuple_info.lat1,\
    tuple_info.lat2,\
    tuple_info.lat3,\
    tuple_info.lat4,\
    tuple_info.lat5,\
    tuple_info.lat6,\
    tuple_info.lat7,\
    tuple_info.lat8,\
    tuple_info.lat9,\
    tuple_info.lat10,\
    tuple_info.lat11,\
    tuple_info.lat12,\
    tuple_info.lat13,\
    tuple_info.lat14,\
    tuple_info.lat15,\
    _ , _ , _ , _,\
    tuple_info.retransmit_cnt,\
    _ , _ , tuple_info.base_appid = string.unpack(format, sbytes, pos)\
\
    tuple_info['type'] = tuple.upload_type\
    tuple_info['is_app'] = 0\
    tuple_info['app_id'] = tuple_info.appid\
    tuple_info['sip'] = myip.inet_ntoa(tuple_info['sip'])\
    tuple_info['dip'] = myip.inet_ntoa(tuple_info['dip'])\
    tuple_info['mac'] = mystring.data2hex(tuple_info['mac'], \":\")\
    tuple_info['action'] = policy_com.get_actint(tuple_info['action']) or \"\"\
\
    if tuple_info.proto == 6 then\
        if tuple_info.latency_valid > 0 then\
            if tuple_info.state == CENUM.CTX_STAT_STATE_TCP_FIN then\
                tuple_info.lat_status = \"fin\"\
            elseif tuple_info.state == CENUM.CTX_STAT_STATE_TCP_RST then\
                tuple_info.lat_status = \"rst\"\
            elseif tuple_info.latency_cnt >= 2 then\
                tuple_info.lat_status = \"ok\"\
            else\
                tuple_info.lat_status = \"fail\"\
            end\
        else\
            tuple_info.lat_status = \"abnormal\"\
        end\
    elseif tuple_info.proto == 17 then\
        if tuple_info.latency_valid > 0 then\
            if tuple_info.latency_cnt >= 1 then\
                tuple_info.lat_status = \"ok\"\
            else\
                tuple_info.lat_status = \"fail\"\
            end\
        else\
            tuple_info.lat_status = \"abnormal\"\
        end\
    else\
        tuple_info.lat_status = \"none\"\
    end\
    local all_len = tuple_info.all_len\
    tuple_info.all_len = nil\
    tuple_info.latency_valid = nil\
    tuple_info.state = nil\
\
    --log.info(\"get one tuple, \", cjson.encode(tuple_info))\
    actor.publish({msgtype = \"TUPLE\", tuple_info = tuple_info})\
    tuple_info.latency_cnt = nil\
    tuple_info.retransmit_cnt = nil\
    tuple_info.L7_total = nil\
    tuple_info.lat5, tuple_info.lat6, tuple_info.lat7, tuple_info.lat8, tuple_info.lat9, tuple_info.lat10, tuple_info.lat11, tuple_info.lat12, tuple_info.lat13, tuple_info.lat14, tuple_info.lat15 = nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil\
\
    if tuple.upload_mode ~= \"none\" then\
        if tuple.upload_mode == \"operdata\" or tuple.upload_mode == \"all\" then\
            lcmd_run({subtype = \"__oper_data\", action = \"add\", data = tuple_info})\
        end\
        if tuple.upload_mode == \"svrdata\" or tuple.upload_mode == \"all\" then\
            lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = tuple_info})\
        end\
        tuple.all_len = tuple.all_len + string.len(cjson.encode(tuple_info))\
        tuple.all_count = tuple.all_count + 1\
    end\
\
    return all_len\
end\
\
local function tuple_get(sbytes)\
    local len, used_len = sbytes:len(), 0\
\
    while used_len < len do\
        local one_size = tuple_get_one(sbytes, used_len + 1, len)\
        if one_size <= 0 then\
            return -1\
        end\
        used_len = used_len + one_size\
    end\
\
    if used_len ~= len then\
        return -1;\
    end\
\
    return len\
end\
\
local function tuple_engine_opt(is_enable)\
    local sbytes = \"\"\
    local enable = 0\
\9if is_enable ~= 0 then\
        enable = 1\
\9end\
\9sbytes = string.pack(\"=i\", enable)\
\9kernel.send(CENUM.MEMSHR_U2K_TUPLE_ENABLE, sbytes)\
end\
\
local function write(msg)\
    log.info(\"tuple period change to \", msg.period, \"from \", tuple.period)\
    if type(msg.period) == \"number\" and msg.period ~= tuple.period then\
        tuple.period = msg.period\
        timer.mod(tuple.timer_name, tuple.period, 0, function () kernel.call(CENUM.MEMSHR_K2U_TUPLE, \"\", tuple_get) end)\
        if tuple.period > 0 then\
\9\9\9tuple_engine_opt(1)\
        else\
\9\9\9tuple_engine_opt(0)\
        end\
    end\
    if type(msg.upload_mode) == \"string\" and msg.upload_mode ~= tuple.upload_mode then\
        if msg.upload_mode == \"none\" or msg.upload_mode == \"svrdata\" or msg.upload_mode == \"operdata\" or msg.upload_mode == \"all\" then\
            tuple.upload_mode = msg.upload_mode\
        end\
    end\
end\
\
function tuple.preinit()\
    -- if kernel module not reload, it must set default and clean first\
    tuple_engine_opt(0)\
    kernel.send(CENUM.MEMSHR_U2K_SESS_FLUSH, \"\")\
end\
\
function tuple.postinit()\
    if tuple.period > 0 then\
        tuple_engine_opt(1)\
        timer.mod(tuple.timer_name, tuple.period, 0, function () kernel.call(CENUM.MEMSHR_K2U_TUPLE, \"\", tuple_get) end)\
    end\
end\
\
actor.action_set(tuple.subtype, \"get_kernel\", function () kernel.call(CENUM.MEMSHR_K2U_TUPLE, \"\", tuple_get) end, \
                 \"get tuple from kernel manualy\")\
actor.action_set(tuple.subtype, \"read\", function () return {period = tuple.period, upload_mode = tuple.upload_mode} end, \"read period\")\
actor.action_set(tuple.subtype, \"stat\", function () return {all_count = tuple.all_count, all_len = tuple.all_len} end, \"read stat count and len\")\
actor.action_set(tuple.subtype, \"write\", write, [[set tuple period, {period = number}, 0 means close engine]])\
\
return tuple\
"
, '@'.."./service/tuple.lua" ) )

package.preload[ "upgrade" ] = assert( (loadstring or load)(
"local actor = require\"luactor\"\
local cthread = require\"c.thread\"\
local log = require\"log\"\
local myfile = require\"myfile\"\
\
local upgrade = {\
    type = \"upgrade\", \
    subtype = \"upgrade\", \
    help = \"upgrade for plugin/lua/sig\", \
    upgrading = false, \
    ufile = \"ttupgrade.tgz\", \
}\
\
-------------------------------------------------------------------\
-- New Thread to run this function, download file , write to tmppath,\
-- and trigger upgrade_post\
-------------------------------------------------------------------\
local function upgrade_http(t)\
    local http = require\"socket.http\"\
    log.warn(string.format(\"upgrade http, url(%s), module(%s)......\", t.url, t.module))\
    local body, code = http.request(t.url)\
    if code ~= 200 then\
        log.error(string.format(\"failed to load (%s), code (%d)\", t.url, code))\
        return\
    end\
\
    log.warn(string.format(\"upgrade http, url(%s), module(%s)......Done, size(%d)\", t.url, t.module, #body))\
    myfile.write(body, lcmd_tmp_path(upgrade.ufile))\
    local args = string.format([[{\"subtype\":\"upgrade\", \"action\":\"upgrade_post\", \"module\":\"%s\", \"version\":\"%s\"}]], t.module, t.version)\
    lcmd_client(true, lcmd_tmp_path(\"\"), args)\
end\
\
-------------------------------------------------------------------\
-- origin thread to run, exit code, see app_dpi_process.h\
-------------------------------------------------------------------\
-- enum {\
--     APP_RETCODE_NORMAL = 128,\
--     APP_RETCODE_ERROR = 129,\
--     APP_RETCODE_UPDATE = 130,\
--     APP_RETCODE_UPDATE_LUA = 131, \
--     APP_RETCODE_UPDATE_SIG = 132, \
\
--     APP_RETCODE_RESTORE = 160, \
-- };\
local function upgrade_post(t)\
    local ret_code = 0\
    log.warn(\"will upgrade post\", t.module)\
    if t.module ~= \"lua\" and t.module ~= \"sig\" and t.module ~= \"plugin\" then\
        log.error(\"wrong module, \", t.module)\
        return\
    end\
\
    if t.module == \"lua\" then\
        -- bootjs.luadata = 1\
        ret_code = 131\
    elseif t.module == \"sig\" then\
        -- bootjs.sigdata = 1\
        ret_code = 132\
    else\
        -- only write version here\
        local bootjs, err = myfile.load_json(lcmd_data_path(\".bootchk\"))\
        if not bootjs then\
            bootjs = {}\
            log.warn(\"first upgrade with empty bootjs\")\
        end\
        bootjs.version = t.version\
        myfile.store_json(bootjs, lcmd_data_path(\".bootchk\"))\
        ret_code = 130\
    end\
\
    -- will rename/unzip file in watch_daemon\
    -- os.remove(lcmd_tmp_path(upgrade.ufile))\
    log.warn(\"will restart program for upgrade \", t.module, t.version)\
    os.exit(ret_code)\
end\
\
local function do_upgrade(t)\
    if upgrade.upgrading then\
        log.error(\"Please wait upgrade done...\")\
        return\
    end\
\
    if type(t.url) ~= \"string\" or type(t.module) ~= \"string\" then\
        log.error(\"wrong upgrade parameter, module \", t.module)\
        return\
    end\
\
    local version = t.version or \"\"\
    local args = string.format([[{\"subtype\":\"upgrade\", \"action\":\"upgrade_http\", \"url\":\"%s\", \"module\":\"%s\", \"version\":\"%s\"}]], t.url, t.module, version)\
    cthread.run(args)\
end\
\
local function restore()\
    local bb = os.remove(lcmd_data_path(\".bootchk\"))\
    if bb then\
        os.exit(160)\
    end\
end\
\
actor.action_set(upgrade.subtype, \"read\", function () return {upgrading = upgrade.upgrading} end, \"read upgrading status\")\
actor.action_set(upgrade.subtype, \"restore\", restore, \"restore as origin plugin\")\
actor.action_set(upgrade.subtype, \"upgrade_post\", upgrade_post, \"upgrade, {module = xx}\")\
actor.action_set(upgrade.subtype, \"upgrade_http\", upgrade_http, \"upgrade, {url = xx, module = xx}\")\
actor.action_set(upgrade.subtype, \"upgrade\", do_upgrade, \"upgrade, {url = xx, module = [sig | lua | plugin]}, and version needed only for plugin\")\
\
return upgrade\
"
, '@'.."./service/upgrade.lua" ) )

package.preload[ "upnp" ] = assert( (loadstring or load)(
"local socket = require\"socket\"\
local http = require('httpclient').new()\
local myip = require(\"myip\")\
local timer = require(\"timer\")\
local actor = require(\"luactor\")\
local log = require(\"log\")\
local cjson = require(\"cjson\")\
\
local upnp = {\
    type = \"upnp\",\
    subtype = \"upnp\",\
    help = \"upnp find host\",\
    ip = \"\",\
    iface = \"br0\",\
}\
\
local function xml_parse(xml)\
  local idx_cur = 1\
  local root = {}\
  local node_cur = root\
  local nodes = {}\
\
  while true do\
    local idx_start, idx_end, end_tag, label, args, empty = string.find(xml, \"<(%/?)([%w:]+)(.-)(%/?)>\", idx_cur)\
\
    if not idx_start then break end\
\
    if end_tag == \"\" then -- start tag\
      node_cur[label] = {}\
      nodes[#nodes+1] = node_cur[label]\
      node_cur = nodes[#nodes]\
    else -- end tag\
      table.remove(nodes)\
      node_cur = nodes[#nodes]\
\
      local value = string.sub(xml, idx_cur, idx_start - 1)\
\
      if not string.find(value, \"^%s*$\") then\
\9  node_cur[label] = value\
      end\
    end\
    idx_cur = idx_end + 1\
  end\
\
  return root\
end\
\
local function get_upnp(t)\
    local udp=socket.udp4()\
    local timeout = 3\
    local ipaddr = upnp.ip\
    local info = {}\
\
    if not ipaddr or ipaddr == \"\" then\
        local ok\
        ok, ipaddr = myip.getip(upnp.iface)\
        if not ok then\
            return info\
        end\
        upnp.ip = ipaddr\
    end\
    udp:settimeout(0.1)\
    local pkt_ssdp_discover = table.concat({\
        'M-SEARCH * HTTP/1.1\\r\\n',\
        'HOST: 239.255.255.250:1900\\r\\n',\
        'MAN: \"ssdp:discover\"\\r\\n',\
        'MX: 3\\r\\n',\
        'ST: ssdp:all\\r\\n',\
        '\\r\\n'\
    })\
\
    assert(udp:setoption('reuseaddr', true))\
    assert(udp:setsockname(ipaddr, 1900))\
    assert(udp:sendto(pkt_ssdp_discover, \"239.255.255.250\", 1900))\
    local start = os.time()\
    local anwser = {}\
    while (os.time() - start < timeout) do\
        local discover_response, ip, port = udp:receivefrom()\
        if discover_response and not anwser[ip] then\
            local location = string.match(discover_response,\"[lL][oO][cC][aA][tT][iI][oO][nN]:%s+(http://%S+)\")\
            anwser[ip] = location\
        end\
    end\
\
    for k,v in pairs(anwser) do\
        if v ~= \"\" then\
            local response = http:get(v)\
            if not response.err then\
                local deviceinfo = xml_parse(response.body) \
                if deviceinfo and deviceinfo.root and deviceinfo.root.device then\
                    local ss = deviceinfo.root.device.modelName\
                    info[k] = {ss}\
                end\
            end\
        end\
    end\
    assert(udp:close())\
    local tt = {}\
    local arp = myip.getarp()\
    for ip,dev_info in pairs(info) do\
        local mac = arp[ip]\
        if mac then\
            tt[mac] = dev_info\
        end\
    end\
    return tt\
end\
\
local function write(msg) --修改参数设置\
    if msg.iface then\
        upnp.iface = msg.iface\
        upnp.ip = \"\"\
    end\
end\
\
actor.action_set(upnp.subtype, \"read\", function () return {period = upnp.period, iface = upnp.iface} end, \"read period and stat\")\
actor.action_set(upnp.subtype, \"write\", write, [[set upnp iface, {iface = string}]])\
actor.action_set(upnp.subtype, \"get_upnp\", get_upnp, [[show upnp info]])\
\
return upnp\
"
, '@'.."./service/upnp.lua" ) )

