\
    for index, v in pairs(allwans) do\
        assert(v.userdata)\
        local wan = cct.showwan(v.userdata)\
        if wan then\
            if wan.rxbytes == nil or wan.txbytes == nil then\
                -- ignore, maybe api version doesn't support yet\
