    if #fdata <= 0 and #tdata <= 0 then\
        return\
    end\
\
    local info = {tagsig = tdata, flowsig = fdata}\
    lcmd_run({ subtype = \"locdata\", action = \"add\", data = {type = xapp.timer_name, xappdata = info} })\
    local pbtype = actor.pbtype_get(xapp.timer_name)\
    local pbdata = pb.encode(pbtype, info)\
    for _, addr in pairs(xapp.addr) do\
        dpi.pb_asyncall(addr, true, \"ACTION_SHORT_XAPP\", { pbdata }, nil, sig_deal)\
    end\
    local len = string.len(cjson.encode(info))\
    xapp.upload_all_len = xapp.upload_all_len + len\
    xapp.upload_all_count = xapp.upload_all_count + 1\
    xapp.tag_stat.tag_count, xapp.tag_merge_data = 0, {}\
    xapp.flow_stat.flow_count, xapp.flow_stat.with_paylaod_count, xapp.flow_merge_data = 0, 0, {}\
end\
\
local function match_one(t)\
    if not t.stype or not t[t.stype] then\
        return\
    end\
    local rename = {dns = \"domain\", host = \"domain\", sni = \"domain\", dnscheck = \"domain\"}\
    local ruleid, appid = nil, nil\
    local key = (t.dip or \"\") .. \"_\" .. (t.dport or 0)\
    if not t.appid or t.appid <= CENUM.MAX_BASE_APPID or xapp.always_match then\
        local stype = rename[t.stype] or t.stype\
        _, ruleid = lcmd_run({ subtype = \"appsig_bin\", action = \"match\", stype = stype, value = t[t.stype] })\
        if tonumber(ruleid) then\
            local _, appdesc = lcmd_run({ subtype = \"appsig_bin\", action = \"get_desc\", ruleid = ruleid })\
            appid = (type(appdesc) == \"table\") and appdesc.appid or 0\
            -- kernel read need timer to write\
            if t.stype == \"dns\" then\
                lcmd_run({ subtype = \"apprule\", action = \"add\", ruleid = ruleid, appid = appid, ip = t.dip, port = t.dport, maxttl = t.maxttl })\
            else\
                xapp.rules[key] = { subtype = \"apprule\", action = \"add\", ruleid = ruleid, appid = appid, ip = t.dip, port = t.dport, maxttl = t.maxttl }\
            end\
            xapp.pstat[t.stype .. \"_mcnt\"] = (xapp.pstat[t.stype .. \"_mcnt\"] or 0) + 1\
        else\
            ruleid, appid = nil, nil\
            if t.appid and t.appid > CENUM.MAX_BASE_APPID then\
                xapp.rules[key] = { subtype = \"apprule\", action = \"add\", ruleid = t.ruleid, appid = t.appid, ip = t.dip, port = t.dport, maxttl = t.maxttl }\
            end\
        end\
        xapp.pstat[t.stype .. \"_cnt\"] = (xapp.pstat[t.stype .. \"_cnt\"] or 0) + 1\
    else\
        xapp.rules[key] = { subtype = \"apprule\", action = \"add\", ruleid = t.ruleid, appid = t.appid, ip = t.dip, port = t.dport, maxttl = t.maxttl }\
    end\
    t.appid = appid or t.appid or 0\
    t.ruleid = ruleid or t.ruleid or 0\
end\
\
local function merge_tag(t)\
    if not xapp.tag_enable or not t.mac or not t.domain then\
        return\
    end\
    local pkey = string.format(\"%s_%s\", t.mac or \"\", t.domain or \"\")\
    if not xapp.tag_merge_data[pkey] then\
        if xapp.tag_stat.tag_count >= xapp.tag_max_count then\
            xapp.tag_stat.tag_drop_count = xapp.tag_stat.tag_drop_count + 1\
            return\
        end\
        local osid = 0\
        local ok, osinfo = lcmd_run({ subtype = \"osinfo\", action = \"get_oss\", mac = t.mac or \"\" })\
        if ok and type(osinfo) == \"table\" and next(osinfo) then\
            osid = osinfo.decide_osid or osinfo.cloud_osid\
        end\
        xapp.tag_merge_data[pkey] = {osid = osid, count = 1, appid = 0}\
        xapp.tag_stat.tag_count = xapp.tag_stat.tag_count + 1\
        xapp.tag_stat.all_tag_count = xapp.tag_stat.all_tag_count + 1\
    else\
        local one = xapp.tag_merge_data[pkey]\
        one.count = one.count + 1\
        one.appid = t.appid or one.appid\
    end\
end\
\
local function merge_sig(t)\
    if myip.is_localip(t.dip) then\
        return\
    end\
    match_one(t)\
    if t.ua and (t.appid <= CENUM.MAX_BASE_APPID or xapp.always_match) then\
        local ua_t = {stype = \"ua\", mac = t.mac, appid = t.appid, ruleid = t.ruleid, dip = t.dip, dport = t.dport, ua = t.ua, maxttl = t.maxttl}\
        match_one(ua_t)\
        t.appid, t.ruleid = ua_t.appid, ua_t.ruleid\
    end\
    if t.url and (t.appid <= CENUM.MAX_BASE_APPID or xapp.always_match) then\
        local url_t = {stype = \"url\", mac = t.mac, appid = t.appid, ruleid = t.ruleid, dip = t.dip, dport = t.dport, url = t.url, maxttl = t.maxttl}\
        match_one(url_t)\
        t.appid, t.ruleid = url_t.appid, url_t.ruleid\
    end\
    if t.cookie and (t.appid <= CENUM.MAX_BASE_APPID or xapp.always_match) then\
        local cookie_t = {stype = \"cookie\", mac = t.mac, appid = t.appid, ruleid = t.ruleid, dip = t.dip, dport = t.dport, cookie = t.cookie, maxttl = t.maxttl}\
        match_one(cookie_t)\
        t.appid, t.ruleid = cookie_t.appid, cookie_t.ruleid\
    end\
    if t.ref and (t.appid <= CENUM.MAX_BASE_APPID or xapp.always_match) then\
        local ref_t = {stype = \"ref\", mac = t.mac, appid = t.appid, ruleid = t.ruleid, dip = t.dip, dport = t.dport, ref = t.ref, maxttl = t.maxttl}\
        match_one(ref_t)\
        t.appid, t.ruleid = ref_t.appid, ref_t.ruleid\
    end\
    if (t.stype == \"host\" or t.stype == \"sni\") and (t.appid <= CENUM.MAX_BASE_APPID) then\
        merge_tag({mac = t.mac, domain = t[t.stype], appid = t.appid})\
    end\
    if not xapp.flow_enable then\
        return\
    end\
\
    local pkey = string.format(\"%s_%s_%d\", t.mac or \"\", t.dip or \"\", t.dport or 0)\
    if not xapp.flow_merge_data[pkey] then\
        if xapp.flow_stat.flow_count >= xapp.flow_max_count then\
            xapp.flow_stat.flow_drop_count = xapp.flow_stat.flow_drop_count + 1\
            return\
        end\
        local osid = 0\
        local ok, osinfo = lcmd_run({ subtype = \"osinfo\", action = \"get_oss\", mac = t.mac or \"\" })\
        if ok and type(osinfo) == \"table\" and next(osinfo) then\
            osid = osinfo.decide_osid or osinfo.cloud_osid\
        end\
        local _, info = lcmd_run({subtype = \"domcent\", action = \"dnscheck\", mac = t.mac, ip = t.dip})\
        if info and info.domain and (t.appid <= CENUM.MAX_BASE_APPID or xapp.always_match) then\
            local dns_t = {stype = \"dnscheck\", mac = t.mac, appid = t.appid, ruleid = t.ruleid, dip = t.dip, dnscheck = info.domain, maxttl = info.maxttl}\
            match_one(dns_t)\
            t.appid, t.ruleid = dns_t.appid, dns_t.ruleid\
        end\
        xapp.flow_merge_data[pkey] = {proto = t.proto, appid = t.appid or 0, ruleid = t.ruleid or 0, osid = osid, ua = {}, domains = { info and info.domain or nil }, pv = 0, duration = 0, update_duration_time = 0}\
        xapp.flow_stat.flow_count = xapp.flow_stat.flow_count + 1\
        xapp.flow_stat.all_flow_count = xapp.flow_stat.all_flow_count + 1\
    end\
\
    local one = xapp.flow_merge_data[pkey]\
    if t.stype == \"diport\" then\
        local now_time = os.time()\
        one.pv = one.pv + 1\
        if now_time - one.update_duration_time >= 60 then\
            one.duration = one.duration + 1\
            one.update_duration_time = now_time\
        end\
        if not one.payload\
            and xapp.flow_stat.with_paylaod_count < xapp.with_paylaod_max_count\
            and t.appid <= CENUM.MAX_BASE_APPID\
            and t.payload and #t.payload > 4\
            and not myutil.inarr(t.dport, xapp.payload_filter_port) then\
                one.payload = t.payload\
                xapp.flow_stat.with_paylaod_count = xapp.flow_stat.with_paylaod_count + 1\
        end\
    else\
        local domain = t[t.stype]\
        if not myutil.inarr(domain, one.domains) then\
            table.insert(one.domains, domain)\
        end\
        if t.ua and not myutil.inarr(t.ua, one.ua) then\
            table.insert(one.ua, t.ua)\
        end\
        if not one.url then\
            one.url = t.url\
        end\
        if not one.cookie then\
            one.cookie = t.cookie\
        end\
        if not one.ref then\
            one.ref = t.ref\
        end\
    end\
end\
\
local function collect_dns(msg)\
    local info = msg.dnstable\
    for _, ip in pairs({mystring.split(msg.ips, \",\")}) do\
        match_one({stype = \"dns\", dip = ip, dns = info.domain, mac = info.mac, maxttl = msg.maxttl})\
    end\
end\
\
local function collect_http(msg)\
    for _, info in pairs(msg.http_tables) do\
        local host = myutil.urlsplit(info.url)\
        local mac, dip = myip.mac_ntoa(info.mac), myip.inet_ntoa(info.dstip)\
        merge_sig({stype = \"host\", mac = mac, appid = info.appid, ruleid = info.ruleid, dip = dip, dport = info.dport, proto = info.proto, host = host, ua = info.ua, url = info.url, cookie = info.cookie, ref = info.ref, maxttl = xapp.maxttl_tab.host})\
    end\
end\
\
local function collect_https(msg)\
    local info = msg.https_table\
    merge_sig({stype = \"sni\", mac = info.mac, appid = info.appid, ruleid = info.ruleid, dip = info.dip, dport = info.dport, proto = 6, sni = info.domain, maxttl = xapp.maxttl_tab.sni})\
end\
\
local function collect_quic(msg)\
    local info = msg.quic_table\
    -- subscription to pcap, actually not recognized\
    merge_sig({stype = \"sni\", mac = info.mac, dip = info.dip, dport = info.dport, proto = 17, sni = info.domain, maxttl = xapp.maxttl_tab.sni })\
end\
\
local function collect_apprule(msg)\
    local info = msg.apprule_table\
    local ipf = \"\"\
    if info.ip then\
        if string.find(info.ip, \".\", 1, true) then\
            ipf = info.ip\
        else\
            ipf = \"[\"..info.ip..\"]\"\
        end\
    end\
    local diport = string.format(\"%s:%d\", ipf, info.port or 0)\
    merge_sig({stype = \"diport\", mac = info.mac, appid = info.appid, ruleid = info.ruleid, dip = info.ip, dport = info.port, proto = info.proto, diport = diport, payload = info.data, maxttl = xapp.maxttl_tab.diport})\
end\
\
local function sigver_send(deal_func)\
    local _, sig_ver = lcmd_run({subtype = \"appsig_bin\", action = \"get_coresig_ver\"})\
    local _, cidr_ver = lcmd_run({subtype = \"appcidr\", action = \"get_ver\"})\
    local info = { type = \"sig_ver\", sig_ver = sig_ver, cidr_ver = cidr_ver }\
    local pbtype = actor.pbtype_get(info.type)\
    local pbsigs = pb.encode(pbtype, info)\
    for _, addr in pairs(xapp.addr) do\
        dpi.pb_asyncall(addr, true, \"ACTION_SHORT_XAPP_CORE\", { pbsigs }, nil, deal_func)\
    end\
end\
\
local function coresig_update(t)\
    lcmd_run({subtype = \"appsig_bin\", action = \"appsig_update\", simple = t.simple, base = t.base, tag = t.tag, all = t.all})\
    if t.sig_ver then\
        lcmd_run({subtype = \"appsig_bin\", action = \"set_coresig_ver\", sig_ver = t.sig_ver})\
        sigver_send()\
    end\
end\
\
local function appsig_delete(t)\
    if t.flush then\
        lcmd_run({subtype = \"appsig_bin\", action = \"flush\"})\
        lcmd_run({subtype = \"appsig_bin\", action = \"tag_flush\"})\
        lcmd_run({subtype = \"appsig_bin\", action = \"base_flush\"})\
    end\
    if t.appid_list then\
        for _, appid in pairs(t.appid_list) do\
            lcmd_run({subtype = \"appsig_bin\", action = \"del\", appid = tonumber(appid)})\
            lcmd_run({subtype = \"appsig_bin\", action = \"tag_del\", appid = tonumber(appid)})\
            lcmd_run({subtype = \"appsig_bin\", action = \"base_del\", appid = tonumber(appid)})\
        end\
    end\
    if t.ruleid_list then\
        for _, ruleid in pairs(t.ruleid_list) do\
            lcmd_run({subtype = \"appsig_bin\", action = \"del\", ruleid = tonumber(ruleid)})\
            lcmd_run({subtype = \"appsig_bin\", action = \"tag_del\", ruleid = tonumber(ruleid)})\
            lcmd_run({subtype = \"appsig_bin\", action = \"base_del\", ruleid = tonumber(ruleid)})\
        end\
    end\
    return string.format(\"delete appid: %s, ruleid: %s, flush: %s\", cjson.encode(t.appid_list), cjson.encode(t.ruleid_list), tostring(t.flush))\
end\
\
local function trigger_timer(orig_period, timer_name, timer_func, ...)\
    local period = math.floor(orig_period)\
    local half = math.floor(period / 2)\
    local range_min = period - half\
    local range_max = period + half\
    local random_period =  math.random(range_min, range_max)\
    timer.mod(timer_name, random_period, 0, timer_func, ...)\
end\
\
local function read()\
    return {\
        flow_enable = xapp.flow_enable,\
        tag_enable = xapp.tag_enable,\
        period = xapp.period,\
        sigversend_period = xapp.sigversend_period,\
        addr = xapp.addr,\
        payload_filter_port = xapp.payload_filter_port,\
        ratio = xapp.dsmp and xapp.dsmp:getRatio() or nil,\
        seed = xapp.seed,\
        flow_max_count = xapp.flow_max_count,\
        tag_max_count = xapp.tag_max_count,\
        with_paylaod_max_count = xapp.with_paylaod_max_count,\
        send_nexttime = xapp.send_nexttime,\
        refresh_pstat_period = xapp.refresh_pstat_period,\
        maxttl_tab = xapp.maxttl_tab,\
        always_match = xapp.always_match,\
    }\
end\
\
local function write(t)\
    if type(t.flow_enable) == \"boolean\" and t.flow_enable ~= xapp.flow_enable then\
        xapp.flow_enable = t.flow_enable\
        lcmd_run({subtype = \"domcent\", action = \"write\", period = xapp.flow_enable and 10 or 0})\
    end\
    if type(t.tag_enable) == \"boolean\" and t.tag_enable ~= xapp.tag_enable then\
        xapp.tag_enable = t.tag_enable\
    end\
    if type(t.period) == \"number\" and t.period >= 0 and t.period ~= xapp.period then\
        xapp.period = t.period\
        trigger_timer(xapp.period, xapp.timer_name, appsig_send)\
    end\
    if type(t.sigversend_period) == \"number\" and t.sigversend_period >= 0 and t.sigversend_period ~= xapp.sigversend_period then\
        xapp.sigversend_period = t.sigversend_period\
        trigger_timer(xapp.sigversend_period, \"sigver_send\", sigver_send, sig_deal)\
    end\
    if type(t.addr) == \"table\" then\
        xapp.addr = t.addr\
    end\
    if type(t.payload_filter_port) == \"table\" then\
        xapp.payload_filter_port = t.payload_filter_port\
    end\
    if type(t.ratio) == \"number\" and 0 <= t.ratio and t.ratio < 1 then\
        xapp.dsmp = t.ratio > 0 and sampling.newAverager(t.ratio) or nil\
    end\
    if type(t.seed) == \"string\" and t.seed ~= xapp.seed then\
        xapp.seed = t.seed\
    end\
    if type(t.flow_max_count) == \"number\" and t.flow_max_count >= 0 and t.flow_max_count ~= xapp.flow_max_count then\
        xapp.flow_max_count = t.flow_max_count\
    end\
    if type(t.tag_max_count) == \"number\" and t.tag_max_count >= 0 and t.tag_max_count ~= xapp.tag_max_count then\
        xapp.tag_max_count = t.tag_max_count\
    end\
    if type(t.with_paylaod_max_count) == \"number\" and t.with_paylaod_max_count >= 0 and t.with_paylaod_max_count ~= xapp.with_paylaod_max_count then\
        xapp.with_paylaod_max_count = t.with_paylaod_max_count\
    end\
    if type(t.refresh_pstat_period) == \"number\" and t.refresh_pstat_period >= 0 and t.refresh_pstat_period ~= xapp.refresh_pstat_period then\
        xapp.refresh_pstat_period = t.refresh_pstat_period\
        timer.mod(\"refresh_xapp_pstat\", xapp.refresh_pstat_period, 0, function () xapp.pstat = {} end)\
    end\
    if type(t.maxttl_tab) == \"table\" and not mystring.same_table(t.maxttl_tab, xapp.maxttl_tab) then\
        xapp.maxttl_tab = t.maxttl_tab\
    end\
    if type(t.always_match) == \"boolean\" and t.always_match ~= xapp.always_match then\
        xapp.always_match = t.always_match\
    end\
end\
\
local function stat()\
    return {\
        upload_all_len = xapp.upload_all_len,\
        upload_all_count = xapp.upload_all_count,\
        flow_stat = xapp.flow_stat,\
        tag_stat = xapp.tag_stat,\
        dsmp = xapp.dsmp and xapp.dsmp:show() or nil,\
    }\
end\
\
local function pstat()\
    local rate = {}\
    local allmcnt, allcnt = 0, 0\
    for k, v in pairs(xapp.pstat) do\
        local stype, _ = mystring.split(k,\"_\")\
        if not rate[stype] then\
            local mcnt = xapp.pstat[stype..\"_mcnt\"] or 0\
            local cnt = xapp.pstat[stype..\"_cnt\"] or 1\
            allmcnt = allmcnt + mcnt\
            allcnt = allcnt + cnt\
            rate[stype] = string.format(\"%d / %d = %.2f\",mcnt, cnt, mcnt/cnt*100)..\"%\"\
        end\
    end\
    rate[\"all\"] = string.format(\"%d / %d = %.2f\",allmcnt, allcnt, allmcnt/allcnt*100)..\"%\"\
    return rate\
end\
\
local function rule_set()\
    local rules = xapp.rules\
    for _,v in pairs(rules) do\
        lcmd_run(v)\
    end\
    xapp.rules = {}\
end\
\
function xapp.postinit()\
    xapp.dindex = actor.subscribe(\"DNS\", collect_dns)\
    xapp.hindex = actor.subscribe(\"HTTP\", collect_http)\
    xapp.qindex = actor.subscribe(\"QUIC\", collect_quic)\
    xapp.hsindex = actor.subscribe(\"HTTPS\", collect_https)\
    xapp.rindex = actor.subscribe(\"APPRULE\", collect_apprule)\
    trigger_timer(xapp.period, xapp.timer_name, appsig_send)\
    trigger_timer(xapp.sigversend_period, \"sigver_send\", sigver_send, sig_deal)\
    timer.mod(\"appsigs_set_rule\", 5, 0, rule_set)\
    timer.mod(\"init_coresig_check\", 60, 1, function ()\
        local _, sig_ver = lcmd_run({subtype = \"appsig_bin\", action = \"get_coresig_ver\"})\
        if sig_ver == \"0.0.0.0\" then\
            sigver_send(sig_deal)\
        end\
    end)\
    timer.mod(\"refresh_xapp_pstat\", xapp.refresh_pstat_period, 0, function () xapp.pstat = {} end)\
end\
\
function xapp.finish()\
    if xapp.dindex then\
        actor.unsubscribe(\"DNS\", xapp.dindex)\
    end\
    if xapp.hindex then\
        actor.unsubscribe(\"HTTP\", xapp.hindex)\
    end\
    if xapp.hsindex then\
        actor.unsubscribe(\"HTTPS\", xapp.hsindex)\
    end\
    if xapp.qindex then\
        actor.unsubscribe(\"QUIC\", xapp.qindex)\
    end\
    if xapp.rindex then\
        actor.unsubscribe(\"APPRULE\", xapp.rindex)\
    end\
    timer.del(xapp.timer_name)\
    timer.del(\"sigver_send\")\
    timer.del(\"appsigs_set_rule\")\
    timer.del(\"init_coresig_check\")\
end\
\
actor.pbtype_add(xapp.timer_name, \".plugin.XAPPData\")\
actor.pbtype_add(\"sig_ver\", \".plugin.APPCoreSigReq\")\
\
actor.action_set(xapp.subtype, \"read\", read, [[read xapp conf]])\
actor.action_set(xapp.subtype, \"write\", write, [[set xapp conf, {flow_enable=boolean,tag_enable=boolean,period=number,addr=list,payload_filter_port=list,ratio=number,flow_max_count=number,tag_max_count=number,with_paylaod_max_count=number,sigversend_period=number,refresh_pstat_period=number,maxttl_tab={host=number,sni=number,diport=number},always_match=boolean}]])\
actor.action_set(xapp.subtype, \"stat\", stat, [[read xapp stat]])\
actor.action_set(xapp.subtype, \"pstat\", pstat, [[read xapp recognition rate]])\
actor.action_set(xapp.subtype, \"appsig_update\", function (t) lcmd_run({subtype = \"appsig_bin\", action = \"appsig_update\", simple = t.simple, base = t.base, tag = t.tag, all = t.all}) end, [[{all=boolean,app_sig={{ruleid=number,appid=number,prio=number,sig_type=string,name=string,value=string}}}]], \".plugin.XAPPSig\")\
actor.action_set(xapp.subtype, \"coresig_update\", coresig_update, [[{all=boolean,app_sig={{ruleid=number,appid=number,prio=number,sig_type=string,name=string,value=string}},sig_ver=string}]], \".plugin.XAPPSig\")\
actor.action_set(xapp.subtype, \"appsig_delete\", appsig_delete, [[{flush=boolean,appid_list=array<number>,ruleid_list=array<number>}]], \".plugin.XAPPSigDel\")\
actor.action_set(xapp.subtype, \"sigver_send\", function () sigver_send(sig_deal) end, \"update app core sig from server\")\
actor.action_set(xapp.subtype, \"show_conf_svr\", function() return {type = \"xapp\", subtype = \"xapp\", seed = xapp.seed} end, [[show xapp conf msg to oper svr]])\
actor.action_set(xapp.subtype, \"rule_set\", rule_set, \"immediately set rules to the apprule\")\
\
return xapp\
"
, '@'.."./service/xapp.lua" ) )

package.preload[ "xid" ] = assert( (loadstring or load)(
