    cache_cnt = 0,\
    max_cache_cnt = 1000,\
\
    merge_cnt = 0,\
    all_coll_cnt = 0,\
\
    attr = {\"url\", \"ref\", \"cookie\"},\
    keyexpr = {\
        androidid = \"(android_?id\\\"?$)\",\
        bdid = \"(bdid\\\"?$)\",\
        caid = \"(caid\\\"?$)\",\
        device_type = \"(device_type\\\"?$)\",\
        hmac = \"(mac\\\"?$)\",\
        idfa = \"(idfa\\\"?$)\",\
        idfv = \"(idfv\\\"?$)\",\
        imei = \"(imei\\\"?$)\",\
        imsi = \"(imsi\\\"?$)\",\
        latitude = \"(^\\\"?la.*)\",\
        longtitude = \"(^\\\"?lo.*)\",\
        meid = \"(meid\\\"?$)\",\
        model = \"(model\\\"?$)\",\
        oaid = \"(oaid\\\"?$)\",\
        phone = \"(phone\\\"?$)\",\
        stbType = \"(stbType\\\"?$)\"\
    },\
    valexpr = {\
        hmac = \"(^\\\"?[0-9a-fA-F]{12}\\\"?$)\",\
        idfa = \"((^\\\"?[0-9A-F]{8})(((\\\\s|-)[0-9A-F]{4}){3})((\\\\s|-)[0-9A-F]{12}\\\"?$))\",\
        imei = \"(^\\\"?(86|35)[0-9]{13,15}\\\"?$)\",\
        imsi = \"(^\\\"?460[0-9]{12}\\\"?$)\",\
        meid = \"(^\\\"?[0-9A-F]{14}\\\"?$)\",\
        phone = \"((^|[^a-zA-Z0-9])1[3-9][0-9]{9}([^a-zA-Z0-9]|$))\"\
    },\
}\
\
local record_sep = string.char(30)\
\
local function merge_data_send()\
    if xid.period <= 0 then\
        return\
    end\
    local send = false\
    local ok, oss = lcmd_run({subtype = \"osinfo\", action = \"get_oss\"})\
    if not ok or type(oss) ~= \"table\" then oss = {} end\
    for key, value in pairs(xid.cache_msg) do\
        send = true\
        local mac, host, url, ref, cookie = mystring.splits(key, record_sep)\
        local tt = {\
            type = xid.upload_type,\
            period = xid.period,\
            time = value.time,\
            mac = mac,\
            osid = oss[mac] and (oss[mac].decide_osid or oss[mac].cloud_osid or 0) or 0,\
            hostname = oss[mac] and (oss[mac].hostname or \"\") or \"\",\
            appid = value.appid,\
            host = host,\
            query = url,\
            referer = ref,\
            cookie = cookie,\
            count = value.count\
        }\
        if xid.upload_mode ~= \"none\" then\
            if xid.upload_mode == \"operdata\" or xid.upload_mode == \"all\" then\
                lcmd_run({subtype = \"__oper_data\", action = \"add\", data = tt})\
            end\
            if xid.upload_mode == \"svrdata\" or xid.upload_mode == \"all\" then\
                lcmd_run({subtype = \"__svr_data\", action = \"add_json\", data = tt})\
            end\
        end\
        xid.cache_msg[key] = nil\
    end\
    if send then\
        xid.merge_cnt = xid.merge_cnt + 1\
        xid.all_coll_cnt = xid.all_coll_cnt + xid.cache_cnt\
        xid.cache_cnt = 0\
    end\
end\
\
local function kw_match(words, key_patterns, val_patterns)\
    local kk, vv = mystring.split(words, \"=\")\
    if not kk or not vv then return end\
\
    kk = mystring.trim(kk)\
    vv = mystring.trim(vv)\
    if #kk == 0 or #vv == 0 then return end\
\
    for ty, p in pairs(key_patterns) do\
        -- 校验key是否匹配keyexpr\
        if cregex.match(kk:lower(), p:lower()) then return kk..\"=\"..vv end\
    end\
\
    for ty, p in pairs(val_patterns) do\
        -- 校验value是否匹配valexpr\
        if cregex.match(vv:lower(), p:lower()) then return kk..\"=\"..vv end\
    end\
end\
\
local function keywords_match(httpstr, attr, keyexpr, valexpr)\
    local delim\
    if attr == \"url\" or attr == \"ref\" then\
        delim = \"&\"\
        httpstr = string.match(httpstr, \"%?(.*)\")\
        if not httpstr or httpstr == \"\" then return \"\" end\
    elseif attr == \"cookie\" then\
        delim = \";\"\
    else\
        return \"\"\
    end\
\
    local list = {}\
    httpstr:gsub('[^' .. delim .. ']+', function(words)\
        local query = kw_match(words, keyexpr, valexpr)\
        if query then\
            table.insert(list, query)\
        end\
    end)\
\
    return table.concat(list, \";\")\
end\
\
local function collect_one(http)\
    if type(http) ~= \"table\" then\
        return\
    end\
    local data = {url = \"\", ref = \"\", cookie = \"\"}\
    for _, attr in pairs(xid.attr) do\
        if http[attr] then\
            -- get kv in one attr\
            data[attr] = keywords_match(http[attr], attr, xid.keyexpr, xid.valexpr)\
        end\
    end\
    if data.url == \"\" and data.ref == \"\" and data.cookie == \"\" then\
        return\
    end\
    local mac = myip.mac_ntoa(http.mac)\
    local host = myutil.urlsplit(http.url)\
    local pkey = mac..record_sep..host..record_sep..data.url..record_sep..data.ref..record_sep..data.cookie\
    if not xid.cache_msg[pkey] then\
        if xid.cache_cnt >= xid.max_cache_cnt then\
            merge_data_send()\
        end\
        xid.cache_msg[pkey] = {time = tostring(http.ts_sec), appid = http.appid, count = 0}\
        xid.cache_cnt = xid.cache_cnt + 1\
    end\
    xid.cache_msg[pkey].count = xid.cache_msg[pkey].count + 1\
end\
\
local function collect_http(msg)\
    if xid.period <= 0 then\
        return\
    end\
    if type(msg.http_tables) == \"table\" then\
        for _, http_table in pairs(msg.http_tables) do\
            collect_one(http_table)\
        end\
    end\
end\
\
local function write(t)\
    if type(t.upload_mode) == \"string\" and t.upload_mode ~= xid.upload_mode then\
        xid.upload_mode = t.upload_mode\
    end\
    if type(t.upload_type) == \"string\" and t.upload_type ~= xid.upload_type then\
        xid.upload_type = t.upload_type\
    end\
    if type(t.period) == \"number\" and t.period >= 0 and t.period ~= xid.period then\
        xid.period = t.period\
        timer.mod(xid.tname, xid.period, 0, merge_data_send)\
    end\
    if type(t.max_cache_cnt) == \"number\" and t.max_cache_cnt > 0 and t.max_cache_cnt ~= xid.max_cache_cnt then\
        xid.max_cache_cnt = t.max_cache_cnt\
    end\
    if type(t.attr) == \"table\" and #t.attr > 0 then\
        xid.attr = t.attr\
    end\
    if type(t.keyexpr) == \"table\" and next(t.keyexpr) then\
        xid.keyexpr = t.keyexpr\
    end\
    if type(t.valexpr) == \"table\" and next(t.valexpr) then\
        xid.valexpr = t.valexpr\
    end\
end\
\
function xid.postinit()\
    xid.handle = actor.subscribe(\"HTTP\", collect_http)\
    timer.mod(xid.tname, xid.period, 0, merge_data_send)\
end\
\
function xid.finish()\
    timer.del(xid.tname)\
    if type(actor.unsubscribe) == \"function\" then\
        actor.unsubscribe(\"HTTP\", xid.handle)\
    end\
end\
\
actor.action_set(xid.subtype, \"read\", function () return {upload_mode = xid.upload_mode, upload_type = xid.upload_type, period = xid.period, max_cache_cnt = xid.max_cache_cnt, attr = xid.attr, keyexpr = xid.keyexpr, valexpr = xid.valexpr} end, \"read config of xid\")\
actor.action_set(xid.subtype, \"write\", write, \"write config of xid, {upload_mode=string, upload_type=string, period=number, max_cache_cnt=number, attr=array, keyexpr=table, valexpr=table}\")\
actor.action_set(xid.subtype, \"stat\", function () return {merge_cnt = xid.merge_cnt, all_coll_cnt = xid.all_coll_cnt} end, \"read collect status of xid\")\
actor.action_set(xid.subtype, \"show\", function () return {cache_msg = xid.cache_msg, cache_cnt = xid.cache_cnt} end, \"show cache data of xid\")\
\
return xid"
, '@'.."./service/xid.lua" ) )

end

assert( (loadstring or load)(
"\
if not rootpath then rootpath = \".\" end\
\
local function concat_path(prefix, ...)\
    local luapath = \"\"\
    for i, v in ipairs({...}) do\
        luapath = luapath .. prefix..\"/\".. v .. \";\"\
    end\
    return luapath\
end\
\
package.path = concat_path(rootpath, \"?.lua\", \"service/?.lua\", \"service/?/?.lua\", \"lualib/?.lua\", \"lualib/?/?.lua\")\
package.cpath = concat_path(rootpath, \"luaclib/?.so\")\
\
local cjson = require(\"cjson\")\
local actor = require(\"luactor\")\
local log = require(\"log\")\
local timer = require(\"timer\")\
local myfile = require(\"myfile\")\
local sockfile = \".__scli\"\
local loop_running = true\
\
-- path def\
local g_tmppath = \"\"\
local g_datapath = \"\"\
\
cjson.encode_sparse_array(true)\
\
function __lcmd_actor()\
    return actor\
end\
\
function lcmd_errhandle(errmsg)\
    if type(errmsg) ~= \"string\" and type(errmsg) ~= \"nil\" then\
        return \"errmsg type is \"..type(errmsg)\
    end\
    return debug.traceback(errmsg)\
end\
\
function lcmd_loop_exit()\
    loop_running = false\
end\
\
function lcmd_run(t)\
    return pcall(actor.deal_reply, t)\
end\
\
function lcmd_tmp_path(fname)\
    return g_tmppath..\"/\"..fname\
end\
\
function lcmd_data_path(fname)\
    if not g_datapath then\
        return nil\
    end\
    return g_datapath..\"/\"..fname\
end\
\
function lcmd_conf_save_filename()\
    if not g_datapath then\
        return nil\
    end\
    return g_datapath..\"/conf_init.bin\"\
end\
\
function lcmd_runmsg(msg)\
    local ok, t = pcall(cjson.decode, msg)\
    if not ok or type(t) ~= \"table\" then\
        return nil, \"failed to lcmd run msg, cjson decode err, \", t\
    end\
\
    if #t > 0 then\
        for _, v in ipairs(t) do\
            local ok, result = lcmd_run(v)\
            if not ok then\
                return nil, \"failed to run\"..result\
            end\
        end\
        return\
    end\
\
    local ok, result = lcmd_run(t)\
    if not ok then\
        return nil, \"failed to run\"..result\
    end\
    if type(result) == \"string\" or type(result) == \"table\" then\
        return cjson.encode(result), nil\
    end\
    return nil, nil\
end\
\
local function init_config_file(config, config_local)\
    -- init config && config_local\
    local t, err = myfile.load_json(config)\
    if t == nil then\
        return \"failed load config, err is \"..err\
    end\
    for _, v in pairs(t.__conf_init__) do \
        actor.deal_reply(v)\
    end\
    local saveconf\
    if config_local ~= nil then\
        saveconf, err = myfile.load_crypto_json(config_local)\
        if err then\
            -- To ensure compatibility, try loading the old version of the conf_init.json file when loading conf_init.bin fails\
            local config_local_orig = g_datapath..\"/conf_init.json\"\
            if myfile.existed(config_local_orig) then\
                saveconf, err = myfile.load_json(config_local_orig)\
                if not err then\
                    local err_store = myfile.store_crypto_json(saveconf, config_local)\
                    if not err_store then\
                        os.remove(config_local_orig)\
                    end\
                end\
            end\
        end\
        if not err then\
            for _, v in pairs(saveconf) do\
                actor.deal_reply(v)\
            end\
        end\
    end\
    return nil\
end\
\
function lcmd_boot(tmppath, datapath)\
    local mystring = require\"mystring\"\
    local tmpp, fsock = mystring.split(tmppath, \":\")\
    g_tmppath = tmpp\
    g_datapath = datapath\
\
    if fsock then sockfile = fsock end\
    \
    -- load all service\
    local a = assert(require(\"config_service\"))\
    for k, v in pairs(a) do\
        local service = assert(require(v))\
        actor.actor_add(service)\
    end\
\
    -- init protobuf\
    actor.pb_init()\
end\
\
function lcmd_init(config, ...)\
    -- initmsg first\
    for _, initmsg in ipairs({...}) do\
        if type(initmsg) == \"string\" and initmsg ~= \"\" then\
            lcmd_runmsg(initmsg)\
        end\
    end\
\
    actor.pre_init()\
\
    -- kengine init\
    local kengine = require(\"kengine\")\
    kengine.kengine_init()\
\
    -- init config and local\
    init_config_file(config, lcmd_conf_save_filename())\
\
    -- init unix server\
    local cli = require'cliserver'\
    local err = cli.init(lcmd_tmp_path(sockfile))\
    if err then\
        log.fatal(err)\
        return err\
    end\
\
    actor.post_init()\
    return nil\
end\
\
function lcmd_loop()\
    local msocket = require(\"msocket\")\
    local now = os.time()\
    local last = now\
    while loop_running do\
        msocket.run(1000)          -- using 1000 ms precision timer\
        now = os.time()\
        if now - last > 2 or now < last then\
            timer.run_now(now)\
            last = now\
        end\
    end\
end\
\
function lcmd_client(ismainp, tmppath, ...)\
    local csys = require(\"c.sys\")\
    if type(csys.lcmd_client) == \"function\" then\
        return csys.lcmd_client(tmppath, ...)\
    end\
\
    local mystring = require\"mystring\"\
    local cli = require(\"cliclient\")\
\
    local tmpp, fsock = mystring.split(tmppath, \":\")\
    if fsock then\
        return cli.main(ismainp, tmpp ..\"/\".. fsock, ...)\
    else\
        return cli.main(ismainp, tmpp ..\"/\".. sockfile, ...)\
    end\
end\
\
function lcmd_unittest(...)\
    package.path = concat_path(rootpath, \"?.lua\", \"service/?.lua\", \"service/?/?.lua\", \"lualib/?.lua\", \"lualib/?/?.lua\", \"unittest/?.lua\")\
\
    -- load all service\
    local a = assert(require(\"config_service\"))\
    for k, v in pairs(a) do\
        local service = assert(require(v))\
        actor.actor_add(service)\
    end\
\
\
    local lu = require\"luaunit\"\
    local p = io.popen(string.format(\"find %s/unittest -name *_test.lua\", rootpath))\
    for file in p:lines() do\
        local fmod, id = string.gsub(file, \"^.*/(.*_test).lua\",\"%1\")\
        if id == 1 then\
            log.info(\"add unittest \"..fmod)\
            require(fmod)\
        end\
    end\
    p:close()\
\
    lu.LuaUnit.run(...)\
end\
"
, '@'.."init.lua" ) )( ... )

